if not AI_VoiceOverData_BookVoices_RU then return end
AI_VoiceOverData_BookVoices_RU.Books = {
    ["0032c7cd"] = "Это письменное доказательство подтверждает тот факт, что путник убил Маргола Яростня – бич Тлеющего ущелья. Музей Стальгорна ценит этот экспонат и благодарит дарителя за столь щедрое подношение. -Главный куратор музея, Ториус Каменный Сторож",
    ["0037ce32"] = "НАСТАВЛЕНИЕ ПО ВОИНСКИМ ЗВАНИЯМ. Ниже перечислены воинские звания Альянса, снабжённые пояснениями, касающимися народов Орды. Звания представлены в двух разделах – офицерский и рядовой состав – и перечислены в каждом разделе в убывающем порядке, от старших к младшим. Да здравствует Альянс!",
    ["006d5b31"] = "Многие наши соплеменники считают, что тайная магия и чародейство – единственные источники силы. Но ты-то так не думаешь, герой? Клинки – наша магия, щиты – наши обереги, броня – наша мудрость. Будучи мёртвыми, мы сохраняем и умножаем свою силу. Ищи меня в таверне в Могильнике. Там мы обо-всём и поговорим. -Даннал Штерн, наставник воинов",
    ["0122ab90"] = "Драконы встретились высоко в небе над Силитусом, в тысячах метров над твердыней Ан'Кираж. Там был Анахронос, дитя Ноздорму, Аспекта Времени. Из Изумрудного Сна явилась Меритра, дитя Изеры, Аспекта Природы. Келестраз, отпрыск Алекстразы, Аспекта Жизни, представлял Красных драконов. Аригос же, дитя Малигоса, Аспекта Магии, говорил от имени Синих драконов.",
    ["01431271"] = "Кардрос и воины Громового Молота отправились на север через пограничные ворота Дун Альгаз и основали своё собственное королевство под далёкой горой Грим Батол. Там Громовые Молоты разбогатели и построили новые сокровищницы. Тауриссан и другие члены клана Чёрного Железа не были столь же удачливы. Униженные и разгневанные своим поражением, они поклялись отомстить Стальгорну. Уведя своих сородичей далеко на юг, Тауриссан основал город (названный в свою честь) под прекрасным Красногорьем.",
    ["0150058c"] = "Чтобы подчинить коня погибели, нужно сделать три вещи: Сотворить Круг Великого Призыва. Внутри этого круга открыть портал в Ксорот и вывести коня через него. Победить его и покорить его дух. На следующих страницах подробно описан каждый из трёх шагов. Сделать это непросто, но ты доказал, что способности у тебя есть. Я уверен, что ты со своей целеустремлённостью подчинишь себе коня гибели. Читай дальше. -Мор'зул Кровопуск",
    ["015c3d71"] = "Секрет успеха жреца – в его связи с миром. Мудрость и сострадание позволят тебе помогать тем, кто действительно в этом нуждается, а поспешность и необдуманные решения причинят только вред. Но к этому ты должен прийти сам. Когда ты это осознаешь, тебе понадобятся новые способности и заклинания. Вот с этим я могу тебе помочь. Приходи в библиотечное крыло Аббатства Североземья. -Жрица Анетта, наставница жрецов",
    ["0167594b"] = "Искать спасения для своего застигнутого врасплох народа пришлось Малфуриону Ярости Бури. Родной брат Малфуриона, Иллидан, практиковал магию высокорождённых, и Малфуриона очень сильно беспокоила его растущая одержимость. Малфурион убедил брата отказаться от свого пагубного пристрастия и вместе с ним отправиться на поиски Кенария. Кроме того, братьям надлежало собрать силы для сопротивления демонам.",
    ["0174519d"] = "Ван Клиф... Неразборчиво. Вызывает МЕНЯ? ДА КЕМ ОН СЕБЯ ВОЗОМНИЛ??? Я – Клейвен Мортвейк! И чтобы какое-то насекомое ещё мне указывало?! Остальные страницы книги утеряны.",
    ["01dfa75a"] = "Король Лордерона Теренас, уверенный в том, что орки готовят новое нашествие, созвал к себе своих самых преданных военачальников. Он приказал генералу Туралиону и верховному магу Кадгару возглавить поход сквозь Тёмный портал, чтобы раз и навсегда разделаться с орками. Силы Туралиона и Кадгара вторглись в Дренор и вступили в сражение с войсками Нер'зула на Полуострове Адского Пламени.",
    ["020726b6"] = "Элуна с тобой. Ветер прошептал мне твоё имя, и я очень рада, что могу принять участие в обучении следующего поколения охотников. Я знаю, что ты сейчас где-то недалеко от Альдрассила. Я буду ждать там. Наши старейшины поручили мне подготовить всех новых охотников к грядущим испытаниям. Ты входишь в их число. До встречи. -Аянна Вечнобродка, наставница охотников",
    ["0257faad"] = false,
    ["027bfa1d"] = "Ноздорму: Ноздорму известен как Хозяин Времени и Вневременный. Он и его драконы – бронзового цвета, показывают большую сметливость во всём. Внимание Ноздорму всегда привлекают артефакты прошлого, ведь о нынешних делах смертных народов, как и о замыслах его сотоварищей-Аспектов, он особо не заботится. Но его безразличие к задумкам других не означает, что он не уделяет внимания событиям, происходящим в мире.",
    ["02fbab56"] = "Архиепископ Алонсий Фаол. Блаженный покровитель Церкви Света. Несмотря на то что архиепископ Фаол начал свой светлый путь в Стратхольме, что в Лордероне, он всегда был другом Штормграда. В тёмные времена после Второй войны он помогал монастырю в Североземье и жертвовал значительные средства на восстановление самого города. Сей собор стоит не только как бастион Света, но и как памятник благородному духу и щедрости человека.",
    ["0319794a"] = "Сейчас Король-лич Артас пребывает в Нордсколе. Говорят, что он собирается восстановить Ледяную Корону. Его верный помощник Кел'Тузад командует силами Плети в Чумных землях. Сильвана же со своими Отрёкшимися удерживает лишь Тирисфальские луга – небольшую часть растерзанного войной королевства.",
    ["033b6750"] = "Соломон! Предъявителю данного приказа дарован официальный статус действующего представителя Штормграда. Вы можете воспользоваться его помощью в поисках доказательства участия чёрных драконов в делах клана Чёрной Горы. В случае если подобное доказательство будет обнаружено, данный представитель должен будет вернуться с вышеуказанным доказательством ко мне в Штормград, и тогда я издам приказ об отправке необходимой военной помощи в Приозёрье. С наилучшими пожеланиями, Верховный лорд Болвар Фордрагон",
    ["034adc19"] = "Лорд Брант Вэлор, глава рода Вэлор. Лорд Брант, да упокоится он с миром, был воплощением всего лучшего, что есть в Альянсе. Прирождённый вождь, он привёл жителей Вороньего Холма к процветанию. Когда тьма начала расползаться по лесам, он первым поднял наш народ на защиту. Не было для лорда Бранта врага омерзительнее нежити. Он сам обходил кладбища Сумеречного леса, сдерживая бредущие орды мертвецов. В тот день, когда чудовища тяжело ранили его, весь город разделил его боль. Благодаря заботе семьи он вернулся к своему долгу, но недуг так и не отпустил его до конца дней.",
    ["037649dd"] = "Военные звания Альянса. Офицеры: главнокомандующий, фельдмаршал, маршал, командор, лейтенант-командор, рыцарь-защитник, рыцарь-капитан, рыцарь-лейтенант, рыцарь. Рядовые: старшина, старший сержант, капрал, рядовой.",
    ["03965fbd"] = "Полубог Кенарий обитал неподалёку оттуда на Лунных полянах горы Хиджал. Его сыновья, известные как Хранители Рощ, наблюдали за ночными эльфами и регулярно помогали Часовым поддерживать мир на этих землях. Даже скромные дочери Кенария, дриады, стали появляться всё чаще и чаще.",
    ["03a545ac"] = "Наши союзники Отрёкшиеся обитают в землях под названием Тирисфальские леса – это на восточном континенте. Глубоко под руинами города, что некогда звался Лордероном, ты найдёшь Подгород. Чтобы попасть в Тирисфаль, выйди из города через великие южные ворота и отправляйся на восток, к башне дирижаблей. Садись на дирижабль, что причаливает с южной стороны башни. Перелетев через великое море, ты прибудешь в городок Брилл. Оттуда просто иди на север, к руинам Лордерона. Найди подъёмник, спустись на нём в глубины Подгорода и разыщи в Королевском квартале Тёмную Госпожу. Только предупреждаю: столица Отрёкшихся может показаться тебе... жутковатой.",
    ["03c0c9f2"] = "Кормок. Двухголовый огр некромант Что сказать о Кормоке? Это двухголовый огр-заклинатель, который, кстати, не всегда был так уж плох. Когда мы его приняли к себе, мы взялись за одну работу в Пылающих степях, и он был нашим пленником. Но он оказал нам неоценимую помощь, когда мы попали там в небольшую переделку, и после этого стал одним из наших главных магов. Что нас в нём немало удивило, так это то, что две его головы вели себя совершенно по-разному. Одна из них была вечно весёлая, даже немного глуповатая, вторая же – коварная и расчётливая, а взгляд в её глазах был совершенно безжизненным. Пугающее зрелище, скажу я тебе.",
    ["03e3d245"] = "Здесь опасность кругом! Жаждут враги заковать Нас обратно в оковы. Помни же в яростной битве О том, кто свой выполнил долг. Адский Крик вечно живёт!",
    ["03e429de"] = "Отчёт о положении дел с троллями из племени Мерзлогривов в регионе Дун Морога. Большая часть троллей, обитающих в Дун Мороге, сконцентрирована в форте Мерзлогривов, горной пещере на западной границе. Их численность может вызывать некоторые опасения, однако, похоже, они не собираются покидать свою пещеру. Вне всяких сомнений, они не хотят вызывать гнев дворфов и рисковать своей шкурой. Они всего лишь обороняют свою территорию, и",
    ["03fbb2db"] = "Общими усилиями Медив и волшебники Совета Теней открыли портал между измерениями – Тёмный портал. Этот портал позволил армии Дренора попасть на Азерот. Гул'дан послал через портал разведчиков, чтобы они исследовали земли, которые им предстояло завоевать. Вернувшись, они доложили Совету Теней, что можно начать вторжение.",
    ["04265f3d"] = "Анналы Дарроушира. Поселение Дарроушир, названное в честь озёра Дарроумир, находится к западу от этого озера на южной границе Лордерона. Известное своими скромными, но трудолюбивыми обитателями, это поселение было ничем не примечательно, пока не началась Вторая война. Герои появляются во время войны, а после неё их забывают.",
    ["0447da2b"] = "Моя дорогая Амелия! То, что я увидел сегодня, навсегда останется в моей памяти. Стратхольм охвачен огнём… и в этом наша вина. Сегодня ночью мы вышли на городские улицы, и наш принц велел нам врываться в дома мирных жителей и… убивать их, пока они спят. Принц Артас сказал, что они поражены чумой и их нужно лишить жизни, пока они не сделали то же самое с нами. Началась резня. Сотни людей погибли от рук тех, кто поклялся их защищать. Я просто не мог на это смотреть и сбежал. Да, я теперь дезертир, но у меня не поднялась рука совершить столь ужасное злодеяние. Смотря на лица этих несчастных, обречённых на смерть горожан, я видел тебя… и наших детей… И если противостоять подобной жестокости – предательство, значит так тому и быть. Надеюсь, мне удастся вернуться к тебе вовремя, но на дорогах сейчас небезопасно. Передай детям, что я люблю их. Джеймс",
    ["04581935"] = "Удачи тебе. Вот тебе подсказка, как справится с приспешниками Аррока: Заклятие Омокка, убивающее огров, останется в силе даже после гибели самого Омокка. В бою с приспешниками Аррока пробуди силу в голове Омокка – и она, может быть, убьёт твоих врагов! Способ что надо.",
    ["04622942"] = "Сначала Анахронос отказывался вовлекать свой народ в дела низших рас. Лишь после дерзкого нападения киражей на Пещеры Времени он согласился выступить сообща с ночными эльфами.",
    ["04835242"] = "Несса, рад был получить от тебя весточку. Коллекция костей и чешуек, которую ты послала мне, превосходна. Никогда ещё я не видел за пределами материка рыб такого размера. Должно быть, рыбаки деревни Рут'теран с лёгкостью выуживают по тонне за день! Я хоть и завидую размеру их добычи, но всё же немного обеспокоен. Может ли наше новое древо Жизни сделать так, чтобы наша рыба дорастала до таких же размеров? И если может, то чего ещё следует ожидать? Это стоит обдумать. -Лайрд",
    ["04a26278"] = "Компендиум Форора по убийству драконов - это толстая исписанная книга. К сожалению, текст выглядит искажённым и не имеет для вас смысла.",
    ["04c71eb6"] = "Здравствуй, Вильям! Мы уже много лет не разговариваем, но я надеюсь, что у вас с братом всё в порядке и что ваша аптека процветает. У меня к тебе просьба, Вильям. В общем, мой внук Томми Джо влюблён в юную Мейбелл Маклюр. Они друг в друге души не чают, но наши семьи... Конечно, наши семьи враждуют уже много лет...",
    ["0506f7fc"] = "Эльфы сказали Торадину, что армия троллей неисчислима, что, уничтожив Кель'Талас, они двинутся на юг. Будучи в отчаянии, эльфы, нуждавшиеся в военной помощи, быстро согласились обучить некоторых избранных людей искусству магии в обмен на помощь.",
    ["0517d062"] = "Дорогой дневник, сегодня мой злейший враг Нарайн Причудень пытался меня обмануть, послав вместо себя друзей на казнь. На СВОЮ казнь. Ты можешь в это поверить? Я, несмотря ни на что, разрабатывал свой дьявольский план, чтобы выманить его из этой проклятой хижины, а он выкинул такое! Да что там… Больше писать не могу, слишком зол. Продолжу позже.",
    ["052ee89b"] = "Затем Артас погрузил останки Кел'Тузада в священные воды Солнечного Колодца. Могучие воды Вечности были осквернены этим злодеянием, но Кел'Тузад воскрес и вернулся в этот мир могущественным личом. Кел'Тузад, чьи силы теперь многократно возросли, объяснил, в чём состоял следующий этап плана Короля-лича.",
    ["058fa927"] = false,
    ["05a1ba8e"] = "Я начала мои эксперименты с предположения, что кровавые камни были каким-то видом камня, как кварц или обсидиан. Посему я запустила серию экспериментов для опознания того, какие минералы содержатся в кровавом камне, какие силы использовались для придания ему такой твёрдости и цвета, и других свойств, сходных с камнем или рудой. Но подвеска Кровавого камня, к моему разочарованию, не отреагировала на мои процедуры так, как это сделала бы обычная руда.",
    ["05c9e398"] = "Я долго исследовал Аспекты и их создателей-титанов – так долго, насколько хватит человеческой жизни. Когда титаны покинули этот мир, Аспектов насчитывалось пять; это были могучие драконы, в задачи которых входила защита мира Азерота. О них сложено множество разных историй, и даже сейчас, когда я собрал множество сведений, я знаю, что нам ещё очень многое предстоит узнать об этих величественных существах.",
    ["05f02e54"] = false,
    ["062a2128"] = "Здесь покоится Дуротан – вождь клана Северного Волка и отец нашего почтенного Военного Вождя Тралла. Он был храбрейшим среди нас, и его предали те, кто жаждал нашего порабощения. Дуротан отдал свою жизнь, чтобы мы могли обрести свободу. Мы чтим его и заветы, что он передал нам через своего сына. Дрек'Тар, шаман клана Северного Волка",
    ["06984e3d"] = "Владыкой Приливов. Так продолжалось много веков: Камень выносило на берег, а потом Владыка Приливов уходил в море. Камень Приливов периодически упоминается в современных источниках, но почему столь могущественный предмет появляется с такой регулярностью и кто тому причиной, остаётся загадкой.",
    ["06b2630d"] = "Потеряв свою королеву, воины клана Чёрного Железа бежали от ярости Громовых Молотов. Они бежали на юг, к крепости своего короля, но столкнулись с армией Стальгорна, пришедшей помочь Грим Батолу. Зажатые между двух армий, силы Чёрного Железа были полностью уничтожены.",
    ["06b52881"] = "Демоны-чернокнижники призвали инферналов, которые обрушились на изящные шпили калимдорских храмов будто адские пылающие метеоры. Армия кровожадных убийц, называемых стражниками ужаса, прошла по калимдорским полям, уничтожая всё живое на своём пути. Демонические гончие Скверны наводнили сельскую местность. Разумеется, храбрые воины-кальдорай пытались защитить свои родные земли, но они не могли сдержать всю ярость Пылающего Легиона, и им пришлось шаг за шагом отступать.",
    ["06c9c811"] = "Нер'зул выпустил на просторы ледяной пустыни чуму нежити, зародившуюся глубоко внутри Ледяного Трона. Направляя её силами одного лишь разума, он привёл её в поселение людей. Спустя три дня все его жители погибли, но вскоре восстали, превратившись в ужасных зомби. Нер'зул чувствовал их мысли и настроения так же ясно, как свои.",
    ["06de738a"] = "Болиды, что участвуют в гонках на Равнинах, имеют очень тонкие настройки и требуют внимательнейшего ухода. Поэтому неудивительно, что у команды работа есть всегда. Механики команды постоянно проверяют машины, чинят их и доводят. Только так можно содержать технику в идеальном состоянии. Итак... мы изыскиваем возможность немного притупить бдительность команды, поскольку при этом их машина быстро придёт в негодность.",
    ["0710b7a4"] = "Несколько воинов, оставшихся в Строме, решили и дальше защищать древние стены. Стром более не был центром империи, но он превратился в новое государство – Стромгард. Хотя каждый город-государство сам по себе процветал, империя Аратор практически распалась. Каждое государство завело свои собственные обычаи и верования, и они начали всё больше отдаляться друг от друга. Мечта короля Торадина об объединении человечества развеялась.",
    ["0723097a"] = "Пробираясь через Ясеневый лес, Адский Крик и его верные воины Песни Войны наткнулись на древних ночных эльфов-Часовых. Полубог Кенарий решил, что орки вновь возжаждали войны, и хотел прогнать их из своих земель. Но Адский Крик со своими воинами, преисполненные сверхъестественной ярости и злобы, убили Кенария и осквернили древние леса.",
    ["076110b9"] = "Или кровавый камень состоит из крови? И, если так, чьей крови? Моей? Крови другого человека? Животного? Или, может быть, кровавый камень – это кровь некоего неизвестного существа – того самого существа, которого Кеган одновременно почитал и боялся, когда отдавал мне эту подвеску? Вот вопрос, на который нужно получить ответ. Это – ключ.",
    ["0761b3ca"] = "Дуротан, по-прежнему уверенный в том, что Гул'дан приведёт их народ к гибели, снова высказался против действий волшебников. Храбрый воин сказал, что они уничтожили чистый дух орков и что это безрассудное нападение на Азерот погубит их всех. Гул'дан не мог пойти на риск, убив любимого всеми героя, и был вынужден отправить Дуротана вместе с его кланом Северного Волка в самые отдалённые области нового мира.",
    ["07748c77"] = "Мой дневник. Ужасы последних недель почти лишают меня разума; единственное, что меня спасает, – записи в дневнике. Я как будто исповедуюсь в своих грехах перед безмолвным собеседником или как будто освобождаю свою голову от мрачных мыслей, перенося их на бумагу. Это второй мой дневник, первый остался в месте, куда я не могу вернуться. Поэтому я начал всё с нуля. Но в этот раз я буду писать только правду.",
    ["07c53d8e"] = "Некогда за власть над большей частью Калимдора боролась древняя раса разумных насекомых, известная под именем киражи. Именно напыщенный Олений Шлем со своим войском ночных эльфов и сошёлся в бою с ними.",
    ["07f2cea1"] = "Когда Артас со своей армией нежити повернул на юг, в землях Кель'Таласа уже не осталось ни одного живого эльфа. Славного королевства высших эльфов, просуществовавшего более девяти тысяч лет, больше не существовало.",
    ["08146dbc"] = "РЯДОВЫЕ ЗВАНИЯ ОРДЫ. Высший Сержант. Старший Сержант. Сержант. Рубака. Разведчик.",
    ["08195eb6"] = "Легенда о Дедушке Зиме. Говорят, что название \"Зимний Покров\" происходит от сверхъестественного существа, именуемого во многих культурах Дедушкой Зимой. Считается, что, когда на исходе года он шествует по земле, за ним вздымающимся шлейфом ложится снежный покров. Говорят, что просыпается Дедушка Зима под одеялом из снега и укрывает снежной вуалью землю. Месяцы, когда Азерот частично укрыт снегом, дают земле время обновиться и переродиться.",
    ["0857cf05"] = "Зависимость Иллидана от магической энергии непрестанно мучила его, и он с трудом сдерживался, чтобы не броситься к источнику Вечности. Однако Тиранда всё время была рядом и поддерживала его, так что в итоге они всё же добрались до полубога-отшельника по имени Кенарий.",
    ["08c79c41"] = "ЖИЗНЕННО ВАЖНЫЕ ДАННЫЕ! УРОВЕНЬ СЕКРЕТНОСТИ пять тысяч сто двадцать два! Дальше страница испещрена нулями и единицами.",
    ["08d06d5b"] = "Вот от этой самой бочки иди прямёхонько на север. Иди, пока не увидишь пустой кувшин рядом с заброшенной ветряной мельницей, стоящей на крутом берегу у моря. В том кувшине найдёшь, что ищешь.",
    ["090f50da"] = "Но зная, что все вожди, в первую очередь Адский Крик и Оргрим Молот Рока, начнут борьбу за превосходство, Гул'дан поставил во главу Орды своего вождя-марионетку. На эту роль он выбрал Чернорука Разрушителя, злобного и жестокого орка. Под командованием Чернорука Орда выдвинулась в первый пробный бой против дренеев.",
    ["091d3906"] = "Шли месяцы; к Кел'Тузаду приходили всё новые и новые приверженцы Культа Проклятых. Кел'Тузад на удивление легко добился своей цели: многие потеряли веру в Священный Свет и стали поклоняться тёмному владыке Нер'зулу. Культ Проклятых становился всё более влиятельным, но благодаря Кел'Тузаду власти Лордерона всё ещё не замечали перемен…",
    ["09370170"] = "И так он бродил, и так он искал. И его рука оставалась потерянной для него. И так он изрыгал проклятия и рычал при ходьбе. Но Гри'лек давно перестал слушать духов, и они были сердиты на него и не слышали его проклятий. Гри'лек был обречён. Обречён бродить без руки.",
    ["097e2cab"] = "Судьба Карлина Редпата Карлин, брат капитана Джозефа Редпата, был тяжело ранен в битве за Дарроушир, однако ему удалось выжить. Через несколько дней измученного жаждой и сильным жаром Карлина, неизвестно как оказавшегося возле Перекрёстка Корина, подобрали агенты Серебряного Рассвета. Они залечили его раны и доставили в часовню Последней Надежды. Благодарный Карлин вступил в ряды Серебряного Рассвета. И в наши дни он сражается с Плетью, стремясь отомстить тем, кто погубил его дом и его брата.",
    ["09927249"] = "Добудь нефрит. Он попадается в различных местах. Камень довольно редок, но если ты спросишь о нём у кузнеца или инженера, они, вероятно, смогут продать тебе несколько таких камней.",
    ["0a759759"] = "Избавившись от всех противников, Король-лич мог, наконец, приступить к выполнению своей истинной миссии в этом мире. Он устремил свои помыслы к землям людей, выискивая тех, в чьих душах скрывалась тьма, тех, кто слышал его зловещий зов…",
    ["0aaec017"] = "Саргерас выжидал подходящего момента, когда таящаяся в юноше сила даст о себе знать. Уже будучи подростком, Медив заработал себе популярность среди жителей Азерота своими выдающимися магическими способностями и часто отправлялся на поиски приключений вместе со своими друзьями – принцем Азерота Лланом и Андуином Лотаром, одним из последних сыновей рода Арати. Трое мальчишек постоянно попадали в переделки, но горожане их очень любили.",
    ["0ae80c2f"] = false,
    ["0b052e45"] = "Ружьё резко подалось назад в его руках. Дуло ушло в сторону и попало под ствол ружья Ажек. И именно в этот момент Ажек спустила курок. Неуклюже вздёрнувшееся к кронам деревьев ружьё отчётливо и громко выстрелило. Стая птиц, крича, вспорхнула в небо, разлетаясь во все стороны. Струйка дыма вилась из дерева. Мы в оцепенении смотрели, как гигантская ветка рухнула прямо на убегающую пантеру и сломала ей хребет.",
    ["0b1384d3"] = "Похоже, то, что прятал в своём сундуке Клейвен, оно оказало неблагоприятный эффект на обитателей башни. Я подозреваю, что и другие стражники столь же слабы, и, возможно, даже сам Клейвен пал жертвой этих нежелательных побочных эффектов. Агент Эмбер Кеарнен ШРУ семь, полевой оперативник, отдел восемь",
    ["0b8af7ae"] = "В то время как высшие эльфы сражались не на жизнь, а на смерть против яростного натиска троллей, разрозненные, ведущие кочевой образ жизни люди Лордерона боролись за объединение своих земель. Изначально племена людей постоянно совершали набеги на другие людские поселения, пренебрегая честью и не заботясь об объединении расы.",
    ["0bfb5c7d"] = "Луна над долиной взошла, Освещая ночные джунгли, Где воины сошлись на зов Защищать свой народ и святыни. Луна над долиной взошла, Раздаются крики битвы, И кровь ручьями струится, Погибают враги и побратимы.",
    ["0c0ce4b6"] = false,
    ["0c6686af"] = "Когда проклятие демонов было снято, Орда превратилась из безжалостной военной машины в относительно свободный союз, направленный не столько на захват новых земель, сколько на жизнь и процветание. Тралл и его орки предвкушали начало новой мирной эры, получая помощь от благородных тауренов и хитрых троллей из племени Чёрного Копья.",
    ["0c85c3c0"] = "Если бы я знал, что произойдёт, я бы отрезал свою собственную руку, лишь бы не вытаскивать этот кусок дерева, покрытый рунами. Как сильно я жалею об этом! Я всегда думал, что сожаления – привилегия старости. Теперь я знаю, что не старость, а отчаяние надевает на нас мантию из сожалений, не способную и не желающую спадать с плеч, сгорбленных страданием. Но достаточно стенать, как какой-нибудь недоделанный поэт. Я должен продолжать свои хроники...",
    ["0c8a2a68"] = "Ещё до дней, которые мы помним, Мать-Земля своим дыханием создала золотые туманы рассвета. Там где эти янтарные облака коснулись земли, появились бесконечные пшеничные и ячменные поля. Это была чаша её творений – великая чаша жизни и надежды.",
    ["0c95658e"] = "Северная комбинация кристаллов Есть два возможных эффекта: наносящий урон и нейтрализующий его. КРИСТАЛЬНЫЙ ЗАРЯД: требует жёлтых и красных кристаллов. Провоцирует сильный взрыв. КРИСТАЛЬНОЕ ВОССТАНОВЛЕНИЕ: требует жёлтых и зелёных кристаллов. Наделяет вас целительной аурой.",
    ["0c9aee3d"] = "Гриш, твоя просьба об отпуске удовлетворена. Посылаю тебе на смену таурена-воина, чтобы он занял твой пост, пока ты будешь проводить время с семьёй. Через неделю доложи о возвращении! -Землепряд Маггран",
    ["0cb83855"] = "Единственными, кто внушал им тревогу, были могущественные древние драконы. Хотя эти большие змееподобные существа часто жили отшельниками, они всегда старались охранять известные им земли от возможной угрозы. Ночные эльфы решили, что драконы провозгласили себя защитниками мира и что их вместе с их секретами лучше не трогать.",
    ["0cf501d2"] = "Брат, я надеюсь, ты получил эту руну. Хочу сообщить тебе, что я в Старой Наковальне, что в Холодной долине. Я знаю, как важно для нас держаться вместе, особенно в такое неспокойное время. Загляни ко мне, когда будет свободное время. -Сольм Харгрин, наставник разбойников",
    ["0d3cf4b2"] = "Немного хорошего белокаменного дуба – прежде чем шахты под Луноречьем в Западном Крае были захвачены, в них было полно такой древесины. Её использовали для производства наиболее важных решёток и инструментов из-за её жаростойкости и сопротивляемости нагрузкам. Дуб завезли туда откуда-то из-за моря. Эта редкая древесина достаточно прочна, чтобы использовать её при создании твоего оружия. Если хотя бы немного её осталось в шахтах, то она найдётся у гоблинских резчиков по дереву.",
    ["0d7d5a01"] = "После долгих лет странствий высшие эльфы, наконец, нашли земли, напоминавшие Калимдор. В глуши северных лесов они основали королевство Кель'Талас и поклялись создать могущественную империю, которая будет во всём превосходить цивилизацию их собратьев, калдорай. К сожалению, эльфы вскоре узнали, что основали Кель'Талас на развалинах древнего города троллей, который те до сих пор считали священным. Тролли почти сразу же начали атаковать эльфийские поселения.",
    ["0d91990a"] = "Глава третья: ЗАПАДНЫЙ ПИЛОН. Западный пилон принимает красные, зелёные и синие кристаллы. Пилон фокусирует энергию, которая создаётся при использовании красных кристаллов в качестве основного источника энергии.",
    ["0d984456"] = "Глава три: ЗАПАДНЫЙ ПИЛОН. Западный пилон принимает красные, зелёные и синие кристаллы. Пилон фокусирует энергию, которая создаётся при использовании красных кристаллов в качестве основного источника энергии.",
    ["0da34f7e"] = "Приближённые слуги Азшары, которых она называла Кель'дорай или высокорождёнными, выполняли каждое её желание и считали себя выше своих собратьев. И хотя королеву Азшару одинаково любили все её подданные, ревнивые массы эльфов втайне ненавидели высокорождённых. Разделяя стремление жрецов познать тайны Источника Вечности, Азшара приказала мудрецам из числа Высокорождённых проникнуть в его секреты и раскрыть миру его истинное назначение.",
    ["0dbbd136"] = "От капитана Крассена порча перекинулась и на других защитников Дарроушира, которые после этого предавали и убивали своих бывших союзников. Потом они вошли в поселение и перерезали всех, кто укрылся в домах. Остатки армии Плети вместе с чёрной тенью Редпата покинули разорённое поселение и ворвались в Лордерон, неся с собой боль и смерть Второй войны.",
    ["0dd4980c"] = "Для немедленного распространения среди всех членов Сумеречного Молота. В связи с текущим положением дел в Силитусе, всякое распространение текстов Истинно Верующего отныне должно проводиться в сопровождении не менее чем четырёх вооружённых бойцов Сумеречного Молота. Все, уличённые в нарушении этого нового приказа, будут без промедления наказаны. -Д'Сак Сумеречный Владыка.",
    ["0de1feba"] = "Вступление, продолжение. Жаровню нужно использовать так же, как и Жаровню Призыва. Просто помести её в любом из пяти мест с привидениями, и в ней пробудятся духи мертвецов. Думаю, тебе будет интересно знать, что Знамя Вызова можно также использовать на арене в глубинах Чёрной горы. Преподай Телдрену и этим болванам хороший урок, когда будешь там. Если тебя это заинтересовало, читай дальше.",
    ["0e029920"] = false,
    ["0e66dfe2"] = "Рука Дагуна. Дагун – существо из глубины, которому поклоняются мурлоки в Пылевых топях. Они заманивают его на поверхность при помощи особенных морских водорослей, зачарованных их шаманами. Найди мурлоков, собери их зачарованные водоросли, затем помести их на Алтарь Мурлоков. Дагун придёт, когда будешь ждать его. Мне нужна эта рука.",
    ["0e8c5eec"] = "В память о моём дорогом учителе, Горацио М. Монтгомери, докторе медицины, целителе, учителе, друге. Пятьдесят би-ти-эф-ти – двадцать пять эй-ти-эф-ти \"Мир полон боли и тягот. Наша задача как целителей, НЕТ – мужчин или женщин, отдавших себя медицине, очистить его от всех болезней.\" - Почётный работник медицины, доктор медицины, доктор философии, доктор юридических наук, Великий Фермер, Экстраординарный Танцор, Друг Животных",
    ["0ea393cc"] = false,
    ["0ec17625"] = "Малигос: Малигос известен как Управитель магии или Заклинатель. Его естественное обличье не типично для драконов, и говорят, что он может изменять свой внешний вид по желанию. Его редко видят после ухода далеко на север, а если и видят, то чаще всего в образе насекомоподобного создания, но, принимая форму драконов, он и его сородичи отливают различными оттенками синего цвета.",
    ["0f3cb32d"] = "Малигос: Малигос известен как Управитель или хранитель магии. Его естественное обличье не типично для драконов, и говорят, что он может изменять свой внешний вид по желанию. Его редко видят после ухода далеко на север, а если и видят, то чаще всего в образе насекомоподобного создания, но, принимая форму драконов, он и его сородичи отливают различными оттенками синего цвета.",
    ["0fc6a728"] = "Его старый друг Дуротан, вернувшийся из изгнания, напомнил ему о предательстве Гул'дана. По приказу мстительного Гул'дана Дуротан и вся его семья были убиты, в живых оставили лишь его юного сына. Но Молот Рока не знал о том, что сын Дуротана попал в плен к Адэласу Блэкмуру, одному из командиров армии людей, и стал его рабом. Именно этому юному орку суждено было стать величайшим вождём в истории своего народа.",
    ["0fdab607"] = "Судьба Мардука Чёрного. Мардук пережил Вторую войну, сея смерть и страдания своим руническим мечом. Хотя Мардук жив и сейчас, его меч был утерян в битве при Перекрёстке Корина. Храбрый капитан дворфов разбил его своим зачарованным щитом, обратив Мардука в бегство и обеспечив победу Альянсу. Сломанный меч погрузился в землю и осквернил её, образовав впадину, которую в наши дни называют Чумным Шрамом.",
    ["0ff8f3a9"] = "Любезная Гелиана! Жаль вас разочаровывать, но я, Варгус, всё ещё пребываю в добром здравии. Мне надоело быть посмешищем для всех и бродить по деревням в этих шутовских доспехах. Теперь нам приказали отправиться в Андорал за зерном или ещё за чем-то там. Скажите, пожалуйста, какое мне дело до зерна в Андорале? Да вся эта служба в армии – просто бред сумасшедшего. Будьте уверены, тётя Гелиана, что я вернусь, и ваше наследство будет моим; даже если я буду истекать кровью и умирать от голода, моя злоба не даст мне умереть. Варгус",
    ["10453677"] = "Джин'Зил, Прошло немало времени, но я подумал, что ты захочешь узнать, что были убиты последние представители Кровавого Пера. Но не благодари меня, убил человек, доставивший тебе это письмо. Если хочешь, я могу прислать тебе их головы, после того как караван пройдёт через Степи. Я знаю, что ты любишь использовать такие вещи в своей магии вуду. Береги себя, старый друг. -Дарсок Быстрый Нож",
    ["107339c9"] = "Некоторое время назад в штабе Лиги Исследователей в Стальгорне нам читал лекцию главный археолог Седой Ус. Старикан упоминал такое божество, почитаемое странными эльфами Дарнаса за его, по слухам, бескорыстную натуру... Ба! Один момент. Я слышу хрюканье за моей палаткой. Наверняка это просто щетинистые вепри пытаются добраться до моего запаса яблок...",
    ["10b514f6"] = "Объединившиеся эльфийские и человеческие армии вступили в схватку с огромной армией троллей у подножья Альтеракских гор. Битва продолжалась много дней, но неослабевавшая армия Аратора не уставала и не отступала под натиском троллей. Эльфийские властители решили, что пришло время ниспослать силы магии на врага.",
    ["10b520d9"] = "Секрет успеха жреца – в его связи с миром. Мудрость и сострадание позволят тебе помогать тем, кто действительно в этом нуждается, а поспешность и необдуманные решения причинят только вред. Но к этому ты должен прийти сам. Когда ты это осознаешь, тебе понадобятся новые способности и заклинания. Вот с этим я могу тебе помочь. Приходи в библиотечное крыло Аббатства Североземья. -Жрица Анетта, наставница жрецов",
    ["10d17b4d"] = "Война бушевала на просторах Каз Модана, Лордерона и самого Азерота. Свирепая Орда сожгла дотла пограничные земли Кель'Таласа, после чего эльфы наконец-таки присоединились к Альянсу. Война разрушила и разорила некогда процветавшие города Лордерона. Несмотря на превосходящие силы врага, Лотар и его союзники сумели сдержать наступление Орды.",
    ["110e1822"] = "Изера Дремлющая тоже зачаровала Древо Жизни, связав его со своим миром, астральным измерением, известным как Изумрудный Сон. Этот огромный мир, населённый духами, не подчинялся законам физического мира. Из своего Сна Изера могла управлять жизнью природы и развитием всего остального мира.",
    ["114d27c9"] = "Объединённые армии Стальгорна и Грим Батола отправились на юг с целью уничтожить Тауриссана и клан Чёрного Железа раз и навсегда. Они не успели далеко уйти, когда гнев Тауриссана вызвал заклинание, приведшее к катаклизму. Желая призвать сверхъестественное существо, которое поможет ему победить, Тауриссан призвал древние силы, спавшие в глубинах мира, и к своему ужасу он обнаружил, что появившееся существо было ужаснее самых страшных ночных кошмаров.",
    ["11991a3a"] = "Спустя несколько дней после того, как я начал прятаться в сарае, Свен отправился со своей фермы в Темнолесье. Он поцеловал жену и улыбнулся детям, и обещал вскоре вернуться с игрушками и сладостями. Несчастный человек. То был последний раз, когда он видел свою семью живой. По крайней мере, они расстались счастливыми. И по крайней мере, его жена умерла первой, и ей не пришлось смотреть, как убивали её детей. Но этот малый жест благоволения судьбы мне ничем не помог. Я видел всё, что случилось, и это преследует меня в моих кошмарах.",
    ["119bd7b1"] = "Затем Нер'зул создал артефакты, чтобы распространить чуму среди народов Лордерона. Он отдал их Кел'Тузаду и повелел волшебнику разнести их по земле. А служителям своего культа приказал защищать артефакты любой ценой.",
    ["11cc3b12"] = "Из древнего подземного королевства Азжол-Неруб, основанного расой зловещих пауков-гуманоидов, был послан элитный отряд воинов. Они должны были напасть на Ледяную Корону и остановить помешанного на абсолютном господстве Короля-лича. К своему разочарованию, Нер'зул обнаружил, что воины Неруба невосприимчивы не только к чуме, но и к его телепатии.",
    ["11d64d3c"] = "Когда измождённые ночные эльфы высадились на берег, они увидели, что священная гора Хиджал не пострадала при взрыве. В поисках места для нового дома Малфурион и остальные эльфы поднялись на горные склоны и остановились на овеваемой всеми ветрами вершине. Спустившись в поросшую лесом низину между двумя огромными пиками, они обнаружили там маленькое тихое озеро и, к своему ужасу, поняли, что воды его светятся магией.",
    ["1217ec81"] = "Снег ослепляет… Племя нужно защитить. Дать им силу. Быть сильным. Не знаю…",
    ["12411654"] = "Эгвин никогда так и не узнала, что она поступила именно так, как хотел Саргерас. Она неосознанно подписала приговор смертному миру, так как Саргерас во время своей физической смерти вселился духом в ослабленное тело Эгвин. Без ведома юной Хранительницы Саргерас оставался скрытым в тёмных уголках её души многие годы.",
    ["12417e11"] = false,
    ["12bc35e8"] = "В поисках правды о своих предках Тралл отправился на север, где обнаружил легендарный клан Северного Волка. Там ему рассказали, как Гул'дан отправил Северного Волка в изгнание в самом начале Первой войны. Тралл также узнал, что он – сын и наследник храброго орка Дуротана, вождя Северного Волка, погибшего на этих пустынных просторах почти двадцать лет назад.",
    ["12e55f9b"] = "Был создан огромный заслон, питаемый энергией как ночных эльфов, так и драконов, – магический барьер, которому под силу было удержать силитидов и их повелителей в пределах стен Ан'Киража и выдерживать напор снаружи. Ан'Кираж сам стал тюрьмой для врагов.",
    ["12faddf2"] = "Мы спрятались в укромной пещере; похоже, это достаточно безопасное место. Но мы всё равно находимся в ловушке до тех пор, пока не прибудет подкрепление. Вельгар пытается продолжать работу, но, похоже, он всё ещё слишком напуган. Мы находимся в тяжёлом положении, Таррел. Пожалуйста, поторопи Длинную Косу со сбором дополнительных сил. Я всё также сильно тебя люблю, даже в эти ужасные времена. Меррин",
    ["1301758a"] = "Когда Иллидан, сопровождаемый нагами, отправился в путь, его начала преследовать Майев Песнь Теней. Майев была тюремным стражником Иллидана десять тысяч лет и страстно желала вернуть его в заточение. Но Иллидан, перехитрив Майев и её Смотрящих, сумел завладеть Оком Саргераса. Найдя могущественное Око, Иллидан отправился в бывший город волшебников – Даларан.",
    ["1361dbce"] = "Ни один из моих тестов не пролил свет на загадку происхождения кровавого камня. В то время единственной загадкой, что мне удалось разгадать, было то, что кровавый камень – ни живое, ни мёртвое существо! Но тогда, на грани поражения, я сделала прорыв. В моём последнем тесте не последнюю роль сыграла стеклянная колба с отколотым горлышком. Когда я закончила свой тест, опять ничего не обнаружив, я убирала инструменты со своего рабочего стола и порезалась об острый край колбы.",
    ["13620e52"] = "Один. Добыть один или восемь человек Два. Бить человек сильно Три. Бить человек ещё Четыре. Класть его в огонь Пять. Есть человек",
    ["139e1638"] = "Тем временем я посылаю лейтенанта Элверолда в экспедицию вокруг континента Калимдор. После того как его силы завершат экспедицию, им следует воссоединиться с нашими силами в крепости Тирагард. По расчётам, экспедиция лейтенанта Элверолда должна занять довольно много времени. Новый материк выглядит обширным и опасным. Но если со мной или Бенедиктом стрясётся какая-либо беда, войска Элверолда сумеют снова захватить крепость. Мы будем посылать одну экспедицию за другой, пока Тирагард не станет нашим! --Адмирал Праудмур",
    ["13c72669"] = "Озеро, которое позже назовут Источником Вечности, было подлинным средоточием магических и природных сил мира. Черпая энергию из Великой Запредельной Тьмы, Источник был как мистический ключ, питающий этой энергией мир и поддерживающий жизнь во всём её удивительном многообразии. Со временем до берегов завораживающего колдовского озера добралось примитивное племя гуманоидов, ведущих ночной образ жизни.",
    ["13ccc917"] = "Этим чудищем был самец тигра Тернистой долины. Прежде чем мне удалось взвести винтовку, Эрлгедин поднял свой арбалет и выстрелил в зверя. Стрела ушла немного в сторону и вонзилась в левый бок тигра. Зверь попытался убежать, но его рана была слишком глубокой. Он сумел сделать лишь несколько шагов, а затем его настиг метательный топор Барнила.",
    ["13e1ddf5"] = "Для немедленного распространения среди всех членов Сумеречного Молота. Поиски предателя Ортелла продвигаются наилучшим образом. Наши разведчики узнали, что он скрывается в лабиринте пещер Западного Края. Предательство Ортелла прощать нельзя, а его побег ставит под угрозу всю нашу организацию. Любой, кто станет утаивать сведения о местонахождении Ортелла, будет должным образом наказан. -Эверан Сумеречный Владыка",
    ["1415d36a"] = false,
    ["146a9e66"] = "Демоны-чернокнижники призвали инферналов, которые обрушились на изящные шпили калимдорских храмов будто адские пылающие метеоры. Армия кровожадных убийц, называемых стражниками ужаса, прошла по калимдорским полям, уничтожая всё живое на своём пути. Демонические гончие Скверны наводнили сельскую местность. Разумеется, храбрые воины-калдорай пытались защитить свои родные земли, но они не могли сдержать всю ярость Пылающего Легиона, и им пришлось шаг за шагом отступать.",
    ["14769c08"] = "Когда последние очаги войны были ликвидированы, Альянс предпринял жёсткие меры для предотвращения угрозы со стороны орков. На юге Лордерона были построены несколько лагерей специально для пленных орков. Лагеря, охраняемые паладинами и опытными воинами Альянса, успешно справились со своей задачей.",
    ["14b30b07"] = "Ажек и сэр Эрлгедин вскинули своё оружие, прикрывая меня с боков, спиной к морю. Барнил обречённо вздохнул и обнажил свой топор. Кнутохвосты были практически рядом с нами. Их уверенные шаги замедлились. Они крадучись подбирались к своим жертвам, зная, что загнали нас в ловушку.",
    ["14b69adf"] = "Дорогая Иветта, я доверяю это письмо нашему самому быстрому бегуну. Я молюсь, чтобы он смог пробраться сквозь кольцо окруживших нас сил. И молюсь, что ты прочитаешь мои слова, поскольку это последнее, что ты услышишь от меня. Единственное, что меня успокаивает в эти мрачные дни, – это чувство облегчения от того, что я знаю: ты не разделишь мою участь.",
    ["14c95a45"] = "Судьба Мардука Чёрного Мардук пережил Вторую войну, сея смерть и страдания своим рунным мечом. Хотя Мардук жив и сейчас, его меч был утерян в битве при Перекрёстке Корина. Храбрый капитан дворфов разбил его своим зачарованным щитом, обратив Мардука в бегство и обеспечив победу Альянсу. Сломанный меч погрузился в землю и осквернил её, образовав впадину, которую в наши дни называют Чумным Шрамом.",
    ["14f4891d"] = "Несса, рад был получить от тебя весточку. Коллекция костей и чешуек, которую ты послала мне, превосходна. Никогда ещё я не видел за пределами материка рыб такого размера. Должно быть, рыбаки деревни Руттеран с лёгкостью выуживают по тонне за день! Я хоть и завидую размеру их добычи, но всё же немного обеспокоен. Может ли наше новое древо Жизни сделать так, чтобы наша рыба дорастала до таких же размеров? И если может, то чего ещё следует ожидать? Это стоит обдумать. — Лайрд",
    ["15047cee"] = "Благородные кланы орков странствовали по необъятным степям и охотились – больше ради развлечения, а дренеи начинали возводить города среди скал и горных вершин. Кил'джеден решил, что, приложив немного усилий, из жителей Дренора можно сделать превосходных солдат для Пылающего Легиона.",
    ["1511d9f0"] = "Пленные орки жаждали сражений, но начальники лагерей, обосновавшиеся в крепости-тюрьме Дарнхольде, поддерживали среди них видимость порядка и спокойствия.",
    ["154d9075"] = "Сара, моя любовь к тебе бессмертна, она словно связывает меня мощными путами, которые не разорвало бы ничто, кроме Всемогущества. А любовь к королевству подхватывает меня, словно ураган, и необоримо влечёт меня вместе со всеми этими цепями на поле боя.",
    ["15799408"] = "Рассказ о добродетели его Со смертью рыцаря не будет завершён. Его мы чтим и воздаём хвалу! Пусть Утер в славе почиет и в Свете!",
    ["158d33e3"] = "Иллидан потревожил своих старых должников высокорождённых и выманил из подводных убежищ змееподобных существ – наг. Наги во главе с леди Вайш помогли Иллидану добраться до Таинственных островов, где, по слухам, находилась Гробница Саргераса.",
    ["15eaaca8"] = "Зверь, который правит этим островом, действительно ужасен. Другие существа трепещут перед ним – и небогривые гориллы, и жагуары. Его рёв постоянно звучит у меня в ушах и заставляет съёживаться от страха. Эти существа наверняка остановят любого, кто придёт на остров. Но придётся довериться воле предков...",
    ["160154b0"] = "ДИАГРАММА ВОСТОЧНОГО ПИЛОНА",
    ["1609f3a1"] = "Глава два – Башни-близнецы Учти: Вандар Грозовая Вершина – враг умный и хитрый. Разрушив передовые укрепления, надо помнить о том, что впереди ещё вторая линия обороны. Это – башни-близнецы Каменный Очаг и Ледяное Крыло, из которых командиры управляют стражниками Грозовой Вершины вне Дун Болдара и патрулями Грозовой Вершины.",
    ["1611f36f"] = "Наследники Арати, оставшиеся в ветшающих стенах древнего Строма, решили отправиться на юг, за каменистые горы Каз Модана. Их странствия длились не один год, но наконец путешествие окончилось, и они поселились в северном регионе континента, который позднее назовут Азерот. В плодородной долине они основали королевство Штормград, быстро ставшее независимой силой.",
    ["163afccc"] = "Анналы Дарроушира Поселение Дарроушир, названное в честь озёра Дарроумир, находится к востоку от этого озера на южной границе Лордерона. Известное своими скромными, но трудолюбивыми обитателями, это поселение было ничем не примечательно, пока не началась Вторая война. Герои появляются во время войны, а после неё их забывают.",
    ["168bae3f"] = "К тому времени, как безумие Саргераса поглотило остатки его некогда отважного духа, он уверовал в то, что титаны сами несут ответственность за ошибки своих созданий. Решив, в конечном счёте, уничтожить плоды их трудов во всей вселенной, он захотел создать несокрушимую армию, которая огнём и мечом пройдёт по вселенной.",
    ["16e69e3d"] = "Нам, \"Шмыг Инк.\", неприятно говорить о том, что мы получили несколько жалоб на некоторых жадных охотников за корнями, мало заботящихся о своих милых питомцах и отправляющих их в тёмные, опасные места на поиски корней. Мы не станем мириться с такими безответственными хозяевами, но, желая удовлетворить пожелания клиента, мы выдаём гарантию на каждого проданного шмыгуноса, позволяющую новым владельцам вернуть покупку или получить нового зверька взамен потерянного. Удачной охоты!",
    ["170a3f37"] = "Спустя десять тысяч лет могучий демон Архимонд вновь ступил на Азерот. Но в Даларане их путешествие не закончилось. По приказу самого Кил'джедена Архимонд и его демоны последовали за Плетью в Калимдор, чтобы уничтожить Нордрассил, Древо Жизни.",
    ["17349979"] = "КОРМЛЕНИЕ И УХОД: Мы хотим обеспечить вас всем необходимым для ухода за питомцем. Наши клиенты ожидают от «Шмыг Инкорпорейтед» именно такого уровня обслуживания, и мы с ними согласны! С этой целью мы разработали крепкие ящики для шмыгуносов, чтобы вы могли содержать питомца в безопасности и вне доступа света. Для вашего удобства в каждом ящике находится отделение для корма, пронизанное чарующим ароматом клубней синелиста (любимого лакомства шмыгуносов)!",
    ["17361e69"] = "Наш мир наполнен историей. Историей народов, новых и старых. Историей войн, тех, что давно угасли, и тех, что ещё тлеют. Историей богов юных, что приходят вниз с небес. Историей богов старых, что дремлют в земле. Именно о них мой рассказ, о Древних Богах. О тех, кто жил и бушевал по всему Азероту, когда мир был ещё молод.",
    ["17365ef6"] = "Пантеон разрушил цитадель Древних Богов и заточил пятерых злых богов глубоко в недрах мира. Элементали, которые не могли сдерживать своё буйство без власти Древних богов, были изгнаны в бездну миров, где они остались сражаться друг с другом на веки вечные. С исчезновением элементалей природа смягчилась, и в мире наступила полная гармония. Титаны увидели, что с угрозой покончено, и принялись за работу.",
    ["1787b0ae"] = "В любом случае, по-видимому, его действия сопровождались определённым успехом. Хотел ли он потренироваться на фурболгах перед тем, как заняться моим народом? Было ли у фурболгов что-то, чем он желал завладеть? Кто знает? Используя созданную им вещь (какой-то жезл или посох), он попытался проникнуть в племена фурболгов Ясеневого леса. В какой-то момент – и именно здесь многое всё ещё не ясно – его обнаружили фурболги когда он пытался натравить их",
    ["17be48f2"] = "Пелвер Вмятина Тёмный хранитель Пелвер – наш наиболее почётный последователь. Он хранит ключ гораздо дольше других, и это стоило ему многого. Когда его ноша взывает к нему, он содержится под стражей в Жилом квартале. Мы склоняемся пред его жертвой, и он останется в наших сердцах на многие годы... после того как его поглотит тьма.",
    ["17c770b2"] = "Хотя битвы с людьми заканчивались довольно быстро, обе расы успели выяснить сильные и слабые стороны соперников. Ллейну и Лотару не удавалось получить точные сведения о численности орков, и они могли лишь догадываться о том, насколько могуч был их противник.",
    ["17e24057"] = "За то, что ты нашёл для меня бутылочку старого доброго виски, я скажу, где находится сокровище! Иди вдоль берега, двигаясь на запад от бутылки. Дойдёшь до воды – плыви дальше на запад. Через некоторое время ты приплывёшь на остров, где и найдёшь мой сундук с сокровищами!",
    ["17f3eac0"] = "С тяжёлым сердцем, обуянный жаждой мести, могучий Фэндрал Олений Шлем усилил натиск. Поражение в Силитусе стало бы великой бедой для ночных эльфов и, вполне возможно, для всего мира. Битва кипела несколько месяцев. Весь Силитус был захвачен киражами. Оленьего Шлема и его армию отбросили к Танарису. Видя, как уменьшилось его войско и сколько невинных жертв погибло, Фэндрал Олений Шлем утратил ту самонадеянность, что двигала им.",
    ["186112c3"] = "Большинство этих встреч с демонами были отдельными случаями, и правившие магократы делали всё, что могли, чтобы хранить такие происшествия в тайне от народа. Самые могущественные маги были посланы на борьбу с неуловимыми демонами, но нередко они обнаруживали, что безнадёжно уступают одиноким шпионам могучего Легиона.",
    ["1879666e"] = "*Цитаты* \"Ты хочешь узнать о гоблинском инженерном деле? Спроси об этом одного из их лучших и талантливейших инженеров – мне кажется, его имя Набби Толстопал. Хочешь знать, почему его так зовут? Таково гоблинское инженерное дело.\" -- Ринго Трагедикс, гномский инженер. *\"Говори, что хочешь, о нас, гоблинах, но я скажу тебе вот что: У НАС ЕСТЬ ВЗРЫВЧАТКА!\" - Блямс Динамиттер, гоблинский бомбардир*",
    ["18871cb6"] = "В эти месяцы у меня было достаточно времени для раздумий о моих старых верованиях и фанатизме. Альянс? Орда? Добро? Зло? Значение этих слов, когда-то таких простых, теперь расплывалось перед моим взором, устремлённым на бескрайнее море. Теперь я знаю, в чём причина. Эти бананы следят за мной. Сидят высоко и недоброжелательно следят за мной своими глазками. И когда последний раз я пытался съесть один из них, он чуть не задушил меня! Я почти слышал его крик, когда я размазал его, наполовину откушенного, по камням. Это – война, и я её выиграю.",
    ["1903ff99"] = "Магократы предложили решение – дать отдельным смертным воинам огромную силу, чтобы они использовали её для вечной тайной борьбы с Легионом. Они настаивали на том, чтобы большая часть человечества никогда не узнала о Хранителях или угрозе нападения Легиона, поскольку иначе воцарится ужас и хаос. Эльфы согласились с предложением и основали тайное общество, наблюдавшее за отбором Хранителей и помогавшее сдерживать хаос.",
    ["191085ea"] = "Друг на друга. Эльфы на месте фурболгов очень разозлились бы, но те отреагировали гораздо сильнее и убили Дартола. Фурболги, по крайней мере в то время, не были теми порчеными существами, которыми они стали. Они были всё ещё рациональными и умными – их отношения с нашим народом были дружественными. Я надеюсь, что, если я смогу воссоздать жезл с помощью дриады по имени Шаэл'дрин, я смогу использовать его силу, чтобы помочь нашему народу... и фурболгам.",
    ["19180e2d"] = "Они были первыми хозяевами мира и правили железной рукой. И хотя теперь они закованы в цепи и спят, их слуги ещё на свободе, а нам, жалким смертным, с мощью этих слуг не совладать. Те, кто пытался это сделать, изничтожены. Те же, кто знает своё место, кто склоняет колени в мольбе перед прислужниками Древних Богов, кто без раздумий жертвует им душу и разум... лишь они обретут их милость.",
    ["1928d0de"] = "День два Мы долго спорили о том, где следует возводить Ветровой Камень. Даже мудрейшие из нас не могут сказать наверняка, что за место описано в древнем пророчестве. Я примкнул к тем, кто считает, что строить надо на севере, и время несомненно докажет нашу правоту. Доводы, что энергетические линии якобы пересекаются там под плохим углом, наивны и глупы. Мы уже собираем с великой поспешностью всё, что нужно для строительства.",
    ["1937cfdd"] = "Но он был прав. Мы обречены. Линия семьи Агамондов прервётся. Несмотря на то что я всё ещё жив, скоро я погибну. Я не боюсь, и не сожалею о том, что остался со своей семьёй. Но мои последние мысли – о тебе. Продолжай жить, моя возлюбленная Иветта, и я обрету покой. Тармен",
    ["193cb88b"] = "Лорд Сильноплечий - Возглавляемое Эдвином ван Клифом братство Каменщиков состояло из лучших строителей среди людей. Каменщики помогали восстанавливать Штормград, разрушенный до основания орками во время Первой войны. ван Клиф и его товарищи были непревзойдёнными зодчими. Их вкус и чутьё отразились в величии Собора Света и Крепости Штормграда.",
    ["19dd955d"] = "РЯДОВОЙ И СЕРЖАНТСКИЙ СОСТАВ ОРДЫ. Высший сержант. Старший сержант. Рубака. Разведчик.",
    ["1a512c85"] = "Корень жизни: Он встречается в природе, а также может быть извлечён из тварей Сухой Лозы в Пылевых топях. Его сила будет необходима для привлечения жизненной эссенции Циклониана в этот мир.",
    ["1a825f54"] = "Эпилог \"Сдобрить сердцевину артишока маслом с чесноком и майонезом. Запивать блюдо лучше крепким, выдержанным элем.\" Теперь Дрек'Тар совсем один, если не считать двух болванов-подопечных по обе руки. Захвати Приют Северного Волка и убей Дрек'Тара. Когда Генерал падёт, его земли наконец-то перейдут к их истинному владельцу – Грозовой Вершине.",
    ["1ab146f2"] = "Судьба Хоргуса Опустошителя Хоргус Опустошитель погиб в битве за Дарроушир. Но зло, которое он нёс в себе, не умерло вместе с ним. Победившие воины Плети отрезали его голову и забрали её с собой, чтобы наводить ужас на всё живое. Через несколько дней отряд Плети, у которого была голова Хоргуса, был уничтожен паладинами Серебряной Длани, а саму голову утопили в озере Чернолесья.",
    ["1b03d204"] = "Я вёл отряд по направлению к морю в надежде, что вода остановит ящеров. Но в спешке мы зашли слишком далеко на север, на возвышенность. Исправлять ошибку было уже поздно. И вина была в этом моя. Мы остановились на краю отвесной скалы, а ящеры были уже в нескольких шагах от нас.",
    ["1b27aeee"] = "День пять: Торсен был сегодня очень взволнован. Кого бы или что бы он ни встретил на своей вчерашней прогулке, это его, должно быть, испугало. Мне думалось, что с ним говорили наши агенты, но на мой вопрос, куда он ходил, Торсен ничего не ответил. Он считает, что я его друг, и думает, будто мне безопаснее не знать его тайны. Он служит не тем, кому следовало бы, но его преданность крепка. Когда он вернётся к нам, он станет ценным приобретением для Курцена.",
    ["1b3a077f"] = "Бедный Гералат бледен, точно смерть. Его с каждой минутой лихорадит всё сильнее. А свинолюди без устали готовятся к какому-то крупному военному походу. Боюсь, что если я не попытаюсь вскоре бежать, мне будет уготована та же судьба, что и моему сотоварищу эльфу. Я планирую тайком пробраться наружу, когда свинолюди в очередной раз уйдут на охоту. Стражники, охраняющие меня, ленивы и то и дело спят на посту.",
    ["1b4724bf"] = "Одни боятся нас больше, чем драконов. Другие завидуют нам больше, чем самым искусным кузнецам. Третьи превозносят нас за подвиги на поле боя. Четвёртые преклоняются перед нашей верой. А пятым просто обидно, что мы можем с лёгкостью перепить любого из них! Но помни, герой, Что на самом деле мы – величайшие защитники Азерота. Божественный Свет даёт нам тем больше силы, чем больше мы служим ему. Я расскажу тебе больше, когда ты освоишься. Ищи меня в Старой Наковальне над долиной. -Бромос Груммнер, наставник паладинов",
    ["1b4a5f0a"] = "Лайо, мы получили щедрую помощь от этого доброго странника. Я направил его к тебе в Силитус. Используй его способности во благо себе и раскрой все нужные тебе тайны. Круг с нетерпением ждёт новостей о твоих успехах. Да убережёт тебя Кенарий… Рабин",
    ["1b625972"] = "После очередного неверного шага Барнила Эрлгедин положил свою тяжёлую руку ему на плечо. Мы с Ажек переглянулись, уверенные, что он решил-таки напомнить Барнилу о необходимости соблюдать осторожность. Но вместо этого Эрлгедин кивнул головой в сторону лежащего неподалёку дерева. Оттуда на нас пристально смотрели два чёрных глаза, а под ними была пасть, полная острых зубов.",
    ["1b6f0ef6"] = "Битва продолжалась, и капитан Редпат со своим ополчением твёрдо держал оборону. Они бы победили, если бы не магия рыцаря смерти Мардука Чёрного. В самом разгаре битвы Мардук приблизился к Редпату и своей чёрной магией растерзал его душу, обратив отважного капитана в злобную тень.",
    ["1b748dd3"] = "Торадин, не доверявший любой магии, согласился помочь эльфам исключительно по необходимости. Практически немедленно эльфийские волшебники прибыли в Аратор и начали обучать группу людей магии.",
    ["1b750542"] = "ДИАГРАММА ВОСТОЧНОГО ПИЛОНА",
    ["1b76b56f"] = "Планируя нанести удар Альянсу силами своей армии и могучих красных драконов, Некрос надеялся вновь объединить Орду и продолжить завоевание Азерота. Но его надеждам не суждено было сбыться: небольшая группа бойцов сопротивления, возглавляемая магом Ронином, смогла уничтожить Душу Демона и освободить королеву драконов.",
    ["1b82e395"] = "Мы отправились на запад через дикие непроходимые джунгли. В поисках добычи мы медленно, но верно прокладывали себе путь сквозь густую растительность. К нашему сожалению, утром всё было тихо. Даже ветер не шумел в кронах деревьев. К полудню мы начали волноваться. Шаги Барнила уже не были столь осторожными и тихими, как раньше. Теперь он неуклюже переваливался с ноги на ногу, с треском ломая упавшие на землю сухие ветки.",
    ["1c18c8a0"] = "Я медленно шагнул вперёд, держа ружьё наготове. Я привёл этих отважных охотников к гибели. И готов был погибнуть сам, защищая их. Ящеры-кнутохвосты известны своей свирепостью и неумолимой жаждой крови. Их было намного больше нас. Но я бы себе не простил, если бы позволил расправиться с собой и моими товарищами, не прикончив сначала несколько этих тварей!",
    ["1c2254af"] = "Отчёт о положении дел с троллями из племени Мерзлогривов в регионе Холодной долины. Подготовлен Грелином Белобородом, особым посланником Сената. Я потратил немало времени, наблюдая за деятельностью племени Мерзлогривов в Холодной долине, и полагаю, что они не представляют особой угрозы дворфским поселениям в этом районе. Более того, эту угрозу можно уничтожить даже без особой поддержки со стороны армии. Учитывая помощь горных пехотинцев, уже находящихся в",
    ["1c2743d1"] = "Лорд Сильноплечий -- Городской совет Озёр смиренно просит у вас военной помощи. В то время как я пишу эти строки, нас держат в осаде орки Чёрной Горы и гноллы из стаи Темношкуров, прислуживающие Морганту. Я бы никогда не попросил о помощи, но мы в тяжёлом положении. Мы ожидаем подкрепление из Штормграда, но пока оно прибудет, я прошу вас оказать нам поддержку. Падёт королевство – и все люди будут обречены. Мировой судья Соломон",
    ["1c749423"] = "Совет поступил мудро, назначив вас главой Недремлющего Аргуса, исполнителем их предначертаний в землях людей и дворфов. И для меня большая честь служить проводником вашей воли в Альтераке. Во имя Саргераса! Нагаз, Жрец Аргуса",
    ["1cc69bac"] = "Приветствую вас, Господин, Приношу свои извинения за то, как моё послание попало к вам. Тёмные маги в Альтераке сосредоточили все свои силы на выполнении поставленной задачи, и я был вынужден передать вам сообщение с этим гонцом – новобранцем из рядов наших новых \"союзников\". Однако я зашифровал послание самым тайным из наших шифром. Эта деревенщина не поймёт ни слова.",
    ["1cf4cd73"] = "Когда мир раскололся после взрыва Источника Вечности, это очень сильно задело земельников. Ошеломлённые болью самой земли, земельники сделались непохожи на самих себя и закрылись в каменных чертогах, где некогда были созданы. Ульдаман, Ульдум, Ульдуар… это имена древних городов титанов, где земельники впервые обрели свой облик. Погребённые в недрах мира, земельники спокойно отдыхали почти восемь тысяч лет.",
    ["1cf6df83"] = false,
    ["1d153c67"] = false,
    ["1da6ac2b"] = "Желая восстановить отношения и торговлю со своими собратьями, дворфы Стальгорна построили две огромные арки, называемые Мост Тандола, между Каз Моданом и Лордероном. Поддерживаемые обоюдной торговлей, два королевства процветали. После смерти Мадорана и Кардроса их сыновья вместе построили две большие статуи в честь своих отцов.",
    ["1dc1f511"] = "Изера: Изера Спящая представляет подсознание смертных. Она олицетворяет Изумрудный Сон... Она благоволит к искусствам и амбициям смертных народов, но в то же время считает, как и все её драконы, что настоящий мир – это лишь иллюзия. Изера – одно из самых могучих и грациозных созданий, которое только может узреть смертный.",
    ["1dd1bb4c"] = false,
    ["1ded0e3c"] = "Моему досточтимому королю: Не пристало скромной жене солдата подвергать сомнению действия великих военачальников, таких как вы. Битвы, бушующие в наших землях, ведутся, чтобы сохранить прекрасную жизнь, которую мы знаем и любим, – от прохладных вод озёра Лок Модан до острых заснеженных пиков Дун Морога.",
    ["1e45b263"] = "В центре континента титаны поместили озеро искрящейся энергии. Озеро, которое они назвали Источником Вечности, было источником жизни в мире. Его могущественная энергия питала корни мира и давала возможность жизни пустить побеги в его плодородной почве. Со временем травы, деревья, монстры и создания всех видов появились на первобытном континенте.",
    ["1e6013ca"] = "Зная, что Кил'джеден будет недоволен его неудавшейся попыткой разрушить Ледяной Трон, Иллидан бежал в безжизненный мир, называемый Запределье: последние остатки Дренора, бывшей родины орков. Там он хотел укрыться от гнева Кил'джедена и обдумать свои дальнейшие планы.",
    ["1e7f0358"] = "Упрямые эльфы, не желавшие отдавать свои новые владения, использовали магию, оставшуюся от Источника Вечности, и заставили свирепых троллей отступить. Под командой Дат'Ремара они сумели победить отряды Амани, которые десятикратно превосходили их числом. Некоторые эльфы, помнившие древние предупреждения калдорай, почувствовали, что использование магии может привлечь внимание изгнанного Пылающего Легиона.",
    ["1ef45b69"] = "Сотворение зверя: Чтобы создать ищейку Скверны, необходимо использовать выданную сферу Скверны. Примечания: Сотворённая ищейка Скверны сможет существовать в этом мире лишь тридцать минут. Сотворённая ищейка Скверны будет помогать лишь в поиске отложений азшарита. Сотворённая ищейка Скверны НЕ БУДЕТ делать следующее: фокусы, нападать на кого-либо, помогать в чём-либо, танцевать, уничтожать магических существ. Пожалуйста, переверните страницу...",
    ["1ef4f307"] = "Энтони Рэй Старк. Одна тысяча девятьсот шестьдесят один – две тысячи пять",
    ["1f1dd3ee"] = "Судьба Дейвила Лёгкого Горна Дейвил Лёгкий Горн погиб в битве за Дарроушир, но его храбрость вдохновляла воинов Альянса до самого окончания войны. Написанный им манускрипт паладина был найден армией Алого ордена. Теперь она хранится в ратуше Дольного Очага, где воины Алых черпают из неё силу и мудрость Дейвила.",
    ["1f374b7c"] = "Ценарион научил детей земли разговаривать с деревьями и травами. Шу'хало стали друидами и совершили множество чудес, приносящих земле здоровье. Многие поколения Шу'хало охотились вместе с Ценарионом и хранили землю от тёмных сил.",
    ["1f3ddf10"] = "Командир! Возвращайтесь в Оргриммар. Ваши войска несостоятельны. Следует пересмотреть наше положение на основании поступившей новой информации. Крупные силы Приверженцев Тени и огров. Демоны охраняют Тёмный портал. -Тралл, Вождь Орды",
    ["1f68bdaf"] = "Могущественный Архимонд также избрал для себя агентов. Призвав зловредных разрушителей и их жестокого предводителя, Маннорота Разрушителя, Архимонд надеялся создать военную элиту, которая искореняла бы всё живое.",
    ["1fa3e3d1"] = false,
    ["1fac7210"] = "Разъярённые драконы Алекстразы разрушили Грим Батол и сожгли большую часть орков Драконьей Пасти. Грандиозные планы Некросса рухнули; войска Альянса окружили уцелевших орков и заключили их в лагерь для военнопленных. Поражение Драконьей Пасти ознаменовало конец Орды и кровожадности орков.",
    ["2069de8e"] = "День один Наше странствие закончено. Мы наконец-то дошли до Силитуса, где и свяжемся с ними. Мы пришли сюда из самых разных мест, чтобы сообща свершить великое дело. Воздух весь наполнен предвкушениями. Завтра мы целиком посвятим себя строительству сооружения, которое позволит нам общаться с НИМИ. Завтра мы будем возводить ветровой камень!",
    ["20927901"] = "ОФИЦЕРСКИЕ ЗВАНИЯ ОРДЫ. Часть вторая. Центурион. Легионер. Кровавый страж. Каменный страж.",
    ["211b04d5"] = "\"Легенды троллей\", том третий. \"Камень Приливов\". Принадлежит перу верховного мага Ансарема Руноплета, Даларан. Вступление. Древняя империя Гурубаши была источником многих завораживающих и интригующих легенд, которые, без сомнения, основаны на пристальных наблюдениях за живой природой, поскольку исследования верований и традиций этих троллей указывают на благоговение перед своей естественной средой обитания. В то время как я исследовал многие",
    ["21235792"] = "Гильнеас и Альтерак были надёжными союзниками Строма. Они отправили свои могучие армии изучать гористые южные земли Каз Модана. Именно тогда люди впервые столкнулись с древней расой дворфов и пришли в их подземный город Стальгорн. Люди и дворфы делились друг с другом секретами обработки металлов и инженерного дела. К тому же оба народа одинаково любили битвы и древние предания.",
    ["216414ef"] = "В первый раз за почти три тысячи лет разрозненные народы Аратора объединились под одним знаменем. Лорд Лотар был назначен главнокомандующим войск Альянса и начал подготовку своих воинов к нашествию Орды.",
    ["21704780"] = "\"Но это далеко отсюда, а у меня на руках дети. Мы должны оставить их здесь.\" Её уловка была проста, но лишь простая уловка могла увенчаться успехом. Если бы она сработала, она бы увела всадников далеко от фермы. Она была бы убита, но её дети были бы спасены. Это было бы так, если бы всадники поверили её благородной лжи. Несмотря на то что я никогда не был последователем Света, я яростно молился за жену Свена, когда она стояла перед ужасными всадниками. \"Пожалуйста, – молился я. – Пусть они поверят\".",
    ["21af6493"] = "Тролльских развалин в Тернистой долине, позволили обнаружить упоминания о предмете, известном как Камень Приливов. Объединяя различные фрагменты тролльских преданий, мы получим достаточно сложную картину представлений о Камне и его значении для древней империи Гурубаши. Складывается впечатление, что Камень Приливов позволял своему владельцу повелевать водой в любых её видах: реками, дождями, приливами. На основании легенд, связанных с использованием Камня Приливов, я пришёл к выводу, что он,",
    ["21d2b347"] = "На добрую память о Джесс Моралес",
    ["21d88e76"] = "Как только всё было готово, Саргерас начал вторжение в Азерот. Демоны Пылающего Легиона ворвались в мир через источник Вечности и осадили мирно спящие города ночных эльфов. Под предводительством Маннорота и Архимонда Легион промчался по землям Калимдора, оставляя за собой лишь боль и пепел.",
    ["21e505d9"] = "ПЕРВЫЙ ДЕНЬ. Мы с учеником приехали сегодня в Холодную Долину. Путешествие мимо пещеры прошло без приключений. Мы разбили лагерь подальше от неё, так как нас предупредили, что там водятся тролли. ВТОРОЙ ДЕНЬ. Проклятый волчий вой не давал мне спать всю ночь. Не пройдёт и нескольких дней, как у меня будет накидка из шкуры этой твари. Паренёк столкнулся сегодня с троггом, ввязался в бой и",
    ["21e80606"] = "Общество людей Аратора росло и процветало, но Торадин, боявшийся, что его королевство расколется, если оно будет расти дальше, сохранял Стром центром Араторской империи. Через много лет спокойного развития и торговли могучий Торадин умер от старости, давая юному поколению Аратора возможность распространить власть империи дальше земель Строма.",
    ["21ee1bd9"] = "Четвёртое: регуляторы потока. Увеличивают или уменьшают скорость потока. Это автоматически регулируется управляющим механизмом самофланжа. Пятое: индикатор температуры. Отображает температуру внутри системы в целом.",
    ["21f55d32"] = "\"Коса?\" – спросила она спокойным голосом. \"Конечно, знаю. А кто о ней здесь не знает?\" Она посмотрела на всадников твёрдым взглядом, и я бы поклялся, что она говорит правду, если бы не знал, что это не так. Она не могла знать ничего о косе. Её уловка сработала. Тот же всадник, что задал вопрос, нагнулся к ней и проскрежетал: \"Где?\" \"Я отведу вас. Всех вас,\" – сказала она, и я увидел проблеск надежды в её глазах.",
    ["2210287d"] = "Аман-Тул, Великий Отец Пантеона, отдал часть своей вселенской силы огромному бронзовому дракону, Ноздорму. Великий Отец велел Ноздорму защищать само время и управлять извечными потоками рока и судьбы. Мужественный и благородный Ноздорму стал известен как Вневременный.",
    ["22193fe9"] = "Аман-Тул, Великий Отец Пантеона, отдал часть своей вселенской силы огромному бронзовому дракону, Ноздорму. Великий Отец велел Ноздорму защищать само время и управлять извечными потоками рока и судьбы. Мужественный и благородный Ноздорму стал известен как Вневременной.",
    ["223e4521"] = "Эл Эф приказал увеличить давление на дураков из Альянса. Ниже – список материалов, необходимых для важной миссии против Южнобережья: Недельные походные рационы для двадцати человек Двадцать чёрных ночных костюмов Двадцать новых пар туфель Двадцать пять новых мечей Тридцать метательных ножей Двадцать чёрных масок Десять склянок зажигательного масла Пятьдесят доз парализующего яда Пять украденных униформ стражников Южнобережья, если есть Сто серебряных монет Барон Вэ, Квартирмейстер.",
    ["225dc153"] = "Эти барельефы с бегунами – возможно, наиболее значительная находка в первых залах Ульдамана. Барельеф ясно показывает связь между големоподобными землевиками и расой дворфов. Если в дальнейшем обнаружатся ещё подобные свидетельства, теория нашего предполагаемого создания мифическими титанами может оказаться верной.",
    ["227598f7"] = "*Здесь покоится Утер Светоносный –* Первый паладин и основатель ордена Серебряной Длани Утер жил и умер, защищая королевство Лордерон. Его предал любимый ученик, но мы верим, что дух Утера всё ещё жив. Он по-прежнему наблюдает за нами теперь, когда вокруг нашей разорённой земли сгущаются тени. Его свет – свет всего человечества, и пока мы чтим пример Утера, этот свет никогда не угаснет. - Аноним",
    ["229e99d4"] = false,
    ["22b3a6f2"] = "Убежать от Занзила в этой гниющей лодке в то время казалось хорошей идеей, но я начинаю думать, что смерть могла быть лучшей судьбой. Мне казалось, будто мне повезло, что предки позволили мне спастись от своего гнева. Но сейчас я не понимаю, какую мудрость обрету, если переживу свой плен.",
    ["230ac9b1"] = "Король-лич был доволен новобранцем. Он пообещал Кел'Тузаду бессмертие и невиданную силу в обмен на преданность и покорность. Кел'Тузад жаждал получить эту силу и знание тёмных искусств и с радостью принял свою первую великую миссию – отправиться в мир людей и основать новую религию, последователи которой должны поклоняться Королю-личу как богу.",
    ["23254677"] = "Сердце Медива заполняла тьма, и Саргерас был доволен: почти всё было готово для его повторного вторжения в этот мир, а последний Страж должен был помочь ему с лёгкостью осуществить все свои планы.",
    ["232f76bf"] = "Официальный приказ флоту Кул-Тираса Я, адмирал Праудмур, буду лично командовать первой высадкой на берега Калимдора. Лейтенант Бенедикт назначается моим заместителем на время моего отсутствия. Все вопросы обороны Кул-Тираса будут решаться им. Если от меня не поступит вестей из крепости Тирагард в течение двенадцати месяцев, лейтенант Бенедикт возглавит вторую экспедицию, которая должна будет захватить крепость.",
    ["235536a3"] = "Досточтимый директор Криллиан! Наставник, я пишу вам затем, чтобы поведать о своей нынешней жизни. Прислушавшись к вашему совету, я покинул наш любимый Штормград в поисках знаний. Во время своих странствий я побывал во многих местах, но решил остановиться в славном городке Луноречье. С приближением жатвы поля Западного Края становятся особенно красивы...",
    ["24bb707f"] = "Агашам! Скоро наши агенты из Лордерона встретятся с вашими посланниками. Мы сообщим вам, как только найдём подходящее место для встречи. Подпись: Вестник Гракус",
    ["24d50158"] = "Скажи-ка мне, герой, Ты когда-нибудь слышал боевой клич орков? А может быть, ты защищал свой дом от гноллов, желающих перегрызть глотку тебе и твоим близким? Жутковато звучит, не правда ли? Что ж, тебе пригодится моя помощь. Меня можно найти в североземском аббатстве. Мои знания стоят недёшево, но если ты достаточно опытен, я могу научить тебя приёмам и хитростям, которые помогут тебе защищать Штормград и наши земли. Ллан Бишер, наставник воинов",
    ["24f47ac6"] = "Он хотел знать как можно больше о мире магии и тёмных чудес, но ограниченность и старомодность взглядов коллег разочаровывала его. Когда верховный маг услышал таинственный голос из Нордскола, он приложил все свои силы, чтобы ответить на этот зов. Кел'Тузад был убеждён, что Кирин-Тор слишком слаб, чтобы овладеть силой и знаниями, заключёнными в тёмных искусствах, и поэтому сам решил стать учеником могущественного Короля-лича.",
    ["251d8cb5"] = "Сал'ах, друг мой. Я надеюсь, ты получил мой знак. Меня попросили помочь тебе. Я нахожусь в Тенистой долине, среди ветвей великого Альдрассила. Если тебе нужны знания, обращайся ко мне. В наше неспокойное время все благоразумные мастера тонких искусств должны держаться друг друга. По-другому мы не сможем сохранить Тельдрассил и наше ремесло. Приходи, когда сможешь. -Фрагун Шёпот Тени, наставник разбойников",
    ["25309c1b"] = "Король Ллейн сильно недооценил мощь Орды и мог лишь беспомощно смотреть на то, как его королевство рассыпалось под натиском зеленокожих захватчиков. Вскоре и сам король был убит одним из лучших наёмных убийц Совета Теней, полуорком Гароной.",
    ["253b6b24"] = "Группа из Братства Справедливости встретится с Собирателем, после чего он переправит собранное золото. Убедитесь, что этот процесс произойдёт без ошибок и в условиях строжайшей секретности. Собиратель ответственен за переправку золота, но в конечном счёте каждый член Братства Справедливости должен убедиться, что его роль будет выполнена со всем тщанием и осторожностью.",
    ["253c12f1"] = "Укрощение зверей, меткая стрельба, чтение следов – как научиться всему этому за такую короткую жизнь? Умение охотника требует недюжинной смекалки и огромного терпения. Путь охотника не из лёгких, это точно. Тебе нужно много тренироваться, чтобы достичь уровня самого неуклюжего ружейника из нашего народа. Потому я тебе и пишу. Приходи в Старую Наковальню, что в Холодной долине. Я буду ждать тебя там. -Торгас Угрюмсон, наставник охотников",
    ["256b89eb"] = "*Данат Троллебой.* Командир ополчения Стромгарда. Советник генерала Туралиона, командир армии экспедиции Альянса, которая отправилась в Дренор, родной мир орков. Предположительно погиб. Мы чтим твою память и твою жертву, племянник. Со дня основания нашей славной империи путь к доблести всегда был залит кровью героев. - Торас Троллебой, владыка Стромгарда",
    ["257dbd53"] = "После того как я выжил в побеге из Погибели Роланда, я прятался в сарае, принадлежавшем человеку по имени Свен. Я провёл в нём несколько дней, и такой ужас сковал меня, что я никогда не показывался Свену или его семье на глаза. Но оттуда, с моего места, я мог видеть, что эти фермеры – славные ребята. Если бы я вышел из своего укрытия, я думаю, они бы приняли меня, но мне всегда было тяжело кому-то доверять. И стало ещё тяжелее после случившегося ужаса в шахте. Так что я оставался в укрытии.",
    ["257ec00b"] = "Кеган Мракмар, лидер небольшой группы нежити, пришедший к нам в поисках убежища для его \"братьев\", опроверг все обычные представления о таких, как он. Может быть, его кожа гнила, и кровь не течёт по его жилам, но он держал себя очень достойно, и, похоже, заботился больше о безопасности своих товарищей, чем о самом себе. В действительности, признаюсь честно, в нём было больше человечности, чем в некоторых окружающих.",
    ["257f38a0"] = "О страшной войне между слугами Хаккара и остальными троллями Гурубаши говорят только шёпотом. От магии, которую обрушивали друг на друга злой бог и его мятежные дети, содрогалась земля. В самый последний момент троллям удалось изгнать Хаккара из мира, убив его аватару.",
    ["2580c8bb"] = "Дневник – день четыре Я сижу на этом острове наедине со своими мыслями уже четыре дня. Бананы очень вкусные, вот только лазать за ними приходится высоко. В свободное от добывания еды или укрывания от дождя время я думаю лишь о спасении. Я не питал бы такой радостной надежды, если бы на берег вместе со мной не выбросило ящики с бумагой и бутылки. Теперь мне смешно вспоминать о том, как недоволен я был, что застрял на корабле, полном алхимиков и писцов.",
    ["262cda96"] = "Чтобы встретиться с Ледочревом, его надо приманить мясом любимой добычи. Отравляйся в Альтеракские горы, что на Азероте, и поохоться там на крупных горных львов. Убей одного из них и отнеси тушу в Промёрзшую пещеру, святое место для жестоких йети. Положи тушу на Пламя Узеля, и из пещеры потянет ароматом жарящегося мяса. И тогда, в свой черёд, появится Ледочрев.",
    ["26542a62"] = "С неспешным течением времени росла как территория ночных эльфов, так и их культура. Храмы, дороги и жилища протянулись по всему тёмному континенту. Азшара, прекрасная и талантливая королева ночных эльфов, воздвигла на берегу Источника Вечности огромный, изумительный дворец, в роскошных залах которого проживали её любимые слуги.",
    ["26656570"] = "Сенной долгоносик. Отряд: жесткокрылые. Климат: умеренный. Грозная напасть в крошечном панцире. Один-единственный долгоносик меньше чем за час способен сжевать целый тюк сена. Нашествия случаются редко, но чаще всего о них сообщают с севера Восточных королевств.",
    ["2691208a"] = "Валея Два Клинка. Воительница Алого ордена. Жительница Альтерака. Последний раз была замечена в Восточных Чумных землях.",
    ["26bc30e0"] = "Хотя битвы с людьми заканчивались довольно быстро, обе расы успели выяснить сильные и слабые стороны соперников. Ллейну и Лотару не удавалось получить точные сведения о численности орков, и они могли лишь догадываться о том, насколько могуч был их противник.",
    ["26d8899f"] = "ОФИЦЕРСКИЕ ЗВАНИЯ ОРДЫ. Часть два. Центурион. Легионер. Кровавый страж. Каменный страж.",
    ["26d98e4c"] = "Глава вторая: ВОСТОЧНЫЙ ПИЛОН. Восточный пилон принимает синие, жёлтые и зелёные кристаллы. Пилон фокусирует энергию, которая может быть создана при использовании синих кристаллов в качестве основного источника энергии.",
    ["26f15567"] = "Ниже ты найдёшь список того, что мне понадобится для заклинания призыва великого Циклониана. Да сопутствует тебе удача. --Бар-ра Страж Ветра.",
    ["270a39b3"] = "РАПОРТ: Кобольды. Рядом с Долиной Североземья наблюдается повышенная активность кобольдов. Огромное количество этих существ было замечено к северу от аббатства и на Руднике Горного Эха. Я нашёл добровольцев среди паладинов, воинов и всех, кто был готов помочь нам в борьбе с этой напастью. Пока дела идут хорошо. Желающих помочь предостаточно.",
    ["275921e3"] = "Клан Бронзобородов вернулся в Стальгорн и восстановил свой славный город. Громовой Молот также вернулся домой, в Грим Батол. Но смерть Модгуд осквернила крепость, и дворфы Громового Молота не могли уже там жить.",
    ["2769f251"] = "Фермерша Калаба Крупный долг. Выплата сельскохозяйственной продукцией обещана в урожай. Гражданин Уилкс Все задолженности выплачены. Гражданин Боноан Все задолженности выплачены. Шахтёр Веллти Крупный долг. Выплата состоится после поставки руды из Лазурного рудника. Шахтёр Сидней Крупный долг. Выплата состоится после поставки руды из Лазурного рудника. Шахтёр Хакетт Крупный долг. Выплата состоится после поставки руды из Лазурного рудника.",
    ["2792a71c"] = "Имя его не умрёт. Жертва его всегда Нам будет указывать путь. Оковы, что крепко держали Честь, отвагу и смелость, Нас не стесняют теперь.",
    ["27ec8074"] = "Соленор Душегуб: В безводных землях Силитуса рыщет наш враг. Он дьявольски хитёр и очень опасен. Подберись к нему и вынуди его принять свой облик.",
    ["27f4d76a"] = "Панель управления самофланжа можно использовать, чтобы автоматически регулировать поток топлива, газов, жидкостей и связанные с этим механизмы. После завершения исходной регулировки она должна оперировать без проблем при минимальной поддержке. Краткий список компонентов элементов панели управления (слева направо). Первое: тумблер включения. Позиция \"включено\" задействует самофланж. Контрольный механизм не отключится автоматически при переводе рычага в положение \"выключено\". Это лишь",
    ["28033208"] = "ВОИНСКИЕ ЗВАНИЯ ОРДЫ И АЛЬЯНСА. Тром'ка! В этой книге ты найдёшь подробный перечень воинских званий Орды и жалкого Альянса. Сначала в списках идёт Орда, а затем Альянс, и для обеих сторон перечислены офицерские и рядовые звания. Как и подобает, вверху списка располагаются старшие чины, а младшие – ниже.",
    ["2831ce36"] = "Титан Каз'горот, ваятель и кузнец мира, даровал часть своей огромной силы могучему чёрному змею Нелтариону. Великодушный Нелтарион, позже известный как Хранитель Земли, получил власть над почвой, камнем и подземными недрами. Воплотив в себе силу мира, он стал самым могущественным сторонником Алекстразы.",
    ["283251fc"] = "*Призыв на службу в Орду Этот человек показал невероятные достижения силы и навыка во имя Орды.* *Его следует немедленно назначить на работу на Перекрёсток.* *Почтительно ваш:* Мне кажется, неплохо. - Такрин Торитель Путей",
    ["28651e89"] = "Кровь, что я пролила возле подвески Кровавого камня, медленно двигалась по направлению к драгоценности, как если бы её притягивала к камню некая сила. А кровь, что попала на подвеску, похоже, исчезла, и красный цвет камня стал ещё более насыщенным, когда тот всосал ещё немного моей крови.",
    ["287d48a3"] = "Лорд Вальтхалак, продолжение. Мы разделили амулет на части и сосредоточились на спасении собственных жизней от призрака Вальтхалака и его воинов. К несчастью, весь этот шум привлёк внимание остальных защитников Пика. С небольшими потерями нам удалось-таки выбраться из Чёрной горы, и мы думали, что оказались в безопасности. Но мы ошибались: даже с того света Вальтхалак безошибочно указывал своим воинам, где мы скрываемся. Общество Тайных клинков вскоре распалось, и поодиночке мы стали ещё более лёгкой добычей. Как ты уже, должно быть, знаешь, логово Вальтхалака, теперь известное как чертог Зверя в Пике Чёрной горы, и есть последнее из мест с привидениями.",
    ["2889aba4"] = "Здравствуй, Морган! Дела в Златоземье идут бойко, так бойко, что у меня не было времени отправить тебе товар! Я нанял человека, который принесёт эту записку, доставить тебе пачку больших восковых свечей (тех, что кобольды обычно носят на голове). Будь добр, отблагодари этого человека и заплати ему как следует.",
    ["28d022b9"] = "Хранительница Эгвин с течением времени становилась всё могущественнее, используя энергии Тирисфаля, чтобы продлить свою жизнь. Самоуверенно надеясь, что она победила Саргераса, она продолжала охранять мир от приспешников короля демонов почти девятьсот лет. Но в конце концов Совет Тирисфаля объявил, что время её службы подошло к концу.",
    ["295ec870"] = "Обращаюсь ко всем мужчинам и женщинам, способным держать в руках оружие: Плеть вновь объединила свои силы, и мы вместе должны дать ей достойный отпор, отбросив в сторону все наши разногласия. Каждый, кто готов сражаться, должен прийти на сбор к часовне Последней Надежды, что в Восточных чумных землях. Вместе мы победим. Хранитель архивов Серебряного Рассвета",
    ["29a1a82b"] = "Одним из таких вождей был Дуротан из клана Северного Волка; он указал оркам на то, что они начали терять контроль над собой и поддаваться гневу и ненависти. Но они были глухи к его предостережениям, да и многие более могущественные вожди, среди которых был Гром Адский Крик из клана Песни Войны, выступили в поддержку новой эры войны и господства.",
    ["29b8a603"] = "Чиновник Резерфорд Бернсайд Все задолженности выплачены. Кузнец Эйвери Веррингтан Все задолженности выплачены. Клерк Гораций Белоконь Все задолженности выплачены. Советник Гиллис Все задолженности выплачены. Советник Крюкс Все задолженности выплачены. Фермер Гетц Все задолженности выплачены. Фермер Рей Крупный долг. Выплата долга сельскохозяйственной продукцией обещана в урожай. Фермер Лаийон Крупный долг. Выселен с земли.",
    ["29e26c12"] = "Титан Каз'горот, ваятель и кузнец мира, даровал часть своей огромной силы могучему чёрному змею Нелтариону. Великодушный Нелтарион, позже известный как Землестраж, получил власть над почвой, камнем и подземными недрами. Воплотив в себе силу мира, он стал самым могущественным сторонником Алекстразы.",
    ["2a7d0b54"] = "Но втайне от Альянса, большая группа орков продолжала странствовать по пустошам Каз Модана. Клан Драконьей Пасти, возглавляемый коварным чернокнижником Некросом, с помощью могущественного артефакта под названием \"Душа Демона\" подчинил себе королеву драконов Алекстразу и её подданных. Удерживая королеву в заложниках, Некрос собрал тайную армию в заброшенной цитадели Громового Молота, которую многие считали проклятой.",
    ["2a97ebbb"] = "Этот скелет птерадона был найден в Кратере Ун'Горо. Глядя на его структуру, мы можем сделать вывод, что перед нами новый, неизвестный науке вид. Скелет мог пролежать под слоем богатой почвы Ун'Горо много столетий.",
    ["2acebbf4"] = "Чтобы Кел'Тузаду было легче справиться со своим заданием, Нер'зул оставил ему человеческую внешность. Престарелому, но тем не менее умевшему привлечь к себе сторонников магу предстояло использовать свой дар убеждения и иллюзии, чтобы внушить угнетённым жителям Лордерона веру и надежду. После этого он должен был показать им, насколько лучше они могли бы жить под властью нового короля.",
    ["2afcdf12"] = "Исследуя окаменелости, я пришёл к выводу, что в древние времена великая чума свирепствовала у озера Лордамер. Что послужило её причиной? Мы никогда не узнаем. Но уровень загрязнения весьма высок, исходя из насыщенной концентрации останков, представленных в залежах озёрного пласта.",
    ["2b07f3c0"] = "В этом самом зале ты найдёшь Вол'джина из племени Чёрного Копья. Тролли Чёрного Копья – верные друзья орков; наш союз скреплён кровью в жарких боях во время бегства из земель людей на восточном континенте. Отнесись к нему с уважением – и он ответит тем же. А если проявишь неуважение... в общем, лучше не надо.",
    ["2b1cbdc5"] = "Военные звания Орды. Офицеры: Верховный Вождь, Вождь, Генерал, Лейтенант-генерал, Защитник, Центурион, Легионер, Кровавый Страж, Каменный Страж. Рядовые: Высший Сержант, Старший сержант, Сержант, Рубака, Разведчик.",
    ["2b23fa06"] = "Оргрим, разгневанный убийством Дуротана, решил освободить Орду от ужасного проклятья и, чтобы стать новым вождём Орды, убил Чернорука, марионетку Гул'дана. Под его твёрдым руководством безжалостная Орда наконец окружила Крепость Штормграда.",
    ["2b24888c"] = "Круг большего Единения Создавать Круг Большего Единения нужно там, где сильна магия. Такое место есть в глубине развалин Эльдре'Таласа, называемого также Забытым Городом. В Эльдре'Таласе пленено существо великой силы, Бессмер'тер; именно у подножия его темницы и надо создавать Круг. Проберись к Подножию и выпусти Д'жииви на свободу.",
    ["2b593b35"] = "Больше. Ещё больше… Клан Зимней Спячки… не… слабый…",
    ["2b62f998"] = "Когда Саргерас увидел юный мир Азерота и почуял энергию источника Вечности, в нём проснулся неутолимый голод, и великий тёмный бог Безымянной Бездны решил уничтожить этот мир и завладеть его силой.",
    ["2b869c7c"] = "На следующих страницах ты найдёшь список материалов, необходимых для изготовления закалённого оружия. Удачи, воин. -Фьюрен Длиннобородый.",
    ["2ba020b9"] = "Несмотря на то что мои коллеги в Даларане настороженно отнеслись к идее изучения кровавых камней, что Кеган и его спутники принесли с собой, заключив в карантин четырёх беженцев и оставив их кровавые камни при них, искренность Кегана обязала меня изучить его подвеску Кровавого камня.",
    ["2baf1653"] = "Память о доблести. Повесть о роде Вэлор и их служении Вороньему Холму. Во всех Восточных королевствах не было рода славнее, чем род Вэлор. Их деяния во благо тех, кого они поклялись защищать, были поистине чудом, и их утрата – утрата для всего Вороньего Холма. Я пишу эту повесть, чтобы воздать им по справедливости и рассказать о том, какими удивительными людьми были Брант, Ира, Сильвия и Меррик. Пусть эти строки станут хоть малым утешением – ведь мне бесконечно горько, что их больше нет с нами.",
    ["2bc5024c"] = "Объединившиеся эльфийские и людские армии вступили в схватку с огромной армией троллей у подножья Альтеракских гор. Битва продолжалась много дней, но неослабевавшая армия Аратора не уставала и не отступала под натиском троллей. Эльфийские властители решили, что пришло время ниспослать силы магии на врага.",
    ["2c189c1b"] = "Нептулон восстал из океана огромной водяной башней и наслал на обречённый И'лалай огромных краккенов. Столь огромны были эти твари, что со щупальцев их свисал лес водорослей, и левиафаны проплывали сквозь них. Самый громадный из краккенов воздел конечности и обрушил их на море, подняв волны. И волны эти яростно устремились к И'лалаю.",
    ["2c482863"] = "*Генерал Туралион* . Бывший наместник лорда Андуина Лотара. Рыцарь Серебряной Длани. Верховный генерал экспедиции Альянса, которая отправилась в Дренор, родной мир орков. Предположительно погиб. Эзарус тар-но Дарадор – Кровью и честью мы служим. Ты был правой рукой справедливости и добродетели, старый друг. Твоё имя всегда будет почитаться в наших залах. - Лорд Утер Светоносец, рыцарь Серебряной Длани",
    ["2c4f66a7"] = "Заклятый солнцем и луной, Оставь сей камень роковой, Нетленны рока письмена: В гробнице Смерть заточена, Хранит недрогнувшей рукой Она властителя покой.",
    ["2cab5939"] = "Глава один – Линия фронта Передние линии обороны Клана Северного Волка состоят из воинов клана. Эти воины отправляются на передовую из крепости капитана Гальвангара под названием гарнизон Стылой Крови. Проще всего расправиться с этой линией обороны, разрушив гарнизон. Осади крепость и убей капитана Гальвангара. После этого передовые линии падут.",
    ["2cba589e"] = "Странствуя по полям рассвета, дети земли слышали мрачный шёпот из подземных недр. Этот шёпот рассказывал им про войну и обман. Многие Шу'хало попали под его чары и впустили зло в свои души. Они отвернулись от своих добрых братьев и утратили первозданную чистоту.",
    ["2cc23018"] = "Могучие воины защищают наши дома. Мудрые шаманы охраняют наши души и ведут нас по дороге предков. Друиды сообщают нам волю Матери-Земли. Но ты – охотник, а это призвание объединяет в себе умения воинов, шаманов и друидов. Такие, как ты, являются сердцем нашего народа. К тебе будут обращаться за советом и защитой. Я должен удостовериться, что ты готов к этому. Приходи в Лагерь Нараче. -Ланко Дальний Выстрел, наставник охотников",
    ["2d277fbf"] = "Спиральные символы и пиктограммы, которыми испещрены страницы этого пособия, настолько запутанны, что их невозможно разобрать.",
    ["2d27b686"] = "День четвёртый. Мои запасы подходят к концу. У меня всё ещё очень много еды, но я не планировал столь долго оставаться в лесу, так далеко от моего танка, и взял с собой лишь два кега эля. Я не спал обе прошлые ночи, прислушиваюсь к этому проклятому рёву, и практически до дна выпил оба кега! Завтра мне придётся повернуть назад к Молотоногу и нашим паровым танкам. Я не хочу здесь пропасть без выпивки.",
    ["2d486493"] = "Услыхав от магократов вести о действиях демонов в Даларане, эльфы немедленно послали своих самых могущественных волшебников к людям. Эльфийские волшебники изучили течение энергии в Даларане и составили детальные отчёты о действиях демонов. Они заключили, что, хотя в мире пока не так много демонов, сам Легион будет по-прежнему представлять огромную угрозу, пока люди используют магию.",
    ["2d9e6132"] = "Собирая образцы мха, я случайно стал свидетелем сцены кровавой битвы. Клан мурлоков Коварного Плавника подвергся нападению мародёрствующих банд гноллов. Трупы и гноллов, и мурлоков были разбросаны по всему полю боя. Когда я проходил мимо растерзанного тела мурлока, я заметил странно затвердевшую опухоль, выступающую из раны. Когда я начал изучать её, стало ясно, что похожие свойства я обнаружил у мха, который собирал. К сожалению, больше я не смог найти ни одной опухоли.",
    ["2dce3d41"] = "Доставил бы это письмо тебе сам, но боюсь отлучиться, поскольку могу пропустить нечто очень важное. Если ты желаешь побольше узнать о моих наблюдениях за Башней Алталакса, знай, что податель сего письма немало мне помог и ему вполне можно доверять. Спешно заканчиваю, Балтул Удар Тени",
    ["2df3ec67"] = "Следующие месяцы он провёл, испытывая чуму нежити на оставшихся людях Нордскола, пока не поработил их всех. Армия нежити росла с каждым днём, и он понял, что пришло время для настоящего испытания.",
    ["2e7cf3ec"] = false,
    ["2e84ad33"] = "Прошло время, и Эгвин родила сына в укромной роще. Назвав мальчика Медив, что означало \"хранитель секретов\" на языке высших эльфов, Эгвин верила, что мальчик будет готов к тому, чтобы стать Хранителем. К сожалению, злой дух Саргераса, таившийся в ней, вселился в дитя, ещё находившееся в её чреве. Эгвин не знала, что новый Хранитель мира уже одержим его величайшим врагом.",
    ["2e8668bb"] = "Диаграмма северного пилона.",
    ["2e8d211e"] = "Добрый день, Шнайдер! Надеюсь, дела в районе каналов идут хорошо. У нас тут, в торговом квартале, большой наплыв покупателей. Нам нужно побольше вязаной одежды, наши запасы на исходе. Пожалуйста, пришлите мне стандартную партию при первой же возможности. Удачи. Надеюсь, занятия вашего сына Тармена тоже продвигаются неплохо. Харлан Багли",
    ["2ede0c0b"] = "Сердце Наследия. Старые тексты говорят, что тот, кто обладает сердцем Наследия, не боится могилы. Возможно, это правда, ведь владелец сердца, Тролль Могх, известен как Могх Неумирающий. Знахарь клана Дробителей Черепов, Могх, обитает в Тернистой долине на Руинах Зул'Мамве.",
    ["2f3aaabf"] = "Зато Кеган очень охотно говорил о других вещах, особенно о своём детстве, проведённом в Лордероне до его падения. Он по-прежнему полон любви к этому потерянному королевству, хотя оно сейчас разрушено и мертво. Растущая привязанность к Кегану придавала мне терпения в ожидании результатов анализов.",
    ["2f41143f"] = "Тело жены Свена стояло прямо, как доска, а её глаза распахнулись. И хотя её губы широко открылись в крике, не раздалось ни звука. После нескольких секунд этой пытки рука отпустила её, и она упала на колени. Всадник, державший драгоценность, сел прямо в своём седле и громкий голос раздался из камня. \"Эта женщина лжёт,\" – раздался голос, пугающий меня теперь в кошмарах. \"Она никогда не видела косу\".\"",
    ["2f67aef2"] = "День второй. Степи бескрайни. Мой поход был долог и утомителен, но пока что не дал никаких результатов, могущих заинтересовать Лигу Исследователей. Единственный примечательный инцидент произошёл возле Золотого Пути. Вдали я заметил каких-то странных существ. Наполовину свиньи, наполовину люди – так мне показалось. Я быстро спрятался и дал мерзким животным пройти. Ну и вонь они оставили за собой!",
    ["2f6c466f"] = "Джин'Зил! Прошло немало времени, но я подумал, что ты захочешь узнать, что были убиты последние представители племени Кровавого Пера. Но не благодари меня, убила их та, что доставила тебе это письмо. Если хочешь, я могу прислать тебе её голову, после того как караван пройдёт через Степи. Я знаю, что ты любишь использовать такие вещи в своей магии вуду. Береги себя, старый друг. -Дарсок Быстрый Нож",
    ["2f6fc9cd"] = "Через несколько лет большая часть Орды перебралась на Азерот, и Гул'дан решил, что настало время нанести сокрушительный удар по человечеству. Орда обрушила всю свою мощь на ничего не подозревающих жителей королевства Штормград.",
    ["2f7cc967"] = "Был Астерион, живший среди народа Башал'Арана и много раз отправлявшийся в Амет'Аран, чтобы обеспечить нужды его людей. Итак, оно было на берегах Источника Вечности, города-близнецы росли и процветали, пока мир под звёздами медленно скатывался в безумие.",
    ["2fd89fb3"] = "Королева Азшара, которую магия привела в состояние безумной эйфории, подчинилась невероятному могуществу Саргераса и согласилась пропустить его в свой мир. Перед разлагающим действием магии не устояли даже её служители-высокорожденные, которые начали поклоняться Саргерасу, как богу. Для того чтобы доказать свою верность Легиону, Высокорождённые помогли своей королеве открыть огромный портал в недрах источника Вечности.",
    ["2ffcba82"] = "День первый. Мой танк сломался, но я знаю, что залежи руды хирона – где-то в этих холмах. Я велел Молотоногу оставаться и присматривать за нашими танками. Продолжил поиск в одиночку. Если я не смогу вернуться назад, то журнал останется моим последним завещанием. Бурон Хилдельв, пилот. Паровая бригада Стальгорна.",
    ["30084621"] = "Алекстраза: Алекстраза, древняя и могущественная царица драконов, была названа титанами Связующей Жизнь. Её первую создали титаны для защиты мира после их ухода. Говорят, что она видела зарождение всех народов в мире Азерота. Предводительствуемые ею красные драконы, известные своим гордым нравом, некогда правили всем остальным драконьим племенем.",
    ["30a1d09d"] = "Сейчас я прошу Его Величество помочь в эти трудные времена добрым гражданам Озёр. Нам нужны люди для защиты нашей земли и боевые орудия взамен разрушенных на поле боя. Запасы еды и питья истощились. Умоляю, государь, окажите нам поддержку в защите последнего бастиона на пути ненавистных орков! Враг должен быть изгнан за пределы королевства Штормграда!",
    ["30f8d0e3"] = "Титаны наделили силой многие расы, чтобы те смогли помочь им придавать миру форму. Для создания бездонных подземных пещер титаны сотворили дворфоподобных существ из магического живого камня. Чтобы помочь им осушить моря и поднять землю над уровнем моря, титаны создали огромных, но кротких морских великанов. Многие столетия титаны придавали форму землям, пока не смогли сотворить совершённый континент.",
    ["311eb48b"] = "Нер'зул и его последователи оказались в Круговерти Пустоты, астральной среде между мирами, разбросанными по Великой запредельной тьме. К несчастью, там его поджидал Кил'джеден со своими воинами-демонами. Кил'джеден, поклявшийся отомстить Нер'зулу за его неповиновение, медленно терзал старого шамана, разрывая на части его тело.",
    ["31fd6103"] = "Документы Торговой Компании снаружи шахты... Я думаю, лежат на каких-нибудь ящиках на нижнем уровне. Удачи, и помни... Синий заряд – лесопилка Красный заряд – шахта А, и уничтожь это письмо, после того как выполнишь своё задание. Хм, может быть мне стоит поискать способ заставить эти штуки самоуничтожаться, после того как их прочитают. Это неплохая идея...",
    ["32105e5f"] = "Тром-ка, воин. Меня не интересуют твои подвиги – это все дела прошлого. Когда ты последний раз убивал человека? Наверняка давно. Ты теряешь хватку без дела. Мне нужен напарник. А взамен я дам тебе то, что тебе нужно, – полезную тренировку. Когда до тебя дойдёт, что я дело говорю, – приходи. Я буду ждать тебя под навесом прямо возле Логова. Франг, наставник воинов",
    ["323442d2"] = "Нам, «Шмыг Инкорпорейтед», неприятно говорить о том, что мы получили несколько жалоб на некоторых жадных охотников за корнями, мало заботящихся о своих милых питомцах и отправляющих их в тёмные, опасные места на поиски корней. Мы не станем мириться с такими безответственными хозяевами, но, желая удовлетворить пожелания клиента, мы выдаём гарантию на каждого проданного шмыгуноса, позволяющую новым владельцам вернуть покупку или получить нового зверька взамен потерянного. Удачной охоты!",
    ["32411630"] = "Наш первый план уже провалился! Кулаку удалось поменять распорядок дежурства охранников в тоннелях, но из-за непредвиденного вмешательства некоторых жителей Штормграда объект смог улизнуть прежде, чем нам удалось его поймать. Но мы были готовы к неожиданностям. Сейчас мы действуем по плану два, и всё шло хорошо ещё до засады в Штормграде.",
    ["32753307"] = "Король Теренас из Лордерона, будучи уверенным, что Нер'зул замышляет новое нападение на силы Альянса, послал свои войска на Дренор, чтобы раз и навсегда покончить с орочьей угрозой. Силы Альянса, ведомые Кадгаром и генералом Туралионом, сошлись с орками среди пылающих земель. Даже с помощью Аллерии из числа Высших эльфов, дворфа Курдрана и опытного воина Даната Кадгар не смог помешать Нер'зулу открыть врата в другие миры.",
    ["3288d404"] = "План два довольно прост, но потребует от нас большего терпения. Нашему сообщнику в Менетиле уже заплачено, и свою работу он выполнил блестяще. Теперь мы наверняка с лёгкостью захватим объект, как только отправимся в плаванье.",
    ["32c2a21b"] = "Эти дикие кочевники, которых притягивала энергия Источника, построили на его безмятежных берегах свои хижины. Со временем космическая энергия Источника изменила племя, сделав его сильным, мудрым и практически бессмертным. Племя стало называть себя \"кальдорай\", что на их родном языке означало \"дети звёзд\". Прославляя расцвет своего общества, поселенцы воздвигли по берегам озера большие постройки и храмы.",
    ["32c7b0d6"] = "Я хочу, чтобы капитан Кильватель привёл \"Бурун\" к берегу с юго-востока. Мы отправим его команду по суше, когда будет дан сигнал. Этот здоровый увалень, Солёное Копыто, может повести ребят в атаку. На Ревилгазе и Морском Роге я ставлю чёрную метку. Шлите их прямиком на дно моря. А вы, парни, отвечаете за то, чтобы спасти всё, что может пригодиться для нашей затеи с ван Клифом в Мёртвых копях.",
    ["33018b01"] = false,
    ["337bdfc1"] = "Надеюсь, это письмо дошло до тебя, паладин. Я обращаюсь к тебе с гордостью, потому что немногие обладают столь крепкой верой и готовы войти в число величайших защитников Азерота. Никогда не забывай, твой главный долг – сражаться с теми, кто угрожает нашему миру и несёт порчу в наши дома. Меня назначили твоим наставником на первое время. Когда будешь готов, ищи меня в аббатстве Североземья. -Брат Самуэль, наставник паладинов.",
    ["340602ba"] = "Сэр Эс Джей Эрлгедин принадлежит к знатному людскому роду. Его отец, граф Эрлгедин, славился своей щедростью. Именно граф выступал за улучшение условий труда для Гильдии каменщиков во время восстановления Штормграда после Второй Великой войны.",
    ["3493e5dc"] = "Хартал Проницательный. Предводитель паладинов Алого ордена. Гражданин Азерота – рыцарь Серебряной Длани. Последний раз был замечен входящим в проклятый город Стратхольм.",
    ["34d37e73"] = "Брат Хаалиен! Пора доказать свою преданность Ал'акету. Иди в Теневейный лес и найди там столп. Ты докладывал о своих опасениях по поводу друидов, и высшая ложа ордена оценила твою проницательность. Возьми верных солдат и исполни этот благородный долг. Убей друидов как можно скорее, дабы они не расстроили наши планы. Наши глаза и уши в Валанааре подтвердят, когда дело будет сделано. Час возмездия настал! Никто не остановит рассвет новой эры! Н.",
    ["34dbb356"] = "Страх и решимость Артаса привели его к погибели. Он желал уничтожить угрозу своей земле и ради этого добрался до источника чумы в Нордсколе, но сам пал жертвой могущества Короля-лича. Надеясь спасти свой народ, Артас взял в руки проклятый рунный клинок, Ледяную Скорбь.",
    ["355d9635"] = "Совет Луносвета, правивший эльфами Кель'Таласа, заключил секретный пакт с магократами, владыками Даларана. Эльфы рассказали лордам-магам об истории древнего Калимдора и Пылающем Легионе, который всё ещё угрожал миру. Они сообщили людям, что, пока те используют магию, им придётся защищать своих граждан от коварных посланцев Легиона.",
    ["3568e860"] = false,
    ["357ab1cc"] = "Король Ллейн рассказал об этом Андуину Лотару, последнему потомку рода Арати, которого он сделал своим военачальником. Но никто из них не мог предположить, что беда, случившаяся с Медивом, станет причиной столь ужасных событий.",
    ["358c8048"] = "Орки и люди, враждовавшие не одно поколение, не хотели и слушать его. Медиву пришлось общаться с каждой расой по отдельности, обманом заставить их пересечь море и ступить на легендарную землю Калимдора. Вскоре орки и люди обнаружили скрывавшуюся долгое время цивилизацию калдорай.",
    ["36623720"] = "Но пять родов главенствовали над своими собратьями. Титаны избрали эти пять стай, чтобы те присматривали за расцветающим миром. Величайшие члены Пантеона отдали часть своей силы каждому из лидеров стай. Эти магические драконы (указанные ниже) стали известны как Великие аспекты или Великие драконы.",
    ["36f3c408"] = "Сначала он воззвал к Выводку Изеры. Меритра из Сна ответила на его зов, и затем весть дошла до выводков Алекстразы и Малигоса.",
    ["371662ea"] = "РЕКОМЕНДАЦИЯ: Носитель данного документа, послуживший Североземью с рвением и отличием, должен быть награждён званием делегата в армии Штормграда. Я уверяю вас, что вы найдёте его полезным в Элвиннском лесу. Подпись: Маршал Дуглас Макбрайд, Армия Штормграда, Североземья.",
    ["3727934b"] = false,
    ["3756362e"] = "Ульдаман, День шестой …страшно есть хочется. У меня кончились припасы, я полагаю, придётся доедать заплесневелый хлеб. Голова проходящего мимо трогга на моих глазах превратилась в сочный стейк…",
    ["37666140"] = "Без вести пропавший: капрал Кеешан В последний раз его видели во время кровавого сражения за Башню Каменной Стражи, из докладов стало известно, что его утащили орки Чёрной Горы. Полагают, что он содержится в плену в качестве военного заложника в лагере Чёрной Горы, севернее Приозёрья, южнее дороги, ведущей в Пылающие степи. В соответствии с приказом мирового судьи Соломона – любому, кто поможет спасти капрала Кеешана, будет выдана награда маршалом Маррисом.",
    ["3769c9c6"] = "После долгих лет странствий высшие эльфы, наконец, нашли земли, напоминавшие Калимдор. В глуши северных лесов они основали королевство Кель'Талас и поклялись создать могущественную империю, которая будет во всём превосходить цивилизацию их собратьев, кальдорай. К сожалению, эльфы вскоре узнали, что основали Кель'Талас на развалинах древнего города троллей, который те до сих пор считали священным. Тролли почти сразу же начали атаковать эльфийские поселения.",
    ["37847f11"] = "Кенарий жил на священных Лунных полянах на горе Хиджал. Он согласился помочь ночным эльфам, найти древних драконов и обратиться к ним за помощью. Драконы, в свою очередь, тоже решили не оставаться в стороне и, ведомые исполинской красной Алекстразой, отправились на войну с демонами и их адскими предводителями.",
    ["37af1856"] = "Торговая компания... Неразборчиво. Похоже, эти глупцы сорвали всю свою операцию в попытке стабилизировать зелье. Несколько страниц вырвано.",
    ["383cc6b9"] = "Приветствую тебя. Я был погружён в размышления, когда мне в голову пришла мысль тебе написать. Многие наши соплеменники считают духовными лидерами шаманов, подобных нашему Вождю. Другие предпочитают поклоняться мечу и топору. Но не стоит забывать, что на исход битв и даже целых войн влияют совсем другие силы. Вот об этом я и хочу поговорить с тобой. Ты можешь найти меня в Логове, что в Долине Испытаний. -Руаг, наставник разбойников.",
    ["38d3124d"] = false,
    ["390beb4b"] = "Вурмталак! Твой господин Нефариан дал мне повеление наказать тебя так, как я посчитаю нужным, если ещё хоть кто-нибудь проберётся внутрь крепости. Не забывай, кому ты подчиняешься, рептилия. Сыну Чернорука: Мастеру меча и битвы. Единственному истинному Вождю. -Ренд",
    ["39a4f09f"] = "Внезапное предательство Смертокрыла повлекло за собой столь губительные последствия, что остальные драконы так никогда и не смогли оправиться от потрясения. Израненная и убитая горем Алекстраза и её пятеро собратьев покинули поле боя, оставив своих смертных союзников один на один с многократно превосходящей их армией демонов. Малфуриону и его соратникам едва удалось выжить в последовавшем натиске.",
    ["39db3315"] = "Пребывание в брюхе великана способствует размышлению. Пока моё тело кристаллизовалось, я пришёл к выводу, что, возможно, в этом мире достаточно героев. Если я как-нибудь отсюда выберусь, я здорово врежу этому орку по призрачной шее! -Уинден Шей",
    ["3a6696db"] = "Кел'Тузад оставил учение Кирин-Тора и навсегда покинул Даларан, отказавшись от всех своих богатств и высокого положения в обществе. Повинуясь голосу Короля-лича, звучащему в его мыслях, он продал всё, что у него было, и спрятал свои богатства. Он проделал долгий путь по суше и морю – и наконец достиг ледяных берегов Нордскола.",
    ["3a7f250f"] = "*Призыв на службу в Орду* . Этот человек показал невероятные достижения силы и навыка во имя Орды. Его следует немедленно назначить на работу в Перекрёсток. *С глубоким почтением,* Мне кажется, неплохо. - Такрин Торитель Путей",
    ["3a912801"] = false,
    ["3ac45788"] = "Алекстраза красная, Изера зелёная и Ноздорму бронзовый опустились на тихие поляны ночных эльфов и посмотрели на плоды их трудов. Малфурион, ставший могущественным верховным друидом, поприветствовал драконов и рассказал им о новом Источнике Вечности.",
    ["3b16e517"] = "*Как очистить луковицу Подробное руководство по сражению с Грозовой Вершиной Написано Дрек'Таром* На этих страницах читатель найдёт обширные сведения о политике и боевой тактике. Хороший солдат – это тот солдат, что понимает важность накопленного опыта. Пусть же эта книга послужит читателю руководством по сражению за Альтеракскую Долину.",
    ["3b1a4de4"] = "...я более чем уверен, что она испытывает те же чувства, что и я. Она даже взяла меня за руку сегодня утром. Когда она смеётся, её глаза сверкают как бриллианты. Столько невысказанных слов между нами. Моё сердце стучит, как сумасшедшее, и огонь разливается по венам.",
    ["3b1f78c3"] = "Азерот – страна нескончаемых чудес. Здесь многообразно всё – флора, фауна, культура, магия. Жаждущий знаний может многое здесь найти. Надо лишь внимательно смотреть. И если заглянуть достаточно глубоко, то увидишь окна в новые миры, в каждом из которых есть свои чудеса. А есть и свои бедствия.",
    ["3b2e0ce5"] = "Рад, что твоя душа не попала в Пустоту. Я полагаю, ты стоишь усилий, затраченных на написание этого свитка. Помни: людей, которых ты знал и любил, больше нет в живых! Ты должен пронести этот груз через всё своё дальнейшее существование. Советую тебе смириться с этим с самого начала. Если ты готов к испытаниям, найди меня в церкви Могильника. - Тёмный священник Дьюстен, наставник жрецов",
    ["3b63fc15"] = "Привет тебе, Элло Чернодрев, мэр Темнолесья. Боюсь, у меня плохие вести для вашего города. Видишь ли, я создатель. Я обманом заставил того, кто доставил это письмо, помочь мне в создании моего последнего, самого ужасного творения – демона из плоти, костей и металла! Когда ты читаешь эти строки, он находится рядом с моим скромным жилищем, скрежеща зубами. Одно моё слово – и он начнёт убивать и крушить всё на своём пути. И в скором времени вы испытаете это на себе. Бальзамировщик",
    ["3b642004"] = "*Призыв на службу в Орду Этот человек показал невероятные достижения силы и навыка во имя Орды.* *Его следует немедленно назначить на работу на Перекрёсток.* *Почтительно ваш:* Мне кажется, неплохо. - Такрин Торитель Путей",
    ["3b6d4bf2"] = "Срочное сообщение для дозорного утёсов Долгорога Огромные силы кентавров из Лагеря Э'ток напали на один из наших торговых караванов. Все члены каравана были убиты, а весь товар потерян. Это было наглое и беспрецедентное нападение, и, я боюсь, не последнее.",
    ["3bae8678"] = "День первый. Наконец-то я из Стальгорна добрался до Калимдора! Геолог Хазгорм из Бейл Модана отлично продвигается. Он сегодня раскопал окаменелость, которую местные учёные считают фрагментом кости древнего бога. Хазгорм уверен, что окаменелость – часть великой загадки. Пока он приглядывает за раскопками, но поручил мне найти ещё окаменелостей, чтобы собрать эту историю воедино. Моё задание: отправиться на юг в поисках дополнительных ключей к тайне.",
    ["3bc690c2"] = "ОФИЦЕРСКИЕ ЗВАНИЯ ОРДЫ. Часть вторая. Центурион. Легионер. Кровавый страж. Каменный Страж.",
    ["3c124407"] = "Попытался проучить монстра, но в итоге получил глубокий порез на руке. Похоже, придётся накладывать швы. ТРЕТИЙ ДЕНЬ. Похолодало. Ночью выпало немного снега. ЧЕТВЁРТЫЙ ДЕНЬ. Ученик поправился и пребывает в хорошем расположении духа, поэтому мы рискнули посмотреть на троллей. Судя по отметкам на их коже и различным амулетам, которые они носят, это племя Мерзлогривов.",
    ["3c5f29ed"] = "Дальше страница испещрена нулями и единицами.",
    ["3cb7a7c1"] = "Дела культа, том двести тридцать три Нам снова выпала редкая возможность, о братья мои и сёстры! Круг Кенария, мерзостный культ почитателей природы, посылает на нас своих приспешников. Они хотят воспрепятствовать нам добыть красные камни-приманки. Мы не можем этого допустить! Красные камни очень нужны нашим новым союзникам. Нельзя, чтобы шавки из Круга Кенария добились своего. Держитесь, преданные друзья мои. Держитесь!",
    ["3ccf68dc"] = "*Курдран Громовой Молот* . Знаменитый драконобоец. Укротитель грифонов Заоблачного пика. Командир подразделения всадников на грифонах при экспедиции Альянса, которая отправилась в Дренор, родной мир орков. Предположительно погиб. Ветер донесёт до нас клич Скайри. Мы услышим грохот твоего молота по ту сторону гор. Вступай в загробную жизнь без опасений, брат. Залы наших предков ожидают тебя. - Верховный тан Фалстад Громовой Молот",
    ["3cd7e36c"] = "Эонар также даровала младшей сестре Алекстразы, изящной зелёной драконице Изере, определённую власть над природой. Изера впала в вечный транс, именуемый \"Сном Творения\". Известная под именем Спящей, она следит за природой мира из царства Изумрудного Сна.",
    ["3ce8da78"] = "Но несмотря на то что я был бессилен и не мог остановить это ужасное убийство, одно истинное сожаление всё же остаётся: ведь это я привёл чёрных всадников к ферме Свена. Моя находка не только высвободила воргенов по всему Сумеречному лесу – она привлекла всадников из Мёртвого Ветра. Я знаю это, потому что прежде чем они начали убивать, они задали жене Свена один вопрос в тот момент, когда она прижимала к себе своих детей, пытаясь успокоить их и ободрить, зная, что вскоре их ожидает смерть.",
    ["3cec3656"] = "Тиранда, ставшая Верховной жрицей Элуны, умоляла своего возлюбленного Малфуриона не уходить в Изумрудный Сон Изеры. Но Малфурион, считавший своим долгом вступить на изменчивые тропы Спящей, попрощался со жрицей и поклялся, что они никогда не разлучатся, до тех пор пока хранят верность своей любви.",
    ["3cfd532a"] = false,
    ["3d174885"] = "Моя дорогая Эмили! Несколько дней назад мы снялись с лагеря в этом покинутом Светом месте и по приказу короля отправились домой. Даже эти мрачные пейзажи не могли омрачить моей радости, ибо я знал, что после тяжёлого путешествия ты наконец-то сможешь заключить меня в объятья. Сегодня мы добрались до берега, но обнаружили, что от наших кораблей остались одни лишь дымящиеся угли; лишённые единственного шанса вернуться домой, мы вынуждены идти в самое сердце этой бескрайней пустыни. Эмили, ради тебя я отправлялся в самые дальние уголки этого мира, а теперь… теперь я всей душой желаю повернуть время вспять и вновь оказаться рядом с тобой. Каждое мгновение я думаю о тебе. Любимая, мысли о тебе согревают мою душу в этом ледяном краю, и никто никогда не отнимет их у меня. Максвелл",
    ["3d26348d"] = "Элуна услышала мои молитвы. Мои товарищи пали недаром, и коса Элуны поможет мне отомстить за них. Это древняя вещь, ветка, изогнутая и искорёженная, из дерева, которое, должно быть, старше самих кальдорай. Много часов я исследовала дар богини. С первого взгляда понятно, что это не обычное оружие и не простое магическое устройство. С ним... словно барьеры времени и пространства ослабели. Держа Косу",
    ["3d30cfc5"] = "Бесплодные земли кишат врагами. Огры рыщут по раскалённым пескам, нападая на неосторожных путников. Дворфы из клана Чёрного Железа, обитающие в казармах к востоку от Каргата, бьются со своими светлокожими сородичами у северного озера Лок Модан. Жестокие и примитивные создания, именуемые троггами, яростно сражаются за каждый клочок тени. А в Восточных Бесплодных землях, в долине Летлор, живут драконы. Мы не знаем, много ли их там и насколько они велики, ведь разведчики, которые подбираются слишком близко к ним, назад уже не возвращаются.",
    ["3d924b80"] = "Хелгрум, передай мою похвалу тому, кто приказал основать нашу базу в Каргате среди Бесплодных Земель. Это место идеально подходит для обучения наших войск. Тамошний суровый климат, злобные звери, воинственные аборигены и полное отсутствие помощи извне сделают так, что выйдут оттуда лишь лучшие из воинов и разведчиков. Хорошая задумка. Превосходно.",
    ["3dc804ff"] = "Ажек и сэр Эрлгедин страстно желали научиться стрелять из дворфийских винтовок. Я велел им оставить своё примитивное оружие в лагере. Мы с Барнилом снарядили их лучшими образцами стальгорнских ружей.",
    ["3dedbd2c"] = "Дата занесения: нет данных Имя: Натанос Маррис, человек, предводитель следопытов Лордерона. Тема: Хочу отметить несогласие Кель'таса Солнечного Скитальца с моим решением принять Натаноса Марриса в наши ряды. Следует отметить, что Натанос, несмотря на своё человеческое происхождение, является одним из самых талантливых следопытов, которых мне доводилось обучать. (продолжение следует)",
    ["3e2eea5f"] = "ОФИЦЕРСКИЕ ЗВАНИЯ ОРДЫ. Часть первая. Верховный Вождь. Вождь. Генерал. Лейтенант-генерал. Защитник.",
    ["3e693f37"] = "Валлик, Охраняй раба до нашего возвращения. Теперь здесь небезопасно, мы не можем больше хранить его тут. Мы отправимся на север, обходя стороной любые места, где нас могли бы заметить. Они – животные, но животные безжалостные – мы достаточно от них натерпелись, у нас есть причины для беспокойства. Лучше спрятать любые знаки, что могли бы заставить собраться их вместе. Меньше всего мы бы хотели дать им повод воссоединиться и напасть на нас.",
    ["3e972b4d"] = "Дорогая Памела! Завтра мы доберёмся до Андорала, и, боюсь, я не буду тебе больше писать. Нежить не знает усталости, а мы… мы – всего лишь люди. Нам их не победить. Но не надо печалиться, любовь моя: хотя нам и суждено погибнуть, наша надежда остаётся. Свет победит! И мне греет душу мысль о том, что, когда наша защита падёт и враг сокрушит нас, страх смерти не будет терзать меня. Все мои мысли будут о тебе, дорогая, и моя душа обретёт покой. Кристоф",
    ["3ed5ffc8"] = "Двое заключили между собой пакт. Кел'Тузад получил бессмертие и великую силу в обмен на верность Королю-личу. Перво-наперво он должен был употребить в Лордероне всё своё богатство и влияние, чтобы основать там Культ Проклятых. Этот культ обещал всем своим приверженцам равенство и вечную жизнь, если они присягнут на верность Нер'зулу, богу Культа Проклятых.",
    ["3ef8b786"] = "-День тринадцать Движение войск у Терамора усилилось. Крупные отряды людей оставили город и спешно идут на запад. --День четырнадцать Из города уходят все новые отряды. Я проследил за одной маленькой группой и видел, как всё в ней сняли униформу, удалившись от Терамора на расстояние полёта стрелы. Может быть, они дезертиры? --День пятнадцать Сегодня я слышал, как солдаты в Тераморе говорили о часовых, оставляющих посты. Должно быть, мои подозрения о дезертирах верны",
    ["3f1825e4"] = false,
    ["3f9b85e1"] = "Надеюсь, духи исправно тебя защищали. Тебе предстоит ещё много испытаний, поэтому я хочу вот обучить тебя тому, что сам знаю. Сам решай, хочешь ли обладать нашими силами, и если да, то приходи. Выбирать тебе – я могу только вести тебя. Ну, одни-то, конечно, учатся быстро, а другие вот… помедленней. Но ты не волнуйся заранее. Как захочешь меня увидеть – приходи, поговорим. -Кен'джай, наставница Жрецов.",
    ["3f9fba90"] = "Титан Норганнон, хранитель знаний и владыка магии, даровал синему дракону Малигосу часть своей великой силы. С того времени Малигос, известный как Маготкач, хранит магию и тайные знания.",
    ["3fd00d3f"] = "Глава первая: СЕВЕРНЫЙ ПИЛОН. Северный пилон принимает жёлтые, красные и зелёные кристаллы. Пилон фокусирует энергию, которая возникает при использовании жёлтых кристаллов в качестве основного источника энергии.",
    ["406474c0"] = "Прошло время, и Кенарий стал сильным, как его великий отец. Брат деревьев и звёзд, этот великий охотник странствовал по миру, напевая умиротворяющую песню рассвета. Всё живое склонялось перед его грацией и красотой. Никого на свете не было мудрее сына луны и белого оленя.",
    ["4093d5a0"] = "Разъярённые драконы Алекстразы разрушили Грим Батол и сожгли большую часть орков Драконьей Пасти. Грандиозные планы Некроса рухнули; войска Альянса окружили уцелевших орков и заключили их в лагерь для военнопленных. Поражение Драконьей Пасти ознаменовало конец Орды и кровожадности орков.",
    ["409490f5"] = "Малфурион и друиды не слушали речей Дат'Ремара и объявили высокорождённым, что любое использование магии будет караться смертью. Однако Дат'Ремар и его последователи всё же попытались нарушить закон друидов, но попытка эта закончилась крахом, и в результате в Ясеневом лесу разразилась ужасная магическая буря.",
    ["419c2e4f"] = "Добрый мой Мартек, я в затруднении, мне нужна твоя помощь. Мы с братом собираем гоночный автомобиль, и нам требуются крепкие поршни. Все поршни, что я пробую, недостаточно крепки. Ни один из них не может выдержать скорость нашей новой машины. И поэтому у нас то и дело ломается двигатель! Ты мастер по работе с металлом. Ты должен помочь. Ты – единственная наша надежда.",
    ["41a36456"] = "Кормление и уход: Мы хотим обеспечить вас всем необходимым для ухода за питомцем. Наши клиенты ожидают от \"Шмыг Инк.\" именно такого уровня обслуживания, и мы с ними согласны! С этой целью мы разработали крепкие ящики для шмыгуносов, чтобы вы могли содержать питомца в безопасности и вне доступа света. Для вашего удобства в каждом ящике находится отделение для корма, пронизанное чарующим ароматом клубней синелиста (любимого лакомства шмыгуносов)!",
    ["420d6407"] = "Каменщиков из Штормграда, он воспользовался относительно незащищённым статусом Западного Края и использовал своё превосходство в силе, чтобы выгнать оттуда множество фермеров и захватить несколько золотых рудников. Воспользовавшись ресурсами, оказавшимися в его распоряжении, ван Клиф составил план возмездия правительству Штормграда. Эта информация стала известна лишь недавно благодаря помощи носителя этого документа, который сыграл важную роль в пролитии света на этот громадный заговор.",
    ["4217bc33"] = "Титаны наделили силой многие расы, чтобы те смогли помочь им придавать миру форму. Для создания бездонных подземных пещер титаны сотворили дворфоподобных земельников из магического живого камня. Чтобы помочь им осушить моря и поднять землю над уровнем моря, титаны создали огромных, но кротких морских великанов. Многие столетия титаны придавали форму землям, пока не смогли сотворить совершённый континент.",
    ["4234992a"] = "Охрана Ясеневого леса занимала всё время Тиранды, но она тосковала без Малфуриона. Шли века, друиды спали, а её опасения насчёт нового вторжения демонов росли. Она не могла избавиться от тревожного ощущения, что, возможно, Пылающий Легион всё ещё здесь, за пределами Великой тьмы неба, и что он готовится отомстить ночным эльфам и всему Азероту.",
    ["4241d159"] = "Чтобы добыть энергию, необходимую для порталов, ему нужно было несколько мощных артефактов с Азерота. Нер'зул снова открыл Тёмный портал и послал туда своих верных слуг, чтобы они нашли эти артефакты.",
    ["42459b0c"] = "ПИЛОНЫ: ИНСТРУКЦИЯ ПО ЭКСПЛУАТАЦИИ \"Руководство по сбору и использованию кристаллов силы Кратера Ун'Горо\" Глава первая: Северный пилон Глава вторая: Восточный пилон Глава третья: Западный пилон",
    ["4248e9d3"] = "Родина воргенов – тёмное место, обитель кошмаров. Если в том мире и есть места, куда не могут добраться проклятые воргены, то мне о таких бастионах не известно. Если же лицезреть воочию ярость и злобу воргенов, то на ум приходит, что быть таких мест не может. Есть мнение, что воргенов вполне устраивает их собственный мир: ведь, хотя некоторые из них владеют очень сильной магией, они не предпринимали попыток перенестись в Азерот самостоятельно. И для нас это очень хорошо.",
    ["4285d512"] = "Алекстраза Хранительница Жизни опустила в источник зачарованный жёлудь. Пробуждённый могущественными водами, он вырос в огромное дерево, корни которого тянулись в самые недра Источника, а крона, казалось, достигала небес.",
    ["429c2fcd"] = "Доргар Камнелоб Воин Алого ордена Властитель Красных пещер Последний раз был замечен в горах Альтерака",
    ["42a045fa"] = "Они назвали свои земли Каз Модан, или \"Гора Каза\", в честь титана-кузнеца Каз'горота. Соорудив алтарь своему отцу-титану, дворфы создали огромную кузницу в самом сердце горы. И город, росший вокруг кузницы, стал называться Стальгорн.",
    ["42c4dc88"] = "Холия Солнечный Щит Защитница Алого ордена Погибла при покушении на повелителя ужаса Белтериса",
    ["42f45475"] = "Должна быть собрана об организации нежити в Брилле. Капитан Вакон, похоже, что передвижения нежити около северной башни возросли. Эти волнения должны быть быстро и решительно подавлены. Капитан Мелроуз, меня беспокоит уровень организованности нежити около границ с Лихоземьем. Новая группа солдат будет доставлена в ваше распоряжение в ближайшие недели. Да прославится Свет",
    ["431ad588"] = "Меррик Вэлор, дозорный Темнолесья. Меррик был младшим сыном в семье Вэлор. Видя, как скверна подступает к родным краям, он вступил в Ночной дозор, отчаянно желая уберечь своих близких. Пусть он и был самым неопытным в семье, но вскоре заслужил добрую славу среди дозорных. У него был дар к стрельбе из лука, и очень скоро он стал одним из самых стойких защитников Темнолесья. Своим долгом он считал охрану дорог от тварей, что все свирепее наводняли здешние леса.",
    ["4352bac4"] = "Шахтёр Оруэлл Крупный долг. Выплата состоится после поставки руды из Лазурного рудника. Шахтёр Фитцджеральд Крупный долг. Выплата состоится после поставки руды из Лазурного рудника. Гражданин Недранд Все задолженности выплачены. Гражданин Мэй Все задолженности выплачены. Старшина Бондс Крупный долг. Выплата состоится после поставки руды из Лазурного рудника.",
    ["435c0b16"] = "Брат, я надеюсь, ты получил эту руну. Хочу сообщить тебе, что я в Старой Наковальне, что в Холодной долине. Я знаю, как важно для нас держаться вместе, особенно в такое неспокойное время. Загляни ко мне, когда будет свободное время. -Сольм Харгрин, наставник разбойников",
    ["4390446e"] = "Я начал вести этот журнал, чтобы делать заметки о своих попытках помочь Ясеневому лесу. Некоторые из недавних событий исполнены тайн, и я надеюсь, что смогу пролить свет на часть из них, чтобы помочь своему народу. Начну с того, что запишу некоторые факты, чтобы не забыть их потом. Недавно я нашёл подтверждение слухам о деятельности волшебника Дартола.",
    ["43b543bf"] = "День четвёртый. Я в плену! Нужно... писать... быстро. На меня напали свинолюди из племени Иглошкурых. Я думал, что они ведут меня к кабаньим останкам павшего бога. Вместо этого они обогнули окаменелость и направились прямо к западу от гигантского черепа, пересекая Золотой Путь.",
    ["43d67a54"] = "Дорогой Заргх, мясо, которое ты прислал, очень вкусное. Оно с прожилками жира, нарезано толстыми кусками и обёрнуто в кабанье сало – как раз по моему вкусу. Когда я съем его и разгрызу последние кости, то обязательно буду думать о тебе. Я закрою глаза и буду представлять, как ты рубишь и режешь это мясо своими сильными, покрытыми шрамами руками… Ха! Я сразу вспомнила о том случае, когда ты лишился пальца… О, Заргх! Когда мне на память приходит тот день, я всякий раз хихикаю, будто маленькая девчонка. Ты такой милый, когда истекаешь кровью! -Гришка",
    ["4400d3f3"] = "На скалистом склоне, возвышавшемся над нами, в лучах заходящего солнца вырисовывался силуэт самой большой кошки, которую я когда-либо видел. Мне удалось сделать неловкий выстрел из ружья, но кошка не двинулась с места. Она издала ещё один ужасный рык, громче прошлого, и исчезла. Мы собрали вещи и мрачно двинулись в лагерь.",
    ["443b5d6c"] = false,
    ["449e93c5"] = "Твой драгоценный зверь не очень-то хорошо себя чувствует в обжигающем жаре Тлеющего ущелья… лучше тебе незамедлительно выполнить наши требования. Ты принесёшь нам пять звёздных рубинов и семьсот золотых, и положишь всё это в один пакет без пометок. Пакет не позже чем через неделю оставь у входа на Подгорную тропу. Если наши требования не будут выполнены, Метцен украсит собой традиционный дворфийский стол на Праздник Зимнего Покрова. Олень… вкуснятина…",
    ["44bd3fb4"] = "Северная комбинация кристаллов Есть два возможных эффекта: наносящий урон и нейтрализующий его. КРИСТАЛЬНЫЙ ЗАРЯД: требует жёлтых и красных кристаллов. Провоцирует сильный взрыв. КРИСТАЛЬНОЕ ВОССТАНОВЛЕНИЕ: требует жёлтых и зелёных кристаллов. Наделяет вас целительной аурой.",
    ["44bdd380"] = "Настоящим я отказываю Кел'Тасу в просьбах касательно Натаноса Марриса. Он будет бесценным союзником. Помяните моё слово. Подписано: Сильвана Ветрокрылая Предводитель следопытов Луносвета.",
    ["44d0de02"] = "После изгнания коварных насекомых две империи вернулись к обычной жизни. Победа в войне практически не изменила их границ. Впрочем, в древних рукописях упоминается некое племя, покинувшее в те годы империю Амани и основавшее собственное поселение в самом сердце тёмного континента.",
    ["44d8523b"] = "Далеко на севере, в области, сейчас известной под названием Нордскол, жили малочисленные племена, образовавшие государство Гундрак, но так и не сравнившиеся со своими южными сородичами.",
    ["450ef2f7"] = "Этот побочный эффект невероятно смертоносен. Только представь, что... Текст невозможно прочесть. Ха-ха-ха!",
    ["45eb5cbb"] = "В попытке понять прошлое я начал изучать создания настоящего, надеясь обнаружить недостающие ключи к загадке. Озёрные тихоходы и озёрные ползуны – древние создания, населяющие остров в центре озера Лордамер. Мох, растущий на них, содержит следы частиц тех самых окаменелостей. Необходимо провести больше исследований, прежде чем я смог бы сделать выводы о том, что означает эта связь.",
    ["4602fbe5"] = "Мастер Длиннобородый, как тебе известно, мы в клане Грозовой Вершины разбираемся в отличной работе, так что качество твоих щитов для нас не новость. Именно поэтому я хотел бы заказать у тебя щит. Описание его я привожу на следующей странице:",
    ["465970a6"] = "*Призыв на службу в Орду Держатель этого письма показал невероятные достижения силы и навыка во имя Орды.* *Его следует немедленно назначить на работу в Перекрёсток.* *С глубоким почтением,* Не возражаю. - Такрин Торитель Путей",
    ["46680378"] = "Хорошо, у тебя должны быть заряды и детонаторы эн-джи-пять. Я их пометил для тебя... Синий – для лесопилки. Красный – для Рудника Ветрорезов. Я кое-что разведал и выяснил, что на Утёсе Ветрорезов достаточно взрывчатки, чтобы тебе не было сложно зайти туда, установить детонаторы и выйти оттуда, перед тем как взрывать. Помни, это отвлекающий манёвр. Отойди далеко от вагонов перед тем, как гоблины доберутся туда, чтобы проверить, что случилось, затем проскользни за ними.",
    ["468e7779"] = "Рыцари смерти и последователи Призрачной Луны, верные Нер'зулу, также подверглись трансформации: их разорвали на части, а затем превратили в костяных Королей Мёртвых. Демоны позаботились о том, чтобы даже после смерти последователи Нер'зула беспрекословно служили ему.",
    ["46caa2b4"] = "Необратимость выбора Предыдущий раздел осветил весьма важные моменты о двух направлениях инженерного дела, которые надо усвоить, чтобы начать обучение. Решение заняться тем или иным направлением науки означает, что схемы противоположного направления никогда не будут доступны для изучения. Хотя такая окончательность выбора может отпугнуть непрофессионала, опытный инженер понимает, что гномы и гоблины оберегают свои секреты с великим пылом и что знание о чём-то – всё же лучше, чем никакого знания.",
    ["470aa761"] = "Когда на Азероте родился Медив, Кил'джеден Искуситель и его последователи из Круговерти Пустоты погрузились в размышления. По приказу своего хозяина Саргераса, коварный великий демон готовил зловещие планы по захвату Пылающим Легионом Азерота.",
    ["470b6e45"] = "Саргерас выжидал подходящего момента, когда таящаяся в юноше сила даст о себе знать. Уже будучи подростком, Медив заработал себе популярность среди жителей Азерота своими выдающимися магическими способностями и часто отправлялся на поиски приключений вместе со своими друзьями – принцем Азерота Ллейном и Андуином Лотаром, одним из последних сыновей рода Арати. Трое мальчишек постоянно попадали в переделки, но горожане их очень любили.",
    ["4760c8bc"] = "Орки, уступавшие противнику числом и обезумевшие от собственной жажды крови, пали пред гневом Альянса. Молот Рока был взят в плен и препровождён обратно в Лордерон, как и его разбитые кланы.",
    ["47a9b388"] = "Огромная тень появилась в небе Нордскола. Саргерас, король демонов и повелитель Пылающего Легиона, явился перед Эгвин, горя адским пламенем. Он сказал юной Хранительнице, что время Тирисфаля истекло и мир скоро падёт перед натиском Легиона.",
    ["47bad38b"] = "Антонидас предположил, что спокойствие орков вызвано не болезнью, а отсутствием чёрной магии, которая превращала их в грозных и безжалостных воинов.",
    ["47d55e19"] = "Древо Жизни связывало всех ночных эльфов-друидов, включая Малфуриона, с Изумрудным Сном. Заключая договор с драконами, они согласились периодически засыпать на целые века, чтобы их духи могли блуждать по бесконечным тропам сна Изеры. Конечно, друидов печалило то, что придётся потерять столько лет своей жизни, но, тем не менее, они самоотверженно пошли на эту сделку.",
    ["480d04bb"] = "Ажек и сэр Эрлгедин стояли наготове, направив ружья в сторону колючего кустарника у подножия раскачивающихся деревьев. Полуденное солнце нещадно палило. Капля пота медленно скатилась по виску Эрлгедина, когда он взводил курок. В момент щелчка из кустов на поляну выпрыгнула огромная чёрная пантера – невероятно грациозное животное.",
    ["484c1445"] = "Субстанция изгнанников: Эта субстанция может быть получена путём слияния трёх оберегов элементалей – изгнанников с Нагорий Арати. Собери с духов Громовой, Пылающий обереги и оберег Гребня, а затем помести по восемь штук каждой разновидности амулетов в мой котёл. Из смеси этих оберегов получится субстанция изгнанников.",
    ["486f3f7e"] = "Келю и его подданным не оставалось ничего, кроме как отправиться в Запределье вслед за леди Вайш и сразиться с Майев, которой удалось снова поймать Иллидана. Объединив силы, наги и эльфы крови справились с Майев и освободили его. Обосновавшись в Запределье, Иллидан начал копить силы для следующего удара по Королю-личу и его цитадели Ледяной Короны.",
    ["48cfe23f"] = "Адмирал Бареан Вествинд. Командующий флотом Алого марша. Гражданин Кул-Тираса. Пропал без вести у берегов Нордскола.",
    ["48dafba3"] = "Со временем Ценарион стал другом Шу'хало и рассказывал им о мире. Дети земли назвали его своим братом и поклялись помогать ему в заботе о полях жизни и любимых созданиях Матери-Земли.",
    ["48fc54fe"] = "РЯДОВЫЕ ЗВАНИЯ ОРДЫ. Высший Сержант. Старший Сержант. Рубака. Разведчик.",
    ["4913db8f"] = "Сообщество собиралось на тенистых Тирисфальских лесах, где высшие эльфы впервые поселились в Лордероне. Поэтому секта была названа \"Хранители Тирисфаля\". Смертные поборники, избранные быть Хранителями, получали огромную силу эльфийской и людской магии. Хотя одновременно мог существовать только один такой поборник, Хранители были настолько могущественны, что могли и в одиночку расправиться со шпионами Легиона, где бы они их ни находили.",
    ["4955a294"] = "Король-лич Нер'зул знал, что времени у него мало. Заключённый в Ледяном Троне, он подозревал что Кил'джеден попытается уничтожить его. Заклятие Иллидана необратимо повредило Трон, и с каждым днём Король-лич становился всё слабее. В надежде на спасение он призвал к себе своего величайшего смертного слугу – рыцаря смерти Артаса.",
    ["498141c9"] = "Праздник Зимнего Покрова. Окончание года среди многих народов Азерота считается временем перемен. Дворфы и Таурены особенно любят отмечать появление Зимнего Покрова, когда земля покрывается белым убранством, провозглашая тем самым время обновления. И хотя сами сказания, сложенные по этому поводу разными народами Азерота, не слишком различны, способы, которыми они воздают почести этим легендам, многообразны, как и придумавшие их народности.",
    ["4a43d995"] = "Легенда гласит, что эти храбрые первопроходцы обнаружили источник Вечности, наделивший их невероятной силой. Есть предположение, что именно от них произошли ночные эльфы, но точно это не известно.",
    ["4a59379f"] = "Эгвин, девушка из народа людей, заслужила одобрение Ордена и получила титул Хранителя. Эгвин эффективно выслеживала и уничтожала демонов, но она очень часто подвергала сомнениям действия патриархального совета Тирисфаля.",
    ["4ac44743"] = "О чём я думал? Возможно, более лучшим был бы вопрос: о чём я думаю, когда пишу письмо, находясь в брюхе великана? Оба вопроса хороши, и ни на один у меня нет сейчас ответа… Следует признать, что моя миссия была не миссией доброй воли. Я пришёл сюда в поисках азшарита, уникального кристалла из южной Азшары. О, я был бы так богат! Ба! А теперь посмотрите на меня...",
    ["4ad39e62"] = "Кроме того, они стали ниже ростом, а их кожа потеряла характерный фиолетовый оттенок. Несмотря на трудности, они смогли противостоять многим неведомым существам, каких в Калимдоре и не видывали. Они нашли племена диких людей, которые охотились в древних чащах. Но самую большую угрозу представляли собой алчные и хитрые лесные тролли Зул'Амана.",
    ["4adce818"] = "Лорд Сильноплечий! Возглавляемое Эдвином ван Клифом братство Каменщиков состояло из лучших строителей среди людей. Каменщики помогали восстанавливать Штормград, разрушенный до основания орками во время Первой войны. ван Клиф и его товарищи были непревзойдёнными зодчими. Их вкус и чутьё отразились в величии Храма Света и Крепости Штормграда.",
    ["4b053a3a"] = "Идеально круглый, от центра до края – локоть длины. -По краю – заклёпки. Серебряные. -В центре – большой шип, диаметр основания – три пальца. Серебряный. -Сам щит из дуба, укреплённый железом. -На наружном ободе выгравировать моё имя – Грингер Грозовая Вершина.",
    ["4b064ba6"] = "Достопочтенный мировой судья Соломон! Оплакиваю павших вместе с вами. Я лично доложу королю о случившемся и надеюсь, что смогу убедить его отправить в Приозёрье подкрепление. Его Величество в последнее время совершенно удалился от дел, и его поступки, признаться, меня удивляют. Надеюсь, это останется между нами. Искренне ваш, Генерал Маркус Джонатан Королевство Штормград",
    ["4b470376"] = "Шли месяцы, и всё больше орков попадали в лагеря для военнопленных. В них стало не хватать места, и Альянс был вынужден строить новые лагеря на равнинах к югу от Альтеракских гор. Чтобы содержать их, королю Теренасу пришлось ввести новые налоги.",
    ["4bc467c6"] = "После того как я вытащил косу, волна изменений прокатилась по шахте. Свет от наших мерцающих факелов заметался, и казалось, что мы больше не контролируем силу нашего голоса. То шёпот звучал, как рёв, мечущийся по туннелям, заставляя зажимать уши руками, то наши крики на расстоянии нескольких шагов переставали быть слышны и становились подобны лёгкому дуновению ветра. Это нервировало, да, но недолго мы пытались понять странную природу этих явлений. Это стало лишь предвестником того, что в действительности изгнало нас из шахты. Воргены.",
    ["4bcdcf4b"] = "Вулкан, известный как Чёрная гора, был окружён Тлеющим ущельем с севера и Пылающими степями с юга. И хотя Тауриссан был убит силами, которые он призвал, его выжившие собратья были полностью порабощены Рагнаросом и его элементалями. До сих пор они остаются в глубинах Чёрной горы.",
    ["4bcee569"] = "Самому мне, наверное, никогда не удалось бы достичь нынешних вершин знания. Я очень благодарен ночным эльфам: без них я мало что сумел бы узнать. Из своего опыта могу заключить, что Аспекты значат для них много больше, чем я предполагал. Однако ночные эльфы бережно оберегают свои тайны, и даже я не могу быть до конца уверен в своей правоте.",
    ["4c15bbdf"] = "Я знаю, насколько судьба королевства Стальгорн зависит от победы или поражения Альянса и насколько велик наш долг перед теми, кто раньше нас прошёл через кровь и страдания Великих войн. И я готов полностью отказаться от всех радостей жизни, чтобы помочь поддержать Альянс и вернуть этот долг.",
    ["4c25bc59"] = "Он всё-таки решил зайти на кладбище Вороньего Холма. Морган несколько часов бродил среди могил. Многие имена на надгробиях были ему знакомы, и чувство отчаяния захлёстывало его всё больше и больше. И вдруг он увидел маленький неухоженный участок с тремя небольшими надгробиями. Ужас обуял его, когда он подошёл поближе. Морган смахнул пыль с самого большого надгробия, чтобы прочесть имя. На камне были высечены буквы, которые сложились в",
    ["4ca92aa6"] = "Но даже при поддержке высшего эльфа Аллерии Ветрокрылой, дворфа Курдрана Громового Молота и опытного воина Даната Троллебоя Кадгар не смог помешать Нер'зулу открыть порталы в другие миры.",
    ["4d037978"] = "Остановив Иллидана, Малфурион и Тиранда вернулись на родину, в Ясеневый лес, дабы охранять свой народ. Однако Майев не согласилась отступить так просто – она последовала за Иллиданом в Запределье, чтобы покарать его.",
    ["4d231d01"] = false,
    ["4d90c329"] = false,
    ["4d9a00c1"] = "ПАЛОЧКА-ПОГОНЯЛОЧКА ДЛЯ ШМЫГУНОСОВ Шмыгунос – поразительное животное. Мало того что к нему может привязаться и полюбить его даже самый злобный долгоног, он может почуять запах корней синелиста за пятьдесят метров! Если вы пожелаете отправить вашего шмыгуноса на поиски корней, то вам понадобится ваша (продаётся отдельно) запатентованная палочка-погонялочка для шмыгуносов. Инструкция по применению на следующей странице.",
    ["4db0cfc1"] = "Досточтимый господин! До меня дошли слухи, что вы ищете учителя для своих детей. Сейчас я остановился в Златоземье, в таверне \"Гордость льва\" – из-за произошедших в регионе событий мне пришлось покинуть пост директора школы в Луноречье. Я хотел бы стать учителем ваших детей. При необходимости вы можете поговорить с директором Академии Крилланом о моей компетентности.",
    ["4db19fee"] = "Немало могущественных людей услышали зов Короля-лича из Нордскола. Среди них оказался Кел'Тузад, верховный даларанский маг, один из старейшин Кирин-Тора, совета Даларана. В течение многих лет его считали отступником за желание изучать запретные искусства некромантии.",
    ["4dcb7fc1"] = "СУПЕРВАЖНАЯ КАРТА ДАННЫХ С ТРОЙНЫМ КОДОМ Дальше страница испещрена нулями и единицами.",
    ["4e1ceee5"] = "Лорд Сильноплечий! Городской совет Озёр смиренно просит у вас военной помощи. В то время как я пишу эти строки, нас держат в осаде орки Чёрной Горы и гноллы из стаи Темношкуров, прислужнивающие Морганту. Я бы никогда не попросил о помощи, но мы в тяжёлом положении. Мы ожидаем подкрепления из Штормграда, но пока оно прибудет, я прошу вас оказать нам поддержку. Падёт королевство – и все люди будут обречены. Мировой судья Соломон",
    ["4e3ca86c"] = "Кенарий призвал на помощь духов из зачарованного леса и собрал армию древних энтов, которые двинулись на Легион. Когда союзники ночных эльфов встретились возле храма Азшары и источника Вечности, там завязалась ужасная битва. Однако, несмотря на всю помощь своих новых союзников, Малфурион и его соратники поняли, что даже этих сил не хватит на то, чтобы остановить Легион.",
    ["4e6a1fb2"] = "День шестой. Медведь ещё не вернулся; должно быть, я задал ему хорошую трёпку! Но я всё ещё слышу его рычание. Я думаю, он ждёт, когда я умру! Кто бы ни нашёл эту книгу, я прошу тебя. Убей этого грязного медведя. Убей его и отнеси книгу моему другу Молотоногу. Он захочет узнать, что произошло. И возьми мою броню. Она понадобится тебе в бою со старым Паршивым Когтем!",
    ["4e9389e5"] = "Орки были обречены на вечную неутолимую жажду крови и обрушивали свою ярость на любого, кто стоял у них на пути. Гул'дан почувствовал, что время пришло, и объединил воюющие кланы в одну неудержимую Орду.",
    ["4ec0830e"] = "Тем временем в дьявольском мире Дренора новая армия орков готовилась к нападению на ничего не подозревающий Альянс. Бывший наставник Гул'дана Нер'зул собирал оставшиеся кланы орков под своими знамёнами. С помощью клана Призрачной Луны он намеревался открыть на Дреноре несколько порталов, позволяющих Орде проникнуть в новые нетронутые миры.",
    ["4ece7411"] = "Принеси мне эти вещи, Звезду, Руку и Сердце, и Книга Йагина будет твоей. — Джи Би.",
    ["4eff26d4"] = "Во все времена демонические существа пытались проникнуть в мир Титанов из Круговерти Пустоты, и Пантеон выбрал своего самого великого, Саргераса, чтобы он охранял границы миров. Благородный гигант из расплавленной бронзы, Саргерас выполнял свои обязательства несчётное количество тысячелетий, находя и уничтожая демонов везде, где возможно. Спустя века Саргерас столкнулся с двумя мощными демоническими расами, которые были помешаны на получении силы и господства над физической вселенной.",
    ["4f1c77b0"] = false,
    ["4f456546"] = false,
    ["4f557657"] = "От Бароса Алекстона, Городского архитектора, Штормград. Ваше Величество, Есть множество причин, по которым, мне кажется, должен быть составлен и предоставлен рапорт о недавних аферах \"Братства Справедливости\" и их активности в королевстве. Для начала немного истории. Как вы можете знать – а может быть, и нет – моё служение городу Штормград началось в качестве члена гильдии Каменщиков. Спустя годы работы мы закончили восстановление",
    ["4f788679"] = "Я скучаю по своему племени и по дому. Как я тоскую по вольному ветру над равниной, по закатам над Громовым Утёсом! Но кругом только жаркие джунгли... Я вижу поблизости океан, но эти волны не охлаждают ни моё тело, ни мою тоску. Они только напоминают мне о заточении.",
    ["4f797df1"] = "Гоблинское инженерное дело Будучи расой, нейтрально относящейся практически ко всем конфликтам, гоблины сумели сделать науку доходным делом. Они нашли практическое применение инженерному делу, столь очевидное в их великолепно разработанной взрывчатке, огнестрельном оружии и машинах. Гоблинское инженерное дело не слишком заинтересовано в теории, их изобретения обычно не имеют тенденции не работать, скорее уж работают слишком хорошо. Они точно не для слабонервных.",
    ["4f7edb81"] = "За шесть лет хитрые Арати победили и перехитрили все вражеские племена. После каждой победы Арати предлагали завоёванным людям мир и равноправие, таким образом получая верность побеждённых. В конце концов племя Арати включило в себя много других племён, а мощь их армии росла с огромной скоростью.",
    ["4fb07193"] = "Уровень секретности десять в степени десять тысяч. Суперсекретные данные! Дальше страница испещрена нулями и единицами.",
    ["5146732a"] = "Увидев ужасное разрушение и огонь, распространившийся по южным горам, король Мадоран и король Кардрос остановили свои армии и спешно вернулись назад в свои королевства, не желая пасть жертвами ужасного гнева Рагнароса.",
    ["516f3e6e"] = "ДИАГРАММА ЗАПАДНОГО ПИЛОНА",
    ["51ba14ce"] = "Эти тролли, с кожей цвета мха, умели восстанавливать утраченные конечности и залечивать самые ужасные раны. Но это был варварский, злой народ. Империя Амани растянулась по большей части северного Лордерона, и тролли яростно боролись за свои земли, стараясь держать незваных гостей подальше от своих границ. Эльфы всей душой ненавидели злобных троллей и убивали их при любом удобном случае.",
    ["51c65e1d"] = "В эту экспедицию со мной отправились Ажек Руак и сэр Эс Джей Эрлгедин, а также мой верный слуга Барнил Каменный Кубок. С отцом Ажек мы когда-то сражались за Альянс плечом к плечу. Удивительно, как она выросла за это время. Отец хорошо обучил её искусству владения оружием. Её навыки стрельбы из лука настолько хороши, что невольно заставляют задуматься, не течёт ли в её жилах кровь эльфов.",
    ["52234d91"] = "Вулкан, известный как Чёрная гора, был окружён Выжженной тесниной с севера и Пылающими степями с юга. И хотя Тауриссан был убит силами, которые он призвал, его выжившие собратья были полностью порабощены Рагнаросом и его элементалями. До сих пор они остаются в глубинах Чёрной горы.",
    ["52c553d5"] = "Но краккены – древние, очень древние твари. Они помнили времена, когда земля впервые родилась из моря. Они помнили владычество Древних Богов, они помнили, как явились Титаны и низвергли их. Они помнили времена, когда магия была новой. Они стары и помнят много тайн. И хотя заклинание Мин'лота было могущественно, оно, подобно самим троллям, всё же было смертным. И поэтому оно не сработало.",
    ["52fc3d20"] = "Жизнекорень: Он встречается в природе, а также может быть извлечён из тварей Сухой Лозы в Пылевых топях. Его сила будет необходима для привлечения жизненной эссенции Циклониана в этот мир.",
    ["530680db"] = "Распространение сведений производите на своё усмотрение. Тирисфальское региональное командование. Капитан Мелроуз, капитан Вакон, капитан Перрин. Указания даны самим верховным лордом. Капитан Перрин, продолжайте укреплять позицию на юго-западной башне (как уже было сказано). Припасы подвезут позднее. Материалы можно добывать на близлежащих фермах. Не забывайте о разведке и сборе информации.",
    ["5335e398"] = "Страх и решимость Артаса привели его к погибели. Он желал уничтожить угрозу своей земле и ради этого добрался до источника чумы в Нордсколе, но сам пал жертвой могущества Короля-лича. Надеясь спасти свой народ, Артас взял в руки проклятый рунический клинок, Ледяную Скорбь.",
    ["537c101f"] = "Джариен и Сотос, продолжение. И вот они, наконец, начали проходить испытания, обязательные для всех, кто желает присоединиться к Алому маршу. Они хотели, чтобы их приняли в рыцари, а для этого, по-видимому, и испытания были более сложными. И Сотос не смог справиться со своим последним заданием. Но Джариен заступилась за брата и настаивала на том, чтобы ему также позволили стать рыцарем. По нашим сведениям, за такую дерзость Верховный рыцарь Датрохан лишил их жизни прямо у себя в покоях. Посему Кровавый трон в Бастионе Алого ордена, что в Стратхольме, – ещё одно место с привидениями.",
    ["538de565"] = "Журнал механика. (Небольшой журнал в кожаной обложке вымазан маслом и жиром. Наброски чертежей и механических приспособлений сопровождаются подписями и объяснениями. Вы открываете страницу наобум.) Этот заказ прокормит меня на годы вперёд. Только доработаю нейтрализатор колебаний, который то перегревается, то истирается в металлическую стружку. Надо отвести избыток тепла по воронке в ядро сгорания, но я откладываю и откладываю, потому что придётся вскрывать мехаход и разбирать весь двигатель. Страница семнадцать",
    ["53d342f6"] = "Мин'лот ревел, его магия вобрала силу заклинаний его помощников, и Мин'лот направил её на приближающихся краккенов. Море расступилось, и заклинание Мин'лота устремилось к слугам Нептулона. Молния разорвала небо, и заклинание поразило их, и тысячи огненных стрел рухнули вниз. Вода закипела, дно покрылось кратерами. Мин'лот торжествующе вскричал, зная, что его заклинание сразит огромных тварей.",
    ["53fd752d"] = "Покинув Вотчину, я направлюсь в Тысячу Игл, а затем на запад в сторону Таланаара, к границе с таинственным лесом Фералас. Там я найду друида, известного как Хранитель дорог Фалфиндел. Пытаясь узнать прошлое моего народа, я, кажется, наткнулся на что-то большее. Теперь в моих руках – безопасность всего Альянса...",
    ["54020e2f"] = "Несмотря на то что практически бесконечной силы Саргераса с избытком хватало, чтобы победить зловещих эредаров, он был весьма обеспокоен разрушением и всепоглощающим злом, распространяемыми этими созданиями. Неспособный понять такую развращённость, великий титан начал погружаться в отчаяние. Несмотря на свою растущую тревогу, Саргерас всё же избавил вселенную от колдунов, заманив их в ловушку в Круговерти Пустоты.",
    ["5469f284"] = "Пока Тралл был занят освобождением своих собратьев в Лордероне, Нер'зул продолжал строить базу в Нордсколе. Над Ледяной Короной он возвёл огромную крепость, в которой трудились легионы мертвецов. Но нашлась одна империя, готовая противостоять растущему могуществу Короля-лича.",
    ["54deafbb"] = "Частенько последователи Священного Света запугивают тех, кто интересуется настоящей силой, пытаясь убедить их, что тайная магия непознаваема. Но не всё, что приходит извне, является злом. Не всё сущности стремятся подчинить себе других. Если у тебя будет достаточно силы, те же самые сущности станут твоими слугами. Об этом я хотела бы поговорить с тобой. Жду тебя на кладбище справа от аббатства. -Друзилла ла Салле, наставница чернокнижников",
    ["54e11849"] = "Когда представилась возможность, я всадила нож ему в спину! Его лёгкие не выдержали силы удара, и его тело упало на землю с глухим звуком. Это было такое быстрое и молниеносное нападение, что бедный глупец даже не успел закричать от боли. Странно, но когда я вынула нож из его спины, из раны хлынул зловонный запах.",
    ["54ee13b9"] = "Гордая Эгвин хотела родить сына, которому она передаст свою силу. Она не хотела, чтобы Тирисфальский орден манипулировал её преемником так же, как они пытались манипулировать ей. Отправившись в южное государство Азерот, Эгвин нашла идеального мужчину, который мог бы стать отцом её сына – искусного человека-мага по имени Ниелас Аран.",
    ["5526c6eb"] = "Оплата будет произведена обычным способом. И расплатись с подателем сего письма за доставку. Эти деньги можешь прибавить к цене щита. Премного тебе благодарен, --Грингер Грозовая Вершина.",
    ["555f4459"] = "...какое странное и неконтролируемое чувство. Я никогда ещё не чувствовал ничего подобного. Пока я занимался с Джайлсом историей, Тиллоа прогуливалась в палисаднике снаружи. Через несколько минут она вернулась к нам, положила мне в ладонь ярко-красную бегонию и так улыбнулась мне, что у меня чуть сердце не выскочило из груди...",
    ["5565a54b"] = "ОФИЦЕРСКИЕ ЗВАНИЯ ОРДЫ. Часть один. Верховный Вождь. Генерал. Лейтенант-генерал. Защитник.",
    ["55e5af02"] = "Йорген, мои худшие ожидания оправдались, сбылось то, чего я и представить не мог. Я никогда не думал, что они подберутся так близко, но это случилось. Пожалуйста, помоги подателю сего письма и отправь его к НЕМУ. Откровенно говоря, я думаю, что он поможет нам из-за серьёзности этого дела. Если бы нам грозило что-то другое, он, возможно, так и не обратил бы внимания на нас и на проблемы нашего славного города. Спасибо тебе, старый рыбак. Я, как обычно, у тебя в долгу. Твой друг Делавей",
    ["567c7025"] = "Когда Кель понял, что не сможет найти средство от магической зависимости своего народа, он совершил непоправимое. Вспомнив об общих предках-высокорожденных, он встал на сторону Иллидана и его спутников-наг. Остальные предводители Альянса объявили эльфов крови предателями и изгнали их навсегда.",
    ["569c2df1"] = "В память о моём дорогом учителе, Горацио М. Монтгомери, докторе медицины, целителе, учителе, друге. Пятьдесят би-ти-эф-ти – двадцать пять эй-ти-эф-ти \"Мир полон боли и тягот. Наша задача как целителей, НЕТ – мужчин или женщин, отдавших себя медицине, очистить его от всех болезней.\" - Почётный работник медицины, доктор медицины, доктор философии, доктор юридических наук, Великий Фермер, Экстраординарный Танцор, Друг Животных",
    ["56a8f44a"] = "Тому, Кого Это Касается. Если ты читаешь это письмо, то я могу лишь предположить, что ты в двух местах: (один) На южном полуострове Азшары. (два) В брюхе скального великана. И то, и другое одинаково нежелательно. Следует заметить, что я некогда был в первом, а теперь – во втором.",
    ["56b6c2f1"] = "Глава один: СЕВЕРНЫЙ ПИЛОН. Северный пилон принимает жёлтые, красные и зелёные кристаллы. Пилон фокусирует энергию, которая возникает при использовании жёлтых кристаллов в качестве основного источника энергии.",
    ["56ef770e"] = "ДИАГРАММА ЗАПАДНОГО ПИЛОНА",
    ["57193d7b"] = "Зная Эдвина ван Клифа всю свою жизнь, я могу сказать, что видеть в нём своего врага мне неприятно. Понимаете, он был моим другом детства, и я лично наставлял его в магии Теней, надеясь, что однажды он будет работать вместе со мной. Если ван Клиф стоит во главе Братства Справедливости, то да помилует Свет наши души! Мастер Матиас Шоу Гильдия убийц Штормграда",
    ["572508fd"] = "Ажек не понадобилось много времени, чтобы выследить пантеру; она ушла на юго-запад. Мы шли быстрым шагом, с оружием наготове, и уже предвкушали успех. Треск веток, донёсшийся из рощи неподалёку, немедленно привлёк наше внимание. Там кто-то был. Одного взгляда на Барнила хватило, чтобы он понял меня. Он медленно опустил винтовку. Эта добыча – не для нас, а для наших спутников-людей. Сколько пантер уже погибло от наших пуль! Нет, эта добыча – не для нас.",
    ["57963e57"] = "Когда Медиву было четырнадцать, в нём проснулась великая сила, которая не могла ужиться с дремлющим внутри него духом Саргераса. Медив впал в глубокий сон, продлившийся не один год.",
    ["57ca42d2"] = "Агашам! Вместе мы будем гораздо сильнее, чем все племена тауренов вместе взятые! Всё же мы настаиваем на вашем полном подчинении. Помните, ваш народ получит вознаграждение только после воплощения наших замыслов! Подпись: Вестник Рекс",
    ["58894742"] = "Сбалансированная шпага Сталлинна- И последнее: я хочу вернуть одну из моих лучших кузнечных работ. Эта шпага – невероятное оружие, и я подарил его тому, кого я считал весьма благородным и великим воином. В общем, его побил мурлок по имени... как его там, Джаркай? Как-то так. Он подвергся атаке этого чудища во время своего путешествия по берегу Болота Печали. Он проиграл сражение и, видимо, обратился в бегство, оставив оружие в лапах мурлока.",
    ["58941db2"] = "...меня переполняют гнев и ярость! Да как она смеет! Пока я занимался с Джайлсом арифметикой, вошла Тиллоа с каким-то ухажёром, они невинно держались за руки! Какой-то неотёсанный молодой человек. Вместо того чтобы представить меня как подобает, Тиллоа просто сказала: \"О, это мой учитель, дядя Сталван\". Дядя! Услышав такое, я почувствовал как пылают мои щёки. Я всего лишь на несколько лет старше! И ещё... это предательство...",
    ["58c3faec"] = "Грандиозные битвы Второй войны сотрясали море и воздух. Каким-то образом Орде удалось завладеть могущественным артефактом – Душой Демона – и с его помощью подчинить себе Алекстразу, древнюю королеву драконов. Угрожая уничтожить отложенные ею яйца, Орда заставила Алекстразу отправить своих детей на войну. Благородные красные драконы были вынуждены сражаться на стороне Орды, и сражались они превосходно.",
    ["58cb2d7a"] = "Поэтому они решили скрыть свои земли защитным барьером, который позволял бы им спокойно заниматься магией. Они установили в разных точках Кель'Таласа, на границах магического барьера, цепь Рунических камней. Рунические камни не только скрывали магию эльфов от внеземных угроз, но и помогали отпугивать суеверных троллей.",
    ["58e6eb6d"] = "Даже практически оставшись без сил, Артас сумел опередить Иллидана и первым добраться до Ледяного Трона. Своим рунным мечом, Ледяной Скорбью, Артас разрушил ледяную тюрьму, а потом забрал из неё зачарованный шлем и доспехи Нер'зула.",
    ["59288f69"] = "Наши планы продвигаются споро; как я уже упоминал, мы заключили союз с группой людей, называющих себя Синдикатом. Их лидеры когда-то принадлежали к Альтеракской знати, и они жаждут вновь править там. Итак, они заключили с нами сделку. Сделку, о которой они пожалеют.",
    ["597b7256"] = "Скажи-ка мне, герой, ты когда-нибудь слышал боевой клич орков? А может быть, ты защищал свой дом от гноллов, желающих перегрызть глотку тебе и твоим близким? Жутковато звучит, не правда ли? Что ж, тебе пригодится моя помощь. Меня можно найти в североземском аббатстве. Мои знания стоят недёшево, но если ты достаточно опытен, я могу научить тебя приёмам и хитростям, которые помогут тебе защищать Штормград и наши земли. Ллан Бишер, наставник воинов",
    ["59a6f36e"] = "*(Из-за пятен возможно прочесть лишь часть журнала.)* Ульдаман, День три Поверить не могу, как я был глуп. Эти злобные дворфы Кузни теней провели меня, как простачка. Мои раны заживают медленно, я безусловно отравлен ядом. Я чувствую, как мои силы тают. Несмотря на это я должен двигаться вперёд... ...хуже того, ожерелье, что сделал для меня гном, треснуло! Три его самых больших драгоценных камня потеряны. Я должен найти их, без них ожерелье будет лишено всей своей силы.....",
    ["59c5c67e"] = "Прошло время, и Ценарион стал сильным, как его великий отец. Брат деревьев и звёзд, этот великий охотник странствовал по миру, напевая умиротворяющую песню рассвета. Всё живое склонялось перед его грацией и красотой. Никого на свете не было мудрее сына луны и белого оленя.",
    ["59ec350a"] = "Два королевства некоторое время поддерживали довольно тесную связь, но на клан Громового Молота слишком сильно повлияли ужасы, свидетелями которых дворфы стали у Грим Батола. Вместо того чтобы создать огромное подземное царство, они обжили склоны Заоблачного пика. Идеологические различия между двумя оставшимися кланами дворфов в конце концов привели к отчуждению.",
    ["5a025a0e"] = "Клинфран Безумный: Он блуждает по Пылающим степям. Приближайся к нему с осторожностью и вынуди его показать истинное лицо.",
    ["5a163554"] = "Ночные эльфы разрушали укрепления троллей и препятствовали снабжению их войск. Бессильные перед магией, тролли проигрывали битву за битвой. Сравнившись в жестокости и хитрости с троллями, ночные эльфы навлекли на себя вековечную ненависть последних. Прошло несколько лет, и от империй Амани и Гурубаши остались жалкие осколки.",
    ["5a524ed4"] = "Гномское инженерное дело Раса гномов достигла несравненных успехов в разработке предметов, манипулирующих и управляющих окружающим их миром. Несмотря на то что они обычно стремятся к совершенствованию взрывчатых веществ и оружия, их инженерное дело также сосредоточено на предметах, которые, буквально говоря, делают жизнь проще и удобнее. Эта наука о теоретических возможностях переделки реальности в соответствии с технологией гномских ноу-хау. Некоторые возможности, как бы то ни было, никогда не получится полностью реализовать.",
    ["5a792831"] = "Архиепископ Алонсус Фаол. Благосклонный покровитель Храма Света. Несмотря на то что архиепископ Фаол начал свой светлый путь в лордеронском Стратхольме, он всегда был другом Штормграда. В тёмные времена после Второй войны он помогал монастырю в Североземье и жертвовал значительные средства на восстановление самого города. Сей храм стоит не только как бастион Света, но и как памятник благородному духу и щедрости этого человека.",
    ["5aa4c38e"] = "Они стояли, замерев, а она спокойно смотрела им в глаза. И тогда один из всадников посмотрел вверх, как будто услышал далёкий зов. Он вытащил из-под одежды небольшой камень и заглянул в него. Затем он жестом указал на него жене Свена. Свет полился из всадника в сторону женщины, формируясь в страшную белую руку. Она решительно смотрела на этот свет, но я видел неуверенность за её маской спокойствия. Когда рука достигла её, она обхватила пальцами голову женщины. И сжала её.",
    ["5aaf18e4"] = "Со временем любопытство ночных эльфов привело к тому, что они повстречали и подружились с самыми разными могущественными существами, не последним из которых был Кенарий, могучий полубог древних лесов. Благородному Кенарию пришлись по нраву любознательные ночные эльфы, и он потратил много времени на то, чтобы рассказать им о силах природы. Мирные кальдорай прониклись большим сочувствием к живым лесам Калимдора и наслаждались гармонией природы.",
    ["5ad13e00"] = "Привет и поклон вам, искатели приключений! Мне, Кринкелю Сталлинну, необходима помощь желающих рискнуть своей жизнью ради выполнения некоторых моих трудных поручений. Поскольку у меня множество обязанностей и я загружен взвалившейся на меня работой, я уверяю, что любому, достаточно смелому, чтобы собрать необходимые предметы из данного списка и принести их мне, будет выплачена солидная премия. Список включает в себя следующие страницы...",
    ["5ad78d9b"] = "Морган Ладимор был известным и благородным рыцарем, защищавшим невинных, бедных и страждущих. Многие годы он усердно сражался в отдалённых районах Азерота, помогая угнетённым и творя правосудие над их угнетателями. Когда ему исполнилось восемнадцать лет, он женился на молодой девушке по имени Лиис. Они очень любили друг друга, у них было трое детей: сын и две дочери. Моргану было тридцать два года, когда в Лордероне началась",
    ["5b06f155"] = "Если какой-нибудь представитель разумной формы жизни найдёт это письмо, пусть он спросит себя:\"Какого черта они возятся с этими злобными десятиметровыми великанами?\" -Муук",
    ["5b64f572"] = "Эта наковальня является собственностью Джордана Стивелла – Просьба НЕ трогать! - Джордан",
    ["5b6cfa38"] = "Теперь ты в хороших руках. Джен'шан знает, что ты любишь охотиться, и готова тебя научить… если ты будешь слушать. Приходи в Долину Испытаний. Джен'шан будет учить тебя охотиться и покажет, какими могущественными бывают настоящие охотники. -Джен'шан, наставница охотников",
    ["5b70d970"] = "Тварь, о которой я пишу, – это ворген. О воргенах часто рассказывают в сёлах – какой же ребёнок с фермы не слышал сказок о людях-волках, бродящих по лесам и болотам у его родной деревни? В таких сказках может скрываться и правда – возможно, так нас предупреждают о воргенах, пугая страшными небылицами.",
    ["5baa8c26"] = "Приветствую тебя, молодой герой. Ветер нашептал мне, что ты пришёл. Земля рассказала о твоей силе. И теперь древние духи говорят о том, что ты готов учиться. Наш народ нуждается в мудрых и могущественных наставниках – и находит их среди нас. Если хочешь, я научу тебя большему. Ищи меня в Лагере Нараче на плато Красного Облака – нам есть, о чём поговорить. -Мила Рассветная Странница, наставница шаманов",
    ["5bb0c5be"] = "Чернокоготь-- Море ждёт нас. Нам нужны ресурсы с севера. Несите все: рельсы, вёдра. Нам нужен металл. Ожидается прибытие груза из Пиратской бухты, но поставка задерживается. Потрудитесь как следует, Чернокоготь! В этот раз посылайте припасы прямо в \"амбар\". Времени в обрез. --ван Клиф",
    ["5c26e202"] = "Когда пришло время, Кил'джеден объяснил Королю-личу, зачем тот был создан. Нер'зул должен был распространить в Азероте смертоносную чуму, которая истребила бы расу людей. Заразившиеся этой чумой умирали и превращались в нежить, отдавая свои души во власть железной воли Нер'зула.",
    ["5c27b66e"] = "Нер'зул и верный ему клан Призрачной Луны прошли через самый большой из открытых ими порталов, в то время как извержения вулканов начали разрывать континенты Дренора на части. Кипящие моря вознеслись к небу и обрушились на землю: мир орков исчез во всепоглощающем пламени гигантского взрыва.",
    ["5c95d3d7"] = "Жаровня вызывания духов: инструкция к использованию. Где найти места с привидениями Вступление. На этих страницах написано, где можно найти падших духов и призраков, участвовавших в событии, связанном с амулетом Лорда Вальтхалака. Ты уже спас моих бывших товарищей, но, боюсь, отголоски того зла, что поработило их души, ещё не покинули эти места. Таково могущество злобного духа Лорда Вальтхалака. С помощью жаровни также можно вызвать Лорда Вальтхалака, но нужно соблюдать крайнюю осторожность.",
    ["5d18afb3"] = "К сожалению, адмирал Праудмур умер в бою, не успев помириться с Джайной и узнать, что орки перестали быть кровожадными чудовищами. В награду за помощь орки позволили Джайне и её подданным беспрепятственно вернуться в Терамор.",
    ["5d4b9bb6"] = false,
    ["5d82d969"] = "Войско Плети под предводительством Артаса вторглось в Кель'Талас и окружило немногочисленную армию эльфов. Сильвана Ветрокрылая, предводительница следопытов Луносвета, храбро вступила в неравный бой с врагом, но Артас истребил всю армию высших эльфов и добрался до Солнечного Колодца. В подтверждение своего превосходства безжалостный Артас воскресил Сильвану как банши, чтобы она вечно служила поработителю Кель'Таласа.",
    ["5d87c16d"] = "Глядя правым оком на золотой рассвет, Мать-Земля распростёрла свои нежные руки над золотыми равнинами. Там, где легла тень от её рук, из земли восстал благородный народ. Это Шу'хало, наречённые тауренами, вышли вознести благодарность и молитвы своей любящей матери. Там, в бескрайних полях рассвета, дети земли поклялись восхвалять её имя до скончания времён.",
    ["5d8c01f6"] = "Орман из Стромгарда. Первый капитан-генерал Алого ордена. Гражданин Стромгарда. Пропал без вести на леднике Ледяной Короны.",
    ["5d990727"] = "Полчища нежити продолжали своё шествие по землям Лордерона, и принц Артас, единственный сын Теренаса, решил выступить против них. Артасу удалось убить Кел'Тузада, но ряды нежити пополнялись с каждым павшим солдатом, защищавшим свои земли. Враги казались непобедимыми, и Артас впал в отчаяние; ему пришлось идти на крайние меры. В конце концов он узнал от солдат, что начал терять свои человеческие качества.",
    ["5d9be801"] = "Вчера он впервые сумел заговорить. Он, друид по имени Гералат, послан в эти земли, чтобы проверить слухи о павшем боге-вепре. Слабеющим голосом он поведал мне, что считал, будто бы огромный кабаний череп лежит на том самом месте, где великий бог-вепрь Агамагган пал в битве с Пылающим Легионом примерно десять тысяч лет тому назад, во время Войны Древних. Земля превратилась в равнину там, где рухнула его массивная туша, а кровь бога-вепря впиталась в почву – и там, куда пала кровь, растут острые шипы...",
    ["5e1952d8"] = "Именно Гул'дан повинен в том, что шаманские знания в кланах пошли на убыль. Он обещал всем могущество и власть над врагами, и его охотно слушали. С помощью Кил'джедена Гул'дан начал манипулировать кланами. Орки, некогда благородные, превратились в злобных и неразумных дикарей. Когда же в их жилы попала кровь демонов, орки стали ещё более безжалостными и одержимыми.",
    ["5e45fd44"] = "Пребывание в брюхе великана способствует размышлению. Пока моё тело постепенно кристаллизируется, я размышляю над своей жизнью в Вечной Песне, вспоминая бесконечные приключения на диких просторах великого моря. Я был молод. И глуп. Если я как-нибудь отсюда выберусь, то займусь фермерством или резьбой по дереву. - Ветран Шей",
    ["5e6885c0"] = "Заточённый в ледяной тюрьме Нер'зул почувствовал, что возможности его разума возросли тысячекратно. Наделённый огромной силой демона, он стал невероятно могущественным духом. В этот момент орк по имени Нер'зул перестал существовать, и на свет явился Король-лич.",
    ["5e945e20"] = "Шахтёр Оруэлл Крупный долг. Выплата долга состоится после поставки руды из Лазурного рудника. Шахтёр Фитцджеральд Крупный долг. Выплата долга состоится после поставки руды из Лазурного рудника. Гражданин Недранд Все задолженности выплачены. Гражданин Мэй Все задолженности выплачены. Старшина Бондс Крупный долг. Выплата долга состоится после поставки руды из Лазурного рудника.",
    ["5e9e831a"] = "Сила Хранителя была столь велика, что только Совет Тирисфаля мог отбирать достойных этого титула. Когда Хранитель становился слишком стар или уставал от этой тайной войны против хаоса, Совет выбирал нового защитника и при определённых условиях формально передавал силу старого Хранителя новому.",
    ["5ea8f88c"] = "Ваша честь-- С сожалением сообщаю, что в настоящее время Ночной Дозор не может покинуть свой пост в Темнолесье. Возможно, вы ещё не знаете, но Штормград больше не оказывает военной поддержки нашему региону. Ночной Дозор был создан и подготовлен для защиты Темнолесья в отсутствие поддержки Штормграда. Без защиты Дозора город будет уничтожен. Желаю удачи. --Лорд Элло Чернодрев",
    ["5ec865b5"] = "РЯДОВЫЕ ЗВАНИЯ АЛЬЯНСА. Старший Сержант. Сержант. Младший Сержант. Капрал. Рядовой.",
    ["5f3c16fe"] = "Этот неповреждённый скелет птерадона был найден в далёком Кратере Ун'Горо. Исходя из структуры скелета, был сделан вывод, что подобный вид существ никогда раньше не встречался. Этот скелет, вероятно, был погребён под слоями плодородной земли этого региона много столетий назад.",
    ["5f4039c1"] = "Кел'Тузад спустился глубоко под замёрзшую землю и добрался до сердца ледника. Там, в бесконечных ледяных пещерах, он преклонился перед Ледяным Троном и преподнёс свою душу тёмному повелителю нежити.",
    ["5f53ed57"] = "Назвав себя дворфами, последние земельники покинули Ульдаман и отправились исследовать мир. Их по-прежнему влекли уютные и безопасные подземелья, а потому они основали огромное королевство под самой высокой горой.",
    ["5f978d39"] = "Пытаясь спастись, великий олень прыгнул на небо, но зацепился могучими рогами за звёзды. Как ни старался Апа'ро вырваться, ничего у него не вышло. И тогда его нашла Му'ша, которая гналась за своим братом Ан'ше. Она увидела, как могучий олень борется за свою свободу, и тотчас же влюбилась в него.",
    ["6009ca82"] = "Из-за предательства Гул'дана Молот Рока потерял почти половину своих воинов и был вынужден отступить, выпустив из рук столь близкую победу.",
    ["60139ee2"] = "Это ростовая копия скелета Щелкозуба. Легендарный баран был чудом Каз Модана и объектом многих историй дворфийского фольклора. До сих пор экологи не способны объяснить огромный размер барана и его физическую выносливость.",
    ["60458278"] = "Некоторые считали, что виной этому какое-то заболевание, которому подвержены только орки. Но верховный маг Антонидас из Даларана предложил другое объяснение. Изучив те немногие материалы по истории орков, которые ему удалось найти, Антонидас узнал, что несколько поколений этого народа находилось под влиянием демонов.",
    ["608214c3"] = "День первый. Мой танк сломался, но я знаю, что залежи руды хирона – где-то в этих холмах. Я велел Большеногу оставаться и присматривать за нашими танками. Продолжил поиск в одиночку. Если я не смогу вернуться назад, то журнал останется моим последним завещанием. Бурон Хилдельв, пилот. Паровая бригада Стальгорна.",
    ["608bc22b"] = "Иллидан тоже пережил Раскол и добрался до вершины Хиджала намного раньше Малфуриона и ночных эльфов. Он был одержим идеей сохранить в этом мире магию, поэтому вылил в горное озеро драгоценную воду из Источника Жизни, которую хранил в нескольких сосудах.",
    ["60e8c3b0"] = "Скоро Анахронос понял, что даже могущественные Бронзовые драконы не смогут сдержать напор киражских войск. На место каждой полусотни насекомых, изничтоженных его дыханием, вставала сотня новых. Видя, как трудно приходится ночным эльфам, и понимая, что перед ними маячит угроза отступления на север, в глушь Фераласа, Анахронос решил, что надо предупредить детей Аспектов.",
    ["60ffa902"] = "Под контролем Гул'дана и Совета Теней орки стали грубыми и жестокими. Они построили огромные арены, где соревновались друг с другом в умении сражаться и убивать. В это время вожди некоторых кланов решили высказать своё негодование по поводу упадка их расы.",
    ["610e2c26"] = "Нелтарион: Нелтарион, названный при рождении Землестражем, был предан Азероту сильнее, чем кто-либо из других Аспектов. Его чёрные драконы создали горы и прочие возвышенности, включая и границы между землями смертных народов. До сих пор неизвестно, что толкнуло его в пучину зла: внешнее ли влияние, внутренняя ли слабость. Интересно знать, причастны ли к этой порче, которой подвергся великий чёрный дракон, Древние Боги.",
    ["618a3efc"] = "Изучение инженерного дела Гномы и гоблины столь яростно защищают свои знания друг от друга, что невозможно получить доступ к обоим направлениям этой науки одновременно. Каждая раса, независимо от её политических союзов, даёт доступ к знаниям лишь тем, кто согласен отказаться от стремления заняться другим направлением науки. Если ученик выбирает гномское инженерное дело, например, то ни одного урока гоблинского инженерного дела он никогда не получит.",
    ["61eeb0d7"] = "Меня грубо затащили в какие-то жутко колючие заросли под названием Лабиринты Иглошкурых. Меня бросили в убогую хижину и держали в плену вместе с умирающим ночным эльфом. У меня не осталось ничего, кроме этого дневника, пера и карманных часов... Кто-то идёт...",
    ["639fc24e"] = "По мере того как могущество Высокорождённых и самой Азшары росло, в их характере наметились явственные изменения. И без того высокомерные и холодные, представители высшего класса становились всё более чванливыми и жестокими по отношению к соплеменникам. Некогда завораживающую красоту Азшары окутал тёмный покров. Она начала отдаляться от любящих подданных и не хотела общаться ни с кем, кроме своих доверенных жрецов из числа Высокорождённых.",
    ["63bebeb0"] = "Мне нужен заряженный молнией жезл. Чтобы заполучить такой, собери десять тотемных палочек у троллей из племени Сухокожих в Нагорьях Арати. Принеси палочки к Внешнему Кругу, кругу из камней на этом самом нагорье. Положи палочки на центральный камень круга и подожди, когда в них ударит молния. Когда это случится, заряженный молнией жезл будет готов.",
    ["6424f0f1"] = "Ну что, друг, доставь-ка вот письмо Франгу в Долину Испытаний. Он обычно рядом с Логовом, гоняет там новобранцев, чтобы стали достойными воинами Орды. Ему нужны ловкие бойцы вроде тебя, чтобы показать оркам, как можно драться без грубой силы. Ты быстрее и ловчее многих там, но не очень-то бахвалься – орки оскорблений не любят. Друзья они хорошие, может, ещё и научат тебя чему полезному. -Тар-сир",
    ["642c19be"] = "РЯДОВОЙ И СЕРЖАНТСКИЙ СОСТАВ АЛЬЯНСА. Старшина. Старший сержант. Капрал. Рядовой.",
    ["646499dc"] = "Дорогой дневник, я обнял прислужника и сказал, что очень им доволен. Теперь мне лучше. Только никому ни слова, дневничок. Так о чём я? Ах, да, НАРАЙН! Р-р-р!!! Ненавижу его. Ведь это он так выделывался на каждом экзамене, когда мы учились в Гномреганском Институте Механики. Отчислили меня, значит? Гномреган, насколько мне известно, получил по заслугам! На сегодня всё. Спокойной ночи, дневник!",
    ["64be8481"] = "Симон Совратительница: Ты застанешь её за осквернением Кратера Ун'Горо. Не поддавайся на её уловки. Приближайся к ней с осторожностью, а потом вступай в бой.",
    ["64ff1aea"] = "С уходом своих своевольных собратьев ночные эльфы вновь стали оберегать свою зачарованную родину. Друиды, чувствуя, что скоро должны уснуть, готовились ко сну и прощались со своими родными и близкими.",
    ["6517e09a"] = "Глава три – Четыре командора Если ты следовал мудрым советам этого руководства, то сейчас двое из командоров Дрек'Тара уже мертвы. Так держать, солдат! Решимость врага уже пошатнулась. Теперь нужно окончательно разделаться с командным звеном неприятеля и убить двух оставшихся командоров. Когда будут убиты все четыре командора, в рядах легионеров Северного Волка, охраняющих Крепость Северного Волка наступит сумятица – ведь командовать ими будет некому. Можно брать голыми руками!",
    ["652566a6"] = "После битвы в Крепости Штормграда лорд Лотар собрал остатки армий Азерота и организовал отступление к берегам северного королевства Лордерона. Главы семи человеческих народов решили, что если Орду не остановить, то она уничтожит всё человечество, и создали союз, позже получивший название Лордеронский Альянс.",
    ["6525caaa"] = "Ульдаман, День семь ...последний шанс исправить мои ошибки. Мне кажется, рубин находится за последней баррикадой дворфов, которую они построили против троггов. Несомненно, они сражаются за камень и другие артефакты, найденные здесь, и их постоянно атакуют. Похоже, эти презренные дворфы прячут его где-то у себя. Как бы то ни было, я должен выбрать, куда мне идти дальше. Возможно, бешеный рывок к выходу – самый лучший способ...",
    ["654e8b42"] = "Не представляют для нас реальной угрозы до тех пор, пока мы не нарушаем их границ. Возможно, народу дворфов неприятна сложившаяся ситуация, но, учитывая дефицит военных сил, будет благоразумнее перенести решение этой проблемы на более поздний срок и бросить все усилия на борьбу с троггами и дворфами Чёрного Железа. В письме вы также найдёте отчёт моего брата Грелина о Старой Наковальне. Подписано: Сенир Белобород",
    ["6562370c"] = "Тем временем остатки Орды боролись за выживание в истерзанных войной южных землях. Гром Адский Крик со своим кланом Песни Войны сумел избежать плена, а вот клан Кровавой Глазницы в полном составе, вместе с вождём Мёртвым Глазом, был заключён в лордеронские лагеря для военнопленных. Последовала череда бунтов, но начальникам лагерей вскоре удалось восстановить порядок среди заключённых.",
    ["6588dd77"] = "Он полагал, что орки подверглись пагубному влиянию ещё до первого вторжения на Азерот. Демоны ввели что-то в их кровь, и те стали невероятно сильны, выносливы и агрессивны.",
    ["65c75dd9"] = "Как уже упоминалось выше, некоторые воргены хорошо владеют тайными искусствами, и их магия – магия тьмы и зла. Для них обычны проклятия и жуткие яды, так что пусть читатель знает заранее: те, кто столкнётся с воргенскими магами, должны уметь оградить себя от тьмы.",
    ["66338386"] = "Процветание и прошедшие годы не уменьшили ненависти клана Чёрного Железа к своим собратьям. Тауриссан и его жена-волшебница Модгуд начали войну на два фронта против Стальгорна и Грим Батола. Клан Чёрного Железа хотел заполучить весь Каз Модан для себя.",
    ["666840ad"] = "Стражники этой башни, похоже, ослаблены и не могут противостоять моим атакам. При разведке с задней стороны башни патрулирующая её стражница заметила меня и напала. Мне удалось легко её зарезать, своевременно уклонившись и затем ударив её в спину. На шум пришёл её напарник. Стражник подошёл прямо к тем кустам, куда мне пришлось оттащить труп и обыскать его. Мне пришлось подкрадываться к нему медленно и осторожно, чтобы меня не обнаружили.",
    ["67706253"] = "После этого всадник поник, как будто чей-то дух покинул его. И тогда прежним визгливым голосом старика он произнёс последние слова: \"Повелитель сказал своё слово. Убить их\".",
    ["67d1ec3f"] = "Постарайся принять мои слова во внимание. В наше время хитрость и обман распространены везде… даже в нашем славном Подгороде. Каждый, кто сохраняет верность Сильване, вносит свой вклад в славное будущее Отрёкшихся. Мы не владеем магией и не охраняем границы – наше ремесло иного рода. Найди меня в таверне в Могильнике. Там и поговорим. -Давид Триас, наставник разбойников",
    ["67dd208a"] = "Сейчас Король-лич Артас пребывает в Нордсколе. Говорят, что он собирается восстановить Ледяную Корону. Его верный помощник Кел'Тузад командует силами Плети в Чумных землях. Сильвана же со своими Отрёкшимися удерживает лишь Тирисфальские леса – небольшую часть растерзанного войной королевства.",
    ["67df2eba"] = "Наших суматошных выстрелов оказалось достаточно, чтобы дать Барнилу время убежать. Барнил скатился с холма и присоединился к нашей группе. Мы побежали в джунгли, преследуемые стаей свирепых ящеров-кнутохвостов. Охотники превратились в добычу.",
    ["67ef3b98"] = "Я надеюсь, что ни один даларанский волшебник не станет разыскивать воргенов, даже из лучших побуждений. С этими тварями нельзя заключить союз, у них нельзя ничему научиться и нельзя узнать ничего полезного. Будет лучше, если они останутся в своём мире. Ведь если они придут в наш мир и не будут уничтожены – судьба наша незавидна...",
    ["6803b208"] = "Но даже ослепнув, Мать-Земля не могла оставаться безучастной. Ветер доносил до её ушей вести обо-всём, что происходило на рассветных равнинах. Её любящее сердце всегда пребывало с её детьми, как и её великая мудрость.",
    ["6817574c"] = "Я в это время уже начал уставать – и потому развернул ветролет и направился домой, но по пути сделал ещё две остановки. Я пролетел мимо Владыки Каззака и его демонов в Гниющем Шраме (он этого терпеть не может) и сбросил груз в трубу Ониксии. Устал. Пойду спать.",
    ["683202e3"] = "Хотя смертные расы и одержали победу, их мир был растерзан войной. Плеть и Пылающий Легион практически уничтожили все народы Лордерона и почти закончили свою работу в Калимдоре. Леса нуждались в восстановлении, обиды – в забвении, а разорённые земли – в новых жителях. Война нанесла тяжёлые раны каждой из рас, но все они нашли силы объединиться и начать новую жизнь. Первым шагом к ней было перемирие между Альянсом и Ордой.",
    ["683527eb"] = "То, что я узнал об Аспектах, я привожу здесь для того, чтобы на это могли ссылаться другие. Я знаю, что от моих изысканий будет польза и что эти драконы со временем ещё во многом повлияют на наш мир.",
    ["686fd2ac"] = "Несмотря на то что практически бесконечной силы Саргераса с избытком хватало, чтобы победить зловещих эредаров, он был весьма обеспокоен разрушением и всепоглощающим злом, распространяемыми этими созданиями. Неспособный понять такую развращённость, великий титан начал погружаться в отчаяние. Несмотря на свою растущую тревогу, Саргерас всё же избавил вселенную от чернокнижников, заманив их в ловушку в Круговерти Пустоты.",
    ["68849bb2"] = "Калдорай или ночные эльфы, как их стали называть позже, поклоняются богине Луны, Элуне, и верят, что в дневное время она спит в мерцающей глубине Колодца. В стародавние времена жрецы и провидцы ночных эльфов изучали Колодец с неиссякаемым энтузиазмом, пытаясь раскрыть его тайны и завладеть его силой. Численность ночных эльфов постепенно увеличивалась, и они открывали для себя бескрайние просторы Калимдора, налаживали связи с многочисленными жителями этого материка.",
    ["688a6d98"] = "После смерти Дартола фурболги разделили жезл на три части, чтобы уберечь себя от его воздействия. Найти их будет нелегко, но я знаю, где находится каждая из частей. Самоцвет Первая часть жезла – сверкающий драгоценный камень – была спрятана в святилище на северо-западе Ясеневого леса. От этого святилища остались только развалины, расположенные посреди озера Фалатим. Стражи сообщили мне, что сейчас там обитают мурлоки.",
    ["68aa210a"] = "Трёх служителей кладбища. Когда они попытались его успокоить, он перенёс свой гнев на них и, обвинив их во всех своих несчастьях, убил всех троих. Позже Морган пришёл в себя и увидел свой меч в груди одного из служащих. Осознание произошедшего привело его в отчаяние – он выхватил из ножен кинжал и вонзил его в своё сердце. Тело Моргана Ладимора и тела трёх его жертв были найдены",
    ["68f8ec02"] = "Похлёбка Западного Края Три куска жилистого мяса стервятника Три рыла кровоклыка Три глаза мурлока Три окры Смешать и довести до кипения. Тушить на медленном огне по крайней мере часа два и подавать на стол.",
    ["6932466e"] = "Следует отметить, что податель сего не только помог нам выполнить поставленную задачу, но также участвовал в ликвидации Ивара Нечистого, спасении Эрланда и в доставке данного отчёта. Мы безгранично благодарны ему и хотим, чтобы командование по заслугам вознаградило его за огромный вклад в наш общий успех. Страж смерти Ран Йорик, Командир операции",
    ["6933a220"] = "Постарайся принять мои слова во внимание. В наше время хитрость и обман распространены везде… даже в нашем славном Подгороде. Каждый, кто сохраняет верность Сильване, вносит свой вклад в славное будущее Отрёкшихся. Мы не владеем магией и не охраняем границы – наше ремесло иного рода. Найди меня в таверне в Могильнике. Там и поговорим. -Давид Триас, наставник разбойников",
    ["69590b9a"] = "*(Вы пролистываете ещё несколько скреплённых страниц и попадаете на диаграмму, которая занимает целый разворот.)* Модификации оружейных систем. Ледяная турель – опытный образец. Огнемёт – опытный образец. Электрический пульсатор – опытный образец. Радиационный распылитель – опытный образец. Автоматическое ружьё – опытный образец. Лазерный резак – ПРОТОТИП. Звуковая пушка – ПРОТОТИП. Фазовый луч – В РАЗРАБОТКЕ. Страница тридцать четыре. Страница тридцать пять",
    ["699c8e4f"] = "Тралл взял легендарный боевой молот Молота Рока и надел свои чёрные доспехи; теперь он стал новым предводителем Орды. Следующие несколько месяцев его маленькое неуловимое войско совершало набеги на лагеря военнопленных Альянса; войско Альянса было бессильно против него. Под руководством своего лучшего друга и наставника, Грома Адского Крика, Тралл делал всё возможное, чтобы его народ никогда больше не испытал на себе гнёта рабства.",
    ["699e28d5"] = "Надеюсь, этот знак застанет тебя в добром здравии. Духи поведали мне о твоём приходе, и я сразу же стала писать это письмо. Хочу скорее передать тебе часть моих знаний и направить тебя на верный путь, пока ты готовишься покинуть Тельдрассил для более важных дел. После всего что случилось за последние несколько лет, очень многие народы Азерота нуждаются в нашей помощи. Когда будешь готов, разыщи меня в Альдрассиле, на втором уровне. -Шанда, наставница жрецов.",
    ["69ad8c03"] = "Не пристало скромной жене солдата задавать такие вопросы. Но теперь я пишу вам как скромная вдова солдата. Возможно, для вас мой муж был всего лишь одним солдатом из тысяч. Для меня он был моим ненаглядным Салли Баллу, отцом моих детей и моим единственным спутником в этой жизни. Простите меня, о великий владыка, если мои вопросы кажутся вам неуместными. Но мёртвые не могут сами задать эти вопросы... Ваша верная подданная, Сара Баллу",
    ["69b36293"] = "В качестве последней награды Саргерас пообещал Гул'дану огромную силу в обмен на его согласие повести Орду на Азерот. Через Медива Саргерас сказал чернокнижнику, что может сделать его богом во плоти, если тот найдёт подводную могилу, в которой Страж Эгвин тысячу лет назад укрыла останки Саргераса.",
    ["69b41bc2"] = "Холодной долине и наёмников (нанятых на деньги, выделенные мне старейшиной Сената), Я уверен, что проблема будет решена в ближайшее время. Вся кампания официально одобрена королём Бронзобородом.",
    ["69e91bab"] = "Я приеду, чтобы лично с вами встретиться, когда зимние ливни закончатся и по дорогам снова станет можно ездить. С уважением, Сталван Мистмантл из Серебряного бора",
    ["69ff2582"] = "Глава два – Стылая Кровь и Смотровая башня Когда ты разделаешься с первым слоем \"артишока\", тебе будет открыт второй. Если уничтожить Башни Северного Волка, стоящие у линии фронта, то ослабнут вражеские легионеры и патрули с задних флангов. Эти башни сильно укреплены, и в каждой из них находится по одному из элитных командоров Дрек'Тара. Их надо убить. Так ты ускоришь крах обороны клана Северного Волка.",
    ["6a14d240"] = "Эти дикие кочевники, которых притягивала энергия Источника, построили на его безмятежных берегах свои хижины. Со временем космическая энергия Источника изменила племя, сделав его сильным, мудрым и практически бессмертным. Племя стало называть себя \"калдорай\", что на их родном языке означало \"дети звёзд\". Прославляя расцвет своего общества, поселенцы воздвигли по берегам озера большие постройки и храмы.",
    ["6a18c991"] = "Грелин, у меня мало времени и много забот; надеюсь, ваш интерес к троллям не сильно отвлечёт меня от моих дел. Тем не менее я разрешаю вам ссылаться на меня при необходимости, если вы, разумеется, не станете выходить за рамки целесообразности. Магни Бронзобород",
    ["6a3af636"] = "Глава три – Четыре Командора Третий слой луковицы под названием Грозовая Вершина – четыре Командора. В этом отношении Вандар перенял нашу славную тактику обороны Северного Волка. Сам он, конечно, считает по-другому… Но я отвлёкся. Четыре Командора повелевают Стражниками Грозовой Вершины, неусыпно охраняющими Дун Болдар. Устрани их всех, и Стражники падут. После этого останется лишь один, последний слой.",
    ["6a67e918"] = "Дворфы, от природы любившие придавать формы самоцветам и камню, начали добывать в близлежащих горах драгоценные минералы. Довольные своими подземными трудами, дворфы не стремились общаться с наземными соседями.",
    ["6aa26b69"] = "Обугленные рога: Как и клыки пауков, обугленные рога химер, которые живут в Обугленной долине, что в Когтистых горах в Калимдоре, обладают весьма ценным свойством. Расплющенные и должным образом обработанные, они становятся чрезвычайно стойкими к физическому воздействию.",
    ["6aecd243"] = "В своей ярости Саргерас разрушил темницы, в которых были заперты эредары и Натрезим, и выпустил отвратительных демонов на свободу. Эти коварные существа склонились пред необъятным гневом тёмного титана и предложили служить ему всеми доступными им злокозненными способами. Из рядов могучих эредаров Саргерас выбрал двух предводителей, которых поставил во главе своей демонической армии разрушения.",
    ["6af36ad3"] = "Анналы Дарроушира. Поселение Дарроушир, названное в честь озёра Дарроумир, находится к западу от этого озера на южной границе Лордерона. Известное своими скромными, но трудолюбивыми обитателями, это поселение было ничем не примечательно, пока не началась Вторая война. В ту войну появилось множество героев. И потеряно было немало.",
    ["6b0ae199"] = "Пантера понеслась вдоль опушки леса, а люди ни на секунду не спускали с неё взгляда. Стволы их ружей медленно двигались, оставаясь идеально параллельными друг другу. Барнил посмотрел на меня нетерпеливым взглядом, но я отрицательно покачал головой. Это была охота людей, а не наша. Эрлгедин выстрелил. Раздался оглушительный грохот, но пантера осталась цела. Вероятно, Эрлгедин не был готов к такой мощной отдаче.",
    ["6b0bc572"] = "Элуна услышала мои молитвы. Мои товарищи пали недаром, и коса Элуны поможет мне отомстить за них. Это древняя вещь, ветка, изогнутая и искорёженная, из дерева, которое, должно быть, старше самих калдорай. Много часов я исследовала дар богини. С первого взгляда понятно, что это не обычное оружие и не простое магическое устройство. С ним... словно барьеры времени и пространства ослабели. Держа Косу",
    ["6b237133"] = "Вэллик, Охраняй раба до нашего возвращения. Теперь здесь небезопасно, мы не можем больше хранить его тут. Мы отправимся на север, обходя стороной любые места, где нас могли бы заметить. Они – животные, но животные безжалостные – мы достаточно от них натерпелись, у нас есть причины для беспокойства. Лучше спрятать любые знаки, что могли бы заставить собраться их вместе. Меньше всего мы бы хотели дать им повод воссоединиться и напасть на нас.",
    ["6b4464fe"] = "Лорд Бетор Ледострел, Следуя вашим инструкциям, я отправляю вам агента, которого вы искали. Он и принёс это письмо. Он показал себя заслуживающим доверия и способным следовать приказам, показав себя в бою с силами Плети, и я выбираю его для вашей миссии. Да будет Владычица властвовать безраздельно, Мировой судья Севрен",
    ["6b5bec3a"] = "Хотя когда-то предположение, что человек может прийти в наши земли и учиться у нас, казалось мне смехотворным, этот волшебник, этот злой человек, пришёл сюда и не только выжил, но и обрёл часть наших знаний. Я всё ещё не понимаю, как... Я так и не понял, сам план довольно прост: с помощью магии друидов он хотел подружиться с фурболгами, а затем подчинить их себе. Если это была попытка повредить моим сородичам или совершить что-нибудь зловредное, я надеюсь узнать об этом прежде, чем закончится мой путь.",
    ["6b7536ca"] = "Холодной долине и наёмников (нанятых на деньги, выделенные мне старейшиной Сената), я уверен, что проблема будет решена в ближайшее время. Вся кампания официально одобрена королём Бронзобородом.",
    ["6b872f84"] = "(Глядя на эти страницы, вы чувствуете жгучую боль.)",
    ["6bca6653"] = "Пиршество Обычай устраивать на этот праздник пиршества тянется корнями в глубь самой легенды. Она гласит, что, когда Дедушка Зима шёл по Азероту, укрывая его снегами, тех, кто приветствовал его появление, он осыпал дарами. И потому традиция пировать на Зимний Покров объединила между собой общины, члены которых совместно вкушали на пиру разные яства. Обычно обновление и перерождение земли приветствовали весельем и празднеством в течение целого дня.",
    ["6c5028b0"] = "Битва за Дарроушир Битва за Дарроушир произошла в середине Второй войны, когда силы Плети бесчинствовали по всему Лордерону. Хотя поселение Дарроушир было отрезано от основных сил Альянса, в нём был отряд собственных войск, подразделение паладинов Серебряной Длани, а также местное ополчение, которое возглавлял капитан Джозеф Редпат.",
    ["6c6217e2"] = "Я отдам приказ Многоглазу открыть огонь. Артиллерийский обстрел помешает кораблям Черноводья выходить из гавани и входить в неё. После того как \"Багровый Парус\" разрядит свои пушки, я поставлю его рядом с \"Буруном\" для поддержки и обеспечения резервов, если это понадобится. Когда Солёное Копыто и его парни вычистят город и все наши будут на борту, мы поднимем паруса и ещё разок обстреляем Пиратскую Бухту со стороны Гибельного берега, для очистки совести. --Флотоводец Фираллон",
    ["6c8a2696"] = "Сильвия Вэлор, стражница Вороньего Холма. Сильвия Вэлор прослыла местной героиней задолго до того, как ей предложили вступить в стражу. Больше всего на свете она не терпела тех, кто наживается на чужой беде. Разбойники, мошенники, смутьяны – ей было всё равно. Каждый, кто пытался посеять смуту в её любимом доме, падал от её меча. Неудивительно, что ей доверили настоящую власть, чтобы она вершила правосудие так, как его понимала. Говорят, до последнего вздоха она не покидала фермы и дома Сумеречного леса. А может, не покинула и после.",
    ["6c969d31"] = "Рыцари смерти и последователи клана Призрачной Луны, верные Нер'зулу, также подверглись трансформации: их разорвали на части, а затем превратили в костяных Королей Мёртвых. Демоны позаботились о том, чтобы даже после смерти последователи Нер'зула беспрекословно служили ему.",
    ["6c99452b"] = "Надеюсь, этот знак застанет тебя в добром здравии. Духи поведали мне о твоём приходе, и я сразу же стала писать это письмо. Хочу скорее передать тебе часть моих знаний и направить тебя на верный путь, пока ты готовишься покинуть Тельдрассил для более важных дел. После всего что случилось за последние несколько лет, очень многие народы Азерота нуждаются в нашей помощи. Когда будешь готов, разыщи меня в Альдрассиле, на втором уровне. -Шанда, наставница жрецов.",
    ["6c9fdadd"] = "Мастер Делгрен! Всё так, как ты опасался. Твоя теория о башне Алталакса оказалась верной. В башне собрался культ, среди них много чернокнижников, есть даже сатиры. Они называют себя кланом Тёмной Нити. Я не могу представить себе, какая недобрая цель свела их друг с другом, но это беспокоит меня. Пожалуйста, прости краткость и резкость этого сообщения, но опасность таится в лесу вокруг, и я не могу посвятить много слов описанию происходящего. Я",
    ["6ca4e3e1"] = "*На обратной стороне договора было написано быстрым почерком* Мы припугнули Хмуроброва и получили этот договор. Он может пригодиться, если нам вдруг понадобится их участок. Хмуробровы нам уже не помеха. Последний раз, когда я их видел, они уезжали из Западного Края и остановились, чтобы починить свою повозку.",
    ["6cf1099c"] = "Глава четыре – Укрытия Дун Болдара Как ты, несомненно, заметил, линии обороны Грозовой Вершины выстроены так, чтобы не дать массированному удару сокрушить сразу всю армию. Сразу отвечу на твои вопросы. Да, именно так организована и наша оборона, и нет, менять её расположение я не стану. Они переняли всё у нас, с чего бы нам меняться?",
    ["6cf1eb16"] = "Некоторое время три фракции поддерживали хрупкий мир, однако напряжение возросло, когда король Старая Наковальня скончался от старости. Три правящих клана вступили в войну за контроль над Стальгорном. Гражданская война дворфов многие годы пылала под землёй. В конце концов клан Бронзобородов, имевший самую большую армию, изгнал кланы Чёрного Железа и Громового Молота из-под горы.",
    ["6d3f78aa"] = "Власть Эгвин над космическими силами Тирисфаля росла, и однажды она узнала, что на ледяном северном континенте Нордскол обитает несколько могущественных демонов. Отправившись на дальний север, Эгвин выследила демонов в горах. Там она обнаружила, что демоны охотились на последних драконов и вытягивали из древних существ их магическую силу.",
    ["6d4776d9"] = "Потеря крепости Каменной Стражи стала для нас сильным ударом. Я уже сообщал ранее о союзе между кланом Чёрной горы и чернокнижником Моргантом. Эти орки сражаются с наводящим ужас неистовством, и, похоже, здесь не обошлось без чёрной магии Морганта. Храбрейшие из воинов его величества отдали свои жизни при обороне крепости, но поражение было неминуемо.",
    ["6d4f8ac5"] = "Со временем Нер'зул осознал, что судьба кланов – в руках Пылающего Легиона, и тогда шаман бросил вызов Кил'джедену. Демон, разъярённый поступком Нер'зула, обратился к ученику шамана, Гул'дану, склонить которого ко злу оказалось куда проще, чем Нер'зула.",
    ["6d8ad5b9"] = "Несмотря на тяжёлое детство, Тралл вырос сильным и умным орком; он осознавал, что участь раба – не для него. Повзрослев, он узнал многое об истории своего народа, представителей которого он почти не видел: после поражения в войне практически все орки попали в лагеря для военнопленных. Ходили слухи, что вождю Молоту Рока удалось бежать из Лордерона. И лишь один клан орков всё ещё оставался на свободе, скрываясь от бдительных глаз Альянса.",
    ["6e111cd7"] = "Война. Морган служил под командованием легендарного паладина Утера Светоносного, который сражался с орками и нежитью. Оставив жену и детей, Морган отправился на войну. Шли годы, война затягивалась. Морган стал свидетелем ужаснейших событий, включая расформирование паладинов Серебряной Длани, гибель Утера и эпидемию чумы. Единственная причина, по которой он не сошёл с ума, была уверенность в том, что",
    ["6e24726d"] = false,
    ["6e4f9a34"] = "Джариен и Сотос. Брат и сестра, последователи Алого ордена Я не знаю людей более нетерпимых, чем Джариен и Сотос. Но воины они, надо признать, непревзойдённые, если им хорошо платят; думаю, именно поэтому Антион, глава Тайных клинков, их так ценит. Этих двоих завораживали учения Алого ордена. Мы всегда подозревали, что их родители имели какое-то отношение к этой организации; да и они сами с необыкновенным рвением вступали в сражения с Плетью.",
    ["6e68ae32"] = "Рад, что твоя душа не попала в Пустоту. Я полагаю, ты стоишь усилий, затраченных на написание этого свитка. Помни: людей, которых ты знал и любил, больше нет в живых! Ты должен пронести этот груз через всё своё дальнейшее существование. Советую тебе смириться с этим с самого начала. Если ты готов к испытаниям, найди меня в церкви Могильника. - Тёмный священник Дьюстен, наставник жрецов",
    ["6e94870f"] = "Пока в самом сердце Азшары гремела битва, одурманенная королева с нетерпением дожидалась прибытия Саргераса, который готовился пройти сквозь источник Вечности и самолично ступить на землю Азерота. Его исполинская тень медленно приближалась к поверхности Источника, а Азшара тем временем собрала своих самых могущественных служителей, чтобы они объединили свои силы, прочитали одно заклинание и расширили портал настолько, чтобы Саргерас смог пройти через него.",
    ["6ed9d6c1"] = "Мастер Кэрвин! Принёсший это сообщение осенён благословением Света, может сражаться с мертвецами и демонами, наводнившими пределы Сумеречного леса, и желает присоединиться к семье Кэрвин на их пути к Свету. В моём послании я прошу вас предоставить этому воину Света задание – возможно, это будет поиск горожан, замеченных в помощи врагам Света. С уважением, Калор",
    ["6edb582d"] = "Колокол, Колесо и Свеча Освободившись, Д'жииви разместит Колокол, Колесо и Свечу, после чего появится круг. Так начинается ритуал. Нужно сохранять бдительность: упомянутые предметы испускают мощные потоки энергии и могут разрушиться. Если это случится, скорее используй Чёрный магнит, чтобы восстановить их, прежде чем весь ритуал пойдёт насмарку. Если все три предмета разрушатся прежде, чем ты сумеешь их восстановить, ритуал закончится и его надо будет начинать заново.",
    ["6ee42c86"] = "*Верховный маг Кадгар из Кирин-Тора Бывший ученик Медива.* *Верховный главнокомандующий экспедиции Альянса, которая отправилась на Дренор, родной мир орков.* *Предположительно погиб.* Никто и никогда так самоотверженно не погружался в тёмные глубины магии и искусства войны. Мы желаем тебе добра, смелый странник. Где бы ты ни был. - Антонидас, верховный маг Даларана",
    ["6f2e823e"] = "Глава два: ВОСТОЧНЫЙ ПИЛОН. Восточный пилон принимает синие, жёлтые и зелёные кристаллы. Пилон фокусирует энергию, которая может быть создана при использовании синих кристаллов в качестве основного источника энергии.",
    ["6f335465"] = "Высокий Совет Лордов Бездны Обращаться к Принцу Скальдреноксу, Верховному маршалу Круговерту, Барону Казуму или Лорду Скволу позволено лишь Сумеречным Лордам. Ни при каких обстоятельствах нижние чины Сумеречного Молота не могут начать общение с Высоким Советом. Любой чужак, застигнутый за использованием с этой целью ветровых камней, будет испепелён на месте.",
    ["6f64e6b1"] = "За одним лишь исключением. Странно высеченные идолы, что мы обнаружили недавно (краткое их описание прилагалось к моему последнему докладу), похоже, возымели побочный эффект на троггов на месте раскопок. Их притягивают эти высеченные фигуры, и некоторые трогги впадают из-за них в ярость! Необходимо изучить этих идолов внимательнее, чтобы сделать по поводу них какие либо выводы, но я всё ещё надеюсь, что они прольют свет на связь между троггами и титанами.",
    ["6fb10b04"] = "От капитана Редпата порча перекинулась и на других защитников Дарроушира, которые после этого предавали и убивали своих бывших союзников. Потом они вошли в поселение и перерезали всех, кто укрылся в домах. Остатки армии Плети вместе с чёрной тенью Редпата покинули разорённое поселение и ворвались в Лордерон, неся с собой боль и смерть Второй войны.",
    ["6fc94cce"] = "Поднятая из затопленных руин Сурамара, эта всё ещё работающая астролябия, была создана высокорождёнными эльфами около двенадцати тысяч лет назад. Высокорождённые, одержимые магией, оккультными науками и астрономией, создали множество гениальных инструментов. Это приспособление позволяет нам получить неоценимое представление об уровне развития наук у древних ночных эльфов.",
    ["6ff4e44b"] = "Жители Даларана спокойно отнеслись к деятельности магов и создали бурную экономику под их защитой. Но чем больше и больше магов практиковало свои искусства, тем больше ткань реальности вокруг Даларана слабела и рвалась.",
    ["70238d1a"] = "Призвав на помощь Малфуриона Ярость Бури, свою давнюю любовь, Тиранда укрепила оборону и вынудила Легион отступить. Малфурион заставил саму природу восстать против армий Легиона и Плети.",
    ["703b43d4"] = "Не следует давать новых сведений Торсену. Его нужно убить. Он больше не принесёт пользы нашему полковнику. Я прикончу Торсена, если будет возможность, но если вы получите это письмо, знайте, что пока у меня такой возможности не было. В этом случае я рекомендую, чтобы следующая встреча Торсена с нашими агентами закончилась его смертью. Слава Курцену! Эм.",
    ["70b59b37"] = "Я могу лишь гадать, как я смог выжить в ту ночь. Я всегда был осторожен, всегда быстро уворачивался от ударов и не раздумывая спрыгивал с обрывов. Моё прозвище, Трясунчик, досталось мне из-за этой моей черты. Так что, возможно, лишь эта способность всегда быть настороже спасла меня... Или, возможно, коса, что я вытянул из-под груды щебня. Это не могла быть сама коса, её я потерял во время моего безумного бегства. Но если это я привёл воргенов в Сумеречный лес, то, возможно, воргены отплатили мне неслыханной любезностью. Да будут они прокляты.",
    ["7159e9df"] = "РЯДОВОЙ И СЕРЖАНТСКИЙ СОСТАВ ОРДЫ. Высший сержант. Старший сержант. Сержант. Рубака. Разведчик.",
    ["717b07da"] = "Прежде чем я продолжу, позволь мне поблагодарить тебя ещё раз за то, что ты сделал для меня и моей жены. Ты спас ей жизнь, и за это я обязан тебе большим, чем смогу отплатить за сотни жизней. Она – всё для меня. Если бы она умерла... ну, я не знаю, что бы я сделал. Вот список того, что тебе нужно собрать, если ты хочешь, чтобы я сковал тебе оружие Света. Я записал их по порядку, от простого к сложному – надеюсь, так тебе будет проще.",
    ["71c5cd6d"] = "Сильноплечий -- Однако же нужно обладать немалой наглостью, чтобы посылать чужака обсуждать дела Братства Справедливости! Некогда тебе удалось спасти мне жизнь, а вот теперь ты подвергаешь её серьёзной опасности. Однако я перед тобой в долгу. Братство Справедливости сильнее, чем ты думаешь. Любой рудник от Западного Края до леса находится под их контролем. Кобольды и гноллы делают за них всю грязную работу. У них также есть созданные гоблинами металлические монстры, которые расхаживают по полям Западного Края и вселяют ужас в местных жителей.",
    ["71ca503c"] = "Совет приказал Эгвин вернуться в Даларан, чтобы они могли избрать нового носителя силы Хранителя. Но Эгвин, никогда не доверявшая Совету до конца, решила сама выбрать преемника.",
    ["71f9be68"] = "На следующий день. Его быстро похоронили, без обряда, в спешно выкопанной могиле на окраине кладбища. Из-за того, что Морган убил невинных, что противоречило его убеждениям, а также из-за горя, которое он испытал, так как не смог спасти свою семью, Морган не смог уйти в мир иной и остался в этом мире в облике неупокоенного мертвеца. Через несколько дней его могила была обнаружена пустой, тело так и не было найдено. Существо, в которое превратился Морган, бродит",
    ["7216328c"] = "Враги… со всех сторон. По глазам вижу. Древобрюхи – зло. Враг. Нужно защитить племя. Защитить клан Зимней Спячки. Выгнать врагов с нашей земли.",
    ["72460b39"] = "Тралл привёл орков на материк Калимдор, где они обрели новую родину с помощью своих братьев-тауренов. Стремясь вернуть былое величие, орки назвали свой дом Дуротаром в честь убитого отца Тралла.",
    ["725c1463"] = "Третий день. Рычание не прекращалось всю ночь и преследует меня даже днём. Я не могу сосредоточиться на добыче руды. Думаю, это медведь! Пусть только подойдёт поближе, мне уже не терпится всадить кирку в его череп!",
    ["728165d6"] = "В последующие годы, после того как Штормград предал братство Каменщиков, сэр Эрлгедин разочаровался в аристократии королевства. Он больше не хотел принадлежать к благородным домам, хотя право это унаследовал от отца. Но не будем отвлекаться. Моё повествование не политический трактат и не биография. Я всего лишь делюсь опытом участия в большой охоте среди зелёных холмов Тернистой долины.",
    ["728622ef"] = "Кормок, продолжение. Путешествуя вместе с нами, Кормок стал всё больше интересоваться некромантией. Его жутковатой голове очень нравилось возвращать к жизни духи умерших; наибольшее удовольствие ему доставляло пробуждать духов острова Очищения и командовать ими. После того как наша компания распалась, Кормок отправился в Некроситет, чтобы продолжить там своё \"обучение\". Призрачные убийцы с лёгкостью нашли эту школу и убили Кормока прямо на глазах у его нового учителя, Раса Снегошёпота. Так вот, покои Раса Снегошёпота – ещё одно из мест с привидениями, где можно использовать жаровню.",
    ["72d2a370"] = "Я знаю, что у меня немного оснований претендовать на благосклонность высших сил, но что-то мне подсказывает – может быть, до меня доносятся молитвы моего маленького Эдгара, – что я вернусь невредимым к тем, кого люблю. Если же я не вернусь, никогда не забывай, моя дорогая Сара, как сильно я любил тебя, и знай, что, умирая на поле боя, с последним вздохом я прошептал твоё имя. Прости мне мои многочисленные недостатки и всю боль, которую мне случалось тебе причинить. Как бездумен, как глуп я зачастую бывал!",
    ["736c7c47"] = "Город-государство Кул-Тирас, основанный на большом острове к югу от Лордерона, имел процветающую экономику, основанную на рыболовстве и мореплавании. Со временем у Кул-Тираса появился могучий флот торговых судов, плававших по всему известному миру в поисках экзотических товаров. Но в то время как экономика Аратора процветала, наиболее мощные её элементы начали рушиться.",
    ["73f82b66"] = "Когда сомнения и отчаяние полностью овладели Саргерасом, он потерял веру не только в свою миссию, но отказался от мыслей титанов об упорядоченной вселенной. В конечном счёте он пришёл к выводу, что сам порядок является глупостью и что хаос и порочность – единственно абсолютные понятия в этой тёмной, одинокой вселенной.",
    ["74506442"] = false,
    ["74a33b58"] = "Чёрный дракон прошёл через полное преображение, после чего Нелтариона уже не существовало. Он стал Смертокрылом – злобным и яростным созданием. Он больше не был Землестражем в глазах Высших эльфов, теперь, вместо имени, данному ему титанами, его стали называть Аспектом Смерти и Заккасом. Смертокрыл – воплощение зла и хаоса, вечно алчущее разрушения. Возможно, он – первое зло Азерота, что появилось после изгнания Древних Богов.",
    ["74c655b1"] = "И понимали меня. Передав часть своей силы Косе, я ослабила барьеры мироздания настолько, что смогла привести воргенов в наш мир. С первой попытки мне удалось призвать тридцатерых. Они последовали в сражение за мной, и с их грубой силой в моём распоряжении мы вступили в бой с демонами Осквернённого леса. Элуна исполнила мои желания. Лес будет очищен. Да пребудет со мной благословение Элуны, пока я не сделаю, что должно.",
    ["7536a437"] = "Ночные эльфы собрались с силами и, полные решимости, вступили в сражение с Пылающим Легионом. Легион всегда желал завладеть Источником Вечности, который питал Древо Жизни и был сердцем королевства ночных эльфов. Если бы Легиону удалось захватить Древо, демоны могли бы в буквальном смысле разорвать мир на части.",
    ["75627e49"] = "Прошлой ночью мне во сне явились духи. Они сообщили мне о твоём прибытии и о том, что я должен помогать тебе. Нам нужно о многом поговорить: о природе, духах, Матери-Земле и ночных эльфах. Но для этого нужна личная встреча. Мой долг – подготовить тебя к грядущим испытаниям. Моя мудрость поможет тебе. Я буду ждать. -Гарт Вестник Туманов, наставник друидов",
    ["75febc24"] = "Воплотив наш замысел в жизнь, мы сможем перейти к следующему этапу плана. Необходимо сплотиться вместе и закрепиться в этом регионе, после этого мы сможем начать приготовления к Третьему Походу. Скоро владыки Легиона вознаградят нас за наши труды и снова низвергнут огонь с небес!",
    ["760507c7"] = "День второй. Мой поиск продолжается, но до сих пор нет следов руды. Интересно, не пошутил ли Каменный Убор по поводу этой руды. Если так, то он получит хорошую затрещину от меня, когда я вернусь в Посёлок Сталежара! Когда я размещал свой лагерь, то услышал эхо рычания в каньонах. Это был не волк. Это, должно быть, медведь.",
    ["762eeb31"] = "Из баков с горючим (их должно быть три) к дымовой трубе. Наконец, РЕГУЛИРУЮЩИЙ КЛАПАН можно найти на нижнем из двух больших цилиндрических баков, соединённых с дымовой трубой. Второе: индикаторы топлива. Отображают текущее давление в первом, втором и третьем топливном баке. Третье: индикатор потока. Отображает текущую скорость потока внутри системы.",
    ["762f6221"] = "Жаровня вызывания духов: инструкция к использованию. Где найти места с привидениями. Вступление. На этих страницах написано, где можно найти падших духов и призраков, участвовавших в событии, связанном с амулетом Лорда Вальтхалака. Ты уже спас моих бывших товарищей, но, боюсь, отголоски того зла, что поработило их души, ещё не покинули эти места. Таково могущество злобного духа Лорда Вальтхалака. С помощью жаровни также можно вызвать Лорда Вальтхалака, но нужно соблюдать крайнюю осторожность.",
    ["763cd087"] = "Увидев падение своих детей, Мать-Земля не выдержала такого горя. Она вырвала свои глаза и бросила их на бескрайний небосвод. С тех пор Ан'ше и Му'ша, словно бы желая утешить друг друга, гоняются друг за другом по небу. Поэтому день и сменяет ночь.",
    ["766a3e44"] = "В конечном итоге Адский Крик сумел восстановить свою честь, победив вместе с Траллом Маннорота – демона, обрёкшего орков на вечную жажду крови. Смерть Маннорота положила конец ужасному проклятию орков.",
    ["76edfb30"] = "Ван Клиф... (неразборчиво). Вызывает МЕНЯ? ДА КЕМ ОН СЕБЯ ВОЗОМНИЛ?! Я – Клавьен Мортвейк! И чтобы какое-то насекомое ещё мне указывало?! Остальные страницы книги утеряны.",
    ["771254dc"] = "ВНИМАНИЕ: Немедленно свяжись с Траном Корманом. Он находится на объекте Атри, известном местному населению как \"Старая Наковальня\". После успешного контакта с Корманом продолжай подготовку к войне за возвращение нашего Гномрегана! Все твои действия и усилия должны быть направлены на выполнение этих указаний. Сделав всё, что нужно, ты получишь новое задание.",
    ["778a8994"] = "Тут могут потребоваться дальнейшие исследования. Не знаю, хватит ли мне сил, чтобы сражаться с духами своих мёртвых сородичей... не говоря уже о том, чтобы в одиночку отправиться в Дор'Данил и отыскать это навершие. (Примечание: не так давно во время подготовки в Астранааре мне повстречался дворф-охотник, который провёл много времени в Ясеневом лесу, пытаясь помочь моему народу. Он пришёл из места под названием Штормград. Однажды вечером мы неплохо посидели за несколькими кружками эля, и его рассказ внушил мне надежду, что отыскать навершие всё же удастся...",
    ["778c0fe9"] = "В качестве последней награды Саргерас пообещал Гул'дану огромную силу в обмен на его согласие повести Орду на Азерот. Саргерас сказал волшебнику, что может сделать его богом во плоти, если тот найдёт подводную могилу, в которой Страж Эгвин тысячу лет назад укрыла останки Саргераса.",
    ["78190c92"] = "По сути представляет собой материальное воплощение силы Повелителя вод, могущественного морского элементаля. Как и почему подобный предмет вышел из-под власти Повелителя вод и попал в руки троллей – другой вопрос, ответ на который мне неизвестен. Владыка Приливов. Подобно самим приливам, Камень Приливов был непостоянен: он появлялся в мире троллей и исчезал снова, никогда не оставаясь в их руках дольше жизни одного поколения.",
    ["7826e3b5"] = "Принеси мне эти вещи, Звезду, Руку и Сердце, и я дам тебе копию Книги Йагина. -Хранитель",
    ["7847d9ee"] = "Земля задрожала, когда выкорчевали и повалили древние деревья зачарованного леса. Рощи и лужайки, обихоженные сыновьями и дочерьми Кенария, и каменные башни детей звёзд обрушились на землю. Там была наша королева, яркая даже в отчаянии, в хаосе сражения. Зачарованное небо меняло цвет с каждым новым всплеском магии, со взрывами, которые угрожали разорвать мир на части. Брат сражался с братом. Избранные сражались",
    ["7877961a"] = "Собрав свою армию – великий Пылающий Легион, – Саргерас пошёл на мирный Азерот войной. Легион состоял из миллионов кровожадных демонов, слетевшихся со всех концов Вселенной, и этим демонам не терпелось начать вторжение. Ближайшие помощники Саргераса, Архимонд Осквернитель и Маннорот Разрушитель, подготовили своих зловещих воинов к решительному удару.",
    ["788b82b1"] = "Забрав энергию силовых линий города, Иллидан воспользовался Оком, чтобы нанести магический удар по цитадели Ледяной Короны в далёком Нордсколе. Этот удар сокрушил защиту Короля-лича и поставил под угрозу саму крышу мироздания. В последний момент разрушительное заклятие Иллидана было остановлено, когда его брат Малфурион и жрица Тиранда пришли на помощь Майев.",
    ["78963b6a"] = "Привет тебе, брат. Духи говорят, ты готов нам помочь. Ты очень здорово управляешься со стихиями – гораздо лучше, чем когда только начинал учиться у меня. Ступай к Шикрик, наставнице орочьих шаманов в Долине Испытаний. Она уже знает о тебе. Пусть наши предки гордятся тобой. Да согреет тебя огонь, и да будет тебе попутный ветер. -Иши-йо",
    ["78bba869"] = "Найди наконечник Грубой силы в лагере Изрубленного Щита. Эти глупцы часто прячут их под свои лежанки возле входа во владения Чёрной Вершины. Когда у тебя будет наконечник, иди к вождю Омокку, убей его, а потом насади на наконечник его голову. Тогда ты будешь готов к настоящему делу.",
    ["78d83d30"] = "Ульдаман, День четыре ...первым ключом к разгадке, что я обнаружил в глубинах Ульдамана, стал один из наиболее свирепых из виденных мною троггов, охранявший огромный сапфир, – один из тех, держу пари, что идеально бы подошёл в ожерелье. Я слышал, как один из дворфов Кузни Теней произнёс имя этого чудища: Гримлок. И у этого свирепого Гримлока телохранители те ещё, я скажу...",
    ["78dc2010"] = "Похоже, всё было напрасно. Мгновения спустя жрицу поглотила толпа окруживших её мёртвых крестьян... Павшие восстали.",
    ["78f200ab"] = "*Курдран Громовой Молот Знаменитый драконобоец.* *Укротитель грифонов Заоблачного пика.* *Командир подразделения воздушных всадников при экспедиции Альянса, которая отправилась на Дренор, родной мир орков.* *Предположительно погиб.* Ветер донесёт до нас клич Скайри. Мы услышим грохот твоего молота по ту сторону гор. Вступай в загробную жизнь без опасений, брат. Залы наших предков ожидают тебя. - Верховный тан Фалстад Громовой Молот",
    ["78f5874a"] = "Благодаря успеху Кел'Тузада в Лордероне Король-лич завершил последние приготовления к атаке на человеческую цивилизацию. Нер'зул поместил вызывающие чуму сгустки энергии в несколько переносных артефактов, так называемых чумных котлов, и приказал Кел'Тузаду доставить их в Лордерон, где они должны были быть спрятаны в различных селениях, находящихся под властью культистов.",
    ["791568ef"] = false,
    ["79297bb8"] = "Когда мир раскололся после взрыва Источника Вечности, это очень сильно задело земельников. Ошеломлённые болью самой земли, земельники сделались непохожи на самих себя и закрылись в каменных чертогах, где некогда были созданы. Ульдаман, Ульдум, Ульдуар… это имена древних городов титанов, где земельники впервые обрели свой облик. Погребённые в недрах мира, земельники спокойно отдыхали почти восемь тысяч лет.",
    ["79bf1ec9"] = "Капитан, удачи тебе в путешествиях. К несчастью, в первой нашей попытке похищения удача нам не благоволила. Когда наша команда вышла на объект в тоннеле между Штормградом и Стальгорном, она обнаружила там лишь приманку. Очевидно, он куда умнее, чем мы о нём думаем. Но теперь уже задействован наш второй план. Агенты Братства Справедливости готовятся захватить объект, как только он приблизится к Терамору. Скоро в Штормграде узнают, как мы умеем кусаться... М.",
    ["79c9405a"] = "Инженерные дисциплины. Несмотря на то что вопрос о том, какая раса первой в Азероте додумалась до инженерного дела, является спорным, бесспорен тот факт, что лишь две расы преуспели в ней в настоящее время: гномы и гоблины. Их преданность инженерному делу не только вдохновила их на фантастические изобретения в смутный магический Век Изобретений, но и, как результат, породила интенсивную конкуренцию между расами. Нигде она столь очевидно не проявлялась, как на путях развития их науки.",
    ["79d56bd3"] = "Новая Орда, возглавляемая такими опытными вождями, как Гром Адский Крик и Килрогг Мёртвый Глаз (из клана Кровавой Глазницы), застала врасплох войска Альянса и напала на близлежащие деревни. Под командованием Нер'зула орки быстро добыли нужные артефакты и вернулись обратно на Дренор.",
    ["79da315e"] = "В действительности она часто реагировала с точностью до наоборот! Как будто подвеска умышленно искажала результаты моих экспериментов. Как будто камень был думающим, живым существом. Разгневанная, но не сдавшаяся, я прекратила выдвигать предположения о том, что подвеска была инертным куском скалы, и начала считать, что она была живым существом. Но снова я была не права.",
    ["7a37624d"] = "Поздравляю с пробуждением! Все хитрости и премудрости тайной магии будут твоими – если, конечно, у тебя хватит силёнок их удержать. Как будешь готов, ступай к Май'ах. Она расскажет тебе про такую магию и заклинания, с которыми тебе любой враг не страшен! Май'ах живёт возле Логова, в Долине Испытаний. Ты придёшь, её найдёшь, а она тебе силу даст. А потом ты покажешь всем остальным, что ты крутишь магией как хочешь, а не наоборот.",
    ["7a637e26"] = "Товар у меня. Я буду прятаться к западу от крепости Тирагард, под деревом с тёмными листьями. Если отправите за добром кого-то из своих агентов, пусть убедится, что его никто не видел! Ба'со",
    ["7a71f2ca"] = "Ульдаман, День пятый ...тот трогг, затем взял топаз с тела его убитого \"брата\", побежал в боковую пещеру у внешней стороны зала... ...быстро положил топаз в большую, заметную вазу у задней стены комнаты... ...надо же, дворфы! К тому же трое. Они забаррикадировались от троггов. Звать их на помощь было бы равносильно самоубийству, поскольку на меня бы тут же напали злобные трогги, а в моём ослабленном состоянии... Как только я узнаю, где третий камень, мне следует...",
    ["7ab021a9"] = "Сердце Наследия Старые тексты говорят, что тот, кто обладает Сердцем Наследия, не боится могилы. Возможно, это правда, ведь владелец сердца, Тролль Могх, известен как Могх Неумирающий. Знахарь клана Дробителей Черепов, Могх, обитает в Тернистой долине на Руинах Зул'Мамбве.",
    ["7af2f8fb"] = "ОТЧЁТ: Волки. Атаки животных на Североземье, о которых я сообщал ранее, увеличились. Эоган считает, что появление волков в долине связано с тем, что их спугнули из Сумеречного леса. Несмотря на то что волки редко охотятся на людей, растущее их число привело к нескольким стычкам с фермерами. И пропало очень много домашнего скота.",
    ["7b438fff"] = "Меч дал Артасу невиданную силу, но забрал его душу, превратив принца в одного из самых могущественных рыцарей смерти, подданных Короля-лича. Потеряв душу и рассудок, Артас возглавил Плеть и повёл армию против своего собственного королевства. Артас убил своего отца, короля Теренаса, и бросил поверженное королевство Лордерон к ногам Короля-лича.",
    ["7b9db859"] = "Троллей удаляться от своих исконных владений, или же об их неумении разработать технологии, необходимые для такого путешествия? Ответ на этот вопрос потребует дальнейших исследований, выходящих за рамки моей работы. Однако же вряд ли тролли могли игнорировать столь крупный объект. И новые находки в обширных тролльских развалинах в Тернистой долине демонстрируют ранее не известный аспект их взаимоотношений с морем. Камень Приливов. Недавние открытия, произведённые при обследовании",
    ["7bff7cb7"] = "Ваша честь-- Все жители Западного Края скорбят вместе с вами, но здесь, в Западном Крае, идёт своя война. Крестьяне покидают район из-за воров и механических големов. Штормград отозвал войска, лишив нас всякой защиты. Я организовал местное ополчение на случай, если Штормград не предпримет попыток нас спасти. Направить людей в Красногорье – всё равно что подписать приговор Западному Краю. Сожалею, Гриан Сильноплечий",
    ["7c0adcc6"] = "ОФИЦЕРСКИЕ ЗВАНИЯ АЛЬЯНСА. Часть вторая. Рыцарь-защитник. Рыцарь-капитан. Рыцарь-лейтенант. Рыцарь.",
    ["7c4f0724"] = "ОТЧЁТ: ОРКИ КЛАНА ЧЁРНОЙ ГОРЫ Банды орков клана Чёрной горы появились в долине. Похоже, за этой атакой последует что-то ещё более серьёзное. Необходимо известить мирового судью Соломона в Приозёрье.",
    ["7c65b3ab"] = "Приветствую! Ты показал себя как отличный охотник, и мне бы хотелось, чтобы тебя должным образом обучили. В Тендалской роще дикой природе не дают особо разгуляться следопыты, но за её границами... всё несколько иначе. Разыщи меня в центре деревни как можно скорее. Природа зовёт. Тай'ри Дальний Взор, наставник охотников",
    ["7c820fc9"] = "Мировой судья Резерфорд Бернсайд Все задолженности выплачены. Кузнец Эйвери Веррингтан Все задолженности выплачены. Клерк Гораций Белоконь Все задолженности выплачены. Советник Гиллис Все задолженности выплачены. Советник Крюкс Все задолженности выплачены. Фермер Гетц Все задолженности выплачены. Фермер Рей Крупный долг. Выплата долга сельскохозяйственной продукцией обещана в урожай. Фермер Лаийон Крупный долг. Выселен с земли.",
    ["7c8c76bd"] = "Потеря крепости Каменной Стражи стала для нас сильным ударом. Я уже сообщал ранее о союзе между орками Чёрной Горы и колдуном Моргантом. Эти орки сражаются с наводящим ужас неистовством, и, похоже, здесь не обошлось без чёрной магии Морганта. Храбрейшие из воинов его Величества отдали свои жизни при обороне крепости, но поражение было неминуемо.",
    ["7c8f9623"] = "Феллари Быстрая Стрела Капитан следопытов Алого ордена Жительница Кель'Таласа Пропала без вести в Серебряном бору",
    ["7ccc9812"] = "Сердце Наследия Могх Неумирающий – троллий знахарь из Тернистой долины. И он обладает сердцем Наследия, о котором говорят, что оно отвращает смерть от тех, кто открывает его секреты. Ты найдёшь Могха на Руинах Зул'Мамбве. Одержи над ним победу, если сможешь, и принеси мне Сердце Наследия.",
    ["7cd7f4b0"] = "*Верховный маг Кадгар из Кирин-Тора* . Бывший ученик Медива. Верховный главнокомандующий экспедиции Альянса, которая отправилась в Дренор, родной мир орков. Предположительно погиб. Никто и никогда так самоотверженно не погружался в тёмные глубины магии и войны. Мы желаем тебе добра, смелый странник. Где бы ты ни был. - Антонидас, верховный маг Даларана",
    ["7cd9e135"] = "Я никогда не знал, как зовут жену Свена, поскольку её всегда звали \"дорогая\", \"любовь моя\" или \"мамочка\". Но я хотел бы знать. Я – единственный, кто знает о её подвиге в тот день, и несмотря на то, что она лишь простая жена фермера, никогда не видел я женщину или мужчину, действующих столь храбро. Конечно же, она не знала ничего о косе, но она поняла, что всадники ищут её, и мгновенный план сформировался в её голове. Он был прост и ясен. Если бы он только сработал.",
    ["7cf0211d"] = "Хранитель передал мне найденное тобой письмо, и я хочу сообщить тебе кое-какие новости. Последний оставшийся в живых член семьи \"Варгус\" находится в Силитусе, в Крепости Кенария. Зовут его Гарон Хатчинс. Когда в следующий раз будешь в пустыне, навести его. Ему может быть интересно то, что нам удалось узнать.",
    ["7d0d62b4"] = false,
    ["7d4f0b4d"] = "Кальдорай или ночные эльфы, как их стали называть позже, поклоняются богине Луны, Элуне, и верят, что в дневное время она спит в мерцающей глубине Колодца. В стародавние времена жрецы и провидцы ночных эльфов изучали Колодец с неиссякаемым энтузиазмом, пытаясь раскрыть его тайны и завладеть его силой. Численность ночных эльфов постепенно увеличивалась, и они открывали для себя бескрайние просторы Калимдора, налаживали связи с многочисленными жителями этого материка.",
    ["7e19099d"] = "Столкнувшись с вражескими воинами, Модгуд использовала свои силы, чтобы вселить страх в их сердца. Тени двигались по её команде, и тёмные существа вылезали из глубин земли, нападая на Громовых Молотов в их собственных дворцах. В конце концов Модгуд прорвалась через ворота и осадила саму крепость. Громовые Молоты сражались отчаянно, сам Кардрос был среди воинов, желая убить королеву-колдунью.",
    ["7e706464"] = "Орки оказались неспособны завоевать мир для Пылающего Легиона, и Кил'джеден был вынужден создать новую армию, чтобы сеять хаос в королевствах Азерота. Эта армия не должна была пасть жертвой глупой вражды, подобно Орде. Она должна была быть беспощадной и преданной своему повелителю. В этот раз Кил'джеден не мог позволить себе потерпеть поражение.",
    ["7e7a085e"] = "Орда под предводительством вождя Молота Рока привела под свои знамёна огров из родного Дренора и лесных троллей Амани. Продолжая своё наступление, Орда легко подавила сопротивление дворфов из королевства Каз Модан и южных областей Лордерона.",
    ["7e861a74"] = "Умница луна договорилась с великим оленем, что освободит его в обмен на его любовь. Желание Му'ша исполнилось, и она зачала от Апа'ро ребёнка, который родился тёмной ночью. Он получил имя Кенарий и бродил по звёздной тропе между пробуждающимся миром и небесным царством.",
    ["7ed6de65"] = "Когда ты будешь готов, нажми на взрыватель. Я обеспечил сильный сигнал, соединив медные и серебряные провода с рядом мелтузианских антенн внутри коробки. Это должно обеспечить тебе хороший радиус действия. Но будь осторожен с гоблинами, шляющимися поблизости. Они не оценят моё творение, если поймают тебя на своей территории. Да, на случай, если это не очевидно, не находись рядом с вагончиком в момент взрыва... будет больно.",
    ["7ed7a45d"] = "Я помню битву с армией Пылающего Легиона: враги надвигались со всех направлений, а прямо передо-мной возвышался огромный инфернал. Толпа злобных троллей по сравнению с этим кажется безобидной, как заяц в горах Дун Морога. К величайшей радости Барнила, мы миновали руины Ткаши без всяких приключений. Мы продолжали двигаться на запад к Великому морю, обходя руины Зул'Кунды. Взобравшись на высокий утёс над морем, мы увидели нашего первого ящера.",
    ["7f1e4453"] = "У них действует обширная подземная система. Больше, чем тебе кажется, Сильноплечий. От Пиратской бухты до Крепости Штормграда. Ты храбрый паладин, но глупец, если считаешь, что можешь победить их. Они занимаются разработкой оружия массового поражения. В общем, Каменщики знают только, как строить масштабные сооружения. Надеюсь, ты не подумал, что я о фермах и виноградниках? Я отплатил тебе за услугу. Теперь оставь меня! --В",
    ["7f3e9ef5"] = "Поскольку Кил'джеден не доверял Королю-личу, он послал своих Повелителей ужаса надзирать за духом и следить, чтобы тот выполнял его приказания. Его слуги-вампиры охотно отправились в Азерот, их влекла мощь и ярость Короля-лича, а также возможность изничтожить население целой планеты.",
    ["7f476417"] = "Найденное в отдалённых тропических лесах Кратера Ун'Горо, это яйцо когда-то содержало в себе эмбрион девизавра. Генетический материал этого зверя оказался бесценен для экологов Лиги Исследователей, которые теперь как никогда близки к изобретению сыворотки от лишающего сил яда девизавров.",
    ["7f49c278"] = "Мор Серое Копыто. Друид тауренов и Первый из Павших Мор Серое Копыто всегда был верен Тайным клинкам. Но случилось так, что он первым пал от рук воинов зловещего Лорда Вальтхалака. Когда мы спасались бегством от Вальтхалака, нас преследовала армия его призраков-убийц. Побег из Пика Чёрной горы был настоящим кошмаром. В суматохе Мор оступился и упал (хотя я подозреваю, что его кто-то толкнул). Но как бы то ни было, он упал на нижний уровень крепости и выбраться оттуда уже не мог.",
    ["80534c95"] = "Регистрационная книга Хилсбрада. Мы, народ Хилсбрада, торжественно клянёмся верой и правдой служить Альянсу, ведомому великими монархами, – королём Стальгорна Магни Бронзобородом и королём Штормграда Андуином Ринном. В этом документе содержатся результаты переписи населения для целей управления этим славным городом у подножия холмов в великих Альтеракских горах, также здесь указаны те, кто платил налоги своим королям и великому и могучему Альянсу.",
    ["80758334"] = "Нер'зулу, наконец, удалось открыть порталы, но он даже не предполагал, какую цену придётся за это заплатить. Колоссальная энергия порталов начала буквально разрывать Дренор на части. Мир орков рушился, и войска Туралиона отчаянно пытались добраться до портала, чтобы вернуться домой. Гром Адский Крик и Килрогг Мёртвый Глаз поняли, что безумные планы Нер'зула вот-вот погубят весь их народ, и, собрав всех оставшихся орков, отправились искать спасение на Азероте.",
    ["8089a029"] = "С братьями отправилась юная жрица Тиранда, служительница Элуны. И Малфурион, и Иллидан были влюблены в неё, однако сердце Тиранды принадлежало лишь Малфуриону. Иллидан ревновал девушку к своему брату и завидовал их любви, однако его душевные страдания не шли ни в какое сравнение с муками от магической зависимости.",
    ["80cf282d"] = false,
    ["80ef818c"] = "С течением времени Кель'Талас сделался сияющим памятником трудам и магическому мастерству высших эльфов. Его прекрасные дворцы были созданы в том же архитектурном стиле, что и древние чертоги Калимдора, однако они великолепно вписывались в естественный ландшафт тех мест. Кель'Талас стал сияющим самоцветом, который так хотели создать эльфы.",
    ["80fd203a"] = "Спустя некоторое время после этой находки мы подверглись нападению ящеров. Батальон Длинной Косы сражался мужественно. Но силы были не равны. Почти все погибли. Спаслись только трое. Рабочий Ормер Сталеплет был самым отважным бойцом, он спас меня и геолога Велгара.",
    ["814a431c"] = "Кель, опытный маг, был обеспокоен слабостью Альянса. Его подданные, высшие эльфы, огорчённые потерей своей родины, назвали себя эльфами крови – в память о своём погибшем народе. Лишённые энергии Солнечного Колодца, они ценой огромных страданий сдерживали дальнейшее наступление Плети.",
    ["814b2693"] = "Сердце Наследия. Могх Неумирающий – троллий знахарь из Тернистой долины. И он обладает сердцем Наследия, о котором говорят, что оно отвращает смерть от тех, кто открывает его секреты. Ты найдёшь Могха на Руинах Зул'Мамве. Одержи над ним победу, если сможешь, и принеси мне Сердце Наследия.",
    ["81515dee"] = "Готов спорить, что ты сначала решил, будто это настоящее письмо от короля или кого-то там ещё. Видишь ли, я знаю толк в фальшивых письмах. Мне надо было убедиться, что ты точно прочтёшь это послание, а как ещё этого добиться? Я нахожусь в Старой Наковальне, рядом с огненной ямой. Как будешь готов, приходи, поговорим. Было бы любопытно с тобой познакомиться. -Сольм Харгрин, наставник разбойников",
    ["81a4c1c0"] = "Путешествуя по этому девственному миру, по первобытной земле, титаны встречали множество агрессивных элементалей. Эти духи, поклонявшиеся расе невероятно злых существ, известных как Древние Боги, поклялись отбросить титанов и сохранить их мир от металлического прикосновения захватчиков.",
    ["81cf58d9"] = "Отец и сын неистово дрались бок-о-бок, чтобы сдержать напор насекомых в Силитусе. Из крепости Ан'Кираж тёк, казалось, нескончаемый поток силитидов, пополняя ряды захватчиков-киражей. Весь Силитус был осаждён.",
    ["81d51080"] = "*Данат Троллебой.* *Командир ополчения Стромгарда.* *Советник генерала Туралиона, боевой командир экспедиции Альянса, которая отправилась на Дренор, родной мир орков.* *Предположительно погиб.* Мы чтим твою память и твою жертву, племянник. Со дня основания нашей славной империи путь к доблести всегда был залит кровью героев. - Торас Троллебой, владыка Стромгарда",
    ["81d5d4f1"] = "Я надеялась доказать моим коллегам, что этот камень обладает магическими свойствами, и если мы, волшебники Даларана, не желаем использовать силу кровавых камней, мы должны по крайней мере изучить их свойства, поскольку однажды наши враги могут использовать их против нас. И так начались мои исследования.",
    ["81f67d36"] = "Кил'джеден Искуситель был выбран для поиска самых тёмных рас во вселенной и присоединения их к армии Саргераса. Второй, Архимонд Осквернитель, был избран, чтобы вести огромную армию Саргераса в битву против тех, кто мог воспротивиться воле титана.",
    ["822639f4"] = "Это стало неплохой забавой. Мне так понравилось рвать проклятую книгу на куски! Дальше уже дело пошло просто. Одна глава отправилась в Подгород, обиталище зловонных мертвецов и место, где я пробовал самый, пожалуй, лучший чили. Другая – в Штормград, столицу сыра. Дневник, а ты не пробовал заедать сыром из Штормграда, чили из Подгорода? Эй? Там, никак, тревога.",
    ["826516c8"] = "Среди всего этого хаоса появился таинственный пророк, который стал для смертных спасителем и наставником. Этим пророком оказался не кто иной, как сам Медив, последний Страж, чудесным образом вернувшийся из Бездны, чтобы искупить все свои грехи. Медив поведал Орде и Альянсу о смертельной опасности, которая им грозит, и убеждал их объединить свои силы.",
    ["826f688a"] = "Контроль над зверем: Ищейка Скверны станет слушаться лишь звериных криков. Чтобы заставить вашу ищейку Скверны искать залежи азшарита, необходимо мощно на неё зарычать! (Нацельтесь на ищейку Скверны и издайте рычание). Когда ищейка Скверны обнаружит залежь, она побежит к ней, не обращая внимания на окружающих существ. Хотя вам не нужно защищать ищейку Скверны, возможно, вы захотите быть рядом с ней, чтобы не потерять её.",
    ["82739cad"] = "Ночные эльфы не стали уничтожать новый Источник Вечности, чтобы не вызвать новой катастрофы. Однако Малфурион объявил, что ночные эльфы больше никогда не будут практиковать магию, после чего они под руководством Кенария стали изучать древнее искусство друидизма, которое помогло бы им исцелить истерзанную землю и вырастить новые леса у подножия горы Хиджал.",
    ["82a417bc"] = "Я опишу окружающие земли со слов разведчиков Каргата: -Бурые каменистые холмы и сухие равнины, малопригодные для жизни. -Палящее солнце и суровые ветры. -Озёр или ручьёв нет. Даже мелких луж нет. Чтобы найти воду, жители вынуждены копать глубокие и грязные колодцы или добывать скудную влагу из редких кактусов и прочих колючек. Если вкратце – жарко, жить трудно.",
    ["8356b412"] = "Дорогой дневник, наверное, я старею. Я совершенно забыл, что говорил тебе о Нарайне и его обмане. Как бы то ни было, я так разозлился, когда увидел вместо самого Нарайна его копию, что приказал Номеру Два умертвить глупца! Потом я сел в свой ветролет и начал вырывать страницы из его драгоценной, глупой, идиотской книге на драконьем. Что за бахвальство? Кто сейчас читает на драконьем? Как я его ненавижу!",
    ["83b67325"] = "День пятнадцать Наше упорство себя оправдало. Мы первыми завершили установку Ветрового Камня. Останься с нами другие глупцы, на это ушло бы меньше недели! Завтра мы приступим к ритуалам призыва самого Барона Казума. Он потребовал, чтобы его вызвали первым, и перечить ему мы не можем, поскольку в гневе он скор на расправу. Я надеюсь, что он будет очень нами доволен.",
    ["83ba3e2e"] = "Останки гигантского красного дракона были обнаружены в Болотине вскоре после Битвы за Грим Батол. Тираннистрас, по слухам, был старшим консортом Королевы Драконов, Алекстразы.",
    ["83c491e9"] = "Я боюсь, что война между Стоунфилдами и Маклурами убьёт начинающийся роман между Томми Джо и Мэйбелл. В такие времена, когда мрачные новости и слухи о войне доходят до нас, о молодости и любви должно заботиться. Так вот, просьба: я прошу тебя использовать свои умения и создать зелье или эликсир, который бы помог этим молодым влюблённым встретиться друг с другом. Спасибо тебе, Вильям. И пожалуйста, когда найдёшь время оторваться от работы, заходи в гости. У нас есть о чём вспомнить и посмеяться. Милдред",
    ["83dec8a1"] = "Приятно слышать, что один из братьев Джен'шан явился в долину испытать свои способности. Джен'шан ждёт этого с нетерпением! Не мне тебе рассказывать, какой ты сильный и ловкий охотник. Дело Джен'шан – сделать тебя ещё более сильным и ловким. Найди Джен'шан в долине Испытаний. Она научит тебя, как укрощать самых сильных зверей. -Джен'шан, наставница охотников",
    ["847e8090"] = "Бродит сейчас по Сумеречному лесу, терзаемый горем от потери жены, детей и ненавидящий себя за это. Мор'Ладим, как он теперь себя называет, скитается по Сумеречному лесу и из мести убивает всё живое.",
    ["84883684"] = "Штормграда. К тому времени счета всё ещё не были оплачены, а о вознаграждениях и заработных платах гильдии Каменщиков старательно умалчивалось. В то время Эдвин ван Клиф был избранным главой гильдии Каменщиков, и он в открытую требовал возмещения за нашу работу. В ответ Благородный дом Штормграда приказал распустить гильдию Каменщиков, что, естественно, разозлило ван Клифа. Возглавив бунт, ван Клиф вывел Каменщиков из города. Прежде чем я продолжу, я бы хотел рассказать о других событиях, случившихся",
    ["849f0d12"] = "Бригадир Шумовик, к письму приложен список оборудования, который ты запросил, одобренный Управляющим Раздунком. Он попросил меня напомнить и подчеркнуть для тебя дополнительный интерес Торговой компании в проведении операций по всему Калимдору. Наши бурильные и шахтёрские операции в Степях оказались прибыльными и эффективными, но мы всё ещё ожидаем достаточных норм производительности от Мулгора, который в твоей юрисдикции. Советники сознают всю сложность проведения",
    ["84b93b1f"] = "Планируя нанести удар Альянсу силами своей армии и могучих красных драконов, Некросс надеялся вновь объединить Орду и продолжить завоевание Азерота. Но его надеждам не суждено было сбыться: небольшая группа бойцов сопротивления, возглавляемая магом Ронином, смогла уничтожить Душу Демона и освободить королеву драконов.",
    ["84bf1ba1"] = "Кил'джеден поставил беспомощный дух Нер'зула перед последним выбором между службой Легиону и вечными муками. И вновь Нер'зул принял условия демона. Кил'джеден заточил его душу в глыбу прочного как алмаз льда, собранного в самых дальних пределах Круговерти Пустоты.",
    ["85764716"] = "Герцоги Бездны Только послушникам, имеющим медальон статуса, разрешено обращаться к Герцогам Бездны. Медальоны статуса могут использовать лишь те, кому они были выданы изначально. Члены Сумеречного Молота, замешанные в неправомерном общении с Герцогами бездны либо в использовании без разрешения медальонов статуса будут наказаны мной лично.",
    ["85e09566"] = "В сердца своих светлых детей Мать-Земля вложила любовь к охоте, ибо создания первого рассвета были злобными и жестокими. Они прятались от Матери-Земли в тёмных и глухих уголках мира. Шу'хало охотились на них везде, где находили, и укрощали их нрав с благословения Матери Земли.",
    ["8632a3e7"] = "Самому могучему и коварному из повелителей ужаса, Тикондрусу, это задание пришлось по душе: его завораживала смертоносная сила чумы и небывалая мощь Короля-лича.",
    ["8633ca37"] = "Страшные слова: Лиис Ладимор Любимая жена и мать Опасения Моргана воплотились в жизнь, горе и печаль охватили его, и он, рыдая, упал на колени. Многие часы он смотрел на могилу, прося у холодного камня прощения. И вдруг через несколько часов что-то в нём сломалось, и он впал в бешенство. Он выхватил свой меч из ножен и, яростно крича, начал осыпать надгробия ударами. Ничего не видя и не слыша вокруг, он продолжал крушить всё на своём пути, чем привлёк внимание",
    ["8655d007"] = "Оно не смогло сковать краккенов, но разъярило их. Много эпох смертные не причиняли им боли, а заклинание троллей оказалось болезненным! И вот краккены сбросили оковы заклинания Мин'лота и взревели от ярости. Раздался громовой рокот. Из глубин поднялись большие волны и понеслись к суше. Волны достигли И'лалая и накрыли город тенью. Но прежде чем уничтожить его, краккены на миг замерли.",
    ["868cf786"] = "Но знаешь, Сара, если мёртвые могут вернуться на Азерот и незримо витать вокруг тех, кого они любили, я всегда буду возле тебя, в самый светлый день и в самую тёмную ночь, в счастливейшие моменты и в мрачнейшие часы, и если ты ощутишь на своих щеках лёгкое дуновение ветерка, это будет моё дыхание, а когда ты почувствуешь, как прохладный воздух овевает твой горячий лоб, это будет мой дух. Сара, не оплакивай меня, как мёртвого, думай, что я ушёл и жду тебя, ибо мы встретимся снова. --Твой Салли",
    ["86dacd87"] = "Палач Зуганд! Я считаю, что в наплыве Плети с глубин территории следует винить не слабую оборону. Я довольно давно наблюдаю за нашими войсками в Бастионе и на восточной базе: чтобы там прорваться, потребовалась бы серьёзная армия. Подозреваю, что сейчас некий неведомый враг в наших границах пополняет их численность. Я продолжу идти по этому следу в надежде отыскать и устранить сам источник. Кристоф",
    ["86f76499"] = "Война. Морган служил под командованием легендарного паладина Утера Светоносного, который сражался с орками и нежитью. Оставив жену и детей, Морган отправился на войну. Шли годы, война затягивалась. Морган стал свидетелем ужаснейших событий, включая расформирование паладинов Серебряной Длани, гибель Утера и эпидемию чумы. Единственной причиной, по которой он не сошёл с ума, была уверенность в том, что",
    ["86fd3705"] = "Годы после Великого Раскола были для троллей самыми тяжёлыми. Их разрозненные королевства были охвачены голодом и страхом. Тролли Гурубаши в отчаянии искали помощи у древних мистических сил. Все тролли имели общих многочисленных богов, но на призывы Гурубаши откликнулся самый тёмный и мрачный из них.",
    ["8735c416"] = "Это договор на владение участком земли в Западном Крае. По договору данный участок, включая любую продукцию, полученную на нём, и все строения, находящиеся в его пределах, принадлежит лицам, указанным ниже. Документ подписан: Теодор Хмуробров Верна Хмуробров",
    ["8748d684"] = "Томми Джо - Моё сердце увядает с каждой минутой, проведённой вдали от тебя. Ах, если бы только наши родственники могли забыть о своей глупой вражде и преступлениях и понять, что единственное настоящее преступление – это их взаимная ненависть! Ненависть убивает, и, боюсь, в это тяжёлое время она овладеет не только нашими семьями. Если они это поймут, мы сможем быть вместе. Надеюсь, так оно и будет, я живу мечтами об этом. С любовью, Мэйбелл",
    ["88588119"] = "Прочная хрустальная нога. Хрустальные пауки из Выжженной теснины сделаны из невероятного кристаллоподобного материала. Из их ног, в том случае если они не повреждены при убийстве их владельцев, получаются замечательные трубки, необходимые в экспериментах моих компаньонов-инженеров. Мне понадобится некоторое их количество, чтобы провести тестирование. У пауков есть восемь ног, так что достать их будет не проблемой для крепкого воина или опытного мага.",
    ["885deee8"] = "Используй силу Амулета духов, чтобы они выдали себя, и забери у них камни! Затем вставь камни в Амулет Духов и верни его мне. Когда у меня будет Амулет Соединения, я стану достаточно силён, чтобы изменить жизнь племён, и мы наконец-то сможем жить по заветам предков!",
    ["885e994b"] = "Могучие драконы, бежавшие от быстро распространявшихся по миру людей, обнаружили, что они не могут противостоять могуществу тёмной магии Легиона. Эгвин сразилась с демонами и с помощью благородных драконов победила их. Но как только последний демон был изгнан из мира, ужасная буря разразилась на севере.",
    ["889c6841"] = "Военные звания Альянса. Офицеры. Главнокомандующий Фельдмаршал Маршал Командор Лейтенант-командор Рыцарь-защитник Рыцарь-капитан Рыцарь-лейтенант Рыцарь. Рядовые. Старший Сержант Сержант Младший Сержант Капрал Рядовой",
    ["88bcc8b2"] = "Аптекарь Лидон, я надеюсь, что это письмо дойдёт до тебя быстро, а податель его будет в приличном состоянии. В далёком Калимдоре случилось то, что, как я считаю, потребует твоих умений. Буду кратка. В Когтистых горах, недалеко от Мулгора, родины наших союзников тауренов, грядёт несчастье. Торговая компания, управляемая гоблинами, вовсю ведёт в этих горах добычу и вырубает там леса, гневя горных духов.",
    ["88cf928a"] = false,
    ["88d9a611"] = "В то же время, к которым я хотел бы привлечь ваше внимание. Во-первых, в то время мне предложили пост городского архитектора с условием, что я не стану присоединяться к ван Клифу. Исходя из явственных идеологических разногласий, я принял решение остаться в Штормграде. Во время восстания лейтенанта и самого доверенного помощника ван Клифа, Базиля Тредда, поймали и заключили в тюрьму. В ожидании суда и следствия Тредд был практически забыт в тюрьме Штормграда. Возвращаясь к ван Клифу: после того как он вывел оставшихся",
    ["89477057"] = "Было забыто. Годами Владыка Приливов служил империи Гурубаши, заставляя служивших ему элементалей воды сражаться в бою и управляя течением воды в Тернистой долине во благо империи. Но с годами Владыка Приливов стал более склонен к уединению. Он всё чаще и чаще надолго удалялся от двора. Владыка Приливов скрывал от любопытных глаз придворных свою страшную тайну. Способности, которые дал ему Камень Приливов, сопровождало проклятие. С ходом лет",
    ["894e2936"] = "Леди Кассандра Вэлор, любящая мать и жена. О Кассандре известно немногое – лишь то, как сильно она любила свою семью. Она вырастила отважных детей и была опорой могучему мужу, и иные даже говорили, что всё величие рода – её заслуга. На такую лесть она всегда с достоинством возражала. Если её не запомнят ни за что иное, пусть хотя бы знают: всё, что она делала, она делала ради своей семьи.",
    ["89bbeb77"] = "Ворфалк Железнолоб Ворфалк работает на складе \"Угрюмого обжоры\" и глубоко предан тёмным хранителям. Да укрепится его дух.",
    ["89fb41c1"] = "Привет тебе, брат. Духи говорят, ты готов нам помочь. Ты очень здорово управляешься со стихиями – гораздо лучше, чем когда только начинал учиться у меня. Ступай к Шикрик, наставнице орочьих шаманов в долине Испытаний. Она уже знает о тебе. Пусть наши предки гордятся тобой. Да согреет тебя огонь, и да будет тебе попутный ветер. -Иши-йо",
    ["8ae67989"] = "Со временем любопытство ночных эльфов привело к тому, что они повстречали и подружились с самыми разными могущественными существами, не последним из которых был Кенарий, могучий полубог древних лесов. Благородному Кенарию пришлись по нраву любознательные ночные эльфы, и он потратил много времени на то, чтобы рассказать им о силах природы. Мирные калдорай прониклись большим сочувствием к живым лесам Калимдора и наслаждались гармонией природы.",
    ["8af4fea5"] = "Приветствую тебя, молодой герой. Ветер нашептал мне, что ты пришёл. Земля рассказала о твоей силе. И теперь древние духи говорят о том, что ты готов учиться. Наш народ нуждается в мудрых и могущественных наставниках – и находит их среди нас. Если хочешь, я научу тебя большему. Ищи меня в Лагере Нараче на плато Красного Облака – нам есть, о чём поговорить. -Мила Рассветная Странница, наставница шаманов",
    ["8c368701"] = "Древесный тарантул. Отряд: пауки. Климат: тропический. Вьёт гнёзда в мёртвой и гниющей древесине. Часто встречается там, где идёт рубка леса: тарантул норовит зарыться в свежие пни.",
    ["8c8afa36"] = "Начнёт процесс охлаждения, который в этот момент потребует примерно от одной до двух минут (в зависимости от ситуации) для своего завершения. ВАЖНОЕ ЗАМЕЧАНИЕ: главным силовым рубильником можно манипулировать, только когда три контрольных клапана на самих машинах выключены. Выключать эти клапаны можно в любом порядке. Первый – ГЛАВНЫЙ КОНТРОЛЬНЫЙ КЛАПАН, который можно найти у основания большой вертикальной дымовой трубы. Далее – КЛАПАН УПРАВЛЕНИЯ ТОПЛИВОМ, его можно найти на большой трубе, которая ведёт",
    ["8cf1833f"] = "Самоцвет Кора – судя по тем историям, что я слышал, эти драгоценные камни используются некоторыми заклинателями для сосредоточения в них энергии, необходимой для их магии, что придаёт им ещё больше смертоносной мощи. Ночной эльф, которому я однажды помог, Тандрис Ветропряд, может рассказать тебе более подробно, если ты скажешь ему, что ты от меня. Я считаю, что один из таких драгоценных камней, хранящих энергию, может быть использован для создания твоего оружия. Когда мы говорили с ним последний раз, Тандрис был в городе Аубердин, на Тёмных берегах, в глубине осквернённого леса, что окаймляет побережье в тени родины этого ночного эльфа.",
    ["8d748a88"] = "Эредары, коварная раса демонических чародеев, использовала магию своих колдунов, чтобы поработить множество миров. Расы тех миров мутировали под влиянием злых сил эредаров и сами превращались в демонов.",
    ["8d7ac2e0"] = "Если хочешь получить оленя в целости и сохранности, советуем не медлить с выкупом. Пираты Южных морей очень плохо относятся к задержкам платежей, а нам известно, как ценен зверь для ТВОЕГО разбоя. Принеси тысячу золотых ко входу в Бухту Сорванных Парусов в Танарисе. Если кто-то попытается спасти оленя, то Метцену придётся прогуляться по очень короткой доске. Да-да… Пираты Южных морей.",
    ["8d83dd3c"] = "Прошло больше десяти лет. За это время Король-лич использовал свою огромную мощь, чтобы обрести власть над умами обитателей Нордскола, и повелел им возвести огромную цитадель над его Ледяным Троном. Теперь, когда под его началом был весь Нордскол, Король-лич понял, что настала пора вторгнуться в Лордерон. Находясь в ледяном плену, бывший орочий шаман начал обдумывать новые способы захвата власти. Его призыв достиг всех земель.",
    ["8dbf9a4f"] = "Приветствую. Мне, наконец, удалось выкроить время, чтобы изучить послание, которое ты нашёл у Плети. Это было нелегко, и вот результаты моих трудов – информация о живом родственнике погибшего. Сестру Максвелла зовут Зарена Кромвинд, она – кузнец в Пиратской бухте. Не знаю, насколько они с братом были близки, но тебе стоит заглянуть к ней, если вдруг окажешься рядом. Сейчас такая информация выясняется очень редко, так что ты можешь сделать доброе дело.",
    ["8de07947"] = "День пятый. Мой товарищ по заключению, ночной эльф, страдает от тяжких ран. Свинолюди долго истязали его хлыстом, и, сдаётся мне, он уже скоро испустит дух – если, конечно, в этом зловещем месте каким-то чудом не окажется отряда спасателей. Он то теряет, то вновь обретает сознание. Когда он приходит в себя, я пытаюсь поделиться с ним своим скудным запасом воды.",
    ["8e6d7902"] = "Котлы, которые охраняют верные культисты, должны были действовать как генераторы чумы, рассылая её по поместьям и городам северного Лордерона. План Короля-лича сработал идеально. Многие из северных деревень Лордерона заразились почти сразу же. Как и в Нордсколе, горожане, заболевшие чумой, умерли и возродились уже преданными рабами Короля-лича.",
    ["8e86e046"] = "Если мы сможем сами решать, какой машине быть в отличном состоянии, а какой нет... полагаю, излишне объяснять, какое преимущество это даст нам на ставках. Итак, от вас, милый Шипучка, мы ожидаем средство, которое ослабит прилежание техников. Нет ли в Тернистой долине растений, трав или напитков, что могли бы размягчить мозги гномам и гоблинам? -- К. Углебород",
    ["8ea89dba"] = "Поэтому они решили скрыть свои земли защитным барьером, который позволял бы им спокойно заниматься магией. Они установили в разных точках Кель'Таласа, на границах магического барьера, цепь Рунных камней. Рунные камни не только скрывали магию эльфов от внеземных угроз, но и помогали отпугивать суеверных троллей.",
    ["8ebd722e"] = "О, я проклят! Когда-то я был великим магом огров Чёрной Вершины. Но я бросил вызов Арроку Роковому Смертному Воплю – и он украл мою магию, а потом наслал на меня проклятье. Теперь мне приходится скитаться по залам Ордамара, подобно жалкой твари! Помоги мне! Найди Аррока и укради у него мою магию! Это будет нелегко, потому что Аррок прячется. Чтобы выманить его, нужно очень важное событие. Таким событием могла бы быть смерть его ближайшего помощника, вождя Омокка. Прочти, и ты поймёшь.",
    ["8f0c7fa7"] = "\"Коса Элуны,\" – проскрежетал один из всадников голосом одновременно грубым и пронзительным, как звук точильного камня по лезвию секиры. И последнее слово – Элуны – он прокаркал, как будто заглушая звук. Ужас сковал меня, когда я услышал этот голос, и от страшного его звука, и потому что... я знал, о какой косе говорил всадник. Должно быть, это была та самая проклятая вещь, что я вытащил из-под камней в Погибели Роланда несколькими днями раньше. Вот что искали чёрные всадники! И вот что убило семью Свена.",
    ["8f40de9a"] = "Восточная комбинация кристаллов Существует два возможных эффекта: один оказывает положительный эффект на дух, второй создаёт щит, наносящий урон. КРИСТАЛЬНАЯ СИЛА: требуются синие и зелёные кристаллы. Повышает вашу характеристику \"дух\". КРИСТАЛЬНЫЙ ШИП: требует синих и жёлтых кристаллов. Создаёт щит, который будет наносить урон атакующим.",
    ["8f4788c7"] = "Дети земли не слушали тёмных голосов, но их постигло страшное проклятье. Из тёмных западных земель пришли орды кровожадных существ – кентавров. Каннибалы и разрушители, кентавры набросились на Шу'хало, как саранча. Даже благословение Матери-Земли не помогло смелым охотникам одолеть эту напасть.",
    ["8f59570b"] = "Нелтарион: Нелтарион, названный при рождении Хранителем земли, был предан Азероту сильнее, чем кто-либо другой из Аспектов. Его чёрные драконы создали горы и прочие возвышенности, включая и границы между землями смертных народов. До сих пор неизвестно, что толкнуло его в пучину зла: внешнее ли влияние, внутренняя ли слабость. Интересно знать, причастны ли к этой порче, которой подвергся великий чёрный дракон, Древние боги.",
    ["8f9c6a3e"] = "То обстоятельство, что мы здесь имеем дело с различными мошенниками, заставляет меня считать, что нам понадобится поддержка армии короля. Помимо того что раскопки потребуют военной поддержки, на мой неопытный взгляд, Бейл Модана может представлять стратегическую ценность для Альянса, учитывая нестабильность мировой политики в её текущем состоянии. Увы, я отвлекаюсь. Под скалой нужно проделать много работы. Я провёл слишком много времени за письмом и недостаточно – за раскопками...",
    ["8fe4dbbf"] = "Эти юные маги начали практиковать магию для собственной пользы, а не ради исполнения долга перед своими сородичами.",
    ["8fed2ac2"] = "Ира Вэлор, лесная охотница. Когда отец Иры занемог, она взяла на себя заботу о том, чтобы добывать в окрестных лесах еду и припасы. Недостатка в дичи не было, но в тех лесах можно было с равным успехом и найти себе пищу, и самому стать чьей-то добычей. С годами она сроднилась с лесом и предпочитала проводить время в тёмной чаще, а не в Вороньем Холме. Путники, заблудившиеся среди деревьев, рассказывали о тени, что будто бы указывала им путь обратно к дороге. Никто так и не узнал наверняка, кто это был, но слухи разлетелись быстро. Говорят, Ира и поныне бродит по лесу, протягивая руку помощи тем, кто стал добычей живущих там зверей.",
    ["9008e78a"] = "Ниже представлена схема и расписание перевозки золота Братством Справедливости из шахт Элвиннского леса в наш штаб в Западном Крае. Расписание: Воскресенье: в двенадцать тридцать Среда: в двенадцать тридцать В указанные дни золото, добытое в шахтах Элвин, будет доставляться на тыквенное поле Бреквеллов. Лицо, отвечающее за весь процесс – \"Собиратель\" – будет носить на пальце специальное кольцо, которое я дал ему лично.",
    ["9011bcc7"] = "Решение, впрочем, весьма просто. Используя мякоть дерева в качестве адсорбента, мы можем соединить следы нитроглицерина с нитратом натрия, чтобы получить сильный взрывной заряд, способный пробиться даже через самые плотные массы. Работа будет шумной и разрушительной, но наши поиски гораздо важнее комфорта местных жителей. На самом деле нам уже пришлось выгнать из этой области стаю рогатых, которые мешали нам.",
    ["906b0205"] = "Девлин предупреждал нас, что если мы попробуем противостоять Плети, все мы будем обречены. Он говорил нам об этом, когда они только ступили в Тирисфальские леса, задолго до того как они достигли нашего дома. Возможно, он умолял нас покинуть его, а может быть, злорадствовал. Всегда было сложно понять истинные мотивы Девлина. Ещё будучи ребёнком, он был для нас всех загадкой.",
    ["90715028"] = "Вождь Омокк правит Чёрной Вершиной с помощью магии Аррока. Аррок наложил на Омокка заклятие, которое убивает любого огра, бросившего ему вызов. Омокк применял это заклятье много раз, а черепа его жертв складывал на месте силы над своим жилищем. Вот куда ты должен идти, чтобы встретится с Арроком.",
    ["9074f44e"] = "Лорды Строма, ища на диком севере чистоту и свет, решили оставить свой древний город. Далеко к северу от Даларана лорды Строма построили новый город-государство, названный Лордерон. Весь континент был назван в честь этого города. Лордерон стал местом религиозного паломничества и укрытием для тех, кто искал спокойствия и безопасности.",
    ["908cfd51"] = "Укрощение зверей, меткая стрельба, чтение следов – как научиться всему этому за такую короткую жизнь? Умение охотника требует недюжинной смекалки и огромного терпения. Путь охотника не из лёгких, это точно. Тебе нужно много тренироваться, чтобы достичь уровня самого неуклюжего ружейника из нашего народа. Потому я тебе и пишу. Приходи в Старую Наковальню, что в Холодной долине. Я буду ждать тебя там. -Торгас Мрачнон, наставник охотников",
    ["90b7898a"] = false,
    ["90bd36ac"] = "(Письмена на странице кружатся и перемещаются. Вам кажется, будто книга дразнит вас.)",
    ["90c319d1"] = "Ослабевший, но исполненный решимости спасти своего господина, Артас добрался в Нордскол – и обнаружил там наг Иллидана с эльфами крови. Стремясь опередить обнаруженные силы врага, Артас со своими союзниками из Неруба направился к Ледяному Трону.",
    ["9153922a"] = "Ульдаман, день четвёртый. ...первым ключом к разгадке, что я обнаружил в глубинах Ульдамана, стал один из наиболее свирепых из виденных мною троггов, охранявший огромный сапфир, – один из тех, держу пари, что идеально бы подошёл в ожерелье. Я слышал, как один из дворфов Тенегорна произнёс имя этого чудища: Гримлок. И у этого свирепого Гримлока телохранители те ещё, я скажу...",
    ["915ae2e7"] = "Несмотря на то, что мои коллеги в Даларане настороженно отнеслись к идее изучения кровавых камней, которые принесли с собой Кеган и его спутники, заключив в карантин четырёх беженцев и оставив кровавые камни при них, искренность Кегана обязала меня изучить его подвеску Кровавого камня.",
    ["917e7f10"] = "Даже титаническое тело Саргераса пострадало от порчи, что поразила его когда-то благородное сердце. Его глаза, волосы и борода горели пламенем, а его металлическая бронзовая кожа раскололась, открыв бездонное горнило пылающей ненависти.",
    ["918962b4"] = "Ноздорму Вневременный наложил на Древо Жизни заклятье, которое сделало ночных эльфов бессмертными, вечно молодыми и невосприимчивыми к любым болезням.",
    ["928c5f41"] = "Король Ллейн Первый из дома Ринн. Властительный лорд Штормграда. Защитник Азерота.",
    ["92b496ea"] = "Надеюсь, это письмо дойдёт до тебя. Мне пришлось попотеть, чтобы выяснить хоть что-то об авторах той записки, что ты обнаружил. Отец Самла возглавляет паломничество верующих отрёкшихся и троллей к Громовому Утёсу. Его зовут Майлз Уэльш, а найти его и его друзей-нежить можно на прудах Видений. У Торгала в живых осталась сестра, Элисса Дюма. Насколько мне удалось выяснить, она живёт отшельником в Храме Луны в Дарнассе. Думаю, тебе стоит навестить кого-нибудь из них. Быть может, они не знают о том, что случилось с Торгалом и Самлой.",
    ["92ff3a91"] = "В конце концов они ступили на берега королевства, которое люди позднее назовут Лордерон. Продвигаясь в глубь континента, высшие эльфы основали поселение на спокойных Тирисфальских лесах. Но через несколько лет многие из них начали сходить с ума. Возникло предположение, что-то злое спало в недрах тех земель, но эти слухи так и не оправдались. Высшие эльфы собрали всё своё добро и двинулись на север, к землям, богатым энергетическими линиями.",
    ["934058b9"] = "Однако многие из выживших высокорождённых становились всё беспокойнее. Как и Иллидан, они пали жертвами магии, и изо дня в день их снедало искушение, безумное желание вновь почувствовать энергию Источника Вечности и насладиться его магией. Дат'Ремар, вспыльчивый и беззастенчивый предводитель Высокорождённых, начал в открытую насмехаться над друидами и обвинять их в трусости за то, что они отказались от использования магии, которая, как он считал, принадлежала им по праву.",
    ["9380bf10"] = "Находчивый, но неопытный Тралл решил бежать от Блэкмура и отправиться на поиски своих собратьев. Путешествуя от одного лагеря к другому, Тралл обнаружил, что некогда могучие и воинственные орки превратились в совершенно безжизненных существ. Не сумев найти среди них могучих воинов, о которых он так много слышал, Тралл отправился искать последнего непобеждённого вождя Грома Адского Крика.",
    ["93bb5d46"] = "Хотя Азшара вместе с её высокорождёнными понимали, что при безответственном обхождении такая магия может быть опасна, они начали практиковать её с неуёмной страстью. Кенарий и многие из ночных эльфов-мудрецов предупреждали, что безрассудство при обращении со столь неуловимой магической силой неизбежно грозит бедой. Но Азшара и её последователи упрямо продолжали усиливать своё растущее могущество.",
    ["93ea570a"] = "Приятно слышать, что один из братьев Джен'шан явился в долину испытать свои способности. Джен'шан ждёт этого с нетерпением! Не мне тебе рассказывать, какой ты сильный и ловкий охотник. Дело Джен'шан – сделать тебя ещё более сильным и ловким. Найди Джен'шан в Долине Испытаний. Она научит тебя, как укрощать самых сильных зверей. -Джен'шан, наставница охотников",
    ["93ff02a2"] = false,
    ["9406cf2d"] = "Среди ночных эльфов ходят слухи, будто Алекстраза и полубог Кенарий были близкими друзьями и будто именно Кенарий призвал её во время первого вторжения Пылающего Легиона.",
    ["9449520f"] = "Вера. Вера – вот наш неиссякаемый источник радости порабощения. Вера согреет нас в самые холодные ночи Силитуса. Вера дарует нам благодать Господ, когда настанут Последние Дни. Вера спасёт нас.",
    ["94b611be"] = "Уцелевшие войска Альянса под командованием Джайны Праудмур осели в южном Калимдоре. На восточном краю Пылевых топей они построили укреплённый портовый город Терамор, в котором люди и дворфы объединили усилия ради выживания в этой негостеприимной земле. Хотя жители Дуротара и Терамора и сохраняли непрочное перемирие, оно не могло длиться вечно.",
    ["95287d89"] = "Неизвестно, что именно разбудило земельников, закрывшихся в Ульдамане, но в конце концов они очнулись от сна. Земельники обнаружили, что за время своего забытья сильно изменились. Их каменные шкуры разгладились и сделались мягкой кожей, а их власть над камнем и землёй ослабла. Они стали смертными существами.",
    ["952a1012"] = "Зверь даже не обнаружил нашего присутствия. Если быть честным, единственное приветствие, которое он получил от экспедиции, – это пулю между глаз. Ажек одобрительно кивнула мне, а сэр Эрлгедин радостно крикнул: “Ура!” Настало время отпраздновать успех, выкурив трубку, затерявшуюся в глубинах моего рюкзака. Барнил отправился на вершину утёса за трофеем. Вид поверженного чудища доставлял мне немалое удовольствие, как и любая значительная победа.",
    ["954411e0"] = "Наш первый день прошёл, как обычно проходят первые дни. Большую часть времени мы обустраивали лагерь. Мне удалось найти идеальное место у небольшой чистой заводи. Старые, обветшавшие мостки указывали на то, что в этом месте когда-то жили. Кто именно там жил, мы пока не знали.",
    ["9572b4a3"] = "Когда натиск армии троллей был сломлен и они попытались сбежать, армия Торадина начала преследование, беспощадно убивая всех троллей, которых удалось настичь. Тролли так никогда и не оправились от этого поражения, а в истории больше не будет единого народа троллей. Убеждённые в том, что Кель'Талас спасён от разрушения, эльфы поклялись в верности и дружбе Аратору и семье его короля Торадина. Люди и эльфы с тех пор были в мирных отношениях.",
    ["95830546"] = "Немногие уцелевшие при взрыве эльфы собрались вместе, наспех сколотили несколько плотов и медленно поплыли к далёкой земле. Милостью Элуны Великий Раскол пережили и Малфурион с Тирандой, и Кенарий. Измученные герои согласились стать предводителями своих выживших сородичей и обустроить для них новый дом.",
    ["95d22ade"] = "Эонар также даровала младшей сестре Алекстразы, изящной зелёной драконице Изере, определённую власть над природой. Изера впала в вечный транс, именуемый \"Сном Творения\". Известная под именем Дремлющей, она следит за природой мира из царства Изумрудного Сна.",
    ["95d947ab"] = "Операций в большом масштабе так близко к земле тауренов, но им не кажется, что таурены представляют собой серьёзную угрозу нашему плану в этой местности в целом. Мы рады слышать, что разработки начались в богатых минералами равнинах Мулгора. Из-за этого совет одобрил твой запрос касательно оборудования. Нам кажется, что в Мулгоре можно получить существенную выгоду не только за счёт древесины, но и при добыче минералов, поэтому тебе также предоставят несколько наших новейших резаков и материалы, необходимые для изготовления.",
    ["95e2ff15"] = "После того как я это увидела, моя голова просветлела, возможно, благодаря недавнему порезу (хотя я не верю, что потеряла настолько много крови), а может быть потому, что я, наконец-то, после стольких разочарований, обнаружила одно из свойств кровавого камня. Я добралась до своего стула и села, размышляя. Мысли и вопросы роились в моей голове, вызывая головокружение и угрожая свалить меня наземь. Кровавый камень пьёт кровь? Ему нужна кровь? Он притягивает кровь?",
    ["9606f31f"] = "Кил'джеден понимал, что Король-лич, его собственное творение, достиг слишком большого могущества, и управлять им уже невозможно, а потому он приказал Иллидану убить Нер'зула, уничтожив Плеть раз и навсегда. Взамен он пообещал Иллидану невиданную силу и почётное место среди повелителей Пылающего Легиона.",
    ["96767602"] = "Члены Культа, созданного Кел'Тузадом, добровольно желали умереть и стать слугами своего тёмного повелителя. Они жаждали получить бессмертие через нежизнь. По мере распространения чумы северные земли наводняли полчища беспощадных зомби. Кел'Тузад назвал новую армию Плетью Короля-лича. Этой армии предстояло покорить Лордерон и стереть человечество с лица земли.",
    ["96d5d2d1"] = "Ужас этих последних недель становится невыносимым; и всё же, написав увиденное мною, я чувствую себя немного лучше. И я буду продолжать своё занятие, так как это единственное моё успокоение в эти страшные дни.",
    ["96da5fef"] = "Соломон! Предъявителю данного приказа дарован официальный статус действующего представителя Штормграда. Вы можете воспользоваться его помощью в поисках доказательства участия чёрных драконов в делах орков Чёрной Горы. В случае если подобное доказательство будет обнаружено, данный представитель должен будет вернуться с вышеуказанным доказательством ко мне в Штормград, и тогда я издам приказ об отправке необходимой военной помощи в Приозёрье. С наилучшими пожеланиями, Верховный лорд Болвар Фордрагон",
    ["970862b3"] = "Это был Рагнарос – Повелитель Огня, бессмертный повелитель всех элементалей огня, изгнанный титанами, когда мир ещё был юн. Теперь, освобождённый призывом Тауриссана, Рагнарос явился вновь. Возрождение Рагнароса в Азероте сотрясло Красногорье, и посреди руин воздвигся огромный вулкан.",
    ["9722483f"] = "Древние Боги – воля нашего мира. В каждом шторме слышен громовой хохот одного из них. В пламени каждого пожара виден блеск их глаз. Когда Древние Боги ходят, земля дрожит и трескается, а все, кто слабее их, кричат в отчаянии. И одно лишь отчаяние им уготовано: как огонь не жалеет руки неразумного ребёнка, так и Древние Боги не жалеют тех, кто ниже их. В лучшем случае мы для них пешки. В худшем случае – игрушки.",
    ["978b2745"] = "Первым шагом Кил'джедена было порабощение вампирических повелителей ужаса своей чудовищной властью. Повелители ужаса служили его личными агентами по всей вселенной, они находили удовольствие в поиске примитивных рас для своего повелителя, совращали их и сбивали с пути истинного. Первым среди повелителей ужаса был Тикондрус Затмеватель. Тикондрус безукоризненно служил Кил'джедену и согласился распространять пылающую волю Саргераса во всех тёмных уголках вселенной.",
    ["97d5a0a5"] = "Войскам Туралиона удалось уничтожить Тёмный портал – волшебный портал в родной мир орков, Дренор. Орда, лишённая подкрепления и разрываемая на части внутренней враждой, наконец, пала перед мощью Альянса.",
    ["9821a131"] = "Отправился в деревню в поиске ответов и жены с детьми. Морган спрашивал о судьбе своей семьи, но никто ничего не знал. Жрец из Темнолесья, как теперь называлась деревня, посоветовал ему пойти на кладбище у Вороньего Холма и поискать там. Морган отказывался верить в то, что его семья погибла, и продолжал поиски среди ферм и домов Сумеречного леса, но тщетно. Морган отправился из Темнолесья в соседнее Приозёрье, надеясь, что его семья осела там. По пути",
    ["9835d869"] = "Будь осторожен, воин, ведь обе эти башни сильно укреплены и управляются элитными командорами Вандара. И если твои войска прорвут укрепления, сделай так, чтобы командор в башне был… устранён. Это – следующий важный шаг на пути к победе над Грозовой Вершиной.",
    ["984b1b4d"] = "Зловещие шпионы Пылающего Легиона, которые были изгнаны во время обрушения Источника Вечности, были привлечены обратно в мир неосторожными заклинаниями магов Даларана. Хотя эти относительно слабые демоны не проявляли себя в полной мере, они создавали довольно большую неразбериху и хаос на улицах Даларана.",
    ["98565af6"] = "РЯДОВОЙ И СЕРЖАНТСКИЙ СОСТАВ АЛЬЯНСА. Старший сержант. Сержант. Младший сержант. Капрал. Рядовой.",
    ["9881aa17"] = "Вот цель моей книги: составить список этих существ, этих зловещих созданий, желающих уничтожить наши земли, чтобы те странники, кто на них наткнётся, знали, чего им следует ожидать. Поэтому если ты считаешь себя стражем Азерота, читай дальше. Читай, чтобы знать своего врага. -Ур Маг из Даларана",
    ["988ea6f2"] = "Этот трехстраничный документ пуст.",
    ["98b1e8ac"] = "Эта новость встревожила великих драконов, потому что пока существовал источник, существовала и возможность того, что Пылающий Легион когда-нибудь снова вернётся в этот мир. Малфурион и три дракона договорились вечно охранять Источник и решили сделать всё возможное для того, чтобы демоны никогда больше не появились в этом мире.",
    ["9918a49d"] = "Вернувшись к жизни, он обнаружил, что уже повзрослел, а его друзья Ллейн и Андуин стали правителями Азерота. Он желал использовать обретённые силы на благо своей родной земли, но злой дух Саргераса овладел его разумом и направил его на путь злодеяний.",
    ["99219746"] = "Символом перерождения орков стал поход Тралла на крепость Дарнхольд и освобождение из лагерей всех пленных; зловещим планам Блэкмура не суждено было сбыться. Но эта победа далась дорогой ценой: во время осады одного из лагерей в бою погиб Молот Рока.",
    ["9943dde2"] = "Зимрел Чернозуб Когда безумие тёмного ключа овладевает Зимрелом, лишь крики умирающих могут успокоить его. За свою жертву он всегда будет иметь место над ареной. Да смягчит гнев его сердца наш кровавый спорт.",
    ["9975da69"] = "При продолжении прочёсывания наши агенты задержались на ферме Ивара. Сам Ивар вместе с большей частью своей семьи и работников поддался Плети и стал её слугой. Наши агенты попали в засаду и, хотя они победили атакующих, получили серьёзные повреждения, в особенности агент Квинн.",
    ["9998a220"] = "В ожидании результатов мы с Кеганом много беседовали. Мне хотелось побольше узнать от него о кровавых камнях, но он никогда не говорил мне больше, чем в тот день, когда отдал мне свою подвеску. И он нечасто говорил о времени, проведённом им среди тех, кого он называл \"Отрёкшимися\", – так он именует свой клан нежити.",
    ["9998f022"] = "Эти налоги и постоянные споры по поводу границ вызвали недовольство среди населения. Казалось, что хрупкий союз, который люди заключили в тяжёлый час, может развалиться в любой момент.",
    ["999d7ae3"] = "Дорогой дневник, написав последнюю запись, я вышел из убежища в сильном гневе. Ох, как же я был зол. Хочу придумать для своих прислужников новую униформу, что отражала бы мою ярость. Мне уже лучше, но чего-то не хватает. Скоро вернусь…",
    ["9a05ea09"] = "План бета – Рудник Ветрорезов: Я видел, как гоблины используют другой вагончик со взрывчаткой к северу от входа на шахту. Я думаю, поместить заряд эн-джи-пять (красный) там – это хорошая идея. Установив заряд за вагончиком, отойди на какое-то расстояние и нажми на кнопку. Если гоблины не прибегут, чтобы проверить, что случилось, – скорее всего, это потому, что гора обрушилась им на головы.",
    ["9a1bfcd7"] = false,
    ["9ad834cb"] = "Как узнать, что они любят нас? Некоторым непонятно, как могут Древние Боги и их приспешники любить нас. Не они ли нас убивают? Не они ли причиняют всем нам боль и страдания? Разве есть в сердцах таких жестоких существ место любви? Ответ на эти вопросы очень прост. Так прост, что его излишне даже произносить.",
    ["9ad93fb0"] = "Гоблин Назз Паровой Котёл на самом деле сын богатого гоблина-купца (какого купца? Ответ на этот вопрос дорогого стоит). Похоже, что ему больше нравится тратить заработанное семьёй, а не зарабатывать самому. Поэтому он запустил руку в семейную казну и теперь прячется на Мерцающей равнине. Если бы его отец знал, где он скрывается, то наверняка бы нашёл его и отволок домой... отрезав за нахальство палец на ноге.",
    ["9af8c59c"] = "Орки со всего мира были собраны вместе и помещены в лагеря для военнопленных. Но, хотя с Ордой было покончено, многие сомневались, что мир удастся сохранить надолго. Кадгар, ставший верховным магом, убедил глав Альянса построить Крепость Стражей Пустоты, чтобы охранять руины Тёмного портала и не допустить повторного вторжения из Дренора.",
    ["9b13ba3f"] = "Аран был придворным чародеем и советником короля Азерота. Эгвин соблазнила волшебника и забеременела от него. Ещё не рождённое дитя получило природную способность Ниеласа к магии, что позже определит трагическую судьбу этого ребёнка. Ребёнок также получил силу Тирисфаля, хотя она не проявилась до того, как он стал совершеннолетним.",
    ["9b27d101"] = "Нечестивые, коварные повелители ужаса обращали друг против друга целые народы, манипулируя их бездумной ненавистью и недоверием друг к другу. Саргерас легко победил Натрезим, но их порча глубоко запала в его душу.",
    ["9b86d117"] = "Глава один – Линия фронта Атаковать армию Грозовой Вершины – всё равно что снимать кожицу с луковицы. Чтобы пробраться к сердцевине, нужно сперва разделаться с внешними слоями. Передняя линия обороны, состоящая в основном из горных пехотинцев Грозовой Вершины и Часовых Альянса, связана с Капитанским Укрытием. Снабжает войска и посылает им в случае осады подкрепление Капитан Балинда Каменный Очаг. Срази капитана, и передовые линии падут.",
    ["9ba19460"] = "Гул'дан согласился сделать это и решил, что, как только Азерот будет повержен, он направится на поиски легендарной могилы и получит свою награду. Саргерас, уверенный в том, что Орда будет покорно служить ему, приказал начать вторжение.",
    ["9be353f8"] = "Но он был прав. Мы обречены. Род Агамондов прервётся. Несмотря на то что я всё ещё жив, скоро я погибну. Я не боюсь, и не сожалею о том, что остался со своей семьёй. Но мои последние мысли – о тебе. Продолжай жить, моя возлюбленная Иветта, и я обрету покой. Турман",
    ["9be7f7ec"] = "Завершение ритуала Ход ритуала можно проследить по волшебным рунам на краю круга. Когда там проступят девять рун, ритуал полностью завершится, и ты увидишь, как из заряженного Круга исходит энергия. Затем ты сможешь использовать Ксоротианские Иероглифы, чтобы открыть портал в Ксорот и вывести через него коня погибели. Победи коня и выпусти его дух. Одержи победу над духом, и тогда он будет порабощён, а ты узнаешь секрет его призыва.",
    ["9ca9fa0c"] = "Не дай этой информации попасть в руки врага! Дальше страница испещрена нулями и единицами.",
    ["9ccc88a7"] = "Чудовищные магические штормы, вызванные скапливающейся энергией портала, начали разрывать опустошённый мир на части. Нер'зул, за которым пошли лишь самые преданные его слуги, смог убежать через один такой портал, пока Кадгар отчаянно сражался, чтобы вернуть своих товарищей в Азерот. Поняв, что они окажутся в ловушке в этом гибнущем мире, Кадгар и его спутники приняли самоотверженное решение уничтожить Тёмный портал, чтобы Азерот не пострадал от кошмарного разрушения Дренора.",
    ["9cffd6dd"] = "Этот знак брони можно обменять на изделие из кожи или ткани у Тимберлейнов на Лесопилке Восточной долины.",
    ["9d0c5313"] = "В то время как жители Азерота и Орда бились друг с другом по всему королевству, внутри обеих армий разгорались конфликты. Король Ллейн, убеждённый в том, что звероподобные орки не в состоянии завоевать Азерот, упрямо отказывался покидать столицу Штормграда; Лотар же был уверен, что бой следует перенести на территорию, занятую противником, так что ему пришлось выбирать между своими убеждениями и верностью королю.",
    ["9d4c709e"] = "Не все фурболги подверглись порче. Некоторые ещё живы и стараются защитить лес. Когда пришла порча, некоторые фурболги спаслись бегством, многие были убиты, а других изгнали из кланов. Я нашёл почтенного фурболга из клана Гиблой Чащи, живущего над озером Мистраль, – его зовут Кролг. Я наблюдал за ним несколько дней, и мне кажется, что, приблизившись к нему в обличье фурболга, я мог бы помочь ему и найти способ снова установить связь между нашими народами.",
    ["9d878ca7"] = "Алекстраза Связующая Жизнь опустила в источник зачарованный жёлудь. Пробуждённый могущественными водами, он вырос в огромное дерево, корни которого тянулись в самые недра Источника, а крона, казалось, достигала небес.",
    ["9dbc89bd"] = "О нежити в Брилле. Капитан Вакон, похоже, что передвижения нежити около северной башни возросли. Эти поползновения должны быть быстро и решительно подавлены. Капитан Мелроуз, меня беспокоит уровень организованности нежити около границ с Чумными землями. Новая группа солдат будет доставлена в ваше распоряжение в ближайшие недели. Хвала Свету!",
    ["9ea73b80"] = "Кил'джеден бросил в Азерот через иные измерения глыбу льда, и она упала на континенте Нордскол, принеся в наш мир великое зло. Нер'зул исчез навсегда, вместо него там образовался Ледяной Трон, средоточие ненависти. Некогда уважаемый предводитель шаманов стал невероятно могущественным королём-личом.",
    ["9eb026a9"] = "В последующие годы, после того как Штормград обманул братство Каменщиков, сэр Эрлгедин разочаровался в аристократии Королевства. Он больше не хотел принадлежать к Благородным Домам, хотя право это унаследовал от отца. Но не будем отвлекаться. Моё повествование не политический трактат и не биография. Я всего лишь делюсь опытом участия в большой охоте среди зелёных холмов Тернистой долины.",
    ["9eb90f3d"] = "Армии Чёрного Железа атаковали крепости своих собратьев и практически захватили оба королевства. Но Мадоран Бронзобород в конце концов привёл свой клан к окончательной победе над колдовской армией Тауриссана. Тауриссан и его слуги бежали в свой безопасный город, не зная о том, что происходило в Грим Батоле, где армия Модгуд тоже не особо успешно сражалась с Кардросом и его воинами из клана Громового Молота.",
    ["9ebbbb39"] = "День один: С шести до одиннадцати утра – верхний лагерь С одиннадцати до одиннадцати тридцати утра – перерыв, обед С одиннадцати тридцати утра до четырёх дня – проход через каньон С четырёх дня до семи тридцати вечера – верхний лагерь День два: То же расписание, что в день один День три: То же расписание День четыре: То же расписание, с одним исключением. Перед самым закатом Торсен приказал мне прикрыть его, пока он пробирался по проходу через каньон. Ну, думаю, отправился встречаться с нашими агентами. Но он вернулся через час. Это меня удивило. Я-то думаю: сейчас встретится с нашими агентами, снова присоединится к Курцену... Но что-то пошло не так.",
    ["9ed11fb6"] = "Козни нежити на земле Азерота начались не с падения принца Артаса, они начались задолго до того, как и события, вызвавшие падение Лордерона. Началом всему послужило пришествие орочьих кланов и Пылающего Легиона.",
    ["9f83003a"] = "ВНИМАНИЕ: Ничего не говори! Не оглядывайся! За тобой могут следить. Меня зовут Аламар Гримм. Я обучаю тех, кого интересует мудрость и сила из… из других миров. Меня попросили связаться с тобой и предложить тебе услуги учителя. Когда будешь готов, ищи меня на задворках Старой Наковальни. -Аламар Гримм, наставник чернокнижников",
    ["9fcea13e"] = "Спасибо тебе ещё раз от имени Пастбищ Дымного Леса за твою помощь. Мы не уверены, у кого именно Метцен, и потому определённо стоит проверить обе банды! Время – деньги, и сейчас нам его очень не хватает. Пожалуйста, постарайся спасти оленя скорее, ведь недооценивать жестокость этих бандитов нельзя. Дальше идут две записки с требованием выкупа, которые мы получили. Удачи…",
    ["a00d8043"] = "Мы проснулись чуть свет. Барнил занялся приготовлением завтрака. Мне показалось, что мысли Ажек в этот момент были где-то далеко. Впереди нас ждал долгий день и немало опасностей. Нужна была полная сосредоточенность, иначе последствия могли быть печальными. Но Ажек была не в состоянии отвести взгляд от Барнила, занятого мытьём столовых принадлежностей.",
    ["a01e6a26"] = "Оргрим, разгневанный убийством Дуротана, решил освободить Орду от ужасного проклятья и, чтобы стать новым вождём Орды, убил Чернорука, марионетку Гул'дана. Под его твёрдым руководством безжалостная Орда наконец окружила крепость Штормграда.",
    ["a0230f4e"] = "Стремясь укрепить свою власть над орками, Кил'джеден помог Гул'дану основать тайную секту под названием Совет Теней, чтобы манипулировать кланами и разносить по Дренору слухи о новой колдовской силе. Всё больше орков овладевали искусством наложения чар, и безмятежные просторы Дренора окутывал мрак. Со временем бескрайние степи, служившие домом для орков не одно поколение, поблёкли и превратились в безжизненные пустоши. Энергия демона медленно убивала этот мир.",
    ["a027b07d"] = "Это было невероятно, но орки, некогда считавшиеся самой воинственной расой, ступавшей на земли Азерота, потеряли желание сражаться. Они становились всё более вялыми, чем совершенно сбили с толку предводителей Альянса.",
    ["a036e8d8"] = "Хотя Медив был повержен, Орда по-прежнему брала верх над защитниками Штормграда. Но когда победа была уже у Орды в руках, один из самых могучих вождей орков, Оргрим Молот Рока, стал понимать, насколько изменились некогда миролюбивые кланы, жившие на Дреноре.",
    ["a0649ad3"] = "Ареллас Огненный Лист. Главный волшебник Алого ордена. Гражданин Кель'Таласа. Обречён на вечную битву с некромантом Дисальвеном.",
    ["a0a5761e"] = "И вождь Вар'газул, который находился в безопасности за горами, в Зул'Гурубе, спустился в джунгли и обнаружил, что его народа больше нет. И он пришёл в отчаяние, так как его мечты о завоеваниях потерпели крах. А Мин'лота-Змея так и не нашли.",
    ["a0d3a94d"] = "Получив могущество, пять Аспектов были уполномочены охранять мир в отсутствие титанов. Оставив драконов, готовых защищать их творение, титаны покинули Азерот навеки. К сожалению, Саргерас очень быстро узнал о существовании нового мира…",
    ["a0f71cc0"] = "Звезда Ксиль'и Огр в долине Альтерака, Грел'борг Скряга был последним известным владельцем этого камня, по слухам дававшего своему владельцу умение сообщаться с другими мирами. По нашим сведениям, Грел'борг бродит по руинам Альтерака в одноимённых горах в поисках других реликвий.",
    ["a104bc8f"] = "Во многих племенах способность разговаривать с умершими предками считается очень ценным даром. Но ты, герой, должен помнить, что твой дар не менее ценен. Те, кто говорит с духами, не могут поднять тяжёлое оружие или вытерпеть телесные страдания, причиняемые тайной магией. Ты – можешь. Ты сильный. Я помогу тебе стать ещё сильнее. Ищи меня в Лагере Нараче. -Харутт Громовой Рог, наставник воинов",
    ["a10e5cf9"] = "Западные комбинации кристаллов Существует два возможных эффекта: один повышает вашу защиту от урона, второй ослабляет защиту противника. КРИСТАЛЛ-ХРАНИТЕЛЬ: Требуются красные и зелёные кристаллы. Повышает вашу характеристику \"броня\". КРИСТАЛЛ-ГУБИТЕЛЬ: Требуются синие и красные кристаллы. Может снизить характеристику \"броня\" выбранной цели.",
    ["a1189dc1"] = "Инвар Однорукий. Первый предводитель убийц Алого ордена. Гражданин Даларана. Последний раз был замечен на берегах Нордскола.",
    ["a13f99c5"] = "Бешеный Воробей: Декларация груза и пассажиров. Двадцать бочонков рома. Пункт назначения: Терамор. Пятьдесят мешков муки. Пункт назначения: Терамор. Два ящика с гномскими инструментами. Пункт назначения: Кабестан. Тридцать рулонов хлопчатой ткани. Пункт назначения: Терамор. Четыре ящика пряностей. Пункт назначения: Терамор. Три пассажира. Пункт назначения: Терамор",
    ["a1c9ee42"] = false,
    ["a23fe733"] = "День шесть: Рано утром Торсен долго говорил с сержантом Йохвой. Мне пришлось притворяться, что сплю, так что подойти поближе мне не удалось. Но я думаю, что они говорили о том, куда ходил Торсен. Я за ним пристально слежу – кстати, Йохва тоже. Позднее Торсена вызвал Дорен. У этих троих какая-то общая тайна. Дорен и Йохва, должно быть, знают, что Торсен встречается с вашими агентами. Он шпионит в пользу мятежников.",
    ["a240f042"] = "Отчёт о миссии стражей смерти. Агенты: Ран Йорик, Квинн Йорик, Эрнанд МакКри. Основная цель: произвести рекогносцировку в северном Серебряном бору и определить уровень угрозы от местной фауны и от Плети.",
    ["a2a7624d"] = "Молот Зул'Фаррака Чтобы создать молот Зул'Фаррака, следует отправиться к алтарю Зула и заполучить священный молот, хранящийся у тролля-хранителя. Далее следует принести молот к алтарю в городе троллей Джинта'Алор. Если ударить молотом по алтарю, алтарь наполнит его силой и превратит его в молот Зул'Фаррака.",
    ["a2bab701"] = "Помните, мои братья, когда-то мы были гордыми ремесленниками. Мы будем исполнять наши сегодняшние обязанности с тем же тщанием, что когда-то использовали в нашем ремесле. Эдвин ван Клиф",
    ["a2d2e5f0"] = "К несчастью, эти вонючие орки, кажется, всерьёз принялись за истребление подданных Его Величества. Две недели назад клан Чёрной Горы устроил безжалостную резню в Приозёрье. Много отважных воинов полегло в тот ужасный день. Орки пошли на штурм с таким напором и яростью, что мост через Озеро Безмолвия был разрушен до основания. Наши запасы истощены. Нечем даже перевязывать раненых.",
    ["a3525def"] = "Уверенная в том, что её дитя здорово и невредимо, Эгвин отправила юного Медива ко двору Азерота и оставила его там, чтобы его взрастил его смертный отец и его народ. Сама же она ушла в глушь, готовая встретить всё, что её могло ожидать в загробной жизни. Медив вырос сильным пареньком, но не имел никакого представления о потенциальной мощи силы Тирисфаля, принадлежавшей ему по праву рождения.",
    ["a36f1a06"] = "Тралл взял легендарный Молот Рока и надел свои чёрные доспехи; теперь он стал новым предводителем Орды. Следующие несколько месяцев его маленькое неуловимое войско совершало набеги на лагеря военнопленных Альянса; войско Альянса было бессильно против него. Под руководством своего лучшего друга и наставника, Грома Адского Крика, Тралл делал всё возможное, чтобы его народ никогда больше не испытал на себе гнёта рабства.",
    ["a3968620"] = "С возвращением. Я прекрасно понимаю, что ситуация, в которой ты оказался, несколько шокирует. Тот факт, что тебе удалось продвинуться так далеко, уже делает тебя непохожим на других недавно восставших паладинов. Скоро ты поймёшь, что самая тяжёлая часть твоей новой жизни – понимать, чего ты лишился... и терпеть боль, которую это доставляет. Приходи в Похоронный Звон, и я помогу тебе найти силы, необходимые, чтобы сделать первые шаги. Арамис Хаммерхенд, наставник паладинов",
    ["a3ac4488"] = "Найди место силы над владениями Чёрной Вершины, за Паучим лабиринтом. Там навалены черепа врагов и соперников Аррока. Вот туда-то ты и должен воткнуть наконечник с головой Омокка! Когда голова будет на месте, Аррок точно придёт… но сначала он пришлёт своих приспешников. Убей их – и он придёт сам. Убей Аррока и возьми мою магию обратно. Когда я вновь обрету её, я тебя вознагражу.",
    ["a3b1cb47"] = "Я нашёл способ проникнуть в Чертог Хаз-Мула! Возьми медальон Гни'кива из моего сундука. Победи трогга Ревлоша в зале перед комнатой с картой и забери у него стержень Тсола. Соедини медальон и стержень – и получишь посох Древнейшей Истории. Используй посох в комнате с картой, чтобы открыть двери, ведущие в чертог Хаз-Мула. Сделай это, и комната будет принадлежать нам! -Бейлог",
    ["a3f5a820"] = "Гальванизированный рог: Редкостная твёрдость гальванизированного рога – основа всей детали доспеха, который я намереваюсь создать, так что его тоже надо добыть. Его можно добыть у редких матриархов химер в Обугленной долине.",
    ["a40fe30e"] = "Привет и поклон вам, искатели приключений! Мне, Кринкелю Сталлеру, необходима помощь желающих рискнуть своей жизнью ради выполнения некоторых моих трудных поручений. Поскольку у меня множество обязанностей и я загружен взвалившейся на меня работой, я уверяю, что любому, достаточно смелому, чтобы собрать необходимые предметы из данного списка и принести их мне, будет выплачена солидная премия. Список включает в себя следующие страницы...",
    ["a43bfed7"] = "Спустя десять тысяч лет могучий демон Архимонд вновь ступил на Азерот. Но в Даларане их путешествие не закончилось. По приказу самого Кил'джедена Архимонд и его демоны последовали за Плетью в Калимдор, чтобы уничтожить Нордрассил, Древо Жизни.",
    ["a46d2f69"] = "Доставил бы это письмо тебе сам, но боюсь отлучиться, поскольку могу пропустить нечто очень важное. Если ты желаешь побольше узнать о моих наблюдениях за Башней Алталакса, знай, что податель сего письма немало мне помог и ему вполне можно доверять. Спешно заканчиваю, Балтул Удар Тени",
    ["a4a27081"] = "Кузнечный молот – до прихода Чумы и предательства Артаса мы жили в деревне Погребальных Костров, в глубине прекрасного Серебряного бора. Теперь леса далеко не так красивы, как были раньше, и крепость, где меня обучали секретам литья стали, давно превратилась в руины, и её наводнили злобные твари. Когда я с женой убежал из этого места, что теперь называется крепостью Тёмного Клыка, мы оставили там некоторые дорогие для нас вещи.",
    ["a4af8f07"] = "Как только мне стало известно, что ты готов к обучению, я тотчас же послал тебе знак. Друиды Кенария рады любому пополнению своих рядов. Даже духи становятся сильнее, когда нас больше. Рано или поздно, проявив должное терпение, мы вернём былое величие. Найди меня возле верхушки Альдрассила. Я буду твоим проводником, пока ты живёшь в Тенистой долине. - Мардант Крепкий Дуб, наставник друидов",
    ["a4b58164"] = false,
    ["a4cf6413"] = "Ниже приведён список учеников, получивших Платиновую звезду в школе горного дела и геодезии Брока и заработавших Почётную шахтную кирку: Мелия Потрясательница Камней. Бардин Железняк. Юми Триггервольт. Руми Триггервольт. Ворел Стальной Шип.",
    ["a4f89aba"] = "Иллидан согласился и тотчас отправился на поиски Ледяного Трона, чтобы уничтожить этот ледяной сосуд, в котором хранилась душа Короля-лича. Иллидан знал, что для этого ему понадобится могущественный артефакт. Использовав знания, перешедшие к нему с воспоминаниями Гул'дана, Иллидан отправился к Гробнице Саргераса за останками Титана Мрака.",
    ["a556953d"] = "Эти демонические доспехи носил демон, поразивший наш народ проклятием кровожадности. Благодаря геройскому поступку одного храброго орка он был побеждён. Нет больше Маннорота Разрушителя. Да послужат эти доспехи напоминанием нам о том, как глубоко мы пали и как отчаянно мы сражались за то, чтобы вновь обрести наше доброе имя. - Тралл, Вождь Орды",
    ["a5592c83"] = "Мне, наконец, удалось найти кое-какие сведения о солдате, с которым ты сражался. Его родословная сохранилась очень плохо, так что мне пришлось постараться. Представляешь, что выяснилось: управляющий Ален в часовне Последней Надежды, оказывается, сын Кристофа! Ты можешь облегчить его боль, если расскажешь, что случилось с его отцом. Так что, если будешь на службе у Серебряного Рассвета, поговори с ним. Сделай доброе дело.",
    ["a591aa17"] = "Высокорождённые, или Кель'дорай, как их ранее называла Азшара, в конце концов достигли берегов восточных земель, которые люди позднее назовут Лордерон. Они планировали создать своё собственное королевство магов, Кель'Талас, и отречься от поклонения луне и от ночного образа жизни, свойственных ночным эльфам. С тех пор и вовеки они станут поклоняться солнцу и будут известны как высшие эльфы.",
    ["a5b03de4"] = "В дополнение к крови в камень были вплавлены силы стихий. Огонь, вода, гром и камни были перемешаны с кровью (но всё же, с чьей кровью?), и несмотря на то, что эта смесь была внешне инертна, все эти силы внутри неё бушевали в неистовом противостоянии. Столь много вопросов возникло об этом поразительном, знаковом материале.",
    ["a5cfb871"] = "День шестой. Гералату становится хуже. Сегодня он открыл глаза лишь однажды. Говорил он, превозмогая боль, но вполне ясно. Если мне удастся избежать зловещей судьбы в Лабиринтах Иглошкурых, я должен буду передать Хранителю дорог Фалфинделу в Таланаар, что Чарлга Остробок собирает своих приспешников в южных Степях. Его мощь крепнет с каждым днём. Эту ведьму нужно остановить, пока зло не вышло за пределы Лабиринтов.",
    ["a5df6b98"] = false,
    ["a5e21cb6"] = "Вот что произнёс Кеган, когда протягивал мне свою подвеску Кровавого камня, и был страх и, может быть, благоговение в его глазах, когда он делал это. Когда его рука встретилась с моей, он замешкался, будто не желая расставаться с подвеской. Я содрогнулась от отвращения и по сей день не знаю, из-за того ли, что я ощутила касание его мёртвой плоти, или это подвеска заставила меня поёжиться. Ибо я почувствовала в ней силу. Глубокую, скрытую, ненасытную силу. И острую жажду свободы.",
    ["a684a3bf"] = "Когда наши побратимы уходят В мир иной, потусторонний, Душа застывает В глубине подземелий долины. Когда наши побратимы уходят В Храм Горы, Мы на защиту встаём их духу, Сокрытому в святом синем кристалле. Когда наши побратимы уходят, Восходит Луна над долиной.",
    ["a68953aa"] = "Кенарий научил детей земли разговаривать с деревьями и травами. Шу'хало стали друидами и совершили множество чудес, приносящих земле здоровье. Многие поколения Шу'хало охотились вместе с Кенарием и хранили землю от тёмных сил.",
    ["a6b13400"] = "В последней отчаянной попытке Молот Рока и его командиры храбро ринулись в атаку с Пика и схлестнулись с паладинами Лотара прямо посреди Пылающих степей. Молот Рока и Лотар сошлись в яростном бою, который изрядно измотал обоих могучих бойцов. И хотя Оргрим в итоге смог одолеть Лотара, смерть прославленного героя не возымела того эффекта, на который надеялся орочий вождь.",
    ["a6c5123e"] = "Боюсь, мой отец сделал огромную ошибку, решившись остаться и защищать наш дом. Силы Плети свирепствуют в Тирисфальских лесах, и несмотря на то что мы достаточно укреплены и у нас хватает запасов, после предательства моего брата Девлина у нас не хватает сил и рук, чтобы противостоять их постоянным атакам. Когда ты получишь моё письмо, Иветта, то будешь знать, что Девлин – предатель.",
    ["a70d9966"] = "*(Страница обгорела в нескольких местах, как будто кто-то пытался сжечь её второпях.* *Часть текста уцелела)* Ада! Приятно слышать… остров недалеко от Тёмного берега… Один из наших агентов… пароль… \"Когда задувают одну свечу, зажигают вторую.\" Митчеллс",
    ["a711d7a7"] = "Эонар, титан-покровительница всего живого, отдала часть своей силы красной огромной Алекстразе. С тех пор Алекстраза зовётся Хранительницей Жизни и охраняет всех созданий этого мира. За её мудрость и безграничное сострадание ко всему живому Алекстраза была избрана Королевой драконов и возглавила свой род.",
    ["a729e9fd"] = "Приветствую тебя, брат. Изувеченная Длань выражает тебе своё почтение и надеется, что в нашей долине ты найдёшь, где применить своё ремесло. Учти: мы пристально следим за твоими успехами и неудачами. Мне поручено оценить твоё мастерство и сообщить, когда ты будешь готов к серьёзным делам. Как будет время, навести меня в глубинах Логова. -Руаг, наставник разбойников.",
    ["a7786ad0"] = "Порез был неглубокий, хотя обильно кровоточил. Прежде чем я обмотала мой палец бинтом, добрая порция моей крови пролилась на стол. И когда я начала убирать её, я заметила странную вещь…",
    ["a7a21ac9"] = "Лотар и его войны, возвращавшиеся из Каражана, надеялись остановить кровопролитие и спасти свою некогда славную родину. Но было слишком поздно: когда они вернулись, их королевство лежало в руинах. Орда опустошала деревни и захватывала близлежащие земли. Лотар и его войско, вынужденные скрываться от врагов, поклялись вернуть свою родину любой ценой.",
    ["a7b4afec"] = "Огненная вода. Сделай ещё. Ещё огненной воды. Огненная вода даёт силу. Помогает побеждать врагов. У Зимней Спячки нет союзников. Но есть сила.",
    ["a7d803a3"] = "Существует четыре правила магии: Магия могущественна. Магия развращает. Магия порождает зависимость. Магия притягивает обитателей Круговерти Пустоты к тому, кто её применяет. Эти правила неизменны. Этим правилам ты должен будешь подчинить всю свою жизнь, если захочешь продолжить путь магов… Если у тебя хватит глупости не внять этому предупреждению, приходи ко мне в библиотечное крыло Североземского аббатства. Я буду ждать тебя на втором этаже. -Кельден Бремен, наставник магов",
    ["a7e6702f"] = "Дела культа, том сто двадцать семь Воистину, это счастливый день! Нас испытали в Силитусе, и мы прошли испытание! Рассказы о разгроме нашего северного лагеря могут наполнить страхом сердца неверных, но для нас эта резня не должна быть несчастьем, нет!",
    ["a85520dc"] = "Я провёл следующие недели, перебегая с места на место, нигде не задерживаясь, из страха перед всадниками. Сейчас я остановился в заброшенном городе Вороньем холме – прячусь, как обычно. Я не могу встретиться с той силой, что они использовали на жене Свена, и я знаю, что она рыщет по Сумеречному лесу, всё ещё ищет косу. Я потерял её, и за это я благодарю Свет, ибо если бы я оставил её у себя, я знаю, меня бы обнаружили. Даже теперь в глубине моего сердца я уверен, что меня найдут. Я так устал...",
    ["a85d1f67"] = "Во время битвы на полях Калимдора произошло нечто ужасное. Подробности этого происшествия были утеряны, но известно лишь то, что дракон Нелтарион, аспект земли, в пылу битвы с Демонами вдруг сошёл с ума. Он начал распадаться на части, по всей его чёрной шкуре вспыхивали языки пламени, и в итоге это разъярённое горящее чудовище назвало себя Смертокрылом и напало на своих собратьев, из-за чего пятеро драконов были вынуждены покинуть поле боя.",
    ["a8cbba8e"] = "Дун Модр, Болотина Дорогая моя Сара! Судя по всему, через несколько дней мы сменим позиции, чтобы охранять Мост Тандола. Возможно, я больше не смогу писать тебе. Мне хочется написать несколько строк, которые могут попасться тебе на глаза, когда меня не станет.",
    ["a8edfc23"] = "Господин мой! Война близко. Злой рок стучит нам в двери. Являясь чиновником магистрата города Приозёрье, считаю своим долгом сообщить вам о недавнем вооружённом столкновении в крайней восточной колонии Его Величества. Ниже вы найдёте рассказ об Озёрном государстве, что лежит среди отрогов Красногорья.",
    ["a9016095"] = "Молодой и талантливый учёный по имени Фурион Ярость Бури, который очень долго изучал эффекты Источника, начал подозревать, что Высокорождёнными и обожаемой королевой овладела тёмная сила. И хотя он не мог постичь природы этого зла, он осознавал, что жизнь ночных эльфов скоро изменится навсегда...",
    ["a92ce9c8"] = "Гордая Эгвин, веря, что она сможет противостоять грозному богу, обрушила всю свою силу на аватару Саргераса. С необыкновенной лёгкостью Эгвин одолела лорда демонов и уничтожила его физическую оболочку. Опасаясь, что дух Саргераса выжил, наивная Эгвин спрятала изуродованные останки в одном из древних дворцов Калимдора, ушедших под воду после разрушения Источника Вечности.",
    ["a95c5d04"] = "Современные наблюдения Со временем и другие народы начали признавать праздник Зимнего Покрова временем великого празднества, хотя отмечать праздник они стали не совсем так, как описано в легенде. Сегодня этому торжеству в разных уголках мира соответствует множество обычаев, часто ставящих своей целью лишь собственно празднество и обмен подарками. Иногда на праздниках появляются и портреты Дедушки Зимы, но, как правило, затем, чтобы бойче шла торговля, а не ради восхваления могущественного титана.",
    ["a982c345"] = "Эредары, коварная раса демонических чародеев, использовала магию своих чернокнижников, чтобы поработить множество миров. Расы тех миров мутировали под влиянием злых сил эредаров и сами превращались в демонов.",
    ["a9c4db7e"] = "День пятый. Этот проклятый медведь добрался до меня! Он бросился на меня в полдень и напал со спины. Я бы унюхал его задолго до этого, если бы он напал на меня не с подветренной стороны – запах от него шёл ужасный! Одна только вонь от его грязной шкуры и гнилое дыхание заставили бы меня сбежать оттуда! Я сражался с ним, но он хорошо подрал мою ногу. Теперь я не могу двигаться, эля нет, и я так и не нашёл эту руду. Проклятье!",
    ["a9f35619"] = "Они обрели бы вечную жизнь и им было бы незачем бояться грядущего Раскола...",
    ["aa30a764"] = "В то время как высшие эльфы шли по гористым землям Лордерона, их путешествие становилось всё более опасным. Поскольку они были отрезаны от животворных энергий Источника Вечности, многие из них начали болеть из-за холодного климата или умирать от голода. Но ужаснее всего было то, что теперь они были не бессмертны и не могли противостоять стихиям.",
    ["aa35d4cb"] = "Вернувшись к жизни, он обнаружил, что уже повзрослел, а его друзья Ллан и Андуин стали правителями Азерота. Он желал использовать обретённые силы на благо своей родной земли, но злой дух Саргераса овладел его разумом и направил его на путь злодеяний.",
    ["aa973572"] = "Натака, в Тысяче Игл всё хорошо. Кентавры вот только иногда нападают, но это нельзя назвать реальной угрозой. Впрочем, говорят, что в последнее время кланы кентавров объединяются. Мы всё понимаем, к чему может привести объединение такого безжалостного народа, как кентавры… Я стараюсь не думать об этом, ты же знаешь… их ненависть вечна… даже друг к другу. -Дозорный утёсов Долгорог",
    ["aa9804b3"] = "Попытался проучить монстра, но в итоге получил глубокий порез на руке. Похоже, придётся накладывать швы. ТРЕТИЙ ДЕНЬ. Похолодало. Ночью выпало немного снега. ЧЕТВЁРТЫЙ ДЕНЬ. Ученик поправился и пребывает в хорошем расположении духа, поэтому мы рискнули посмотреть на троллей. Или скорее, Снежную Гриву, исходя из отметок на их коже и различных амулетов, которые они носят.",
    ["aa9df36e"] = "Около шестнадцати тысяч лет назад, задолго до того как ночные эльфы навлекли на себя гнев Пылающего Легиона, большая часть Калимдора принадлежала троллям. Они основали две империи: Гурубаши в юго-восточных джунглях и Амани в центре материка.",
    ["aadffb88"] = "День первый. Торговая компания по-прежнему внушает тревогу. Их рудники только разрастаются, а оттуда доносится новый скрежет – похоже, туда привезли какую-то новую жуткую машину. Пока я не считаю их серьёзной угрозой для Громового Утёса, но если их раздразнить, они вполне могут ударить по деревне Кровавого Копыта с юга.",
    ["ab699c1b"] = "Дополнительные ресурсы, чтобы сократить их распространение. Горные пехотинцы не могут и дальше перекладывать эту проблему на искателей приключений и надеяться на лучшее. Рано или поздно еда закончится, и вендиго будут вынуждены открыто нападать на наши города. Возможно, это коснётся и Стальгорна. Прошу передать мои соболезнования семье горного пехотинца Корнелия. Он отважно сражался ради безопасности Дун Морога и его народа.",
    ["ab816e8f"] = "ДИАГРАММА СЕВЕРНОГО ПИЛОНА",
    ["ab90be8d"] = "Орки и люди, враждовавшие не одно поколение, не хотели и слушать его. Медиву пришлось общаться с каждой расой по отдельности, обманом заставить их пересечь море и ступить на легендарную землю Калимдора. Вскоре орки и люди обнаружили скрывавшуюся долгое время цивилизацию кальдорай.",
    ["ab962a02"] = "Дорогой Таррел! Прости за поспешность, с которой написано это послание, однако сейчас время для нас роскошь. Раскопщики достигли неплохих результатов в поиске артефактов титанов. Но мы обнаружили также другие древние предметы – в частности, огромные кости.",
    ["ac36f8bb"] = "Акири основали две крупнейших колонии – Азжол-Неруб на севере и Ан'Кираж на юге. Тролли предполагали, что существуют и другие колонии под поверхностью Калимдора, но эти подозрения не оправдались.",
    ["ac3e801c"] = "Драконы смотрели, как из Ан'Киража исторгался нескончаемый поток силитидов и киражей. Им стало ясно, что никакая армия, сколь угодно большая, эту войну не выиграет. В главном храме ждали своего часа десятки тысяч воинов. С каждой секундой вылуплялись и вставали под знамёна всё новые их бойцы, готовые ринуться в сечу.",
    ["ac3ff993"] = "Шли века, сообщество ночных эльфов набиралось сил и разрасталось, занимая всё новые и новые территории леса, который они назвали Ясеневым. Появились и расплодились многие существа, жившие ещё до Великого Раскола, – например, фурболги и иглогривы. Ночные эльфы жили под управлением мудрых друидов и наслаждались эрой небывалого спокойствия и мира под звёздами.",
    ["ac763d77"] = "С другой стороны, достоверно установлено, что раса ночных эльфов обрела могущество именно после обнаружения источника Вечности. Несмотря на все попытки троллей защитить свои владения, эта раса стремительно захватывала первобытный Калимдор. Сильная магия, недостижимая для суеверных троллей, позволила ночным эльфам добиться того, что не смогли сделать акири, – разрушить две великие империи.",
    ["acb094a3"] = "*И ветра быстрей прискакали они, И громко он их имена возгласил:* \"Ну, Мерсер! Ну, Чилтон! Ну, Джордан и Каплан! Но, Нэйгл! Но, Пардо! Но, Гудман и Метцен! Бегом на крыльцо! На стену скорей! И мчитесь, мчитесь, мчитесь резвей!\"",
    ["acbbbcd3"] = "Мельницы.",
    ["aceea7ec"] = "Элиза Возлюбленная жена, пусть земля утолит твой голод.",
    ["adb95612"] = "На берегу озера, Амет'Аран и Башал'Аран были впереди всех, обладая благословлением Азшары, возлюбленной королевы калдорай, при своём создании. Её любимые слуги из высокорождённых прибыли вместе с ней для обитания в городах-близнецах; управлять ими она назначила Атрикуса Нарассина, хотя оказалось так, что он стал проводить большую часть времени в своей башне Алталакса, на некотором расстоянии от городов. Его помощником, магом, известным своим мастерством в тайных искусствах наравне со своими физическими способностями,",
    ["ade96ef7"] = "Я никогда так не гордился своим ремеслом, как в последние несколько лет. Спрос на услуги убийц, шпионов и разведчиков высок как никогда. На первый взгляд может показаться, что нас кормит война. Но ни в одну войну мы не процветали так, как процветаем сейчас, когда мирное время подходит к концу. Мне передали, что ты появился в наших краях и хочешь кое-чему научиться. Когда будет время, приходи к стойлам позади аббатства. -Джорик Керридан, наставник разбойников",
    ["ae084a5c"] = "Отчёт о положении дел с троллями из племени Мерзлогривов в регионе Дун Морога. Подготовлен Сениром Белобородом, особым посланником Сената. Большая часть троллей, обитающих в Дун Мороге, сконцентрирована в форте Мерзлогривов, горной пещере на западной границе. Их численность может вызывать некоторые опасения, однако, похоже, они не собираются покидать свою пещеру. Вне всяких сомнений, они не хотят вновь вызывать гнев дворфов, которые могут их полностью изничтожить. Они всего лишь обороняют свою территорию и",
    ["ae1406a0"] = "(Вы не можете разобрать надписи на этих страницах.)",
    ["ae24ce8f"] = "Мои руки дрожат, когда я вспоминаю о подробностях той ночи, когда Свен ушёл и его семья была обречена встретиться с чёрными всадниками один на один. Вновь сожаления гложут меня, ибо я был там и мог восстать против монстров из Мёртвого Ветра. Но это никчёмные сожаления. Подобные сомнения терзают любого, выжившего после трагедии. Я знаю, что если бы я покинул моё убежище, я тоже был бы убит, моё тело было бы разорвано и раскромсано, а его части разбросаны так далеко, что никто не смог бы меня опознать.",
    ["ae7600ba"] = "Вот параметры поршня: Длина: тридцать два ша-у Диаметр: двенадцать ша-у Вес: от двадцати трёх с половиной о-эм-гэ до двадцати пяти с половиной о-эм-гэ Проводимость: семьдесят пэ-зэ Прочность на сдвиг: девяносто восемь или выше Рейтинг перенаправления: \"Суперпрочный\" или выше На случай, если ты забыл гномские сокращения: Ша-у — «Ширина Уса». О-эм-гэ — «Очень Мелкие Граммы». Пэ-зэ — «Пальцевые Завитки».",
    ["ae9a375f"] = "Яна Кровавое Копьё Второй предводитель убийц Алого ордена Жительница Даларана Пропала без вести в Тирисфальских лесах",
    ["ae9f2878"] = "Отчёт о состоянии вендиго в пещерах близ Караноса. Составлен горным пехотинцем Гретхен на основе наблюдений горного пехотинца Корнелия. Вендиго редко выходят из своих пещер, но нам поступают сообщения о том, что они нападают на мирных жителей около близлежащих поселений, таких как Каранос и Посёлок Пивоваров. Судя по всему, агрессия зверей растёт с отчаянными поисками пищи. Недавно мы и сами потеряли товарища, пытаясь их сдерживать. Хотя мы считаем полное устранение этих созданий нецелесообразным, мы запрашиваем",
    ["aeaefc8a"] = "Достопочтенные коллеги и искатели правды. Раскопки продолжаются, но они были приостановлены из-за троггов, о которых я сообщал в моём последнем докладе. Я уверен, их проблему можно решить даже несмотря на то, что некоторые трогги гораздо более агрессивны, чем обычно. Мы нашли ещё больше артефактов, хотя во всех случаях, кроме одного (о котором я напишу ниже), эти находки были такие же, как и раньше, – интересные, если не сказать более.",
    ["aecea9fc"] = "В пещерах Мародона блуждают духи наших первых Ханов. Они – первые дети наших Матери и Отца и наши величайшие вожди, их зовут Гелк, Колк, Магра, Мародос и Венг. Каждый из этих духов хранит один из пропавших камней.",
    ["af369b9e"] = "Но прежде чем читатель поспешит отбросить мысли о сказках, поспешу его уверить: воргены существуют на самом деле. Возможно, они не из нашего мира, но между мирами сейчас проложены свои тропы, и чудовищ можно призвать сюда из их миров с помощью сильной магии. Но лучше такой магией не пользоваться, ведь где бы ни появлялись воргены, с собой они приносят ужас и смерть.",
    ["af36b52d"] = "Всё началось с находки этой проклятой косы в Погибели Роланда. До того, как я нашёл косу, местные страхи казались мне такими же смешными, как страхи жителей Долины Североземья. Но с тех пор как я увидел рукоять косы, выглядывающую из-под груды щебня в шахте, и, будь я проклят, вытащил её, Погибель Роланда превратилась в место ужасной смерти!",
    ["af3dd956"] = "ОФИЦЕРСКИЕ ЗВАНИЯ АЛЬЯНСА. Часть два. Рыцарь-защитник. Рыцарь-капитан. Рыцарь-лейтенант. Рыцарь.",
    ["af6c88fc"] = "После гражданской войны пути оставшихся троллей Гурубаши разошлись. Племена Дробителей Черепов, Кровавого Скальпа и Чёрного Копья племена нашли своё пристанище в джунглях Тернистой долины. На руинах империи воцарился хрупкий мир, но в народной памяти осталось пророчество о том, что однажды Хаккар вернётся в мир и поглотит его.",
    ["afa75e90"] = "Благой Пантеон, желающий оградить свои упорядоченные миры от всякого зла, зорко наблюдал за действиями тёмных сил Круговерти Пустоты. Там, в неосязаемом мире неупорядоченных магических энергий, соединяющем мириады миров во Вселенной, обитали неисчислимые множества зловредных демонических существ, жаждавших лишь умерщвления и пожирания всего сущего в мирах.",
    ["aff1d31f"] = "Под бдительным присмотром Тирисфальского ордена Даларан стал центром обучения для всех волшебников. Магократы, правившие Далараном, основали Кирин-Тор, особое тайное общество, регистрировавшее и изучавшее каждое заклинание, артефакт или магический предмет, известный в то время.",
    ["b007cf8f"] = "В конце страшного противостояния, известного под названием Войны Древних, Источник Вечности взорвался. Мощная волна разорвала Калимдор на части, превратив его в несколько менее крупных континентов и островов.",
    ["b0eed56b"] = "Даже практически оставшись без сил, Артас сумел опередить Иллидана и первым добраться до Ледяного Трона. Своим руническим мечом, Ледяной Скорбью, Артас разрушил ледяную тюрьму, а потом забрал из неё зачарованный шлем и доспехи Нер'зула.",
    ["b117443e"] = "Ну что ж, неплохо! Теперь отправляйся на восток по крутым берегам. Когда выйдешь на дорогу, ищи на обочине развалившуюся дымоходную трубу. Там ты найдёшь старую бочку, а в ней следующую подсказку.",
    ["b16238d5"] = "Могучие воины защищают наши дома. Мудрые шаманы охраняют наши души и ведут нас по дороге предков. Друиды сообщают нам волю Матери-Земли. Но ты – охотник, а это призвание объединяет в себе умения воинов, шаманов и друидов. Такие, как ты, являются сердцем нашего народа. К тебе будут обращаться за советом и защитой. Я должен удостовериться, что ты готов к этому. Приходи в Лагерь Нараче. -Ланко Дальний Выстрел, наставник охотников",
    ["b1c37586"] = "Мы в жутком положении, ты не находишь? Отравленные проклятым принцем. Отвергнутые всеми, кого мы любили. Да, прекрасная Сильвана принесла нам свободу воли, но что это даёт нам сейчас? Мы сменили хозяев, но остались рабами. А что если мы сами станем хозяевами? Ты ведь знаешь о чём я думаю, правда? Мы ведь чужие даже среди Отрёкшихся. И потому нам обязательно нужно встретиться. Я буду в церкви Могильника.",
    ["b1fc19a8"] = "Пока политические споры и соперничество семи людских государств разгорались и утихали, Хранители постоянно оставались на страже в своей войне против хаоса. За годы сменилось немало Хранителей. Одна из последних Хранителей того времени прославилась как могучая воительница, отважно противостоявшая тьме.",
    ["b218ba4a"] = "…и там ты найдёшь легендарный меч Командира Алых – Испепелитель. Разве не замечательно добыть такое на обычной рыбалке?",
    ["b31bc5e8"] = "Ниже приведён список учеников, получивших Платиновую звезду в Школе Горного Дела и Геодезии Брока и заработавших Почётную Шахтную Кирку: Мелия Потрясательница камней, Бардин Железняк, Уми Триггервольт, Руми Триггервольт, Ворел Стальной Шип.",
    ["b32e9bc4"] = "...жизнь мне не мила. Сначала она надо-мной потешалась – и вот уже обручена. Жестокая обманщица притворялась, что любит меня, а на самом деле хотела надо-мной поиздеваться. Меня переполняет злоба, и с каждым днём она становится всё сильнее. Кровь, что вот-вот прольётся, – ничто в сравнении с количеством выплаканных мной слёз...",
    ["b331dc45"] = "Кому: Всем новым студентам тайных искусств Вы должны явиться к своему преподавателю, гному Маррайку Нуррибиту, и находиться в его распоряжении до того момента, пока вы не будете призваны на помощь своему народу в освоении новых земель. Будьте готовы к предельно жёстким экзаменам и изнурительным тренировкам одновременно с поиском жилья и (или) установкой контактов с местным населением. С вопросами по поводу ваших обязанностей и возможностей обращайтесь к Маррику Нуррибиту.",
    ["b337de40"] = "Я боюсь, что война между Стоунфилдами и Маклурами убьёт начинающийся роман между Томми Джо и Мейбелл. В такие времена, когда мрачные новости и слухи о войне доходят до нас, о молодости и любви должно заботиться. Так вот, просьба: я прошу тебя использовать свои умения и создать зелье или эликсир, который бы помог этим молодым влюблённым встретиться друг с другом. Спасибо тебе, Вильям. И пожалуйста, когда найдёшь время оторваться от работы, заходи в гости. У нас есть о чём вспомнить и посмеяться. Милдред",
    ["b34f339f"] = "Хаккар Свежеватель Душ – жестокий и кровожадный дух – решил прийти на помощь троллям. Открыв Гурубаши секреты крови, он помог им захватить большую часть Тернистой долины и несколько островов Южных морей. Но за свою помощь Хаккар потребовал очень дорогую цену.",
    ["b3508cf3"] = "Когда рассветные туманы рассеялись, наступили дни, которые мы помним. Кенарий ушёл по своим неизбывным путям. Из-за его ухода Шу'хало, наречённые тауренами, впали в отчаянье и забыли многое из того, чему он учил. Сменилось поколение, и они разучились говорить с деревьями и травами. И тогда их ушей вновь начали достигать тёмные голоса из недр земли.",
    ["b382b5e2"] = "Но вооружение у них никудышное и нет дисциплины. Небольшое проявление силы – вот и всё, что нужно для устранения \"угрозы\".",
    ["b4506611"] = "Кровожадный бог требовал ежедневного приношения множества жертв. Он мечтал явиться в реальный мир и выпить кровь всех живых существ. Но в конце концов Гурубаши поняли, что за создание им помогает, и восстали против него. Самые сильные племена пошли войной на Хаккара и его верных жрецов Атал'ай.",
    ["b46a20b1"] = "Самоцвет Кора – судя по тем историям, что я слышал, эти драгоценные камни используются некоторыми заклинателями для сосредоточения в них энергии, необходимой для их магии, что придаёт им ещё больше смертоносной мощи. Ночной эльф, которому я однажды помог, Тандрис Ветропряд, может рассказать тебе более подробно, если ты скажешь ему, что ты от меня. Я считаю, что один из таких драгоценных камней, хранящих энергию, может быть использован для создания твоего оружия. Когда мы говорили с ним последний раз, Тандрис был в городе Аубердин, на Тёмном берегу, в глубине осквернённого леса, что окаймляет побережье в тени родины этого ночного эльфа.",
    ["b487b5a6"] = "ОФИЦЕРСКИЕ ЗВАНИЯ АЛЬЯНСА. Часть вторая. Рыцарь-защитник. Рыцарь-капитан. Рыцарь-лейтенант. Рыцарь.",
    ["b4a76425"] = "Предъявитель данного свидетельства имеет права на уважение и почтение, которого заслуживает любой первостатейный жулик и вор.",
    ["b4b66e4f"] = "Уважаемый получатель! Если ты читаешь это письмо, то я могу предположить, что ты находишься в одном из двух мест: (один) На южном полуострове Азшары. (два) В брюхе скального великана. И то, и другое одинаково нежелательно. Следует заметить, что я некогда был в первом, а теперь – во втором.",
    ["b4baa45d"] = "Упрямые эльфы, не желавшие отдавать свои новые владения, использовали магию, оставшуюся от Источника Вечности, и заставили свирепых троллей отступить. Под командой Дат'Ремара они сумели победить отряды Амани, которые десятикратно превосходили их числом. Некоторые эльфы, помнившие древние предупреждения кальдорай, почувствовали, что использование магии может привлечь внимание изгнанного Пылающего Легиона.",
    ["b4d437ec"] = "Второй город-государство Аратора, Даларан, был построен севернее Строма. Многие юные волшебники покинули ограничивавшие их границы Строма и отправились в Даларан, где они надеялись получить свободу в использовании заклинаний. Эти маги использовали свои силы, чтобы создать зачарованные башни Даларана, и с головой погрузились в исследования.",
    ["b4fa9907"] = "Элементалей воды, существ, целиком состоящих из воды, что прежде удавалось только могущественным магам Кирин-Тора. Воин отправился в Зул'Гуруб, в сердце империи, чтобы продемонстрировать свои новые способности императору. Он с лёгкостью добился аудиенции при дворе после того, как продемонстрировал своё могущество в центре столицы империи. Его способности поразили императора Гурубаши, который немедленно предоставил ему почётное место при дворе, назвав воина Владыкой Приливов. Прежнее его имя",
    ["b53be82d"] = "За изгнанным кланом Северного Волка через портал последовали лишь несколько кланов. Орки быстро развернули базу в Чёрных Топях, тёмной болотистой местности на востоке королевства Штормград. Начав исследовать новую территорию, они тут же столкнулись с защитниками Штормграда.",
    ["b5672618"] = "Гурдл, Я с нетерпением ожидаю, когда будет готово твоё новое изобретение. Я жду не дождусь, когда смогу с его помощью записывать результаты моих исследований. Пожалуйста, доверь его моему посланнику. С сердечным приветом, Дарин Лёгкий Ветер",
    ["b5846d72"] = false,
    ["b606e1ca"] = "НАСТАВЛЕНИЕ ПО ВОИНСКИМ ЗВАНИЯМ. Ниже перечислены воинские звания Альянса, снабжённые пояснениями, касающимися народов Орды. Звания представлены в двух разделах – офицерский и рядовой состав – и перечислены в каждом разделе в убывающем порядке, от старших к младшим. Да здравствует Альянс!",
    ["b687ca6e"] = "*Здесь покоится Громмаш Адский Крик, вождь клана Песни Войны* Проклятие нашего народа началось с него – и им же закончилось. На нашем древнем языке его имя означает \"Сердце великана\". Он заслужил его, вступив в поединок с демоном Манноротом и купив нам свободу ценой собственной крови. Лок'тар огар, брат. Да пребудет вечно клан Песни Войны. -Тралл, вождь Орды",
    ["b6c785ff"] = "Хотя я перестала призывать новых воргенов, их число по-прежнему растёт. Коса словно больше не нуждается в моей помощи. Это призывает беспокойство. Я собрала все возможные стаи и приказала им оставаться в святилище Мел-Тандрис. Тем временем я обыскала библиотеки Дарнасса и посоветовалась с Кругом Древних на Тёмных берегах. Я не нашла абсолютно никаких сведений об этих воргенах. До меня дошли слухи,",
    ["b6f2581e"] = "Рука Дагуна Древние тексты утверждают, что когти Дагуна источают яд, который не убивает жертву, но превращает её в нечто иное – представителя старых рас. Его ценность для нас неоспорима. Дагун живёт глубоко в море, но его регулярно выманивает на поверхность племя мурлоков Болотного Плавника в Пылевых топях. Их оракулы призывают его при помощи зачарованных морских водорослей. Если ты убьёшь достаточно оракулов, то соберёшь необходимое количество этих водорослей. Положи их на алтарь мурлоков: так ты сможешь призвать Дагуна.",
    ["b7fa8739"] = "День третий. Кентавры вторглись в Мулгор! Наш самый мерзкий и древний враг посмел вернуться на эти равнины, откуда его однажды изгнали. Гнев верховного вождя обрушится на них! Я должна узнать, что они замышляют, чтобы дать им самый верный отпор. Если буду двигаться бесшумно, думаю, смогу подобраться достаточно близко и подслушать. Похоже, они собираются... (Остальной текст залит кровью.)",
    ["b805ec74"] = "Господин Шипучка! Напиток, который вы дали моему помощнику, возымел большой успех. Мало того что он крепок и сильно затуманивает разум, он, похоже, ещё и вызывает привыкание. Уверен: те, кто его отведали, будут просить добавки. Мы в долгу перед вами, Кранк. Также приглашаю вас посетить Мерцающую равнину либо послать своё доверенное лицо, дабы воспользоваться нашими новыми возможностями в азартных играх. --Крейвел",
    ["b85a9f95"] = "Но одно племя, известное как Арати, поняло, что тролли сделались слишком серьёзной угрозой, чтобы продолжать их игнорировать. Арати хотели подчинить себе все племена, чтобы выступить единым фронтом против троллей.",
    ["b9848074"] = "Малфурион был уверен, что демоны рвутся в этот мир из Источника Вечности, поэтому он стал настаивать на его уничтожении. Но так как именно Источник являлся залогом могущества и бессмертия Ночных эльфов, такое решение привело остальных в ужас. Однако Тиранда поняла весь замысел Малфуриона и убедила Кенария и его соратников напасть на храм Азшары и найти способ закрыть источник раз и навсегда.",
    ["b9a855f9"] = "Эти образцы древней глиняной посуды были найдены при раскопках Ульдамана. Хотя на них не так много загадочных рун или иероглифов, они позволяют оценить мастерство изготовления этих повседневных предметов древней расы дворфов.",
    ["b9ce44ea"] = "По приказу верховного палача Хадрика ниже я привожу список предметов, требуемых для пополнения запаса Гробницы: Двенадцать длинных мечей Девять кинжалов Восемь круглых щитов Пятнадцать топоров Одна тысяча стрел Поставку запасов из данного списка считать личным распоряжением Тёмной Госпожи. Те, кто ответственен за выполнение приказа, будут находиться под Её неусыпным наблюдением, как и те, кто будет противиться либо ещё как-нибудь препятствовать Её воле.",
    ["b9e1052c"] = "Лок-тар, брат. Стихии указали на тебя и поручили мне показать тебе путь шамана. Духи наших предков смотрят на нас и гордятся тем, что ты вступил в наши ряды. Когда будешь готов, найди меня у входа в Логово. Я обучаю там наших собратьев. Да будет тебе попутный ветер. -Шикрик, наставница шаманов",
    ["ba1a7214"] = "Изера Спящая тоже зачаровала Древо Жизни, связав его со своим миром, астральным измерением, известным как Изумрудный Сон. Этот огромный мир, населённый духами, не подчинялся законам физического мира. Из своего Сна Изера могла управлять жизнью природы и развитием всего остального мира.",
    ["ba2aab5b"] = "В намерении добраться до Ледяной Короны и предложить свою службу Королю-личу, верховный маг миновал опустошённые войной земли Азжол-Неруба. Кел'Тузад своими глазами увидел, насколько могучим и яростным был Нер'зул. Он начал осознавать, сколь мудрым было его решение вступить в союз с загадочным Королём-личом и какие плоды этот союз мог принести.",
    ["ba3ab6a6"] = "Шаэл'дрин – это дриада, охраняющая лунный колодец к северо-востоку от озера Ирисов. Она отказывается покинуть лес и оставить его во власти порчи. Я знаю, что у неё достаточно сил и знаний, чтобы восстановить жезл или по крайней мере сказать мне, как я могу это сделать самостоятельно. Навершие Навершие попало в руки друидов Дор'Данила. Но тут всё не так просто: эти друиды погибли. Теперь в Дор'Даниле обитают их духи, которые не отличаются гостеприимством.",
    ["ba3eb689"] = "-День шестнадцать Улег и Таргил вернулись с задания в доках Терамора. В порту они видели новый корабль – \"Бешеный Воробей\". Корабль прибыл из Гавани Менетилов. Завтра Улег и Таргил вернутся в доки и прокрадутся на корабль. Они надеются найти там политические документы, раскрывающие отношения Терамора и Альянса.",
    ["ba4f246e"] = "В старом доме Ивара была занята оборонительная позиция, и пока Ран стоял на страже в ожидании дальнейших атак, Эрланд продолжил миссию рекогносцировки. Затем Эрланда прижали Ворги в северном фруктовом саду, и ему удалось спастись лишь при помощи другого агента Отрёкшихся. Этот агент и несёт данный отчёт.",
    ["ba4f68bb"] = "Обескураживало могущественных троллей. Здесь следует отметить, что последние открытия, по всей видимости, показывают, что тролли мало интересовались исследованием земель, находящихся за Великим морем. Хотя различные племена троллей обитали на всей территории Азерота, Каз Модана и Лордерона, в новооткрытых землях Калимдора и на островах Южных морей следов их цивилизации обнаружено практически не было. Говорит ли это о нежелании",
    ["ba8e966f"] = "Под руководством мудрого шамана Дрек'Тара Тралл изучил древнюю культуру своего народа, которая была почти полностью забыта при правлении коварного Гул'дана. Со временем Тралл сам стал могучим шаманом и занял своё законное место вождя клана. Исполненный силы самих стихий, Тралл отправился в путь, чтобы освободить свой народ и снять с него демоническое проклятие.",
    ["bac5198b"] = "Несмотря на то что причина стала ясна, Антонидасу не удалось найти лекарства, чтобы вывести орков из этого состояния. Кроме того, многие маги и некоторые лидеры Альянса полагали, что пытаться излечить орков – не самая благоразумная идея. Размышляя над проблемой, Антонидас пришёл к выводу, что лекарство для орков, каким бы оно ни было, должно врачевать душу, а не тело.",
    ["badcb5bf"] = "Пролитие крови нашей одним из Высокого Совета Бездны есть благословение! Мы должны завидовать нашим павшим товарищам, ибо души их теперь покоятся во чреве самого добродетельного зверя! Восславим же Древних Богов! Восславим слуг их! Восславим Сумеречный Молот!",
    ["bb1cf8a0"] = "ОФИЦЕРСКИЕ ЗВАНИЯ ОРДЫ. Часть два. Центурион. Легионер. Кровавый страж. Каменный Страж.",
    ["bb3d0863"] = "Этих грязных троггов так просто обвести вокруг пальца! Их ненависть к нашему роду позволяет двигать ими, как пешками. Вообще непонятно, как они пошли хоть на какой-то союз, ведь мы для них самая страшная угроза... по крайней мере, пока. Когда начнутся нападения, обе стороны ослабнут и не устоят перед нашим натиском. Захватите ферму к югу от озера Ложе Хелма и ждите дальнейших указаний. Стальгорн будет наш.",
    ["bb69e2d0"] = "Друиды не смогли заставить себя вынести стольким сородичам смертный приговор, поэтому решили просто изгнать безрассудных Высокорождённых из своих земель. Дат'Ремар и его сородичи были только рады освободиться от традиционного общества друидов, поэтому они быстро погрузились на флотилию судов и пустились в плавание по морям. Никто не знал, что ждёт их за исполинским бурлящим Водоворотом, но Высокорождённые хотели найти себе новый дом, где они могли бы безнаказанно практиковать свою любимую магию.",
    ["bb7769b1"] = "Когда рассветные туманы рассеялись, наступили дни, которые мы помним. Ценарион ушёл по своим неизбывным путям. Из-за его ухода Шу'хало, наречённые тауренами, впали в отчаянье и забыли многое из того, чему он учил. Сменилось поколение, и они разучились говорить с деревьями и травами. И тогда их ушей вновь начали достигать тёмные голоса из недр земли.",
    ["bb9aee08"] = false,
    ["bbc5b78b"] = "Довольный успехами Кел'Тузада в Лордероне, Король-лич готовился к нападению на людскую цивилизацию. Нер'зул поместил сгустки энергии чумы в передвижные артефакты, именовавшиеся котлами чумы, и приказал Кел'Тузаду перенести их в Лордерон, где их нужно было спрятать в селениях последователей Культа.",
    ["bc3074ba"] = "Я повёл группу по направлению к морю, надеясь, что линия берега послужит нам защитой от ящеров. В спешке мы забрались слишком далеко к северу, на особенно высокий холм. Это было ошибкой. Я был виноват. Мы остановились прямо перед обрывом, заканчивающимся отвесной скалой, а ящеры были всего в нескольких шагах позади нас.",
    ["bc4af43c"] = "ОФИЦЕРСКИЕ ЗВАНИЯ АЛЬЯНСА. Часть один. Главнокомандующий. Фельдмаршал. Маршал. Командир. Лейтенант-командор.",
    ["bc518815"] = "Западные комбинации кристаллов. Существует два возможных эффекта: один повышает вашу защиту от урона, второй ослабляет защиту противника. КРИСТАЛЛ-ХРАНИТЕЛЬ: Требуются красные и зелёные кристаллы. Повышает вашу характеристику \"броня\". КРИСТАЛЛ-ГУБИТЕЛЬ: Требуются синие и красные кристаллы. Может снизить характеристику \"броня\" выбранной цели.",
    ["bc628ab0"] = "Кил'джеден знал, что Орда, наконец, готова. Орки стали мощнейшей силой Пылающего Легиона. Коварный демон рассказал обо-всём своему повелителю, и Саргерас согласился, что час расплаты настал.",
    ["bcc96b8d"] = "Не понимаю, как мне удалось выжить в ту ночь. Я всегда был осторожным, не ввязывался в драки и не попадался в ловушки. Я даже получил за это своё прозвище. Наверное, эта природная осторожность спасла меня от смерти... Или Коса, которую я вытащил из хлама. Хотя вряд ли сама Коса, её я потерял во время своего отчаянного бегства. Но если воргены появились в Сумеречном лесу из-за меня, тогда, похоже, они оказали мне ответную любезность. Чтоб им провалиться!",
    ["bccdbd25"] = "Сотня людских магов и множество эльфийских волшебников вызвали ярость небес и напустили пламя на армию троллей. Огонь стихий лишал троллей возможности исцеления ран, сжигая их изнутри и снаружи.",
    ["bced6fdf"] = "Начать процесс охлаждения, который в этот момент потребует примерно от одной до двух минут (в зависимости от ситуации) для своего завершения. ВАЖНОЕ ЗАМЕЧАНИЕ: главным силовым рубильником можно манипулировать, только когда три контрольных клапана на самих машинах выключены. Выключать эти клапаны можно в любом порядке. Первый – ГЛАВНЫЙ КОНТРОЛЬНЫЙ КЛАПАН, который можно найти у основания большой вертикальной дымовой трубы. Далее – КЛАПАН УПРАВЛЕНИЯ ТОПЛИВОМ, его можно найти на большой трубе, которая ведёт",
    ["bcfdddcb"] = false,
    ["bd39f105"] = false,
    ["bd59f608"] = "Опалённый паучий клык: Огневитовая жила, найденная в Пещере Тельгена, сожгла живших по соседству пауков. Яд из их жвал кипит и вступает в реакцию с самими их клыками, в результате чего получается очень стойкое вещество.",
    ["bd9d66a7"] = "Среди политической неразберихи многие начальники лагерей стали замечать изменения в поведении пленных орков. Число попыток побега и даже драк между заключёнными резко уменьшилось. Орки стали спокойными и безразличными.",
    ["bdabd758"] = "Надеюсь, ты получил мой знак. Я пишу тебе, потому что нашему народу нужны мечники, копьеносцы и другие отважные воины. С тех пор как нам стало известно о других расах Азерота, мы ещё больше нуждаемся в сильных защитниках. Это твой путь. Твоё призвание. Я расскажу тебе больше, но только при встрече с глазу на глаз. Ищи меня на нижнем уровне Альдрассила. -Алайссия, наставница воинов",
    ["bdd2ed79"] = "Некоторое время назад в штабе Лиги исследователей в Стальгорне нам читал лекцию главный археолог Седой Ус. Старикан упоминал такое божество, почитаемое странными эльфами Дарнасса за его, по слухам, бескорыстную натуру... Ба! Один момент. Я слышу хрюканье за моей палаткой. Наверняка это просто щетинистые вепри пытаются добраться до моего запаса яблок...",
    ["be892041"] = "Высшие эльфы, ведомые Дат'ремаром, покинули Калимдор и миновали Водоворот с его бурями. Их флот много долгих лет плавал среди обломков старого мира, они открыли множество тайн и потерянных королевств. Дат'ремар, взявший имя Солнечный Скиталец (или \"тот, кто ходит весь день\"), искал места с большей магической энергией, чтобы построить там новое королевство для своего народа.",
    ["bebe12f1"] = "В это время, когда Божественный Свет согревает наши души, а каждый день дарит нам новые открытия, особенно хорошо быть одним из сыновей Стальгорна. Лига Исследователей с каждым днём всё более продвигается вперёд, находя давно потерянные ответы на ещё более древние вопросы. А ещё теперь среди нас есть ты, способный помочь в борьбе с троггами и всеми другими врагами. Найди меня, когда у тебя будет время. Я буду в Старой Наковальне, что находится выше по склону. - Брансток Халдер, наставник жрецов",
    ["becc55b8"] = "Призывы Короля-лича не остались незамеченными, особенно в небольшой группе могущественных личностей. Среди них был верховный маг Кел'Тузад, влиятельный участник правящего круга Даларана, Кирин-Тора. Его стремление овладеть всеми видами волшебства нарушало правила Кирин-Тора, возбраняющие практиковаться в чёрной магии. Кел'Тузад оставил Кирин-Тор, порвал все связи с обычным миром и поклялся стать прилежным учеником Короля-лича.",
    ["beccdb7c"] = "*Страницы покрыты древними эльфийскими рунами.* Эти страницы содержат воспоминания о событиях, произошедших при сборе и приготовлении реактивов, необходимых для создания простого магического камня. Да не получат наши враги никогда доступ к этим письменам. Да доживу я до тех пор, когда бледный свет луны вновь осветит Кель'Талас. Да умру я во имя Кель'таса. Да буду убивать я во славу Иллидана. -Мастер Кариэль Винтхалус",
    ["bf732235"] = "Хотя империи Гурубаши и Амани недолюбливали друг друга, конфликты между ними были редкостью. Их общим врагом был Аз'Акир – цивилизация насекомоподобных существ с дальнего запада. Разумные насекомые отличались невероятной агрессивностью и стремились искоренить все остальные формы жизни Калимдора.",
    ["bfbd5440"] = "Отчёт о положении дел с троллями из племени Мерзлогривов в регионе Холодной долины. Подготовлен Грелином Белобородом, особым посланником Сената. Я потратил немало времени, наблюдая за деятельностью племени Мерзлогривов в Холодной долине, и полагаю, что они не представляют особой угрозы дворфийским поселениям в этом районе. Более того, эту угрозу можно уничтожить даже без особой поддержки со стороны армии. Учитывая помощь горных пехотинцев, уже находящихся в",
    ["bffca993"] = "*Генерал Туралион Правая рука лорда Андуина Лотара.* *Рыцарь ордена Серебряной Длани.* *Главнокомандующий экспедиции Альянса, которая отправилась на Дренор, родной мир орков.* *Предположительно погиб.* Эзарус тар но-Дарадор – \"Кровью и честью мы служим\". Ты был десницей справедливости и добродетели, старый друг. Твоё имя всегда будет почитаться в наших землях. - Лорд Утер Светоносный, рыцарь ордена Серебряной Длани",
    ["c034ceeb"] = false,
    ["c0759c14"] = "Восточная комбинация кристаллов Существует два возможных эффекта: один оказывает положительный эффект на дух, второй создаёт щит, наносящий урон. КРИСТАЛЬНАЯ СИЛА: требуются синие и зелёные кристаллы. Повышает вашу характеристику \"дух\". КРИСТАЛЬНЫЙ ШИП: требует синих и жёлтых кристаллов. Создаёт щит, который будет наносить урон атакующим.",
    ["c0d17d85"] = "Привет, Фелнок! Мои исследования в Пылающих степях продвигаются отлично. Я весьма обязана путнику за его помощь! Вот что мне нужно, чтобы продолжать исследования: Бумбербитцель из рулонной стали, Ледяной гаечный ключ номер семнадцать, Двенадцать фунтов утиных перьев И банку твоего клея. Спасибо тебе большое, Фелнок, когда мы увидимся снова, напомни, чтобы я не подкладывала уголь в твои ботинки! — Тинки",
    ["c0dabe69"] = "Приветствую тебя. Мне удалось-таки узнать кое-что из той записки. О Джеймсе выяснилось немногое. Но зато о семье Амелии мне удалось разузнать больше. Она и её дети не пережили войну, а вот её брат, Александр Кальдер, выжил; найти его ты можешь в Заброшенном гроте, что в Стальгорне; там он изучает зловещую магию Пылающего легиона. Ещё она близко общалась с сестрой, Дези Холодная, которая теперь живёт в Оргриммаре и занимается проблемой Низины Арати. Когда будешь поблизости, найди одного из них. Уверен, им будет интересно узнать об Амелии.",
    ["c0dd9032"] = "И воды упали на джунгли, смывая всё на своём пути. Тролли и звери кричали от ужаса и муки, пока воды терзали и поглощали их. Многие Гурубаши гадали, за что океан обрушился на них, но они умерли, так ничего и не узнав. И наконец, достигнув гор, воды остановились. Умиротворённые, они вернулись в свои берега, оставляя за собой смерть. Воды отступили, но И'лалай они окружили и затопили навсегда.",
    ["c12c2ecb"] = "Наш поход может продлиться всего несколько дней и оказаться приятной прогулкой, а может завершиться кровопролитным сражением, в котором я погибну. Если уж мне суждено пасть, сражаясь за Альянс, то я готов. Меня не терзают никакие сомнения или колебания, моя храбрость несокрушима.",
    ["c12c5d0d"] = "Первые удары Плети по Дарроуширу были сравнительно редкими и слабыми. Отдельные группы скелетов и ходячих трупов, нападавшие на окрестности деревни, легко отгонялись её защитниками. Но Плеть не собиралась отступать, и вскоре на поселение обрушилась вторая волна атак. Отборные вурдалаки под предводительством лорда Хоргуса спустились с холмов и вступили в бой с защитниками Дарроушира.",
    ["c13346f1"] = "Дорогой дневник, прости, я заснул. Когда я в ярости летал и разбрасывал листы из этой глупой книги, то увидел под собой в Теснине Зловещего Шёпота демона и решил сделать из страниц первой главы магическое торнадо, чтобы разорвать его тело на миллион кусочков! Я словно заново родился. Магия плюс бумага равно веселье. Этот случай меня изрядно развеселил, и я решил полететь в Восточные королевства. Первой моей остановкой были Огненные Недра. Нарайн постоянно о них твердил! \"А вот когда я был в Огненных Недрах, да в Рагнаросе...\"",
    ["c136a0ad"] = "Клан Бронзобородов под управлением тана Мадорана Бронзоборода имел хорошие связи с королём и был защитником Стальгорна. Клан Громового Молота, управляемый таном Кардросом Громовым Молотом, населял холмы и утёсы у подножья горы и пытался добиться большей власти в городе.",
    ["c14495c4"] = "Всё более снедаемый тревогой и тоской, Саргерас был вынужден по приказу титанов вступить в бой с ещё одной группой тварей, жаждавшей разрушения: Натрезим. Эта тёмная раса демонов-вампиров (также известных как повелители ужаса) завоевала множество населённых миров, вселяясь в их обитателей и склоняя их ко тьме.",
    ["c16cc2c6"] = "Элиза. Возлюбленная жена, пусть земля утолит твой голод.",
    ["c18a7251"] = "Матиас Шоу послал какого-то рассыльного убить меня... *Текст неразборчив* Теперь он бродит снаружи. Тупой, безжизненный чурбан. Ха-ха-ха!",
    ["c1e34c02"] = "Империя росла и охватывала все новые земли, а юные маги двинулись на юг. Используя свои мистические силы, маги защищали своих собратьев от диких животных и сделали возможной постройку новых городов-государств в диких местах. Но в то время как их силы росли, маги становились всё более высокомерными и всё больше отдалялись от остальных людей.",
    ["c1ea0851"] = "На протяжении многих лет ночные эльфы работали не покладая рук, чтобы восстановить то, что осталось от их древней родины. Они оставили свои разрушенные храмы и дороги зарастать и построили новые дома среди зелёных деревьев и тенистых холмов у подножия горы Хиджал. Мало-помалу из своих укрытий выбрались и драконы, пережившие Великий Раскол.",
    ["c2e3047d"] = "Уровень секретности этой информации СТОЛЬ высок, что понадобится изобретение нового числа, чтобы описать его!",
    ["c2fde3ef"] = "Составляющие Ритуала Перед началом ритуала у тебя должны быть следующие компоненты: Кувшин Д'жииви Чёрный Магнит Ксоротианские Иероглифы За определённую цену мой слуга Горзиеки добудет их для тебя. Без них ни одно действие ритуала выполнять нельзя. Каждый компонент очень важен. На следующих страницах я подробно опишу их применение.",
    ["c326cfcf"] = "ОТЧЁТ: Воры. Более тревожит то, что не только кобольды, но и банды людей-воров появились в долине. Они носят красные повязки и называют себя братством. Такой уровень организованности может доставить неприятности и здесь, и во всём Элвиннском лесу. Мы идентифицировали одного из их лидеров – это Гаррик Тихокрад – и надеемся вскоре предать его правосудию.",
    ["c3275500"] = "Со временем лорды Строма переселились в богатые северные земли Лордерона, оставив засушливый юг. Наследники короля Торадина, последние потомки рода Арати, запретили покидать Стром, чем вызвали недовольство богачей, которые желали уехать.",
    ["c3a0986e"] = "Девлином завладело отчаяние, и он искал, как избежать ожидающей нас печальной участи, и вот почему он заключил договор с Плетью. Я не знаю, сколько ему пообещали за предательство, но я уверен, всё это было ложью. Если ты встретишь моего брата, беги от него. Он – монстр. Несколько ночей назад он убил двоих наших часовых и провёл небольшую группу Плети через эту брешь к тому месту, где спало большинство из нас.",
    ["c3d933a2"] = "Храмовники Бездны Тебе, как новичку, разрешается обращаться к Храмовникам Бездны для проведения обычных ритуалов. Не забывай надевать подобающее убранство при обращении с Ветровыми Камнями, чтобы на тебя не подействовали наши защитные чары. Если вдруг случится нечто непредвиденное в отсутствие старших, тебе разрешается вызвать Храмовника Бездны. За подробностями о проведении соответствующих ритуалов призыва обращайся к выпуску Истинно Верующего за прошлый месяц.",
    ["c4b2710e"] = "(Значительная часть текста на странице залита кровью, но вы можете разобрать одно имя) Карендин",
    ["c51e1374"] = "Проходили века, Хранители защищали людей от невидимой угрозы Пылающего Легиона по всему Аратору и Кель'Таласу. Аратор рос и процветал, а использование магии распространилось по всей империи. Тем временем Хранители пристально наблюдали: не появится ли признаков активности демонов.",
    ["c5688049"] = "Не стоит и говорить, что мы, служащие в Каргате, очень рады своему назначению. Мы всё – как неприступная твердыня, ведь иначе нам не выжить. А ничего другого мне и не надо. Ника Алый Шрам Глава разведчиков, Каргат.",
    ["c5728ed1"] = "Среди них – кузнечный молот, что дал мне мой отец. В молодости я сомневался в этом, но он всегда говорил мне, что этот молот зачарован, и это последнее, что он сказал мне перед тем, как его погубила Плеть. Принеси мне этот молот, чтобы я смог использовать его со всем своим пылом. Если он действительно зачарован, то он поможет нам обоим. Я оставил его в стойлах в главном внутреннем дворе крепости. Если населяющие её чудовища сами не занимаются кузнечным делом, то, я думаю, он всё ещё лежит там.",
    ["c5ea0591"] = "История Гри'лека Странника. ...Начало надписи, выбитой на камне, стёрлось, но окончание всё ещё можно было прочитать... Гри'лек топал по джунглям. Его глаза горели, и его грудь клокотала, ибо великий гнев переполнял его. В ярости он рычал на небо и воздевал руку. Он воздевал левую руку, ставшую сильной и крепкой от охоты без своего близнеца. Ибо правая рука Гри'лека была утрачена безвозвратно.",
    ["c633038b"] = "Кстати, будь осторожен с ними. Один нитромирглицероний сам по себе может разнести тебя в пыль. Я поместил часть жидкости в медные пробирки, которые должны защитить от сотрясений и обеспечить безопасность. Свиток, который ты получил от Коллина, я использовал в коробках с детонаторами. Теперь они пошлют бесшумное сообщение зарядам эн-джи-пять когда ты их включишь. Я использовал простой сталтваргонский механизм, чтобы обеспечить оптимальную проводимость проводов и скорость потока нитромирглицерония между разностными жидкостями лучше среднего.",
    ["c64adf97"] = "При поддержке своих помощников Утера Светоносного, адмирала Даэлина Праудмура и Туралиона, Лотар убедил получеловеческие народы Лордерона в необходимости противостоять надвигающемуся вторжению. Альянс также смог заручиться поддержкой дворфов из Стальгорна и некоторых высших эльфов из Кель'Таласа.",
    ["c6539a1d"] = "Адмирал поставил Джайну перед страшным выбором: выступить против новообретенных союзников-орков или сразиться с собственным отцом в надежде сохранить хрупкий мир между Альянсом и Ордой. После сильных душевных метаний Джайна выбрала последнее и встала на сторону Тралла.",
    ["c660eed5"] = "Звезда Ксиль'и Звезда у Грелборга Скряги. Он – жадный огр, который проводит свои дни в горах и руинах Альтерака в поисках блестяшек. Большая часть его коллекции бесполезна, но одна вещь, Звезда Ксиль'и, обладает ценными свойствами.",
    ["c6c31679"] = "Прежде чем я продолжу, позволь мне поблагодарить тебя ещё раз за то, что ты сделал для меня и моей жены. Ты спас ей жизнь, и за это я обязан тебе большим, чем смогу отплатить за сотни жизней. Она – всё для меня. Если бы она умерла... ну, я не знаю, что бы я сделал. Вот список того, что тебе нужно собрать, если ты хочешь, чтобы я сковал тебе оружие Света. Я записал их по порядку, от простого к сложному – надеюсь, так тебе будет проще.",
    ["c6e5a11b"] = "В конце концов ночные эльфы обожглись именно на том чародейском огне, который стремились подчинить. Их безрассудное злоупотребление магией привлекло в мир демонов Пылающего Легиона, которые нанесли существенный урон эльфийской цивилизации. Насчёт войн демонов с троллями ничего не известно, но можно предположить, что нашествие не обошло их стороной.",
    ["c6fe9976"] = "ОФИЦЕРСКИЕ ЗВАНИЯ АЛЬЯНСА. Часть один. Главнокомандующий. Фельдмаршал. Маршал. Командор. Лейтенант-командор.",
    ["c7214e3b"] = "Как только мне стало известно, что ты готов к обучению, я тотчас же послал тебе знак. Друиды Кенария рады любому пополнению своих рядов. Даже духи становятся сильнее, когда нас больше. Рано или поздно, проявив должное терпение, мы вернём былое величие. Найди меня возле верхушки Альдрассила. Я буду твоим проводником, пока ты живёшь в Тенистой долине. - Мардант Крепкий Дуб, наставник друидов",
    ["c764f34e"] = "Я никогда так не гордился своим ремеслом, как в последние несколько лет. Спрос на услуги убийц, шпионов и разведчиков высок как никогда. На первый взгляд может показаться, что нас кормит война. Но ни в одну войну мы не процветали так, как процветаем сейчас, когда мирное время подходит к концу. Мне передали, что ты появился в наших краях и хочешь кое-чему научиться. Когда будет время, приходи к стойлам позади аббатства. -Джорик Керридан, наставник разбойников",
    ["c79b1df6"] = "Мор Серое Копыто, продолжение. Позже мы узнали, что Мор тогда выжил. Но после этого его ждала ещё более страшная участь, чем смерть: его взяли в плен тролли Тазз'Алаора. Там его подверг страшным пыткам Воевода Вун, а потом его нашли убийцы Вальтхалака и избавили, наконец, от мучений. Дух Мора Серого Копыта ты найдёшь в логове Воеводы Вуна; это ещё одно из мест с привидениями.",
    ["c7babf30"] = "Титан Норганнон, хранитель знаний и владыка магии, даровал синему дракону Малигосу часть своей великой силы. С того времени Малигос, известный как Хранитель Магии, хранит магию и тайные знания.",
    ["c7cabfd9"] = "Эльфы под предводительством Анастериана Солнечного Скитальца не хотели вмешиваться в предстоящий конфликт. Но они не могли отказать Лотару – последнему из рода Арати, который поддерживал их в прошлом.",
    ["c837f886"] = "Аргус, как тебе известно, я сейчас занимаюсь различным ремонтом в армии. Работа спорится, но вот мои запасы железа иссякли. У меня не хватает материалов на подковы. Зная, что ты всегда хранишь большой запас, хочу одолжить у тебя пятьдесят пар, пока я не получу следующую партию железа. Заранее благодарю, -Вернер",
    ["c87b2488"] = "Здесь покоятся останки короля Теренаса Менетила Второго – Последнего Истинного Короля Лордерона. Велики были его дела, долгим было его правление, немыслимой была его смерть. \"Да не будет на отце вины за бесстыдные поступки сына. Да останется потерянной и забытой окровавленная корона\".",
    ["c87d349f"] = "*Ещё цитаты!* \"Знаешь это чувство, когда ты заканчиваешь делать что-то и включаешь это первый раз, чтобы испытать его силу и насладиться своим изобретением, когда оно начинает оживать? А вот гномы не знают\". -- Никс Шепружин, главный гоблинский инженер из Прибамбасска *\"Инженерное дело – это когда берётся фантазия и делается ещё более фантастичной!\" - Ровис Мак-Хрясьшатун, гномский изобретатель.*",
    ["c8b536e0"] = "Список дел. Уложить снаряжение перед выходом на охоту. Снабдить пояс Грунда карабинами. Починить сварочную маску. Послать маме открытку. Страница сорок пять.",
    ["c914f655"] = "Всего через несколько месяцев после завершения строительства Крепости Стражей Пустоты вся энергия Тёмного портала слилась воедино и открылся новый проход на Дренор. Оставшиеся кланы орков под предводительством старого шамана Нер'зула вновь напали на Азерот. Собираясь украсть ряд магических артефактов, которые должны были увеличить могущество Нер'зула, орки планировали открыть несколько новых порталов на Дреноре, которые позволили бы им навсегда покинуть свой обречённый мир.",
    ["c924e0d3"] = "Потрёпанным и обескровленным оркам оставалось лишь спешно сбежать в последний оплот орочьей силы – в Тёмный портал. Туралион и его воины гнались за остатками войска орков по зловонному Болоту Печали в мрачные Выжженные земли, где стоял Тёмный портал. Там, у подножия колоссального портала, обессиленная Орда и измотанный Альянс схлестнулись в схватке – той, что должна была стать последней, самой кровавой битвой Второй войны.",
    ["c952f53d"] = "Все наши шмыгуносы хорошо обучены, и вам достаточно лёгкого взмаха вашей палочки-погонялочки, чтобы перевести ближайшего шмыгуноса в режим поиска. После этого шмыгунос начнёт принюхиваться в поисках корней, и если он почует один из них, то двинется по направлению к нему и начнёт его выкапывать. Если вы ещё раз взмахнете палочкой-погонялочкой в сторону шмыгуноса, ищущего корни, он прекратит свои поиски и радостно вернётся к вам. Мы уверяем вас, что вы найдёте наших шмыгуносов хорошо обученным, полезным и невероятно подходящим приобретением для вашей команды!",
    ["c96285de"] = "Убеждённые в том, что они могут самостоятельно противостоять троллям или даже эльфам, военачальники Арати решили построить могучий город-крепость в южных регионах Лордерона. Город, названный Стром, стал столицей государства Арати, Аратора. В то время как Аратор процветал, люди со всего огромного континента шли на юг, дабы жить под защитой Строма.",
    ["c9668620"] = "Твой драгоценный зверь не очень-то хорошо себя чувствует в обжигающем жаре Выжженной Теснины… лучше тебе незамедлительно выполнить наши требования. Ты принесёшь нам пять звёздных рубинов и семьсот золотых, и положишь всё это в один пакет без пометок. Пакет не позже чем через неделю оставь у входа на Подгорную тропу. Если наши требования не будут выполнены, Метцен украсит собой традиционный дворфийский стол на Праздник Зимнего Покрова. Олень… вкуснятина…",
    ["c9a79c79"] = "Рыболовный чемпионат Тернистой долины! Проводится по воскресеньям, с четырнадцати до шестнадцати часов. Закиньте удочки где угодно на побережье Тернистой долины (кроме Пиратской бухты) и ищите косяки вкуснорыбы, что появляются вдоль берега! Старайтесь забросить удочку как можно ближе к стайке рыб, и тогда у вас будет возможность поймать особенную рыбу вместо обычных, которых полно в Тернистой долине. Первый, кто выловит сорок вкуснорыб, сможет сдать их Мастеру Мормышу в Пиратской бухте и получить вознаграждение! Даже если вам не удалось поймать сорок вкуснорыб первому, вы сможете обменять их на деньги, а за некоторых рыб можно получить ценные призы!",
    ["c9b7ff9d"] = "*Капитан следопытов Аллерия Ветрокрылая* . Знаменитая охотница на троллей из Кель'Таласа. Главная разведчица при экспедиции Альянса, которая отправилась в Дренор, родной мир орков. Предположительно погибла. Сестра, твоё сердце было решительно и неукротимо, как стрела, летящая по ветру. Ты была самой яркой из нашего Ордена. Ты была самой любимой из нашего рода. - Сильвана Ветрокрылая, предводитель егерей Кель'Таласа",
    ["c9d4ae1d"] = "Знай, охотник, эти демоны дерутся только по своим правилам. Если им покажется, что одолеть тебя нельзя, они сбегут. ИДИ К НИМ ОДИН.",
    ["c9f66ff6"] = "Несмотря на то что восстание было подавлено, Орде не удалось оправиться от ужасных потерь. Предательство Гул'дана не только придало Альянсу уверенности, но и обеспечило им время на перегруппировку и подготовку к ответной атаке.",
    ["ca01ccb5"] = "Видя, что Орда раскалывается изнутри, лорд Лотар собрал последние силы и отбросил Молота Рока на юг, к центру Штормграда. Там войска Альянса окружили Орду в вулканической крепости пика Чёрной горы. Лотар пал в этой битве, но один из его командиров, Туралион, в последний момент взял на себя командование войском и заставил Орду отступить к бескрайнему Болоту Печали.",
    ["ca0340f7"] = "Привет, Фелнок! Мои исследования в Пылающих степях продвигаются отлично. Я весьма обязана путнику за его помощь! Вот что мне нужно, чтобы продолжать исследования: Бумбербитцель из рулонной стали. Ледяной гаечный ключ номер семнадцать. Двенадцать фунтов утиных перьев. Банка твоего клея. Спасибо тебе большое, Фелнок. Когда мы увидимся снова, напомни, чтобы я не подкладывала уголь в твои ботинки! -Тинки",
    ["ca2017db"] = "Брат Нилз, Мой виноград спасён! Путник, предъявитель сего письма, спас мой наводненный головорезами виноградник и собрал весь виноград, что я не успела собрать. Несмотря на то что бандиты всё ещё бродят у реки, практически весь мой урожай был спасён. Ты можешь добавить к своим запасам полные корзины винограда. Да защитит нас Свет, -Милли Осворт",
    ["ca92d96a"] = "Во главе с Громом Адским Криком все вожди, кроме Дуротана, повиновались и тем самым обрекли себя на вечную службу Пылающему Легиону. Те, кого коснулась ярость Маннорота, пусть не желая того, превратили своих ничего не подозревающих собратьев в таких же рабов, какими стали сами.",
    ["ca9b0141"] = "В преданиях троллей говорится, что в первый раз Камень Приливов попал в империю Гурубаши, будучи найденным воином-троллем, бродившим по побережью Тернистой долины. Воину попался на глаза таинственный синий камень, внутри которого сплетались и струились молочно-белые прожилки. Заинтригованный воин взял камень с собой и продолжил свой путь. Со временем воин обнаружил, что камень даёт ему власть над водами. Он мог вызывать",
    ["caac48f2"] = "Зная Эдвина ван Клифа всю свою жизнь, я могу сказать, что видеть в нём своего врага мне неприятно. Понимаете, он был моим другом детства, и я лично учил его мастерству теней, надеясь, что однажды он будет работать вместе со мной. Если ван Клиф стоит во главе Братства Справедливости, то да помилует Свет наши души! Мастер Матиас Шоу, Гильдия убийц Штормграда",
    ["cac73745"] = "Кил'джеден отправил Нер'зула обратно на Азерот. Его ледяная тюрьма пронеслась по ночному небу и упала на заснеженный северный континент Нордскол, погрузившись глубоко в ледник Ледяной Короны. После падения кристалл принял форму трона, а дух Нер'зула, заключённый в нём, вскоре пробудился.",
    ["cb38bb75"] = "Гордость Оленьего Шлема была растоптана. Во второй раз за всю свою жизнь он почувствовал в животе трепетание, которое могло быть вызвано лишь страхом. Позже, в Танарисе, он пришёл к Анахроносу, отпрыску Ноздорму, и попросил Бронзовых драконов о помощи.",
    ["cbbdaba9"] = "(Оставшаяся часть книги пуста.)",
    ["cbc226c8"] = "Феррен Маркус Аббат Монастыря Алого ордена Гражданин Стратхольма Погиб при обороне монастыря во время Первого летнего штурма",
    ["cbd3cfe2"] = "Долго дети звёзд обитали на берегах мерцающих вод Источника Вечности. Всем было известно, что Элуна, свет вечной полуночи, аспект и богиня луны, обитала в его водах в то время, когда отдыхала от трудов. На берегах Источника построили свои дома дети звёзд, любимцы Элуны, живущие, не отводя взора от неба, глядя в лунную ночь. Хотя было построено много городов и мест обитания",
    ["cbd61b4c"] = "Во многих племенах способность разговаривать с умершими предками считается очень ценным даром. Но ты, герой, должен помнить, что твой дар не менее ценен. Те, кто говорит с духами, не могут поднять тяжёлое оружие или вытерпеть телесные страдания, причиняемые тайной магией. Ты – можешь. Ты сильный. Я помогу тебе стать ещё сильнее. Ищи меня в Лагере Нараче. -Харутт Громовой Рог, наставник воинов",
    ["cc20d145"] = "*Артишок клана Северного Волка: Повести о славе Грозовой Вершины Автор Вандар Грозовая Вершина* Что такое клан Северного Волка? Ответ прост: клан Северного Волка – сборище дикарей, жаждущих низвергнуть нас, своих законных повелителей. Он, подобно артишоку, окружён колючим и твёрдым защитным слоем, сняв который, можно добраться до сердцевины и съесть её с доброй чесночной подливой. Вкусно!",
    ["cc2b037b"] = "Я не могу описать того, что случилось дальше. Я ясно помню всё, но даже моя истерзанная душа не может изложить на бумагу последовавшие за тем несколько ужасающих минут. Я могу лишь написать, что семья Свена была убита. И вскоре вернулся Свен, чтобы увидеть эту страшную картину смерти. Такое горе исказило его черты, что я боялся выйти к нему. И я так боялся, что он может обнаружить меня сам, что покинул своё убежище в сарае. Я не знаю, где теперь Свен, но я молюсь, что когда-нибудь он обретёт покой.",
    ["cc2f2f06"] = "После гражданской войны пути оставшихся троллей из племени Гурубаши разошлись. Племена Дробителей Черепов, Кровавого Скальпа и Чёрного Копья нашли своё пристанище в джунглях Тернистой долины. На руинах империи воцарился хрупкий мир, но в народной памяти осталось пророчество о том, что однажды Хаккар вернётся в мир и поглотит его.",
    ["cc9b64cf"] = "Отчёт о положении дел с троллями из племени мерзлогривов в регионе Холодной долины. Подготовлен Грелином Белобородом, особым посланником Сената. Я потратил немало времени, наблюдая за деятельностью племени Мерзлогривов в Холодной долине, и полагаю, что они не представляют особой угрозы дворфским поселениям в этом районе. Более того, эту угрозу можно уничтожить даже без особой поддержки со стороны армии. Учитывая помощь горных пехотинцев, уже находящихся в",
    ["cca906bc"] = "Так о чём я? В общем, Укрытиями Дун Болдара (расположены они в Дун Болдаре) управляют защитники из клана Грозовой Вершины – лучшие стражи Вандара, которым он доверяет больше всех. Уничтожь две башни, и подкрепление, которое выходит на помощь Вандару, прекратит своё существование.",
    ["ccbb82b8"] = "Агашам! Наши планы должны оставаться тайной при любых обстоятельствах! Нельзя допустить, чтобы остальные племена узнали о них. Подпись: Вестник Эльм",
    ["ccc5b530"] = "Третья фракция, клан Чёрного Железа, была под командованием тана-чародея Тауриссана. Дворфы Чёрного Железа таились в самых глубоких тенях под горой и замышляли заговор против своих собратьев из клана Бронзобородов и клана Громового Молота.",
    ["cd7d70e6"] = "Высокорождённые с головой ушли в работу и беспрерывно изучали Источник. Со временем они развили в себе способности управлять его космической энергией. Чем больших успехов Высокорождённые достигали в своих опытах, тем явственней они понимали, что с помощью своих новообретенных навыков они могут как творить, так и разрушать. Злосчастные Высокорождённые зациклились на примитивной магии и твёрдо решили добиться мастерского владения ею.",
    ["cd90c367"] = false,
    ["cdcfc786"] = "Первый успех взбодрил нашу команду. Барнил налил всем меда, чтобы отметить его. Но нашему празднованию не суждено было продолжаться долго. Когда мы подготавливали тушу к транспортировке в лагерь, внезапно раздался ужасный рёв. Я в жизни не слышал такого леденящего кровь звука.",
    ["ce70956b"] = "Культисты под командованием Кел'Тузада жаждали смерти, после которой они могли бы восстать и служить своему тёмному властелину. В этом они увидели шанс на бессмертие и возрадовались ему. Чем дальше расходилась чума, тем больше ужасных зомби появлялось в северных землях. Кел'Тузад, глядя на растущее войско Короля-лича, назвал его Плетью – ведь скоро она придёт к воротам Лордерона... и могучим ударом бича снесёт человечество с лица земли.",
    ["ceeb1ce3"] = "На этот раз не должно было быть никаких ошибок. Кил'джеден решил, что нужно ослабить оборону Азерота ещё до того, как Легион ступит на его земли. Расы смертных, такие как ночные эльфы и драконы, занятые борьбой с новым врагом, были бы уже неспособны противостоять нашествию Легиона.",
    ["cef0a91d"] = "Дворфы Они, неустанно исследуя свои собственные корни, предпочитают отмечать праздник, восхваляя самого Дедушку Зиму. Его дворфы считают воплощением древних жителей Азерота – титанов. Полагая, что сами они приходятся в какой-то мере родней этим таинственным существам, дворфы объявили своё снежное обиталище Дун Морог главным доказательством благосклонности Дедушки Зимы.",
    ["cefce42b"] = "*К ящику прилагается записка.* *В ней значится:* \"Вернер, грустно слышать, что в Красногорье нехватка ресурсов. Вот подковы, которые ты просил. Когда будет возможность, пришли мне сто серебряных монет.\" \"Или, если хочешь, можешь расплатиться брюшной чешуёй детёнышей чёрного дракона (слышал, что в Красногорье их полно). Так как ты мой друг... Четырёх чешуек будет более чем достаточно. Благодарю. -- Аргус\"",
    ["cf07176d"] = "Мне вспоминаются блаженные минуты, проведённые с тобой, и я испытываю огромную благодарность Свету и тебе за то, что наслаждался ими так долго. Но как же тяжело мне отказаться от них и спалить дотла надежды на будущие годы, в которых мы всё ещё могли бы жить вместе, любить друг друга и смотреть, как наши сыновья растут честными дворфами!",
    ["cf6a6fbf"] = "Флот Праудмура представлял серьёзную угрозу стабильности в регионе. Будучи знаменитым героем Второй войны, отец Джайны всей душой ненавидел Орду. Он твёрдо решил уничтожить Дуротар прежде, чем орки закрепятся на этой земле.",
    ["cf728091"] = "Жаждавший могущества, Гул'дан отправился на поиски подводной Гробницы Саргераса, где он надеялся раскрыть тайну абсолютной силы. Гул'дан уже обрёк своих воинов на вечное рабство в Пылающем Легионе и о своём долге перед Молотом Рока он беспокоился меньше всего.",
    ["cf8c83cf"] = "С какой радостью я бы смыл своими собственными слезами малейшее пятнышко на твоём счастье и боролся бы со всеми невзгодами этого мира, чтобы защитить тебя и наших дорогих деток! Но я не могу. Мне придётся наблюдать за тобой из Круговерти Пустоты и витать возле тебя, пока ты в одиночку противостоишь всем бурями со своей драгоценной маленькой ношей, выдерживаешь шторм со своим маленьким ценным грузом. Мне придётся терпеливо ждать, пока мы встретимся, чтобы больше не расставаться никогда.",
    ["cf9378f9"] = "Лорд Элло Чернодрев-- Город Приозёрье смиренно просит Ночной дозор о помощи. Нас осаждают, нас держат в осаде орки Чёрной Горы и гноллы из стаи Темношкуров, прислуживающие Морганту. Я бы никогда не попросил о помощи, но мы в тяжёлом положении. Мы ожидаем подкрепления из Штормграда, но пока оно прибудет, я прошу Вас оказать нам поддержку. Падёт королевство – и все люди будут обречены. Мировой судья Соломон",
    ["cfb831f9"] = "Кил'джеден подготавливал Орду к нападению на Азерот, а Медив в это время продолжал сражаться с Саргерасом за свою душу. Король Ллейн, благородный правитель Штормграда, узнал о том, что тьма завладела душой его бывшего друга.",
    ["cfc12f74"] = "Боюсь, за происходящим в Северных землях стоит более могущественное и ужасное зло, чем мы предполагали. Королевство Штормград обязано принять меры, иначе нас ждёт погибель или, что хуже, мы станем послушными рабами нашего врага. Подпись, Чиновник Соломон Приозёрье Королевство Штормград",
    ["cfc58b7d"] = "Прежде чем я вернусь к подробностям своего плана, давай я объясню тебе, куда поместить взрывчатку. План альфа – лесопилка: Перед лесопилкой есть вагончик (это к северо-востоку от места, где они вырубают лес и собирают древесину). Я подозреваю, что инженерные планы находятся внутри лесопилки. Чтобы установить заряд, направляйся за вагончик. Установив его, поспеши удалиться на приличное расстояние.",
    ["d0037d12"] = "Очищенная руда – есть в Телсамаре дворф-кузнец по имени Балор Крепкорук, в своё время он учил меня. Он делает очень специфичный сплав, который, я думаю, идеально подошёл бы для твоего оружия. По идее, партия сплава должна была прибыть ещё во время моего пребывания в Стальгорне, но до сих пор ни слуху ни духу. Найди его и проверь, не готова ли моя партия товара. Если его нет на озере Лок Модан, то мне хотелось бы хотя бы узнать, что случилось с моим старым учителем.",
    ["d02ec687"] = "Шу'хало навсегда покинули родные земли и стали кочевать по бескрайним равнинам. Но они хранят надежду, что их племена найдут новое пристанище под сенью любящих рук Матери-Земли.",
    ["d100e87b"] = "Тысячелетиями мы скрывались от чужаков. Я буду первой из нас, кто признает, что в прошлом мы ошибались. Нельзя было открывать людям магию. Я не отрицаю этого, но и не желаю приговаривать нас к заточению за промахи предшественников. Совместное существование Кель'дорай и других народов этого мира может принести много пользы. Мы должны учиться терпимости. (продолжение следует)",
    ["d15b70e9"] = "Краккены взревели, и голоса их были подобны грому в час бури: \"Мы идём!\" Но Мин'лот не дрогнул. Он призвал свою магию. Волны, посланные на И'лалай, расступились, обогнули город и залили джунгли позади него. Затем Мин'лот велел своим помощникам произнести сковывающие заклинания, и десятки тролльих голосов слились в нестройную песнь. Но один голос звучал громче остальных.",
    ["d18d95f1"] = "Нечестивые, коварные повелители ужаса обращали друг против друга целые народы, манипулируя их бездумной ненавистью и недоверием друг к другу. Саргерас легко победил натрезимов, но их порча глубоко запала в его душу.",
    ["d198655c"] = "На этот раз Плеть превратила практически весь Лордерон и Кель'Талас в ядовитые Чумные земли. Там осталось лишь несколько очагов сопротивления Альянса. Один из них, состоявший в основном из высших эльфов, возглавлял последний представитель династии Солнечного Скитальца – принц Кель'тас.",
    ["d1ad7e08"] = "Никто не знает точно, как зародилась Вселенная. Кто-то предполагает, что после сильнейшего космического взрыва в Великой Тьме стали вращаться бесконечные миры – миры, в которых затем зародилось великое многообразие форм жизни. Другие же считают, что Вселенная в её современном виде была создана одной-единственной всемогущей сущностью.",
    ["d1d1d16b"] = "ВОИНСКИЕ ЗВАНИЯ ОРДЫ И АЛЬЯНСА. Тром-ка! В этой книге ты найдёшь подробный перечень воинских званий Орды и жалкого Альянса. Сначала в списках идёт Орда, а затем Альянс, и для обеих сторон перечислены офицерские и рядовые звания. Как и подобает, вверху списка располагаются старшие чины, а младшие – ниже.",
    ["d1fd9b0a"] = "Приказ пиратам Кровавого Паруса Читайте и запоминайте, ребятки, другого такого удачного шанса напасть на Пиратскую бухту у нас не будет! Старину Данкена я послал с разведкой на север и сказал ему ждать сигнала. \"Госпожа Удача\" бросит якорь у южного мыса, чтобы взять припасы. Наш коротышка, капитан Штиллец, со своей командой приготовится забрать всё награбленное на борт. Ну а с остальным управится наш болван Брут.",
    ["d2033063"] = "Кил'джеден не давал духу шамана умереть, заставляя его в полной мере чувствовать ужасную боль, которую ему причинял. Нер'зул умолял демона послать ему смерть, но тот был непреклонен: он сказал, что Кровавый договор, который они очень давно заключили, всё ещё в силе, и Нер'зул ещё должен был сослужить демону службу.",
    ["d2442eeb"] = "Здравствуй, Вильям! Мы уже много лет не разговариваем, но я надеюсь, что у вас с братом всё в порядке и что ваша аптека процветает. У меня к тебе просьба, Вильям. В общем, мой внук Томми Джо влюблён в юную Мейбелл Маклур. Они друг в друге души не чают, но наши семьи... Конечно, наши семьи враждуют уже много лет...",
    ["d288e78e"] = "Он не искал себе почёт и славу И не хотел сородичами править. Решил он биться за Лордерон, Чтоб после уж народ его жил в мире.",
    ["d2a45130"] = "Надеюсь, это письмо дошло до тебя, герой. Я обращаюсь к тебе с гордостью, потому что немногие обладают столь крепкой верой и готовы войти в число величайших защитников Азерота. Никогда не забывай, твой главный долг – сражаться с теми, кто угрожает нашему миру и несёт скверну в наши дома. Меня назначили твоим наставником на первое время. Когда будешь готов, ищи меня в Аббатстве Североземья. -Брат Самуэль, наставник паладинов.",
    ["d316c67c"] = "Когда тролли были изгнаны из северных земель, эльфы Кель'Таласа направили все свои усилия на воссоздание своего великолепного царства. Армия Аратора с победой вернулась домой, в южные земли Строма.",
    ["d33ed044"] = "КАК ВЫГУЛИВАТЬ ШМЫГУНОСА Шмыгунос любит укромные, тёмные места. И он очень застенчив. Если вы хотите отправиться на прогулку с вашим шмыгуносом, то должны пойти в такое место, где бы он чувствовал себя как дома. И вы ДОЛЖНЫ отвести его туда, где бы он чувствовал запах его любимой еды – корней синелиста! Ближайшее такое место – это \"котлован\" в Лабиринтах Иглошкурых. Если вы откроете клетку неподалёку от неё и ваш шмыгунос почует запах клубней, то он решится отправиться вслед за вами.",
    ["d362d8f3"] = "Кил'джеден пришёл к предводителю кланов, могучему шаману по имени Нер'зул. Он пообещал ему необычайную мощь и мудрость, если тот заключит с демоном пакт, который отдаст кланы во власть Пылающего Легиона. Этот пакт предопределил не только судьбу орков, но и судьбу всего их мира.",
    ["d38fcc1b"] = "Уггель Тяжелорук Уггель – серьёзный и талантливый гравер, и когда он не отягощён тёмным ключом, из-под его рук выходят образчики великих творений, хранящихся в Зале Ремесла.",
    ["d3cd5285"] = "С первыми лучами солнца мы отправились на охоту на юг, за руины Ткаши. Барнил беспокоился, что мы можем наткнуться на троллей племени Кровавого Скальпа. Мои слова о том, что это племя сейчас занято войной со своими заклятыми врагами из племени Дробителей Черепов, конечно же, ничуть не успокоили его. Меня же возможность засады беспокоила гораздо меньше: в моих руках была заряженная винтовка, на поясе – полная сумка пороха, а рядом – трое отличных охотников.",
    ["d3e15111"] = "*Здесь покоится Громмаш Адский Крик, вождь клана Песни Войны* . Проклятие нашего народа началось с Грома – и им же закончилось. На нашем древнем языке его имя означает \"Сердце великана\". Он заслужил его, вступив в поединок с демоном Манноротом и купив нам свободу ценой собственной крови. Лок'тар огар, старший брат. Да пребудет вечно клан Песни Войны. — Тралл, вождь Орды",
    ["d3e287dc"] = "ПОЗДРАВЛЯЕМ! Вы стали владельцем замечательного шмыгуноса! Зверёк довольно робкий, но вам непременно полюбятся его пушистое обаяние и невероятный нюх. На следующих страницах приводится информация о: Один. Кормлении и заботе о шмыгуносе Два. Эксцентричном (и очаровательном) поведении шмыгуноса Три. Применении запатентованной палочки-погонялочки для шмыгуносов Поздравляем вас ещё раз. Вы не пожалеете, -Марвиг Ржавоболт Владелец \"Шмыг Инк.\"",
    ["d471bd28"] = "Одна стая потеряна. Я послала воргенов прочесать лес и выяснить, где кроются демоны, но они не вернулись. Я начинаю волноваться из-за лидеров, которым я доверила руководство. Они примитивны и немедленно начали злоупотреблять данной им властью. Сохраню ли я над ними власть? Может быть, я временно перестану вызывать новых воргенов. Да пребудет со мной благословение Элуны, пока не будет выполнена моя работа.",
    ["d4b2fa3e"] = "Аспекты их поклонения змеям в предыдущих томах этой работы, здесь я хотел бы рассмотреть примеры особого отношения троллей к морю. Великое море. Империя Гурубаши с трёх сторон была окружена морем, так что неудивительно, что морские воды играли значительную роль в жизни их общества. Обширные пространства своей поросшей джунглями империи тролли могли контролировать беспрепятственно, а вот море не желало им подчиняться. Широкое, бескрайнее, оно, несомненно,",
    ["d4ba9d00"] = "Эпилог Проделав всё это, ты доберёшься до самой цели, до центра луковицы. Вандар Грозовая Вершина будет один и безо всякой защиты. Правила ведения войны требуют нам предложить ему сдаться в плен, прежде чем убивать. Поэтому, как увидишь его, обязательно предложи ему сдаться… а потом убей.",
    ["d4c0c01f"] = "Драконы знали, что действовать им надо быстро, не то мир постигнет новая ужасная катастрофа. Тщательно взвесив всё, они решили, что лучше всего будет остановить враждебные армии на этом источнике энергии или рядом с ним.",
    ["d4d2cf39"] = "Несмотря на нехватку сил, вызванную слабостью повелителя, Артас всё же ввязался в братоубийственную войну в Лордероне. Тогда половина его уцелевших войск во главе с банши Сильваной Ветрокрылой вышла из-под его контроля и взяла власть в свои руки. Призванный своим господином, Артас был вынужден передать командование Плетью своему заместителю Кел'Тузаду, а война тем временем охватывала все новые области Чумных земель.",
    ["d4f8adf0"] = "Когда я уже собирался спросить, почему Ажек не участвует в обсуждении плана сегодняшней охоты, она выхватила стрелу из колчана, натянула тетиву и выстрелила в бедного Барнила. Однако стрела пролетела мимо. Разинув рот, Барнил наблюдал за тем, как возле него на поверхность реки всплыл огромный кроколиск, а между глаз у него торчала стрела Ажек.",
    ["d500f8e6"] = "Дорогой будущий я! На этот раз не забудь про хлеб. - два галлона ледяного молока - двадцать ломтиков выдержанного чеддера (крысы вечно всё подъедают) - один восхитительный шоколадный торт - Хотя нет, пусть будет два торта - четыре канистры взрывоопасного гоблинского ракетного топлива - две ториевые трубки - один преобразователь из истинного серебра - *Дальше надпись так размазана, что не разобрать ни слова.* два гирохронатома",
    ["d5137c28"] = "Приветствую тебя, брат. Изувеченная Длань выражает тебе своё почтение и надеется, что в нашей долине ты найдёшь, где применить своё ремесло. Учти: мы пристально следим за твоими успехами и неудачами. Мне поручено оценить твоё мастерство и сообщить, когда ты будешь готов к серьёзным делам. Как будет время, навести меня в глубинах Логова. -Руаг, наставник разбойников.",
    ["d5235c47"] = "И знаешь что? Если уж ему так там нравится, пусть попробует восстановить главу из книги, отправившись в Огненные Недра и покопавшись в куче пепла! Ха! Пока я там летал, обнаружил пресмыкающихся механиков в Лаборатории Виктора Нефариуса – им могут пригодиться Драконьи штуки. Сбросить бомбы!",
    ["d543ede5"] = "Они облекли планеты небесными слоями и бушующими атмосферами, воплощая свой непостижимый и дальновидный замысел, создавая порядок из хаоса. Они научили древние примитивные племена приглядывать за своими детищами и поддерживать целостность созданных миров. Титаны, которыми правила элитная группа – Пантеон, – создали порядок в сотнях миллионов миров, рассеянных по Великой Запредельной Тьме на заре творения.",
    ["d5a07e88"] = "Огромное древо стало символом вечного союза ночных эльфов и природы, а его жизнетворная энергия впоследствии исцелила весь мир. Ночные эльфы дали своему Древу Жизни имя Нордрассил, что на их языке означало \"корона жизни\".",
    ["d5a18625"] = "Правительством Кель'Таласа стал совет Луносвета, хотя династия Солнечных Скитальцев также отчасти сохраняла политическую власть. Включавший в себя семерых величайших эльфийских лордов совет заботился о безопасности эльфов и эльфийских земель. Под защитой барьера высшие эльфы отвергли былые предупреждения кальдорай и с преступной беспечностью продолжали использовать магию практически во всех аспектах своей жизни.",
    ["d5d7a61b"] = "Объединённые под одним знаменем, людские племена создали сильную, жизнерадостную культуру. Торадин, король Аратора, знал, что таинственные эльфы на севере постоянно сражались с троллями, но отказался рисковать безопасностью своих людей ради скрытных незнакомцев. Много месяцев прошло, прежде чем слухи о близком поражении эльфов распространились с севера. Только тогда, когда измученные послы Кель'Таласа добрались до Строма, Торадин осознал истинную угрозу, идущую от троллей.",
    ["d5faede3"] = "Клык тролля из клана Кровавый Скальп: Клыки троллей из клана Кровавый Скальп из Тернистой долины обладают редким качеством. Безнравственность Кровавых скальпов заключена в их клыках, и если их истолочь в порошок, можно выпустить их гибельную силу.",
    ["d64b01d9"] = "В конечном итоге Сильвана и её мятежники, назвавшие себя Отрёкшимися, объявили руины столицы Лордерона своей собственностью. В подземельях под этими руинами они обустроили собственную крепость, поклявшись победить Плеть и изгнать из своих земель Кел'Тузада.",
    ["d652c818"] = "Дневник – день пятьсот двенадцать Бананы начали говорить со мной, и я многое узнал об их культуре. Теперь я перестал бездумно разрушать их дома и поедать их детей. Как же мало мне было известно о великой цивилизации, которую я уничтожал. Кроме того, у меня, кажется, заканчиваются бутылки и бумага. Когда я впервые оглядел ту огромную кучу бумаги, что выбросило волнами на берег, то подумал, что она не переведётся никогда. Увы, скоро мне придётся прекратить свои записи.",
    ["d669e88e"] = "Неясный шёпот, о волшебнике из Кирин Тор по имени Аругал. Согласно тому, что я слышала, возможно, что он тоже вызывал воргенов. Как бы мне ни было неприятно, придётся посоветоваться с этим волшебником, выяснить, что ему известно. Воргены опасны, и я желаю остановить их нашествие. Завтра же я отправлюсь в порт в Степях и оплачу путешествие в Новый мир. Да пребудет со мной благословение Элуны, пока не будет выполнена моя работа.",
    ["d67b5e54"] = "Однажды он вернётся к своей жене и детям. Наконец, Морган вернулся домой, но всё изменилось с тех пор, как он здесь был. Когда-то зелёный лес был заражён и населён нежитью и монстрами. Везде стояли разрушенные дома и фермы, и большую часть округи занимало кладбище возле Вороньего Холма. Поражённый и сбитый с толку, Морган пришёл к своему дому и увидел одни развалины. Не зная, что случилось с его родными местами, он",
    ["d691b20e"] = "Эти следы Второй войны служат грозным напоминанием о том, как опасно близка была орда к завоеванию Железных гор.",
    ["d697ced7"] = "Отпустить зверя: Спустя тридцать минут зверь вернётся к себе домой в Пустоту. Примечание: В этом своём стремлении зверь МОЖЕТ броситься со скалы или упасть с горы. Не горюйте о потере ищейки Скверны, лучше вызовите другую.",
    ["d69cff0d"] = "*(Из-за пятен возможно прочесть лишь часть журнала.)* Ульдаман, день третий. Поверить не могу, как я был глуп. Эти злобные дворфы Тенегорна провели меня, как простачка. Мои раны заживают медленно, я безусловно отравлен ядом. Я чувствую, как мои силы тают. Несмотря на это я должен двигаться вперёд... ...хуже того, ожерелье, что сделал для меня гном, треснуло! Три его самых больших драгоценных камня потеряны. Я должен найти их, без них ожерелье будет лишено всей своей силы.",
    ["d6c529c7"] = "Очи Матери-Земли взирали сверху на созданные ею земли. Её правое око, Ан'ше – солнце, дарило тепло и свет всей земле, а левое, Му'ша – луна, приносило покой и сон детям рассвета. Сила её взгляда была такова, что пока одно её око дремало, небо поворачивалось другой стороной. Её любящий взгляд превращал день в ночь, и наоборот.",
    ["d6fbb3c4"] = false,
    ["d708057b"] = "Знай, охотник, эти демоны дерутся только по своим правилам. Если им покажется, что одолеть тебя нельзя, они сбегут. ИДИ К НИМ ОДИН.",
    ["d73feb92"] = "Брат Нилз, мой виноград спасён! Путник, предъявитель сего письма, спас мой наводненный головорезами виноградник и собрал весь виноград, что я не успела собрать. Несмотря на то что бандиты всё ещё бродят у реки, практически весь мой урожай был спасён. Ты можешь добавить к своим запасам полные корзины винограда. Да защитит нас Свет, -Милли Осворт",
    ["d7463565"] = "Клянусь бородой Магни, нам нужно многое обсудить, а времени очень мало. Как можно скорее найди меня в Старой Наковальне, что в Холодной долине. Там и начнём обучение. Я мог бы открыть тебе секреты быстроты движений… но об этом говорить ещё рано. Сначала тебе нужно научиться правильно держать топор, привыкнуть к весу доспехов и запаху пота, заливающему лицо в тяжёлом бою… Для начала этого будет достаточно. -Тран Корман, наставник воинов",
    ["d750fc0f"] = "Хотя доподлинное происхождение хаотичной Вселенной неизвестно, очевидно, что могущественные создания явились, дабы привнести в миры порядок и обеспечить тем, кто будет их населять, мир и спокойствие. Титаны – колоссальные железнокожие боги из далёких пределов космоса – занимались обустройством встреченных ими миров. Они возводили высокие горы и создавали морские пучины.",
    ["d78dade0"] = "Это риск, но сейчас у меня нет других зацепок... Когда я узнаю больше, я запишу детали сюда, но до тех пор я буду работать над тем, чтобы найти части жезла и помочь Ясеневому лесу.",
    ["d7ad3010"] = "ВНИМАНИЕ: Ничего не говори! Не оглядывайся! За тобой могут следить. Меня зовут Аламар Гримм. Я обучаю тех, кого интересует мудрость и сила из… из других миров. Меня попросили связаться с тобой и предложить тебе услуги учителя. Когда будешь готов, ищи меня на задворках Старой Наковальни. -Аламар Гримм, наставник чернокнижников",
    ["d7b8f95e"] = "Пришлось отправить в Даларан другого посланца. Мне стало известно, что они прочёсывают руины возле нашей защитной сферы в поисках подвески. Остаётся лишь надеяться, что мы не опоздали.",
    ["d7f48da6"] = "ПИЛОНЫ: ИНСТРУКЦИЯ ПО ЭКСПЛУАТАЦИИ. \"Руководство по сбору и использованию кристаллов силы Кратера Ун'Горо\". Глава один: Северный пилон. Глава два: Восточный пилон. Глава три: Западный пилон.",
    ["d84618c5"] = "Скверна и зло, с которыми, как принято считать, сопряжена тайная магия, – ничто по сравнению с тем, что мы уже пережили. Мы больше не жертвы. Мы сами выбираем свою судьбу. Сильвана указала нам путь – она доказала, что у нас есть своя воля и что мы не обязаны подчиняться этому ублюдку Артасу. Найди меня в церкви – я расскажу тебе больше… если захочешь. - Изабелла, наставница магов",
    ["d860934e"] = "Если я не смогу найти камень, спрятанный в храме, он может оказаться у одного из мурлоков. Древковая часть Эта часть жезла была дана древням возле леса, который сейчас называется Осквернённым. Ни фурболги, ни мой народ не могли заподозрить, что такие величественные создания падут жертвой порчи, охватившей эти земли. Мои исследования говорят мне, что стражи хранили эту часть в сундуке, на небольшой лужайке. Чтобы узнать больше, мне нужно будет поговорить с Шаэл'дрин.",
    ["d8b3fa12"] = "Водрузив на свою голову шлем, Артас стал новым Королём-личом. Души Нер'зула и Артаса слились воедино, обретя небывалое могущество. Увидев, что Артас стал самым грозным существом в истории этого мира, Иллидан со своими войсками был вынужден бежать обратно в Запределье.",
    ["d8bdbe74"] = "День второй. От утёсов на востоке, где наш край граничит с равнинами Степей, эхом отдаётся громовой топот, будто несётся целое стадо. Быть может, это очередной табун зебр или газелей, а может, разъярённый громовой ящер – но шум не стихает и глубокой ночью, когда такие звери обычно уже спят. Я пойду дальше, чтобы разузнать больше, но буду держаться на безопасном расстоянии.",
    ["d93cc924"] = "Далеко в Долине Копий стоит святой храм Мародона. Мало того, скоро ты узнаешь, почему я попросил тебя о помощи в делах. Там, за дверями, проходить за которые могут лишь духи и самые чтимые жрецы, есть некто по имени Безымянный Пророк. Он превыше всех в духовных делах и старше многих старейшин.",
    ["d950b879"] = "Она верила, что древние эльфы и люди-старейшины, возглавлявшие совет, были слишком непреклонны в своих решениях и не смотрели в будущее достаточно далеко, чтобы положить конец войне против хаоса. Раздражённая слишком долгим обсуждением и дебатами, она жаждала показать своим завистникам и старшим по званию, на что она способна, и предпочла храбрость мудрости.",
    ["da28c4f1"] = "После того как я выжил при побеге из Погибели Роланда, я прятался в сарае, принадлежавшем человеку по имени Свен. Я провёл в нём несколько дней, и такой ужас сковал меня, что я никогда не показывался Свену или его семье на глаза. Но оттуда, с моего места я мог видеть, что эти фермеры – славные ребята. Если бы я вышел из своего укрытия, я думаю, они бы приняли меня, но мне всегда было тяжело кому-то доверять. И стало ещё тяжелее после случившегося ужаса в шахте. Так что я оставался в укрытии. И это спасло мне жизнь.",
    ["da47a7e3"] = "Армии Альянса под предводительством сэра Андуина Лотара, Утера Светоносного и адмирала Даэлина Праудмура отбросили орков к югу, в разорённые земли Азерота – первого королевства, павшего под яростным напором орков. Силам Альянса под командованием сэра Лотара удалось оттеснить кланы, которыми предводительствовал Молот Рока, из Лордерона обратно в подконтрольные оркам области Азерота. Войска Лотара окружили вулканическую орочью цитадель – Пик Чёрной горы – и осадили её.",
    ["da6661bb"] = "Я пишу это послание самыми могущественными чернилами, какие только могу создать. Они принесут проклятье любому, кроме тебя. Я вызываю могущественных демонов Круговерти Пустоты просто для развлечения. Я убиваю своих врагов, пока они спят. Ты уже видел могущество, которое можно обрести на моём пути. Мои братья этому рады. Когда освоишься, найдёшь меня в глубине Логова. Нам надо поговорить о важных вещях. -Нарток, наставник чернокнижников",
    ["db16cbef"] = "Опустошительная Вторая война против орочьей орды оставила Альянс Лордерона в потрясении и беспорядке. Кровожадные орки, которых возглавлял могущественный вождь, Оргрим Молот Рока, не только силой проложили себе путь через дворфийские земли Каз Модана, но и стёрли с лица земли множество центральных провинций Лордерона. Жестокие орки разграбили даже отдалённое эльфийское королевство Кель'Талас, прежде чем их разрушительный поход был остановлен.",
    ["db2a16ab"] = "Тьмой они созданы – злу нет предела Тому, что на Вершине Тумана Багрового воссело. Несётся над миром смех наглеца, Чьим элементалям не видно конца. Тебе с этим магом оружье скрестить И в схватке смертельной его победить.",
    ["db3948b2"] = "Покинув Лабиринты, я направлюсь в Тысячу Игл, а затем на запад в сторону Таланаара, к границе с таинственным лесом Фералас. Там я найду друида, известного как Хранитель дорог Фалфиндел. Пытаясь узнать прошлое моего народа, я, кажется, наткнулся на что-то большее. Теперь в моих руках – безопасность всего Альянса...",
    ["db54d089"] = "Не знавшие о том, что Саргерас намерен уничтожить плоды их бесчисленных трудов, титаны продолжали передвигаться от мира к миру, формируя и приводя в порядок те планеты, что они находили пригодными. В своём путешествии они случайно попали в небольшой мир, который его обитатели позже назвали Азеротом.",
    ["db6e29e4"] = "Рыболовный чемпионат Тернистой долины! Проводится воскресным днём, с четырнадцати до шестнадцати часов. Закиньте удочки где угодно на побережье Тернистой долины (кроме Пиратской бухты) и ищите косяки вкуснорыбы, что появляются вдоль берега! Если ваш поплавок попадёт прямо в косяк, вы поймаете особенную рыбу вместо обычных, которых полно в Тернистой долине. Первый, кто выловит сорок вкуснорыб, сможет сдать их Мастеру Окуневой Приманке в Пиратской бухте и получить вознаграждение! Даже если вам не удалось поймать сорок вкуснорыб первому, вы сможете обменять их на деньги, а за некоторых рыб можно получить ценные призы!",
    ["db74bd56"] = "Мир между орками и людьми был нарушен с прибытием огромного флота Альянса под командованием отца Джайны, Великого адмирала Даэлина Праудмура. Этот флот покинул Лордерон перед самым падением королевства. В течение долгих месяцев плавания адмирал Праудмур искал любых уцелевших союзников по Альянсу.",
    ["dbd97b95"] = "В распоряжении пауков-повелителей Неруба имелось немалое войско и сеть подземных тоннелей, простирающихся почти на половину территории Нордскола. Они нападали небольшими отрядами, и это не позволяло Королю-личу разделаться с ними раз и навсегда. В конце концов Нер'зулу удалось победить в этой войне, нанеся сокрушительный удар по воинам Неруба. Вместе со зловещими повелителями ужаса и огромной армией нежити Король-лич напал на Азжол-Неруб и обрушил их подземные храмы на головы пауков-повелителей.",
    ["dbf5fe14"] = "После того как я вытащил косу, они напали на нас отовсюду, выползая из укромных щелей под нашими ногами и падая на нас откуда-то с потолка. Половина наших людей погибла в эти первые минуты паники. Оставшиеся, включая меня, пытались бежать. Во время моего бегства я видел, как многих моих братьев разорвали зубами и когтями, слышал обрывающиеся крики и затихающее бульканье.",
    ["dc423fca"] = "*(Прикоснувшись к светящемуся кристаллу, вы ощущаете порыв ветра, который доносит тихие слова.)* Высший орден следил за тобой, и мы уверены, что в тебе скрыт большой потенциал. Духи ветра оставили остров Зефрис, и сейчас такие многообещающие маги, как ты, нужны нам как никогда. Чтобы наш народ научился полагаться на себя и пережил эти трудные времена, нужно использовать наши знания о магии и раскрыть секреты этих земель. Разыщи меня в деревне Тендал, на нижнем уровне великого древа. Твоё обучение начнётся по-настоящему. Дорийя Громкий Шёпот, наставница магов",
    ["dc4ec722"] = "Владыка Приливов таял. С каждым приливом и отливом он терял часть себя, утрачивал свою телесную форму – исчезая и снова появляясь, – пока, наконец, в свой смертный час он не отправился на берег, на котором нашёл Камень, и не вошёл в море, исчезнув в последний раз. Несколько поколений спустя Камень Приливов снова вынесло прибоем на берега Тернистой долины, и тролль, принёсший его в Зул-Гуруб, был избран новым",
    ["dc50e9b5"] = "Ниже находится список предметов, необходимых для создания твоей брони: Закопчённые слитки железа кобольдов Утёса Ветрорезов, что обитают в Руднике Ветрорезов в Когтистых горах. Толчёный азурит, который можно достать у хилсбрадских шахтёров. Железные слитки можно взять у горняков или добыть в месторождениях железа, если ты горняк. Сосуд флогистона, который надо добыть у иглогрива по имени Ругуг из Лабиринтов Иглошкурых.",
    ["dc699bdb"] = "ПЯТЫЙ ДЕНЬ. Оставил парня присматривать за лагерем, а сам прокрался к пещере, чтобы немного осмотреться. Троллей здесь огромное количество. Чтобы очистить пещеру от этих паразитов потребуется немало солдат. Я вспомнил, что в последнее время я вообще не видел троггов. Они появляются в регионе в огромных количествах, но они настолько примитивны, что вряд ли представляют угрозу. Хотя поживём – увидим.",
    ["dc746f6f"] = "Судьба Джозефа Редпат Джозеф Редпат погиб во время битвы при Дарроушире. Его искалеченная душа стала совершенно новым существом, несущим великое зло всему Лордерону. Силы Альянса в конечном счёте победили Редпата на пустоши Гаррона в восточной части Андорала. Его щит до сих пор лежит возле амбара на чумной ферме, и приспешники Плети помнят об этом.",
    ["dc7ff7ad"] = "Уже почти неделю нет ни капли эля. ШЕСТОЙ ДЕНЬ. Опять похолодало. Идёт снег. Тролли. Эля нет. СЕДЬМОЙ ДЕНЬ. Снег белеет, Небо синеет, Волки воют, А эля всё нет. ВОСЬМОЙ ДЕНЬ. Тролли, возможно, не такая уж проблема. Их много,",
    ["dd1688db"] = "Во время атаки Легиона на Ясеневый лес Иллидан был освобождён из своей тюрьмы, где он провёл в заточении десять тысяч лет. Сначала Иллидан пытался помочь своим товарищам, но вскоре он принял своё истинное обличие и поглотил энергию могущественного волшебного артефакта под названием Череп Гул'дана.",
    ["dd22eb5a"] = "Тролли-знахари содрогнулись и воззвали к своему владыке. Мин'лот смотрел на горы, поднявшиеся из моря, обречённый и несгибаемый. Он повернулся к ученикам и прошептал свои последние слова, которые тролли запечатлели в камне. Затем Мин'лот повернулся к надвигающимся краккенам. Он нахмурился и метнул в них свой посох. Это было его последнее деяние. Краккены направили свою ярость на Мин'лота, и океан обрушился на И'лалай. И его не стало.",
    ["dd46bad3"] = "Мы призываем тебя, Занза Зулдазара. Благослови тех, что помощи твоей ищут, Лоа Занза. Благослови тех, что хотят помочь Зандаларскому народу. Помоги нам в эти трудные времена. Помоги нам, Лоа. Дай нам силу сразить врагов наших. Дай нам силу сокрушить Кровавого Бога ещё раз.",
    ["dd4ce197"] = "Сосуд флогистона: Последняя стадия создания брони потребует чрезвычайно горячего кузнечного горна. Чтобы обеспечить необходимый уровень жара, мне понадобится сосуд флогистона. Единственно известный источник данной субстанции – легендарный иглогрив, Ругуг, и он не отдаст её без боя. Ругуг обитает в глубинах Лабиринтов Иглошкурых, в южной части Степей.",
    ["ddadb93b"] = "Туралион, наиболее приближенный к Лотару командир, поднял его окровавленный щит и призвал своих поражённых горем собратьев нанести со всей яростью ответный удар. Под истрёпанными знамёнами Лордерона и Азерота воинство Туралиона разбило почти всю армию Молота Рока в славной, но жестокой сече.",
    ["ddb7206d"] = "Сегодня Синдикат контролирует лишь малые силы, но они хорошо знают эту область и собрали достаточное количество воинов для выполнения задач. С должным руководством, я уверен, Синдикат захватит Альтерак довольно скоро. Мы убедили Синдикат направиться в город Стромгард неподалёку в нагорье Арати. Этот город – поле боя между нашими силами, ограми и людьми Стромгарда, но мы думаем, что продумав тщательную тактику, мы завладеем этим когда-то великим городом.",
    ["ddeefade"] = "Стром по-прежнему оставался центром Аратора, но на континенте Лордерон возникло множество новых городов-государств. Гильнеас, Альтерак и Кул-Тирас были первыми среди этих городов-государств, и хотя во всех этих городах были свои обычаи и своя экономика, все они подчинялись Строму.",
    ["de1b1d2c"] = "Но мне не пришлось долго наслаждаться успехом. На вершине утёса, прямо над несчастным Барнилом, появились несколько силуэтов. “Беги, Барнил!” – закричали мы. Ажек, сэр Эрлгедин и я выстрелили поверх головы Барнила в сторону преследующих его ящеров. Кто-то даже убил одного из них.",
    ["de205207"] = "Плотоклюй. Отряд: скорпионы. Климат: засушливый. Как следует из названия, этот скорпид отщипывает и пожирает плоть с костей других животных. Он падальщик и предпочитает кормиться крупными тушами.",
    ["de30e7f5"] = "Офгут Каменный Кулак Бессчётно количество павших от молота Тёмного хранителя Офгута. Солдаты Западного гарнизона склоняются пред ним в благоговении, когда он проходит мимо. Кто среди них может заглянуть в глаза Офгуту и увидеть там секреты, что нашёптывает ему тёмный ключ?",
    ["df6e8b05"] = "РАПОРТ: Кобольды. Рядом с Долиной Североземья наблюдается повышенная активность кобольдов. Все кобольды были оттеснены ордой обезумевших орков клана Чёрной горы.",
    ["df75837a"] = "Убив тело Медива, Лотар и юный Кадгар, сами того не зная, изгнали дух Саргераса в бездну. А праведный дух Медива остался жив… и долгие годы скитался по астральному миру.",
    ["df891cd8"] = "Люди, верящие в Свет, часто боятся тех, кто интересуется настоящей силой, считая, что тайная магия непознаваема. Но не всё, что приходит извне, является злом. Не все сущности стремятся подчинить себе других. Если у тебя будет достаточно силы, те же самые сущности станут твоими слугами. Об этом я хотела бы поговорить с тобой. Жду тебя на кладбище справа от аббатства. -Друзилла ла Салле, наставница чернокнижников",
    ["dfcf8b56"] = "Этот окаменевший коготь был найден у южных берегов Тернистой долины. Экологи полагают, что этот коготь принадлежал древнему солнечному руху. Несмотря на то что упоминания об этих существах присутствуют в примитивных мифологических сказаниях тауренов, находка этого когтя предполагает тот факт, что, вероятно, подобное создание действительно существовало.",
    ["e00ee524"] = "Горечь потери своего дома ожесточила их сердца. Король Бронзобород предложил дворфам Громового Молота место, где они бы могли жить в границах Стальгорна, но они отказались. Кардрос повёл свой народ на север к землям Лордерона. Поселившись в буйно зеленеющих лесах Внутренних земель, клан Громового Молота построил город Заоблачный пик, где дворфы стали ближе к природе и даже приручили могучих грифонов, живших там.",
    ["e02e51f0"] = "Я не устаю удивляться, как легко можно подчинять всех своей воле, играя на их ненависти. С орками и троллями было легче всего, ненависть к Альянсу сделала их прилежными учениками Тёмной Нити. Понимают ли они хоть отчасти, какой могучей силе служат? Этот паладин, который меня бесит, Делгрен Очиститель, суёт нос в наши дела в Ясеневом лесу, пока его прислужник, Балтул, шпионит за моей башней, думая, что мне о его присутствии неизвестно. Делгрен считает нас незначительной",
    ["e03593be"] = "Озрик! Ниже приведён перечень доспехов, которые нам требуются: Десять кольчужных рубах Двадцать шлемов Тридцать накладок на доспехи Пятнадцать кольчужных ботинок Мы, как обычно, у тебя в долгу. И если Западный край когда-нибудь избавится от досаждающих ему воров, я сочту себя обязанным пригласить тебя в наш дом на вкусный обед, достойный былой щедрости, что некогда прославляла эти земли. -Льюис Интендант, Сторожевой Холм.",
    ["e064e792"] = "Арториус Судьбоносный: Всему, чего касается в Зимних Ключах, он приносит смерть и разрушение. Найди его и убей.",
    ["e06edab6"] = "Клык тролля из клана Кровавого Скальпа: Клыки троллей из клана Кровавого Скальпа из Тернистой долины обладают редким качеством. Всё зло этого клана сконцентрировано в клыках, и если их истолочь в порошок, можно выпустить эту гибельную силу.",
    ["e092405a"] = false,
    ["e17e3e43"] = "Командующий флотами Альянса. Друг Штормграда.",
    ["e17e6b88"] = "Распространение сведений производите на своё усмотрение. Тирисфальское региональное командование Капитан Мелроуз Капитан Вакон Капитан Перрин Указания даны самим верховным лордом. Капитан Перрин, продолжайте укреплять позицию на юго-западной башне (как уже было сказано). Провиант подвезут позднее. Материалы можно добывать на близлежащих фермах. Не забывайте о разведке и собирании информации.",
    ["e1d0714d"] = "Капралу Адамору. С первыми лучами солнца соберите максимум десять пехотинцев и доложитесь охотнику за головами Терри Долгопиву. С ним вы пойдёте по следу опасного дезертира – вероятно, вооружённого и агрессивного. Этот охотник за головами был близким союзником покойного лорда-адмирала, и я прошу относиться к нему с почтением, как к старшему офицеру. Лейтенант Бенедикт",
    ["e21e73bc"] = "Чтобы подчинить коня погибели, нужно сделать три вещи: Сотворить Круг Великого Призыва. Внутри этого круга открыть портал в Ксорот и вывести коня через него. Победить его и покорить его дух. На следующих страницах подробно описан каждый из трёх шагов. Сделать это непросто, но ты доказал, что способности у тебя есть. Я уверен, что ты со своей целеустремлённостью подчинишь себе коня гибели. Читай дальше. -Мор'зул Вестник Крови",
    ["e2ac508a"] = "Милая Ройбен! Знаю, скорее всего ты никогда не получишь это письмо, но мне просто нечем больше заняться. Мне надо как-то отвлечься от этих чудовищных звуков, доносящихся из-за крепостных стен, окружающих Дольный Очаг. Нежить окружила нашу деревню и не собирается отступать, а нам поручено защищать жителей и ждать подкрепления. В последнем сражении я сломал ногу и теперь совершенно беспомощен; мне остаётся только сидеть и ждать, когда наша оборона падёт. Вокруг только стоны и смерть… это ужасно. Страх повсюду, даже в воздухе. На нашей стороне сражается принц Артас. Если бы не он, нам бы уже давно пришёл конец. Его преданность и любовь к родине завораживает; я с радостью буду сражаться и погибну рядом с ним. Бой идёт уже у наших ворот, и я не могу больше сидеть тут, жалея сломанную ногу. Нам нужен каждый, кто может держать в руках меч. Надеюсь, эти строки ты будешь читать в лучшие времена. Твой друг, Леагрем",
    ["e2ef6553"] = "Аку'май, Принцесса Глубин, служит Древним Богам. Она проживает в Непроглядной Пучине, озаряя тамошние подземелья своей древней мудростью. Аку'май, пришедшая в Пучину по воле старейшин смертных, олицетворяет божественность. Она обладает лишь частичкой мощи и ярости Древних Богов, но и такая малость выше нашего разумения. Поэтому ей поклоняются. Поэтому её боятся и любят. --Лоргалис",
    ["e30ef480"] = "Эти силы хаоса бушевали и бились с колоссами-титанами на груди мира. Несмотря на то что элементали были настолько могущественны, что смертным даже представить невозможно, их объединённых сил было недостаточно, чтобы остановить могучих титанов. Один за другим повелители элементалей пали, а их силы отступили.",
    ["e3229478"] = "Пророк обладает большим могуществом и общается с духами наших предков. Но он глуп! Он сам не знает, насколько силён. Он носит Амулет Духов, в котором и содержится большая часть его силы. Я узнал, что Амулет силён, но не полон.",
    ["e330089c"] = "Удовлетворённые упорядочением этого небольшого мира и окончанием трудов, титаны приготовились покинуть Азерот. Однако перед своим уходом они поручили величайшим существам этого мира присматривать за Калимдором, поскольку любое враждебное вмешательство могло поколебать его идеальный баланс. В то время существовало множество родов драконов.",
    ["e3341211"] = "Буквы вспыхивают на записке и исчезают. Уловить их смысл невозможно...",
    ["e398b19a"] = "Полагаю, что беспорядки, которые устраивают в недрах горы духи при поддержке тауренов-шаманов и друидов, отвлекают добытчиков – ведь таурены считают Торговую компанию в Когтистых горах явной угрозой. Угроза это или нет, мы должны помочь союзникам. Лидон, ты отлично разбираешься в ядах. Можешь ли ты придумать такую отраву, которой мы могли бы заразить гоблинов в Когтистых горах? С почтением к учёному, П. Зама.",
    ["e3c55f73"] = false,
    ["e3d2887c"] = "Адэлас Блэкмур, руководитель всех лагерей для военнопленных, наблюдал за орками из своей крепости Дарнхольд. Один из орков пользовался его особым вниманием: молодой сирота, пойманный почти восемнадцать лет назад. Блэкмур воспитал орчонка как своего раба, назвал его Траллом и обучил тактике, философии и фехтованию. Тралл даже пробовал себя в качестве гладиатора. Блэкмур пытался сделать из юного орка орудие убийства.",
    ["e41ace51"] = "Добрый день, Шнайдер! Надеюсь, дела в районе каналов идут хорошо. У нас тут, в торговом квартале, большой наплыв покупателей. Нам нужно побольше вязаной одежды, наши запасы на исходе. Пожалуйста, пришлите мне стандартную партию при первой же возможности. Удачи. Надеюсь, занятия вашего сына Турмана тоже продвигаются неплохо. Харлан Багли",
    ["e4da015e"] = "*Страницы покрыты древними эльфийскими рунами.* Эти страницы содержат воспоминания о событиях, произошедших при сборе и приготовлении реактивов, необходимых для создания простого магического камня. Да не получат наши враги никогда доступ к этим письменам. Да доживу я до тех пор, когда бледный свет луны вновь осветит Кель'Талас. Да умру я во имя Кель'таса. Да буду убивать я во славу Иллидана. -Мастер Кариэль Винтхалус",
    ["e4daff75"] = "Когда Саргерас убедился, что его армии в сборе и готовы следовать всем его приказам, он выпустил свои необъятные силы на просторы Великой запредельной тьмы. Он назвал свою растущую армию Пылающим Легионом. До сих пор никто не знает, сколько миров они уничтожили, пройда по вселенной огнём и мечом.",
    ["e5090961"] = "Орков, отправившихся в путь через Степи Калимдора под предводительством Тралла, преследовали неудачи. Они заключили союз с Кэрном Кровавым Копытом и его могучими тауренами-воинами, но при этом многих орков стала одолевать жажда крови, мучившая их на протяжении многих лет. Гром Адский Крик, лучший лейтенант Тралла, предал Орду и позволил своим самым низменным инстинктам взять верх над собой.",
    ["e50c5e74"] = "Сал'ах, друг мой. Я надеюсь, ты получил мой знак. Меня попросили помочь тебе. Я нахожусь в Тенистой долине, среди ветвей великого Альдрассила. Если тебе нужны знания, обращайся ко мне. В наше неспокойное время все благоразумные мастера тонких искусств должны держаться друг друга. По-другому мы не сможем сохранить Тельдрассил и наше ремесло. Приходи, когда сможешь. -Фрагун Шёпот Тени, наставник разбойников",
    ["e5a589ea"] = false,
    ["e5b1312d"] = "Никчёмные глупцы! Мой план требовал одновременного уничтожения обоих мостов. А вы что сделали, тупые головорезы? Вы сделали лишь полдела и предупредили весь Альянс о наших намерениях. Глупцы! Но у вас есть шанс исправить то, что вы натворили. У нас есть запас взрывчатки на нагорье Арати, недалеко от моста. Закончите дело, если вам дороги ваши жалкие жизни! --Кам Гневливый",
    ["e5b73065"] = "И тогда случилось чудо. Прямо рядом с нами раздался резкий, ужасающий рёв огромного белого тигра. Несмотря на количество, ящеры развернулись и бросились врассыпную. Мы увидели лишь белый сполох, когда тигр минул нас и помчался за одним из ящеров. Нам не требовалось команды. Все четыре члена нашего отряда знали, что пришло время бежать.",
    ["e5c40bee"] = "Странно, но Моргант отверг своё орочье войско сразу же после их жалкой победы. Чернокнижник возвёл магическую башню на северо-востоке и использовал всю свою силу, чтобы создать небольшую армию гноллов из стаи Темношкуров, которые воплощают его злые замыслы. Орки и люди стали жертвами звероподобных монстров, служащих чернокнижнику. Что до того, почему Моргант предал Гат'Илзогга, вождя Чёрной горы, – об этом остаётся только догадываться.",
    ["e61734b5"] = "НОМЕР ЗАКАЗА: сорок пять, ка, три ПОКУПАТЕЛЬ: Крейвел Угольная Борода НАКЛАДНАЯ: Гидромеханизмы (три) Усилительные болты (пятьдесят) Тридцатидюймовая медная труба калибра двадцать (двенадцать) Табак марки Тёмная Ярость (один) Высококачественная призма (три)",
    ["e61ad97c"] = "Порча и зло, с которыми, как принято считать, сопряжена тайная магия, – ничто по сравнению с тем, что мы уже пережили. Мы больше не жертвы. Мы сами выбираем свою судьбу. Сильвана указала нам путь – она доказала, что у нас есть своя воля и что мы не обязаны подчиняться этому ублюдку Артасу. Найди меня в церкви – я расскажу тебе больше… если захочешь. - Изабелла, наставница магов",
    ["e6358a5a"] = "Всё началось с находки этой проклятой косы в шахте, которую называют Погибелью Роланда. Да, тогда всё и началось. Прежде чем это случилось, Братство Справедливости радовалось нашим успехам в Сумеречном лесу. До того, как я нашёл косу, местные страхи казались мне такими же смешными, как страхи жителей Долины Североземья. Но с тех пор как я увидел рукоять косы, выглядывающую из-под груды щебня в шахте, и, будь я проклят, вытащил её, Погибель Роланда превратилась в место ужасной смерти!",
    ["e6456aca"] = "Глава четыре – Восточная и Западная башни Северного Волка Теперь от победы тебя отделяет только один рубеж – самые преданные и сильные стражи Дрек'Тара, стражи Северного Волка. Их присылают из резервных отрядов, что содержатся в Восточной и Западной Башнях Северного Волка. Уничтожь эти башни – и увидишь, как позорно побегут оставшиеся Стражи.",
    ["e6685cb2"] = "Они нападали на нас отовсюду, выползая из укромных щелей под ногами и падая на нас откуда-то с потолка. Половина моих товарищей погибла в эти первые минуты паники. Оставшиеся, включая меня, пытались бежать. Во время моего бегства я видел, как многих моих братьев разорвали зубами и когтями, слышал обрывающиеся крики и затихающее бульканье. Всё, что я знаю, – это то, что я – единственный, кто смог спастись из этого места.",
    ["e677524b"] = "Дворфы Стальгорна многие века жили в спокойствии. Но их стало слишком много, им перестало хватать места в подземных городах. И хотя могучий король Модимус Старая Наковальня правил всеми дворфами мудро и справедливо, три мощные фракции появились в обществе дворфов.",
    ["e68173e1"] = "Малфурион знал, что планы его брата, одержимого жаждой могущества, не сулят ничего хорошего, поэтому он решил раз и навсегда избавиться от Иллидана. Вместе с Кенарием они заключили его в тюрьму под холмами, где Иллидану надлежало оставаться до конца его жизни, обессиленным и закованным в цепи. Малфурион поручил юной стражнице по имени Майев Песнь Теней следить за пленником, чтобы тот не сбежал.",
    ["e6bcead1"] = "День шестой. Медведь ещё не вернулся; должно быть, я задал ему хорошую трёпку! Но я всё ещё слышу его рычание. Я думаю, он ждёт, когда я умру! Кто бы ни нашёл эту книгу, я прошу тебя. Убей этого грязного медведя. Убей его и отнеси книгу моему другу Большеногу. Он захочет узнать, что произошло. И возьми мою броню. Она понадобится тебе в бою со старым Паршивым Когтем!",
    ["e7311f89"] = "Конечно, героям удалось разрушить портал и спасти Азерот, но сумели ли они выжить среди предсмертных мук Дренора – остаётся загадкой.",
    ["e74327b6"] = "Умница луна договорилась с великим оленем, что освободит его в обмен на его любовь. Желание Му'ша исполнилось, и она зачала от Апа'ро ребёнка, который родился тёмной ночью. Он получил имя Ценарион и бродил по звёздной тропе между пробуждающимся миром и небесным царством.",
    ["e7679855"] = "Гералат и его помощники хотят найти здесь источник зла. Он сказал мне, что Агамагган почитается за подлинного бога. А почему эта земля кишит зловредными тварями и колкими шипами – вот это тайна. Я хотел узнать у Гералата больше, но он впал в очередное забытьё...",
    ["e7820dfd"] = "Для немедленного распространения среди всех членов Сумеречного Молота. Ниже описан порядок применения Ветровых Камней для связи с нашими повелителями из Совета Бездны. Всякое неподобающее использование Ветровых Камней будет караться самым жестоким образом. -Хранитель Хавунт из культа Сумеречного Молота",
    ["e782a01f"] = "*Святилище Мел-Тандрис* \"Пусть свет Элуны вечно озаряет эту долину и освещает пути леса, как было с незапамятных времён\".",
    ["e7986438"] = "Несмотря на невосприимчивость воинов Неруба к чуме, Нер'зулу удалось воскресить пауков-воинов и подчинить их своей воле. Нер'зул отдал дань уважения их силе и храбрости, позаимствовав их необычный архитектурный стиль для строительства своих крепостей и сооружений.",
    ["e7a9522b"] = "Слышишь ли ты его крик? Клич боевой за Орду: Победа или смерть! Должны мы вовек запомнить, Как отважно презрел он смерть. Мечты его воплотились.",
    ["e7c40427"] = "Хотя Кил'джедену удалось склонить к себе Гул'дана после неудачи с Нер'зулом, он по-прежнему ненавидел шамана и поклялся заставить его принять тот самый пакт. Кил'джеден захватил Нер'зула и начал истязать шамана невыносимой медленной пыткой. Нер'зул молил о смерти, а Кил'джеден всё напоминал ему о пакте. Затем Кил'джеден убил орка, но умертвил при этом лишь его тело. Душу орочьего шамана Кил'джеден удерживал, пока она не нашла свой путь в Круговерть Пустоты.",
    ["e80cca28"] = "Совершенствуя свои навыки под неусыпным надзором повелителей ужаса, Король-лич вскоре сумел дотянуться до небольшого поселения людей на самом краю Драконьего Погоста. На нём Нер'зул и решил испытать свои силы.",
    ["e81c13c3"] = "Когда вы вглядываетесь в Око, перед вами встают картины великой битвы. Похоже, что эта ужасная схватка происходит где-то в Лордероне. Вы с трудом можете разглядеть одинокий силуэт женщины, стоящей среди тысячи трупов, отгоняющей полчища Плети. Полчища эти несметны. Из её рук исходят лучи света, разя нежить сотнями.",
    ["e8a70209"] = "Яростный диссонанс чужих душ, наполнивший разум бывшего шамана, ещё более увеличил его силу. Нер'зул буквально пожирал души умерших. Но вскоре контроль над зомби наскучил Нер'зулу – слишком уж это было просто.",
    ["e8a787f9"] = "Похлёбка Западного Края. Три куска жилистого мяса стервятника, три рыла жутеклыка, три глаза мурлока, три окры. Смешать и довести до кипения. Тушить на медленном огне по крайней мере часа два и подавать на стол.",
    ["e8e6a6b1"] = "Вновь получив силу и возможность свободно странствовать по миру, Иллидан отправился на поиски своей судьбы; но на этом пути он столкнулся с Кил'джеденом, который сделал Иллидану предложение, от которого тот не мог отказаться. Кил'джеден был разгневан поражением Архимонда у горы Хиджал, но ему предстояли более важные дела, чем отмщение.",
    ["e9086bb8"] = "Кел'Тузад вернулся в Лордерон в новом обличии и через три года, благодаря богатству и уму, собрал вокруг себя тайное братство. Это братство, которое он назвал Культом Проклятых, обещало всем своим служителям абсолютное равенство и вечную жизнь в Азероте в обмен на службу и покорность Нер'зулу.",
    ["e90f83bc"] = "Зелёные холмы Тернистой долины. Наш первый день прошёл, как обычно проходят первые дни. Большую часть времени мы обустраивали лагерь. Мне удалось найти идеальное место у небольшой чистой заводи. Старые, обветшавшие мостки указывали на то, что в этом месте когда-то жили. Кто именно там жил, мы пока не знали.",
    ["e91de543"] = "План приведён в действие. Сделай из этого некогда великого бастиона веры Геройской Стражи наш лагерь, и мы начнём перебрасывать туда подкрепление из Западного Края, как только узнаем от тебя, что лагерь должным образом подготовлен. Жители и солдаты Штормграда давно забыли об этом месте, и мы сможем успешно устраивать оттуда набеги. Братство Справедливости отобьёт Штормград! Жду твоего ответа.",
    ["e92155ce"] = "План Короля-лича сработал идеально. Многие северные деревни чума поразила почти мгновенно. Как и в Нордсколе, жители, заразившиеся чумой, умирали и восставали из мёртвых верными рабами Короля-лича.",
    ["e92b1aea"] = "Воды горного озера вмиг напитались энергией Источника Вечности, и оно превратилось в новый источник. Иллидан ликовал: он считал, что это станет настоящим даром для будущих поколений, поэтому был несказанно удивлён, когда на него вдруг набросился его брат. Малфурион объяснил Иллидану, что в основе всей магии лежит хаос и что её использование неизбежно приведёт к одержимости и войнам. Иллидан, однако, не спешил отказываться от своей магической силы.",
    ["e99b6f18"] = "Тром-ка, воин. Меня не интересуют твои подвиги – это все дела прошлого. Когда ты последний раз убивал человека? Наверняка давно. Ты теряешь хватку без дела. Мне нужен напарник. А взамен я дам тебе то, что тебе нужно, – полезную тренировку. Когда до тебя дойдёт, что я дело говорю, – приходи. Я буду ждать тебя под навесом прямо возле Логова. -Франг, наставник воинов",
    ["ea23d740"] = "Существует четыре правила магии: Магия могущественна. Магия развращает. Магия порождает зависимость. Магия притягивает обитателей Круговерти Пустоты к тому, кто её применяет. Эти правила неизменны. Этим правилам ты должен будешь подчинить всю свою жизнь, если захочешь продолжить путь магов… Если у тебя хватит глупости не внять этому предупреждению, приходи ко мне в библиотечное крыло Североземского аббатства. Я буду ждать тебя на втором этаже. Кельден Бремен, наставник магов",
    ["ea665846"] = "Господин Шипучка! Податель сего письма и я затеваем одно дело, к которому просим присоединиться и вас. Как вам известно, большую часть своего времени я провожу на Мерцающей равнине – упомянутое дело относится к проводимым там гонкам. Если гонки – а особенно ставки на их исход – вас интересуют, читайте, пожалуйста, дальше, ведь ваше знание Тернистой долины наверняка можно будет использовать во благо нашего плана.",
    ["eacb2bbc"] = "Я схожу с ума? Сегодня я оторвал голову одному из самых доверенных стражников под предлогом того, что я хочу получше рассмотреть его душу. И когда я смотрел, как воздух покидает его дыхательные пути, я вспомнил, что несколько дней не ел!",
    ["eb30c624"] = "Несмотря на постоянные преследования со стороны людей, душа Адского Крика была по-прежнему полна неутолимой жажды боя. Вместе со своим верным кланом Песни Войны он продолжал партизанскую войну против поработителей своего народа. К несчастью, он так и не нашёл способ вернуть пленным оркам их жизненную энергию. Юного Тралла завораживал идеализм Адского Крика и воинские традиции Орды.",
    ["eb370643"] = "Но после нескольких недель отсутствия новостей терпение у меня иссякло. Из Даларана мне сообщили, что кровавый камень к моим коллегам так и не попал. Курьер каким-то образом пропал по дороге, а с ним была утрачена и подвеска кровавого камня! Это очень печальные новости, так как, хотя у Кегана и его последователей есть ещё образцы кровавого камня, с которыми мы можем экспериментировать, я опасаюсь, что подвеска попадёт в неподходящие руки.",
    ["eb54a3d3"] = "Кил'джеден поместил душу Нер'зула в ледяную глыбу, принесённую из Круговерти Пустоты, и наделил её ещё большим могуществом. Потеря телесной оболочки и обладание невероятной силой привели к перевоплощению Нер'зула.",
    ["ec0d1e6b"] = "Или, возможно, я был обречён стать свидетелем тех перемен, что навлёк я на Сумеречный лес. Возможно, мой жребий – наблюдать, как воргены врываются на эту землю, окрашивая её в ещё более тёмный цвет своей злобой. Если это и правда мой жребий, то он выпал мне дважды. Поскольку воргены – не единственная сила, что пыталась ворваться в Сумеречный лес: монстры со стороны Мёртвого Ветра также пытались вторгнуться в него. Это будет в следующей главе моей истории, и я молюсь, чтобы она была последней...",
    ["ec326120"] = "Две статуи должны были стоять на страже прохода в южные земли, покрытого застывшей лавой из-за близости всесжигающего Рагнароса. Они служили не только грозным предупреждением всем тем, кто решится напасть на дворфийские королевства, но также и напоминанием о цене, которую клан Чёрного Железа заплатил за свои преступления.",
    ["ec3fb343"] = "(Грубый набросок дворфийского лица занимает почти весь листок. Под ним написано несколько строчек.) Известный нарушитель! Шпион! Ещё и посмел допрашивать НАШИХ горожан! Посетители Тенегорна, путешествующие парами, докладывают о столкновениях с преступником. Свидетели отмечают его странный акцент и то, что он постоянно повторяет фразу: \"Это не те двое, кого мы ищем\". Если заметите нарушителя, тут же дайте знать любому офицеру Ярости Горна! Обратите внимание: ещё ни одна большая группа горожан не столкнулась со шпионом. Будьте начеку!",
    ["ec724160"] = "Группа из братства Справедливости встретится с Вымогателем, после чего он переправит собранное золото. Убедитесь, что этот процесс произойдёт без ошибок и в условиях строжайшей секретности. Вымогатель ответственен за переправку золота, но в конечном счёте каждый член братства Справедливости должен убедиться, что его роль будет выполнена со всем тщанием и осторожностью.",
    ["eca1e012"] = "Ниже представлена схема и расписание перевозки золота братством Справедливости из шахт Элвиннского леса в наш штаб в Западном крае. Расписание: Воскресенье – в двенадцать тридцать Среда – в двенадцать тридцать В указанные дни золото, добытое в шахтах Элвин, будет доставляться на тыквенное поле Бреквеллов. Лицо, отвечающее за весь процесс – \"Вымогатель\" – будет носить на пальце специальное кольцо, которое я дал ему лично.",
    ["eca5a3ed"] = "Силы защитников были на исходе, когда им на помощь пришли паладины Серебряной Длани. Их предводитель Дейвил Крокфорд сам был родом из Дарроушира. Услышав о нападении, он привёл на помощь своих соратников. Совместными усилиями они остановили слуг Хоргуса. Когда на поле битвы появился сам Хоргус, Дейвил вышел ему навстречу. Их поединок длился очень долго, но Дейвил сумел одержать верх. Однако смертельная рана, полученная им, не позволила ему намного пережить своего врага.",
    ["ece145cc"] = "Панель управления самофланжа можно использовать, чтобы автоматически регулировать поток топлива, газов, жидкостей и связанные с этим механизмы. После завершения исходной регулировки она должна работать без проблем при минимальной поддержке. Краткий список компонентов панели управления (слева направо). Первое: тумблер включения. Позиция «включено» задействует самофланж. Контрольный механизм не отключится автоматически при переводе рычага в положение «выключено». Это лишь",
    ["ecf60bb7"] = "Несмотря на то что Нер'Зул согласился сыграть свою роль, Кил'джеден не был уверен в его преданности. Удерживая дух Короля-лича в заточении, демон мог не беспокоиться о его покорности, но, тем не менее, он предпочёл не оставлять его без присмотра. Для этого Кил'джеден приставил к Нер'Зулу своих лучших демонов-стражников, повелителей ужаса, чтобы те охраняли его и следили за тем, чтобы он выполнил свою жуткую миссию.",
    ["ecf8ee74"] = "Гордая Эгвин, веря, что она сможет противостоять грозному богу, использовала свои силы против аватары Саргераса. С необыкновенной лёгкостью Эгвин одолела лорда демонов и убила его физическую оболочку. Опасаясь, что дух Саргераса выжил, наивная Эгвин сокрыла изуродованные останки в одном из древних дворцов Калимдора, утонувшего в море во время разрушения Источника Вечности.",
    ["ed24cac7"] = "Приветствую тебя. Думаю, тебя заинтересуют результаты моего расследования. Оказывается, и у Ройбена, и у Леагрема есть родные. Советую навестить кого-нибудь из них, даже если они и знают, что случилось с пропавшими солдатами. Бывшую жену Ройбена, Джоанну Вайтхолл, ты найдёшь в Квартале Воинов Подгорода; там она проводит большую часть времени. А вот как она воспримет твою новость – это вопрос. Что касается Леагрема – у него есть тётя, которая теперь хозяйка сиротского приюта в Штормграде. Какой бы путь в жизни ты ни выбрал, желаю удачи во всех твоих делах.",
    ["ed3b5ddd"] = "Изалиен. Жрица Луны ночных эльфов Изалиен решила распрощаться со своими товарищами и отправиться в Забытый Город, разорённый город ночных эльфов, некогда известный как Эльдре'Талас. В нём сохранилась огромная библиотека, святая святых, которую небольшой группе ночных эльфов удалось спасти от разрушения. Там Изалиен надеялась найти информацию о своём наследии и о частях амулета. Стоит заметить, что она была хорошим другом Фарлина Садовника Дерева.",
    ["ed5e24dd"] = "РЯДОВЫЕ ЗВАНИЯ АЛЬЯНСА. Старшина. Старший сержант. Капрал. Рядовой.",
    ["ed7643f6"] = "Орки Дренора (мира, из которого они изначально пришли) были благородными и стремились к знаниям. Они были могучими воинами, сильными телом и душой. Именно поэтому их упорно разыскивал Пылающий Легион. Кил'джеден, демон великой мощи из рядов Легиона, возжаждал поработить орочьи кланы и напустить их полчища на те миры, которые ещё только предстояло покорить Пылающему Легиону.",
    ["edfdde07"] = "День четвёртый. Мои запасы подходят к концу. У меня всё ещё очень много еды, но я не планировал столь долго оставаться в лесу, так далеко от моего танка, и взял с собой лишь два кега эля. Я не спал обе прошлые ночи, прислушиваясь к этому проклятому рёву, и практически до дна выпил оба кега! Завтра мне придётся повернуть назад к Большеногу и нашим паровым танкам. Я не хочу здесь пропасть без выпивки.",
    ["ee00fd4a"] = "Я нашёл способ проникнуть в Чертог Хаз'Мула! Возьми медальон Вогникив из моего сундука. Победи трогга Ревлоша в зале перед комнатой с картой и забери у него стержень Хыннещихоп. Соедини медальон и стержень – и получишь посох Древнейшей Истории. Используй посох в комнате с картой, чтобы открыть двери, ведущие в чертог Хаз'Мула. Сделай это, и комната будет принадлежать нам! — Бейлог",
    ["ee0cb10a"] = "Правительством Кель'Таласа стал совет Луносвета, хотя династия Солнечных Скитальцев также отчасти сохраняла политическую власть. Включавший в себя семерых величайших эльфийских лордов совет заботился о безопасности эльфов и эльфийских земель. Под защитой барьера высшие эльфы отвергли былые предупреждения калдорай и с преступной беспечностью продолжали использовать магию практически во всех аспектах своей жизни.",
    ["ee1efad8"] = "В ходе своих путешествий Тралл встретил старого вождя Оргрима Молота Рока, который долгие годы жил отшельником. Молот Рока был близким другом отца Тралла. Он решил помочь юному орку освободить пленённые кланы. При поддержке опытных воинов Траллу удалось вернуть Орду к жизни и стать её духовным учителем.",
    ["ee5d9ba9"] = "Дела культа, том девяносто два С радостным сердцем приветствую я вас, братья и сёстры мои, ибо дела нашего культа идут наилучшим образом. Имя нам – легион, и всякие замыслы наши всё ближе к воплощению. В ряды наши встаёт всё больше новичков. Хвалебная песнь возносится к нашим господам на Тёмных берегах, и склоняются они в радостных грёзах среди Тлеющего ущелья, и обнимают они слугу наших господ, Аку'май, в Непроглядной Пучине. Поистине, братья мои и сёстры, скоро вера наша разнесётся по всему Азероту!",
    ["ee5e6eae"] = "День третий. О, какое великолепное открытие! Сегодня я нашёл потрясающую вещь: массивные останки существа, похожего на кабана. Его череп возвышался надо-мной на много ростов. Каждый зуб зверя мог заставить казаться карликом даже... ну, дворфа. Учитывая размер находки, я склонен полагать, что это останки одного из Древних Богов, о которых повествуют предания.",
    ["ee7ac797"] = "Эльфы обнаружили, что хотя люди были неловки в обращении с магией, у них была потрясающая природная связь с ней. Эльфы обучили сотню людей самым азам своих магических тайн: не больше, чем было нужно для битвы с троллями. Убеждённые в том, что их ученики-люди готовы вступить в бой, эльфы покинули Стром и пошли на север вместе с могучей армией короля Торадина.",
    ["eeced428"] = "В амулете не хватает пяти камней. Если их найти и вставить на место, сила амулета возрастёт многократно. Я узнал, где находятся пять камней, но для того чтобы их собрать, мне понадобится один из твоих навыков. Разумеется, убийство Безымянного Пророка – тягчайший грех, как и воровство с его бездыханного тела, но о том, о чём я тебя сейчас попрошу, всякому кентавру запрещено даже думать.",
    ["eed9deac"] = "Имя его принесло Свет во тьму Азерота. Доблесть его победила всякое отчаяние. Серебряная Длань не могла сделать большего, Чем дать миру рыцаря, что отдал миру себя.",
    ["ef0a6278"] = "Пантеон, обеспокоенный склонностью Древних Богов ко злу, начал войну против элементалей и их тёмных повелителей. Армии Древних Богов вели в бой наиболее могущественные элементали: Рагнарос Повелитель Огня, Теразан Матерь Камня, Ал'Акир Владыка Ветра и Нептулон Охотник Прилива.",
    ["ef34c049"] = "Не представляют для нас реальной угрозы до тех пор, пока мы не нарушаем их границ. Возможно, народу дворфов неприятна сложившаяся ситуация, но, учитывая дефицит военных сил, будет благоразумнее перенести решение этой проблемы на более поздний срок и бросить все усилия на борьбу с троггами и дворфами Чёрного Железа. В письме вы также найдёте отчёт моего брата Грелина о Старой Наковальне и данные о вендиго, полученные от одного из наших горных пехотинцев. Подписано: Сенир Белобород",
    ["ef3eb330"] = "*Капитан следопытов Аллерия Ветрокрылая Знаменитая охотница на троллей из Кель'Таласа.* *Главная разведчица при экспедиции Альянса, которая отправилась на Дренор, родной мир орков.* *Предположительно погибла.* Сестра, твоё сердце было решительно и неукротимо, как стрела, летящая по ветру. Ты была самой яркой из нашего ордена. Ты была самой любимой из нашего рода. - Сильвана Ветрокрылая, предводительница следопытов Кель'Таласа",
    ["ef904111"] = "Воргена можно узнать по его сходству с волками из нашего мира. Глядя на воргена, каждый с лёгкостью заметит, как сильно его грубая шерсть, заострённые уши и длинная морда похожи на волчьи. Но сразу же станут заметны и отличия: грубая шерсть покрывает мощное тело с двумя ногами, из пасти торчат длинные клыки, а когти – словно кинжалы. В завываниях же его слышится такая злоба, которой нет ни у одного здешнего зверя.",
    ["efa24d27"] = "Найденное в знойной пустыне Танарис, это необычное яйцо остаётся загадкой для современных экологов. Работы по определению его возраста позволяют предположить, что этому яйцу около тысячи лет. Несмотря на то что определённые элементы указывают на его принадлежность насекомовидному существу, его настоящее происхождение невозможно понять. Особей, откладывающих столь характерные яйца, всё ещё предстоит обнаружить.",
    ["efeb0576"] = "Бешеный Воробей: Декларация груза и пассажиров. Двадцать бочонков рома. Пункт назначения: Терамор. Пятьдесят мешков муки. Пункт назначения: Терамор. Два ящика с гномскими инструментами. Пункт назначения: Кабестан. Тридцать рулонов хлопчатой ткани. Пункт назначения: Терамор. Четыре ящика пряностей. Пункт назначения: Терамор. Три пассажира. Пункт назначения: Терамор.",
    ["f01699bf"] = "Фермерша Калаба Крупный долг. Выплата долга сельскохозяйственной продукцией обещана в урожай. Гражданин Уилкс Все задолженности выплачены. Гражданин Боноан Все задолженности выплачены. Шахтёр Веллти Крупный долг. Выплата долга состоится после поставки руды из Лазурного рудника. Шахтёр Сидней Крупный долг. Выплата долга состоится после поставки руды из Лазурного рудника. Шахтёр Хакетт Крупный долг. Выплата долга состоится после поставки руды из Лазурного рудника.",
    ["f0235d49"] = "Это письменное доказательство подтверждает тот факт, что податель сего убил Маргола Яростня – бич Выжженной теснины. Музей Стальгорна ценит этот экспонат и благодарит дарителя за столь щедрое подношение. -Главный смотритель музея, Ториус Каменный Сторож",
    ["f099770a"] = "...Джайлс, мальчик, показался мне непослушным, с его обучением, возможно, будут проблемы. А вот девочка постарше, Тиллоа, – исключительно сообразительный ребёнок. Я также обратил внимание на её пленительную красоту. Она уже превращается из подростка в женщину. Господин, кажется, в будущем году собирается выдать её замуж... Но я что-то отвлёкся. На этой неделе я отправлюсь со всем семейством в летний домик рядом с Лесопилкой Восточной Долины в Элвиннском лесе, это совсем недалеко от Красногорья. Рассчитываю там продолжить работу.",
    ["f0b67bf1"] = "Именно тогда Кил'джеден обнаружил покрытый густыми зарослями мир Дренора, который мирно парил по бескрайним просторам Великой запредельной тьмы. Дренор, родина поклонявшихся духам орков и миролюбивых дренеев, был миром настолько же безмятежным и тихим, насколько бескрайним.",
    ["f0da963a"] = "Но втайне от Альянса, большая группа орков продолжала странствовать по пустошам Каз Модана. Клан Драконьей Пасти, возглавляемый коварным чернокнижником Некроссом, с помощью могущественного артефакта под названием \"Душа Демона\" подчинил себе королеву драконов Алекстразу и её подданных. Удерживая королеву в заложниках, Некросс собрал тайную армию в заброшенной цитадели Громового Молота, которую многие считали проклятой.",
    ["f10e442f"] = "Раскопки Бейл Модана Первая исследовательская команда, отправленная Лигой Исследователей, не ошиблась в своих выводах. Здешняя земля содержит артефакты неограниченной ценности для нашего народа. Без сомнения, под песком и скалами Бейл Модана мы найдём много новых знаний. Геология этого региона, однако, заставляет нас прибегать к крайним мерам. Многие из залежей песка затвердели под воздействием суровой погоды и переменчивого климата.",
    ["f16ee066"] = "Мы без остановки мчались назад, к нашему лагерю. Позже той ночью мы тихо сидели у костра, зная, что наши жизни были спасены по странной прихоти судьбы. Этому риску подвергается любой участник большой охоты. Мы – игрушки в руках судьбы. Когда-нибудь каждый из нас встретится с хищным оскалом смерти. И ваш покорный слуга рад, что эта встреча не произошла на зелёных холмах Тернистой долины. Конец.",
    ["f18e6a79"] = "Из двух рас Кил'джеден выбрал воинственных орков: их было легче привлечь под знамёна Легиона. Он околдовал главного шамана орков Нер'зула точно так же, как много лет назад Саргерас подчинил своей воле королеву Азшару. Коварный шаман стал исполнителем воли демона, пробуждая в орках жестокость и жажду сражения.",
    ["f1a4a1d3"] = "Хотя Артас сокрушил всех, кого теперь считал своими врагами, его не переставал преследовать дух Кел'Тузада. Призрак сказал, что Артас должен помочь вернуть его к жизни, чтобы продолжить выполнение плана Короля-лича. Для этого Артас должен был принести останки Кел'Тузада к волшебному Солнечному Колодцу, сокрытому в королевстве высших эльфов Кель'Таласе.",
    ["f1abcfae"] = "Привет тебе, Элло Чернодрев, мэр Темнолесья. Боюсь, у меня плохие вести для вашего города. Видишь ли, я создатель. Я обманом заставил того, кто доставил это письмо, помочь мне в создании моего последнего, самого ужасного творения – демона из плоти, костей и металла! Когда ты читаешь эти строки, он находится рядом с моим скромным жилищем, скрежеща зубами. Одно моё слово – и он начнёт убивать и крушить всё на своём пути. И в скором времени вы испытаете это на себе. -Бальзамировщик",
    ["f1db33aa"] = "ОФИЦЕРСКИЕ ЗВАНИЯ АЛЬЯНСА. Часть первая. Главнокомандующий. Фельдмаршал. Маршал. Командир. Лейтенант-командор.",
    ["f1ee957d"] = "Сейчас я прошу Его Величество помочь в эти трудные времена добрым гражданам Озёр. Нам нужны люди для защиты нашей земли и боевые орудия взамен разрушенных на поле боя. Запасы еды и питья истощились. Умоляю, государь, окажите нам поддержку в защите последнего бастиона на пути ненавистных орков! Враг должен быть изгнан за пределы королевства Штормград!",
    ["f234e011"] = "Товар у меня. Я буду прятаться в верховьях реки, неподалёку от Хрустального озера, возле стены. Если отправите за добром кого-то из своих агентов, пусть убедится, что его никто не видел! Катти",
    ["f2442373"] = "Потом чума начала заполонять страну и заражать её ничего не подозревающих обитателей. Под присмотром Кел'Тузада войско Короля-лича быстро росло, и вскоре тот подчинил себе обширные земли. Это войско стало известным под именем Плеть, и единственной его целью было истребление всех жителей Азерота.",
    ["f24df2a6"] = "Таурены Таурены с их шаманистическим отношением к зиме и интересом к делам друидов, буквально подтверждают собой легенду о Зимнем Покрове. Они, однако же, видят в ней прежде всего путь обновления знаний, а поклонение собственно легенде оставляют тем народам, что, по их мнению, не так глубоко познали природу вещей. Многие таурены считают, что именно во время этого праздника им приличествует благодарить судьбу за благословение их нового обиталища, Мулгора.",
    ["f267ac64"] = "Он рассказал мне, что исходил Дор'Данил вдоль и поперёк, но ни разу не видел такого сундука или другого места, где могло бы храниться навершие. Он также рассказал мне, что в тех краях завелась гниющая слизь, которая пожирает почти всё, что ей попадётся. Он видел, как она \"поедает\" столы, скульптуры, медведей, и даже гномов! Эта слизь, похоже, обретает силу, поглощая магические предметы. Если сундук, в котором лежало навершие, был зачарован, слизь могла сожрать и его.",
    ["f2873a23"] = "За десять тысяч лет до того, как орки и люди сошлись в Первой войне, мир Азерота вмещал лишь один массивный континент, окружённый бескрайними бушующими морями. На этом континенте, известном как Калимдор, жило множество самых разных народов и существ, борющихся за выживание на просторах нового мира. В центре тёмного континента находилось таинственное озеро, бурлившее энергией.",
    ["f28d8b41"] = "Но почему я вспомнила об этом? Я это сделала для того, чтобы вы поверили тому, что я собираюсь написать, словам, что произнесли губы Кегана, и надеюсь, мои коллеги, читая этот дневник, поймут, почему я поверила тому, что он сказал: \"То, что осталось от Древних Богов, всё ещё влачит жалкое существование в глубоких расщелинах этого мира. Новые силы ищут способ обуздать эти древние силы, и тот, кто сумеет это сделать, получит в своё распоряжение ужасное орудие против своих врагов\".",
    ["f2ad3f58"] = "С благословенными. Сражались не все из высокорождённых. Многие стояли в оцепенении, словно охваченные безумием. Большие и маленькие города, как один, падали вокруг них. В Амет'Аране всё было в руинах, его жители цеплялись за землю, словно это могло их спасти от уничтожения. Именно тогда Атрикус Нарассин, любимец Азшары, появился, чтобы спасти их. Он сказал, что может защитить их заклинаниями. Пока вокруг них погибали братья и сёстры, отцы и матери,",
    ["f2ceb207"] = "В поисках друидов, которых ещё не удалось пробудить, Малфурион наткнулся на древнюю тюрьму, в которой он заточил своего брата Иллидана. Тиранда освободила его в надежде, что он присоединится к ним в битве с Легионом. Некоторое время Иллидан помогал им, но затем бежал, решив, что личные цели для него важнее.",
    ["f2d22fd4"] = "Приветствую тебя. Думаю, тебя заинтересуют результаты моего расследования. Оказывается, и у Ройбена, и у Леагрема есть родные. Советую навестить кого-нибудь из них, даже если они и знают, что случилось с пропавшими солдатами. Бывшую жену Ройбена, Джоанну Вайтхолл, ты найдёшь в Квартале Воинов Подгорода; там она проводит большую часть времени. А вот как она воспримет твою новость – это вопрос. Что касается Леагрема – у него есть тётя, которая теперь хозяйка сиротского приюта в Штормграде. Какой бы путь в жизни ты ни выбрал, желаю удачи во всех твоих делах.",
    ["f2e267aa"] = "Но чтобы ответить на эти вопросы, понадобятся ещё тесты и исследования подвески, и я боюсь, что Лордамерские выселки не смогут снабдить меня ни помощниками, ни оборудованием для выполнения этой задачи. Поэтому я отправила подвеску Кровавого камня вместе с посыльным в Даларан с особыми инструкциями о том, как исследовать его, чтобы они могли избежать тех разочарований, что постигли меня с самого начала.",
    ["f2f8453c"] = "Самые большие из птиц-долгоногов, геру, весьма немногочисленны и редко встречаются.",
    ["f3324ba2"] = "Даже его жрецы из племени Атал'ай, были изгнаны из столицы Зул'Гуруба в северные топи. Там, посреди болот, они воздвигли огромный Храм Атал'Хаккара и продолжили дело своего павшего хозяина…",
    ["f33f924f"] = "Лорд Вальтхалак. Благородный драконид и бывший генерал Пика Чёрной горы Лорд Вальтхалак, невероятно могущественный волшебник-драконид, жил ещё до генерала Драккисата. Пик часто переходил из рук в руки, но, к сожалению, в этот раз нам суждено было сыграть свою роль в смене власти. Один гоблин-контрабандист из Пиратской бухты, Гремник Риззлшмыг, дал нам задание украсть книгу заклинаний Вальтхалака. Мы не знаем, хотел ли он её продать или изучить сам (или и то, и другое), да теперь это и неважно. Важно то, что мы проникли на верхние уровни Пика Чёрной горы и убили Вальтхалака прямо в его логове. Тогда-то и началось настоящее веселье.",
    ["f3bcc2fc"] = "Туралион и Кадгар решили героически принести себя в жертву, разрушив Тёмный портал со стороны Дренора. Их жизни и жизни их воинов – немалая цена за разрушение портала, но они понимали, что это единственный шанс спасти Азерот. Адский Крик и Мёртвый Глаз успели пройти через Тёмный портал навстречу своей свободе, и через мгновение он взорвался за их спинами. Для них и остальных орков на Азероте пути назад больше не было.",
    ["f4010e73"] = "Лотар решил последовать своим инстинктам и, заручившись поддержкой ученика Медива – Кадгара, – пошёл на штурм крепости волшебника – Каражана. Кадгару и Лотару удалось победить Стражника, которого они считали причиной всей войны.",
    ["f414990e"] = "Но один великий дух ускользнул от них. Это был Апа'ро, которого ночные эльфы называли Малорном, гордый белоснежный олень. Его рога упирались в небеса, а его сильные копыта оставляли глубокие следы по всей земле. Шу'хало долго охотились за Апа'ро, но в конце концов сумели окружить гордого оленя.",
    ["f4328b29"] = "Прошло около тысячи лет после \"Войны Зыбучих песков\". Именно на этой войне в сердце пустыни Силитуса случилось великое горе и великое бремя пало на Фэндрала Олений Шлем. Считается, что именно описанные здесь события отвратили от добра верховного Друида.",
    ["f49b9676"] = "Высокорождённые довольно бездумно обращались с магией, в результате чего из источника Вечности начали расходиться волны, проникающие даже в самые дальние уголки Великой запредельной тьмы и привлекающие внимание тамошних обитателей. Вскоре и Саргерас – Великий враг всего живого и Разрушитель миров – почуял эти волны и устремился к их источнику.",
    ["f4ae9cb9"] = "С помощью кланов Бушующего Шторма и Сумеречного Молота Гул'дану удалось поднять Гробницу Саргераса с морского дна. Но когда он открыл древний склеп, его встретили полчища обезумевших демонов.",
    ["f4e57bb6"] = "Однако благородные мужи Штормграда влезли в огромные долги, расширяя военное присутствие королевства в Элвиннском лесу и Тернистой долине. Огромные долги опустошили казну, и ван Клиф со своими товарищами не получили обещанных денег. Потратив несколько лет на возведение великого города, Каменщики остались ни с чем, забытые продажными чиновниками столицы.",
    ["f4f00623"] = "Но несмотря на все катаклизмы, остатки империй Амани и Гурубаши по-прежнему существуют в современных Кель'Таласе и Тернистой долине. Колонии акири Азжол-Неруб и Ан'Кираж в Нордсколе и Танарисе также пережили катастрофу. Ужаснувшись гибелью большей части привычного им мира, тролли понемногу начали восстанавливать своё былое могущество.",
    ["f52edf9c"] = "Леди Мара Фордрагон. Высший клирик Штормграда. Покровительница беженцев, наводнивших Лордерон после Первой войны. Она была светлой матерью нашего будущего. Да упокоится она в Свете.",
    ["f57a7078"] = "Нужно заметить, что Чёрному магниту, используемому для восстановления Колокола, Колеса и Свечи в случае их поломки, нужны Осколки душ. При каждом восстановлении ритуального предмета с помощью Магнита расходуется один Осколок души, поэтому перед ритуалом стоит запасти их побольше.",
    ["f59553d2"] = "После долгих месяцев приготовлений Культ Проклятых под предводительством Кел'Тузада нанёс первый удар, выпустив чуму на земли Лордерона. Утер и его паладины обследовали заражённые территории в надежде найти способ остановить чуму; но, несмотря на все их старания, болезнь продолжала распространяться, угрожая полностью уничтожить Альянс.",
    ["f5d191d3"] = "В тот день мы пошли на юг, двигаясь по свежим следам пантеры. Вскоре мы пришли к ущелью, через которое был перекинут длинный верёвочный мостик. При виде этого чуда инженерной мысли мне сразу вспомнилось, как описывал этот район Бранн. Тролли, коренные жители этих мест, всегда считались примитивной расой, но мастерство, с которым они сконструировали этот мост через непреодолимую пропасть, было неоспоримо.",
    ["f6229f30"] = "ОФИЦЕРСКИЕ ЗВАНИЯ АЛЬЯНСА. Часть первая. Главнокомандующий. Фельдмаршал. Маршал. Командор. Лейтенант-командор.",
    ["f657a7a4"] = "Кил'джеден знал, что уже справился со своей задачей, но хотел быть уверенным в преданности орков. Он дал Совету Теней тайный приказ призвать Маннорота Уничтожителя, живое воплощение ярости и разрушения. Гул'дан собрал вождей кланов и убедил их, что, испив крови Маннорота, они станут непобедимыми.",
    ["f65f7334"] = "Сбалансированная шпага Сталлера. И последнее: я хочу вернуть одну из моих лучших кузнечных работ. Эта шпага – невероятное оружие, и я подарил его тому, кого я считал весьма благородным и великим воином. В общем, его побил мурлок по имени... как его там, Джаркай? Как-то так. Он подвергся атаке этого чудища во время своего путешествия по берегу Болота Печали. Он проиграл сражение и, видимо, обратился в бегство, оставив оружие в лапах мурлока.",
    ["f688cbb4"] = "…и там ты найдёшь легендарный меч Командира Алых – Пеплоносец. Разве не замечательно добыть такое на обычной рыбалке?",
    ["f69ddeed"] = "Кил'джедена разозлила непокорность Нер'зула, и он стал искать другого орка, который смог бы заставить свой народ присоединиться к Легиону. Хитрому великому демону удалось-таки найти достойного кандидата – им стал тщеславный ученик Нер'зула, Гул'дан. Кил'джеден пообещал ему невиданную силу в обмен на полное повиновение.",
    ["f6a1bff3"] = "Всё идёт хорошо. Я вызвала себе на помощь значительное число воргенов. Хотя они недалёкие существа, они умеют отлично сражаться строем и координировать свои атаки. В каждой стае я отыскала лидера. Им я доверила командование небольшими группами воинов. Мы атакуем сразу из многих мест в лесу, и моя кампания против демонов идёт успешно. Да пребудет со мной благословение Элуны, пока не будет выполнена моя работа.",
    ["f6af07c5"] = "*(Страницы исписаны древними эльфийскими рунами)* На этих страницах описаны события, случившиеся при сборе и создании ингредиентов, нужных для получения мощного зелья. Пусть же наши враги никогда не заполучат эти манускрипты. Пусть же я доживу до того дня, когда снова увижу Кель'Талас, озарённый бледным светом луны. Пусть же я умру, но умру во славу Кель'таса. Пусть же я убью во славу Иллидана. -Кариэль Винтхалус",
    ["f6e64ca5"] = "Первая сотня магов, обученная эльфами использовать магию, развила своё могущество и начали глубже изучать тайны плетения заклинаний. Эти маги, изначально выбранные из-за их сильной воли и доблести, всегда очень осторожно практиковали свою магию; но они передали свою силу и тайны магии новому поколению, не имевшему никакого представления об ужасах войны или необходимости самоконтроля.",
    ["f7078b22"] = "Малфурион знал, что планы его брата, одержимого могуществом, не приведут ни к чему хорошему, поэтому он решил раз и навсегда избавиться от Иллидана. Вместе с Кенарием они заключили его в тюрьму под холмами, где Иллидану надлежало оставаться до конца его жизни, обессиленным и закованным в цепи. Малфурион поручил юной стражнице по имени Майев Песнь Теней следить за Иллиданом, чтобы тот не сбежал.",
    ["f762f773"] = "Я снова загорелась интересом и вернулась к своим экспериментам. В этот раз я не выдвигала никаких предположений, методично делая все тесты, что были в моём распоряжении. Это чрезвычайно увеличило понадобившиеся усилия, но шансы прояснить что-либо увеличились соответственно. И, несмотря на то что моя лаборатория мала и у меня нет помощников, к которым я могла бы обратиться за помощью, я обнаружила ещё одно интригующее свойство кровавого камня...",
    ["f78a18bd"] = "Тролли долгие годы воевали с акири, но так и не смогли одержать над ними настоящую победу. Всё, что им удалось, – это расколоть вражеское королевство на части и изгнать насекомых в далёкие земли севера и юга.",
    ["f7a9838e"] = "Котлы должны были находиться под охраной служителей Культа, а впоследствии использоваться в качестве источников чумы, разносящих по всем деревням и городам на севере Лордерона.",
    ["f7b72f63"] = "Бетек Штормоскал Странствия Бетека завели его в глубины Чёрной горы. Секреты гор манили его. Да укрепится его дух.",
    ["f7d2efa1"] = "Со временем Кенарий стал другом Шу'хало и рассказывал им о мире. Дети земли назвали его своим братом и поклялись помогать ему в заботе о полях жизни и любимых созданиях Матери-Земли.",
    ["f7e55230"] = "В случае успеха миссии по истреблению людей Кил'джеден пообещал Нер'зулу свободу от проклятия и новое здоровое тело.",
    ["f7ecf4ee"] = "Лок-тар, брат. Стихии указали на тебя и поручили мне показать тебе путь шамана. Духи наших предков смотрят на нас и гордятся тем, что ты вступил в наши ряды. Когда будешь готов, найди меня у входа в Логово. Я обучаю там наших собратьев. Да будет тебе попутный ветер. -Шикрик, наставница шаманов",
    ["f8245961"] = "Они плыли в молчании, глядя на то, что осталось от их народа, и понимая, что в этом виноваты лишь они сами и их страсти. Конечно, после уничтожения Источника Саргерасу и Пылающему Легиону больше не было хода в этот мир, но цена, которую пришлось заплатить за это, была поистине ужасной.",
    ["f827d45a"] = "Ниже ты найдёшь список того, что мне понадобится для заклинания призыва великого Циклониана. Да сопутствует тебе удача. --Бат-ра Ветростраж.",
    ["f84e01c5"] = "Молот Рока желал наказать своенравных орков за столь дерзкое предательство и послал своих воинов убить Гул'дана и вернуть остальных изменников. Обезумевшие демоны, которых столь опрометчиво освободил Гул'дан, разорвали его на клочки. Потеряв своего командира, воины тотчас сдались на милость войска Молота Рока.",
    ["f862d9f3"] = "Первое убийство взбодрило нашу команду. Барнил налил всем меда, чтобы отметить его. Но нашему празднованию не суждено было продолжаться долго. Когда мы подготавливали тушу к транспортировке в лагерь, внезапно раздался ужасный рёв. Я в жизни не слышал такого леденящего кровь звука.",
    ["f880dd26"] = "Аригос первым заметил странное излучение. Массивный храм на юге Ан'Киража испускал слабые магические волны, не похожие ни на что, исходящее прежде от киражей. Как союзники ни пытались, никому не удалось проникнуть в храм и найти источник этой энергии. Окружить себя такой непробиваемой защитой могло лишь нечто, обладающее огромной силой. Возможно, это было нечто, управляющее насекомыми. Нечто, управляющее даже киражей.",
    ["f89875ae"] = "И в заключение я должен вновь напомнить о моей просьбе доставить взрывчатого порошка. Мои запасы подходят к концу, что серьёзно препятствует успеху экспедиции. Мне обещали, что взрывчатый порошок вскоре будет доставлен, но я до сих пор его не получил. Какова причина, позвольте спросить, этой задержки? С уважением, Геолог Дартеус Железняк",
    ["f8a9059b"] = "Оставшись в одиночестве защищать Калимдор от опасностей нового мира, Тиранда собрала мощную армию своих сестёр, ночных эльфиек. Бесстрашные, искусные воительницы, поклявшиеся защищать Калимдор, стали известны как Часовые. Хотя они предпочитали самостоятельно патрулировать тенистый Ясеневый лес, у них было множество союзников, которых они призывали во время опасностей.",
    ["f8b8ee04"] = "Контроль над зверем: Ищейка Скверны понимает только звериные эмоции. Чтобы заставить вашу ищейку Скверны искать залежи азшарита, необходимо на неё бешено зарычать! (Нацельтесь на ищейку Скверны и изобразите эмоцию «бешенство».) Когда ищейка Скверны обнаружит залежь, она побежит к ней, не обращая внимания на окружающих существ. Хотя вам не нужно защищать ищейку Скверны, возможно, вы захотите быть рядом с ней, чтобы не потерять её.",
    ["f8d8e254"] = "Ты уже ощутил зов чего-то более великого, чем ты сам, и это зов стихий. У нас, дворфов, крепкая связь с землёй, но при должном обучении ты сможешь разговаривать со всеми стихиями. Элементали бывают требовательными и непокорными, но я могу обучить тебя общаться с ними. Разыщи меня в Старой Наковальне, и я поделюсь знаниями о том, как слушать стихии и заставлять их слышать тебя. Тео Молотошторм, наставник шаманов",
    ["f90d94b6"] = "Готов спорить, что ты сначала решил, будто это настоящее письмо от короля или кого-то там ещё. Видишь ли, я знаю толк в фальшивых письмах. Мне надо было убедиться, что ты точно прочтёшь это послание, а как ещё этого добиться? Я нахожусь в Старой Наковальне, рядом с огненной ямой. Как будешь готов, приходи, поговорим. Было бы любопытно с тобой познакомиться. -Сольм Харгрин, наставник разбойников",
    ["f9138366"] = "Мастер Карвин! Принёсший это сообщение осенён благословением Света, может сражаться с мертвецами и демонами, наводнившими пределы Сумеречного леса, и желает присоединиться к семье Карвин на их пути к Свету. В моём послании я прошу вас предоставить этому воину Света задание – возможно, это будет поиск горожан, замеченных в помощи врагам Света. С уважением, Калор",
    ["f919171a"] = "Самла! Принц Артас ведёт нас всё дальше и дальше на север, и у меня на сердце становится совсем тяжело. Когда-то в этом молодом паладине ярко сиял Свет, а теперь я чувствую, как его поглощает тьма. От его былого рвения и бесстрашия не осталось и следа, его преследует что-то ужасное; как бы мне хотелось знать, что это… Скоро мы выберемся из этой ледяной пустыни. Многие солдаты замёрзли насмерть и пали от когтей местных хищников, но Артас говорит, что если наши поиски увенчаются успехом, всему этому кошмару придёт конец. Но его слова не придали мне никакой уверенности: после окончания речи на лице Артаса появилась мрачная улыбка, от которой у меня на душе стало ещё холоднее. Молись за нас, Самла, и за наш мир, Торгал",
    ["f9229d75"] = "Настал роковой для Оленьего Шлема момент – младшему Оленьему Шлему, Вальстану, было приказано оборонять заставу ночных эльфов в деревне Южного Ветра. Увы, в тот же день Вальстан расстался с жизнью: Деревня Южного Ветра пала под натиском армий Ан'Киража.",
    ["f964d518"] = "Задержанная посылка - Я нанял кое-кого с репутацией надёжного пилота, чтобы доставить груз из Терамора. Я ошибался. Несмотря на то что пилот выжил и смог рассказать мне эту историю, он бросил и свой дирижабль и весь мой груз, чтобы спасти свою шею. В общем, мне нужно вернуть мой товар. Исходя из того, что рассказал мне Бизиль, он потерпел крушение к западу от берега Пылевых топей. Он начал падать сразу после того, как пересёк холмы, окаймляющие море. Хм-м-м... он никогда не рассказывал мне, что послужило причиной аварии...",
    ["f96fe89e"] = "Я обещал своим товарищам, что на следующий день мы отправимся охотиться на пантер, так как их мех очень высоко ценится по всему Азероту. Учитывая, что большинство охотников и торговцев мехом сейчас храбро отдавали свои жизни, сражаясь за Альянс, этот мех ещё больше возрос в цене.",
    ["f9971be0"] = "Но в последние дни Второй войны, когда победа Орды казалась уже неизбежной, между двумя самыми могучими орками Азерота возникли небывалые раздоры. Когда Молот Рока готовился к решающей атаке на столицу Лордерона, которая должна была сокрушить последние силы Альянса, Гул'дан и его сторонники покинули остальное войско и отправились в море.",
    ["f9deacb3"] = "Эльф! Как гостю Орды, вождь дозволяет тебе свободно передвигаться по её территориям. Этот путеводитель поможет тебе не потеряться на наших землях.",
    ["f9ff6b17"] = "-День семнадцать Улег вернулся с задания. Он потерпел неудачу, а Таргил попал в плен. Я послал Улега доставить это сообщение Назиру. Я останусь здесь. Я видел, что от побережья Терамора всё чаще отходят корабли. Продолжу вести наблюдение и буду лично сообщать о всяком заслуживающем упоминания событии.",
    ["fa0d7706"] = "Нападение произойдёт за несколько миль до места прибытия. Именно там будут ожидать наши союзники. Я не вполне понимаю, почему нам пришлось объединиться с этими созданиями, и меня не покидает ощущение, что союз этот – вынужденный. Но это, в общем-то, не важно. Захватив объект, мы сделаем большой шаг к тому, чтобы отобрать Штормград у тех, кто его у нас отнял!",
    ["fa11d57b"] = "Прочная хрустальная нога- Хрустальные пауки из Тлеющего ущелья сделаны из невероятного кристаллоподобного материала. Из их ног, в том случае если они не повреждены при убийстве их владельцев, получаются замечательные трубки, необходимые в экспериментах моих компаньонов-инженеров. Мне понадобится некоторое их количество, чтобы провести тестирование. У пауков есть восемь ног, так что достать их будет не проблемой для крепкого воина или опытного мага.",
    ["fa1c94c8"] = "Надеюсь, духи исправно тебя защищали. Тебе предстоит ещё много испытаний, поэтому я хочу вот обучить тебя тому, что сам знаю. Сам решай, хочешь ли обладать нашими силами, и если да, то приходи. Выбирать тебе – я могу только вести тебя. Ну, одни-то, конечно, учатся быстро, а другие вот… помедленней. Но ты не волнуйся заранее. Как захочешь меня увидеть – приходи, поговорим. -Кен'джай, наставница Жрецов.",
    ["fa3137c6"] = "Как только Кел'Тузад вернулся к жизни, Артас повёл Плеть на юг, к Даларану. Там лич должен был найти книгу заклинаний Медива и с её помощью вернуть в этот мир Архимонда. После этого Архимонд должен был возглавить Легион и повести его в решающий бой. Даже волшебники Кирин-Тора не смогли помешать Артасу завладеть книгой Медива, и Кел'Тузаду оставалось лишь прочесть заклинание.",
    ["fa35b9b3"] = "Нападение было ужасным. Они убили треть из нас к тому моменту, когда мы смогли их уничтожить. И теперь у нас едва хватает людей для защиты наших границ. Это лишь вопрос времени, когда наши утомлённые стражники падут и Плеть атакует нас. И хотя я видел лицо Девлина среди доведённых до отчаяния мужчин и мрачнолицых воинов Плети в ту проклятую ночь, он ускользнул от меня прежде, чем я смог до него добраться. Возможно, он мёртв – а возможно, выжил, и стал агентом Плети. Как бы то ни было, он – монстр.",
    ["fa7fa085"] = "*(Страницы исписаны древними эльфийскими рунами)* На этих страницах описаны события, случившиеся при сборе и создании ингредиентов, нужных для изготовления магического камня. Пусть же наши враги никогда не заполучат эти манускрипты. Пусть же я доживу до того дня, когда снова увижу Кель'Талас, озарённый бледным светом луны. Пусть же я умру, но умру во славу Кель'таса. Пусть же я убью во славу Иллидана. -Кариэль Винтхалус",
    ["faa63e5f"] = "В честь сумерек, павших на мир в их последний день работы, титаны назвали этот континент Калимдором – \"землёй вечного звёздного света\".",
    ["faadd69d"] = false,
    ["fab08f5e"] = "Череп Гул'дана дал Иллидану демонический облик и огромную силу. Кроме того, он получил часть воспоминаний Гул'дана, главным образом о Гробнице Саргераса – подземелье на острове, где, по слухам, находились останки Титана Мрака Саргераса.",
    ["fadffd0e"] = "Многим высокорождённым тоже удалось выжить, и они отправились к берегам новой земли вместе с ночными эльфами. Малфурион до сих пор сомневался в Высокорождённых, но он был рад хотя бы тому, что Источника больше нет, а без его энергии они не представляют собой угрозы.",
    ["fb256e8c"] = "После долгих месяцев блуждания по суровым снежным пустошам Кел'Тузад, наконец, добрался до Ледяной Короны. Он смело подошёл к тёмной крепости Нер'зула, и, к его удивлению, стражники-нежить молча расступились – так, словно мага здесь ждали.",
    ["fb344233"] = "Колокол, Колесо и Свеча не только хранят энергию для ритуала, но и обладают собственными уникальными свойствами. Колокол Детмуры, испуская звон, дарует чернокнижникам в круге силу и энергию. Колесо Чёрного Похода при вращении защищает тех, кто стоит в круге, от урона. Когда горит Свеча Судного Дня, она поражает врагов, вступивших в круг, магической энергией. Эти предметы очень полезны, и потому очень важно следить за тем, чтобы во время ритуала они работали бесперебойно.",
    ["fb9a4eb3"] = "Вскоре он превратил эту миролюбивую расу в жестоких, кровожадных воинов. Нер'зулу и его народу оставалось сделать последний роковой шаг: стать вестниками смерти, полностью посвятив себя войне. Но старый шаман понял, что для орков это означало вечное рабство, и ему удалось не поддаться воле демона.",
    ["fbb0c70b"] = "Если мы сможем сами решать, какой машине быть в отличном состоянии, а какой нет... полагаю, излишне объяснять, какое преимущество это даст нам на ставках. Итак, от вас, милый Шипучка, мы ожидаем средство, которое ослабит прилежание техников. Нет ли в Тернистой долине растений, трав или напитков, что могли бы размягчить мозги гномам и гоблинам? -- К. Угольная Борода",
    ["fbeb03b3"] = "Шли недели, шкур пантер и тигров становилось всё больше. Мне показалось, что настало время сосредоточить наши силы на более серьёзной добыче: ящерах. Люди поблагодарили нас с Барнилом за уроки, но отказались использовать огнестрельное оружие. Ажек чувствовала себя куда более уверенно с луком в руках, а сэр Эрлгедин не расставался со своим мощным арбалетом.",
    ["fbefa0f2"] = "В то время как Медив пытался убедить орков и людей в необходимости объединить силы, ночные эльфы сами боролись с Легионом. Тиранда Шелест Ветра, бессмертная верховная жрица ночных эльфов-Стражей, отчаянно сражалась с демонами и мертвецами, чтобы не дать им захватить Ясеневый лес. Тиранда поняла, что одной ей не справиться, и велела пробудить друидов ночных эльфов от многовекового сна, чтобы просить их о помощи.",
    ["fc71140e"] = "Почти четыре тысячи лет высшие эльфы спокойно жили в своём укромном королевстве. Тем не менее мстительные тролли сдаваться не собирались. В глуши лесов они строили планы и копили силы. В конце концов могучая армия троллей вышла из тени лесов и вновь осадила сияющие башни Кель'Таласа.",
    ["fc734ce5"] = "Прибыв в этот городок, я уже через несколько дней стал учить местных детишек с близлежащих ферм. Уроки проходили так успешно, что местный глава города поручил мне организацию школы, и строительство здания уже началось! Я прошёл от Серебряного бора до Штормграда, и вот сейчас живу в Луноречье – кто бы мог подумать, что я обойду чуть ли не пол-Азерота? С наилучшими пожеланиями, Сталван Мистмантл",
    ["fcd408f5"] = "Найдите их для меня и принесите в Прибамбасск вместе с этим гроссбухом, и я награжу вас.",
    ["fce0d734"] = "*(Прикоснувшись к светящемуся кристаллу, вы ощущаете порыв ветра, который доносит тихие слова.)* Ваятели ветра внимательно наблюдали за тобой, и пора тебе сделать следующий шаг в освоении искусства шамана. Духи Ветра давно исчезли с острова Зефрис, и теперь мы должны лицом к лицу встретить всё опасности обители стихий, чтобы вернуть их домой. Это наш священный долг, от которого зависит само наше выживание. Разыщи меня в центре деревни Тендал. Я займусь твоим обучением. Ваятель ветра Боро, наставник шаманов",
    ["fd0fd402"] = "В руках, я получила видение хаоса. Люди-волки... воргены... сражались с невероятным врагом. Воргены яростно сражались, как подобает их примитивной расе, но их враг был неодолим – повелители Изумрудного Пламени. И именно тогда я осознала подлинную силу Косы. Сосредотачиваясь на ней, я смогла общаться с воргенами. Только не при помощи речи. Это было что-то другое... мне не описать это словами. Важно было то, что воргены слышали",
    ["fd16c88c"] = "Но какой ценой должны вестись войны за сохранение жизни? После которой смерти павшего в бою солдата мы поймём, что жизнь, которую мы стремимся спасти, ускользает от нас на поле боя? Под сколько мечей и топоров должны мы бросить наше будущее? Под сколькими метрами пропитанной кровью земли должны мы похоронить наше прошлое?",
    ["fd1c78b6"] = "Моё почтение Элло Чернодреву, мэру Темнолесья. Боюсь, что у меня есть новости для вашего города. Важные новости. Видите ли, я – создатель. Я обманул носителя этого письма, чтобы он помог мне создать моё последнее, наиболее ужасающее творение – монстра из плоти, костей и перекрученного металла! В тот момент, когда вы читаете эти слова, оно находится снаружи моего скромного жилища, скрежеща зубами и ожидая одного моего слова, чтобы отправиться убивать. Но вскоре вы сами обо-всём узнаете. Бальзамировщик",
    ["fd36f370"] = "Бронзовые драконы, что считаются защитниками, склонны обитать в обжитых местах. Вневременный и всё его племя по натуре своей очень терпеливы и всегда обдумают всё заранее, прежде чем действовать. Ноздорму неизменно будет защищать нормальное течение времени, а также и смертные народы, если им будут угрожать могущественные враги.",
    ["fd426ed1"] = "Господину Алекстону, Штормград. Позвольте поздравить вас с тем, что долгий труд по восстановлению Штормграда увенчался успехом. Многие из тех, чей путь лежит через Аубердин, с восхищением говорят о его величии и прочных основаниях. Именно этот успех и побудил меня написать вам. Аубердин обрёл своё место в этом мире у моря. Когда-то мы были отрезаны от всех, а ныне надежду нам приносят те самые ветра, что терзают наши берега. Податель сего письма – один из тех странников, которых принесли ко мне ветра. Надеюсь, он поможет вашему народу так же, как помог моему. Взамен прошу вас прислать в Аубердин припасы и мастеровых, дабы мы могли укрепить город против гнева этого мира, отнявшего у нас так много. Тандрис Ветропряд, старейшина Аубердина",
    ["fdb921e3"] = "Агенты приступили к прочёсыванию, обнаружив существенное присутствие воргов. Рекомендую отправить туда отряды охотников для уменьшения этой угрозы. На ферме, названной агентами Мёртвым полем, были обнаружены гноллы-нежить. Что им нужно на этой ферме – неизвестно, хотя их передвижения и уровень готовности делают вероятными грядущие боевые действия. Во время наблюдения за ними среди гноллов не было обнаружено явных лидеров. Предполагается, что они ожидают прибытия командования или подкрепления.",
    ["fdc01707"] = "Через несколько месяцев суеверные простолюдины начали подозревать, что их правители-волшебники от них что-то скрывали. Слухи о революции пронеслись по всем улицам Даларана, в то время как подозрительные горожане начали сомневаться в действиях и принципах магов, которыми они раньше восхищались. Магократы, опасаясь, что крестьяне поднимут бунт и что Стром может предпринять что-то против них, обратились к одной группе, которая, как они надеялись, поймёт их, – к эльфам.",
    ["fddc0c5a"] = "Затем советую тебе вернуться в Мулгор и разыскать в Громовом Утёсе Кэрна Кровавое Копыто. Кэрн – вождь тауренского племени Кровавого Копыта, и именно с его позволения твой народ и Служители Земли получили право обосноваться в Мулгоре. Дорога в Громовой Утёс тебе уже должна быть знакома. Найди распорядителя полётов в центре Оргриммара и лети на ветрокрыле в Громовой Утёс. Кэрна можно найти на центральном плато, чуть восточнее великого тотема, что служит в городе насестом для ветрокрылов.",
    ["fe032efd"] = "Кель, опытный маг, был обеспокоен слабостью Альянса. Его подданные, огорчённые потерей своей родины, назвали себя эльфами крови – в память о своём погибшем народе. Лишённые энергии Солнечного Колодца, они ценой огромных страданий сдерживали дальнейшее наступление Плети.",
    ["fe449523"] = "Дорогой дневник, теперь я в порядке. Я бил своего прислужника до тех пор, пока он не начал рыдать, словно девчонка. Хм… Что-то на душе тоскливо. Минутку! Демоны! Я же ЗЛОЙ гений! Злой, понимаешь? Как я в себе разочарован. Скоро вернусь.",
    ["fe6f0de9"] = "Через несколько месяцев Орда истребила почти всех дренеев, живших на Дреноре. Лишь немногие сумели избежать гнева орков. Гул'дан был доволен: его Орда была непобедима. Но он знал, что если им будет не с кем сражаться, непреодолимая жажда крови заставит их убивать друг друга и войско уничтожит само себя.",
    ["fe7c39df"] = "Юный орк охотно согласился быть учеником демона и вскоре стал одним из самых могущественных смертных волшебников в истории. Он учил других орков тёмным искусствам и пытался искоренить их древние ритуалы. Гул'дан показал своим братьям волшебство, которое никто из них никогда не видел, ужасающую мощь, способную повсюду сеять смерть.",
    ["fec60183"] = "Помехой – возможно, лишь ещё одним культом смерти. Ему невдомёк, что мы – не что иное, как одна из... нитей Совета Теней. Ребёнком я слышал историю о насекомом, один укус которого мог с лёгкостью убить жертву, хотя выглядело оно как обычная мушка, как пятнышко, вряд ли заслуживающее внимания. Именно то, что оставляют без внимания, и наносит нам самый крупный ущерб.",
    ["feebd87e"] = "Слово \"ПРЕДАТЕЛЬ\" криво нацарапано поверх красиво высеченной эпитафии, гласящей: \"Здесь покоится Юрив. Отец, муж, паладин. Пусть же потомки знают, что преданность его Свету была неколебима. Он никогда не требовал от других того, чего не стал бы делать сам\".",
    ["feefdfc6"] = "Его друзья-титаны пытались убедить его не совершать ошибки, пытались успокоить его разбушевавшиеся чувства, но он принимал их более чем оптимистичные верования за корыстные заблуждения. Покинув навсегда их ряды, Саргерас отправился на поиски своего собственного места во вселенной. Несмотря на то что Пантеон был опечален его уходом, даже титаны не могли предугадать того, как далеко зайдёт их заблудший брат.",
    ["fef2a689"] = "Лорд Вальтхалак, продолжение. Если бы мы представляли себе, насколько могущественным волшебником был Вальтхалак (особенно по части подчинения себе душ), то ни за что на свете не согласились бы на это задание. Но судьба распорядилась иначе, и эта работа оказалась для нас последней. Убив Лорда Вальтхалака и забрав его книгу заклинаний, Кормок, должно быть, почувствовал, что с его амулетом что-то не так. Он чуть не затеял драку из-за того, что хотел забрать амулет себе. Тогда мы ещё не знали, что в амулете была заключена часть души Вальтхалака; выяснили мы это, к сожалению, намного позже.",
    ["fef42baa"] = "В древние времена, после того как титаны покинули Азерот, их дети, известные как земельники, продолжали охранять и обустраивать глубины мира. Земельникам не было дела до наземных рас, они желали лишь проникать всё глубже и глубже в землю.",
    ["ff35dbdb"] = "Озрик, ниже приведён перечень доспехов, которые нам требуются: Десять Панцирных Рубах, Двадцать Шлемов, Тридцать Накладок на Доспех, Пятнадцать Бронированных Ботинок. Мы, как обычно, у тебя в долгу. И если Западный Край когда-нибудь избавится от досаждающих ему воров, я сочту себя просто обязанным пригласить тебя в наш дом на вкусный обед, достойный былой щедрости, что некогда прославляла эту страну. — Льюис Интендант, Сторожевой Холм.",
    ["ffc1ce7a"] = "Из глубин Ледяного Трона Нер'зул направил свой могучий разум ко всем обитателям Нордскола. Без особых усилий он подчинил своей воле многих существ, включая ледяных троллей и свирепых вендиго. Силы его духа были практически безграничны, и с их помощью он создал небольшую армию, которую собрал в бесконечных лабиринтах Ледяной Короны.",
    ["ffd78c29"] = false,
    ["ffd90e16"] = "Изалиен, продолжение. Но когда она со своим гиппогрифом Неземным входила в город, на них напал Алззин Перевертень и его воины. И в этом бою её глаза закрылись навеки. Может быть, это и к лучшему, что ей не удалось раскрыть секрет того зловещего проклятия, которое Лорд Вальтхалак наложил на амулет, чтобы заключить там свою душу. Логово Алззина – одно из мест с привидениями.",
    ["ffea38be"] = "Дела культа, том девяносто второй. С радостным сердцем приветствую я вас, братья мои, ибо дела нашего культа идут сейчас наилучшим образом. Имя нам – легион, и всякие замыслы наши всё ближе к воплощению. В ряды наши встаёт всё больше новичков. Хвалебная песнь возносится к нашим господам на Тёмных берегах, и склоняются они в радостных грёзах среди Выжженной теснины, и обнимают они слугу наших господ, Аку'май, в Непроглядной Пучине. Поистине, братья мои и сёстры, скоро вера наша разнесётся по всему Азероту!",
}
